"""Cách làm viết lại cho món đợt mnmn_duyet_1 (lo5_mnmn.py): mô tả + các bước, theo đúng bài Món Ngon Mỗi Ngày."""
CT_MNMN = {
    'dau_bap_nhoi_chien_gion': ('Đậu bắp moi hạt, nhồi nhân tôm và giò sống, nhúng bột chiên giòn rồi chiên vàng, chấm xốt mayonnaise chanh dây chua béo.',
        ['Bóc vỏ tôm sú, đập dập rồi băm nhỏ. Xẻ dọc đậu bắp, lấy hết hạt ra.', 'Làm nhân: cho tôm vào tô, nêm chút tiêu và 1/2 muỗng cà phê hạt nêm, trộn đều; thêm giò sống, 1 muỗng canh hành tỏi phi, 1 muỗng cà phê nước cốt chanh dây rồi trộn lại.', 'Rắc một lớp bột chiên giòn khô vào lòng đậu bắp, dùng muỗng cà phê nhồi nhân vào cho chặt.', 'Pha 1/2 gói bột chiên giòn với nước theo tỉ lệ trên bao bì, thêm nước từ từ đến khi bột sệt vừa, cho 1 muỗng cà phê nước cốt chanh dây vào khuấy đều. Đun nóng dầu, nhúng đậu bắp qua bột rồi chiên đến khi vàng đều, vớt ra để ráo dầu.', 'Pha nước chấm gồm 2 muỗng canh xốt mayonnaise, 1 muỗng canh nước cốt chanh dây, 1/2 muỗng cà phê bột ớt paprika, 1/4 muỗng cà phê muối và 1 muỗng canh hành tỏi phi.', 'Bày đậu bắp ra dĩa cùng rau mầm, cà bi, ăn kèm xốt mayonnaise chanh dây.', 'Mẹo: Lớp bột khô bên trong giúp nhân bám vào đậu bắp; chiên lửa vừa để đậu chín từ từ và không ngấm dầu.']),
    'dau_bap_xao_hai_san': ('Tôm, mực xào lửa lớn với đậu bắp non, ớt chuông và tỏi, nêm nước tương, có chút nước sánh, ngọt và giòn.',
        ['Cắt xéo đậu bắp và ớt sừng; ớt chuông cắt miếng vuông; tỏi đập dập. Hòa bột năng với nước.', 'Mực khứa vảy rồng nhỏ rồi cắt miếng vừa ăn. Tôm bóc vỏ, giữ lại đuôi.', 'Phi thơm tỏi với 2 muỗng canh dầu ăn, cho tôm, mực và 1 muỗng canh rượu trắng vào đảo cho hải sản săn lại.', 'Thêm đậu bắp rồi ớt chuông, nêm 1/2 muỗng cà phê đường, 1 muỗng cà phê hạt nêm gà, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê bột ngọt, 2 muỗng cà phê nước tương và nửa chén nước. Xào lửa lớn đến khi rau củ vừa chín tới.', 'Cho 2 muỗng canh nước bột năng vào cho sánh, thêm hành cần và ớt sừng, đảo đều rồi tắt bếp. Múc ra dĩa, rắc ngò rí.', 'Mẹo: Cho đậu bắp vào xào cùng hải sản từ sớm để đậu chín đều với các nguyên liệu khác.']),
    'dau_bap_thit_ga_xao_chao': ('Đậu bắp xào với thịt đùi gà ướp chao và gừng, thêm rau om và ớt sừng, vị béo mặn đặc trưng của chao.',
        ['Thái mỏng thịt gà, ướp với 1 viên chao, 1 muỗng cà phê gừng băm và 1/2 muỗng cà phê đường cho thấm.', 'Cắt xéo mỏng đậu bắp; rau om cắt nhỏ; ớt sừng bỏ hạt, cắt hình thoi.', 'Phi thơm 1 muỗng canh gừng băm, cho gà vào xào chín. Thêm đậu bắp, chút nước, nêm 1 muỗng cà phê hạt nêm và 1 muỗng cà phê nước chao, xào đến khi đậu bắp vừa chín.', 'Cho ớt sừng vào, rắc rau om, đảo đều rồi tắt bếp. Múc ra dĩa, rắc tiêu, ăn nóng với cơm.', 'Mẹo: Chọn đậu bắp non; nước chao cho vào sau cùng để giữ mùi vị đặc trưng.']),
    'dau_bap_xao_tom': ('Đậu bắp chần giấm cho bớt nhớt, xào lửa lớn với tôm ướp tỏi, nêm dầu hào, dầu mè, nước tương, đậm đà.',
        ['Tôm rửa sạch, bỏ chỉ, để nguyên đầu đuôi, luộc sơ trong nước sôi có 1 muỗng cà phê muối rồi thả vào tô nước lạnh. Sau đó mới bóc vỏ, bỏ đầu đuôi.', 'Ướp tôm với 1/2 muỗng cà phê tỏi băm, 1/4 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê hạt nêm và 1 muỗng cà phê đường.', 'Đậu bắp bỏ đầu đuôi, cắt khúc xéo 1,5cm, rửa sạch, chần nhanh trong nước sôi có 1 muỗng canh giấm gạo và 1/2 muỗng cà phê muối, rồi ngâm vào nước lạnh. Hành lá cắt khúc, ngò rí cắt nhỏ.', 'Cho 4 muỗng canh dầu vào chảo, phi thơm tỏi, cho tôm vào đảo nhanh, nêm 1 muỗng canh dầu hào, 1 muỗng canh dầu mè và 1 muỗng canh nước tương.', 'Thêm đậu bắp, đảo nhanh tay trên lửa lớn, sau cùng cho hành lá, ngò rí rồi tắt bếp. Bày ra dĩa với hành ngò, ớt sợi, ăn cùng cơm.', 'Mẹo: Chần đậu bắp với giấm giúp bớt nhớt; xào tôm lửa lớn để tôm săn và giữ vị ngọt.']),
    'dau_cove_xao_ba_roi_xong_khoi': ('Đậu cove và cà rốt xào với ba rọi xông khói tươm mỡ, thêm trứng vịt đảo chín, chấm nước tương pha tương ớt.',
        ['Đậu cove tước xơ, cắt xéo mỏng 5 ly. Cà rốt cắt khúc 7cm rồi thái sợi bản 2mm. Hành lá cắt khúc, tỏi đập dập.', 'Đánh tan trứng vịt với 1 muỗng cà phê rượu trắng.', 'Pha nước chấm: 1 muỗng canh tương ớt, 1 muỗng canh giấm tiều, 2 muỗng canh nước tương, 1 muỗng cà phê đường, 1/4 muỗng cà phê bột ngọt, khuấy tan.', 'Phi thơm tỏi, cho ba rọi xông khói vào xào đến khi ra mỡ và ngả vàng. Thêm đậu cove, cà rốt, nêm 1/2 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê đường, thêm chút nước cho rau nhanh chín.', 'Đổ trứng vào giữa chảo, đảo cho trứng chín, thêm hành lá rồi đảo đều. Múc ra dĩa, rắc tiêu và ngò, ăn nóng chấm nước tương pha.', 'Mẹo: Cắt xéo đậu cove để mau chín, dễ thấm; rượu trắng giúp trứng vịt bớt tanh.']),
    'dau_hu_bao_bo': ('Đậu hũ chiên khoét ruột làm túi, nhồi rau củ, nấm, chả chay, buộc bông hẹ rồi kho xốt dầu hào chay, mặn ngọt.',
        ['Cắt đậu hũ thành khối chữ nhật 6x4cm, chiên vàng rồi khoét phần ruột tạo thành túi nhỏ; phần ruột tán nhuyễn. Nấm đông cô ngâm mềm, cắt hạt lựu.', 'Phi thơm poa-rô, cho rau củ vào xào, nêm 2 muỗng cà phê hạt nêm chay, 1 muỗng cà phê đường, chút tiêu. Trút ra dĩa, trộn cùng phần ruột đậu đã tán.', 'Nhồi nhân vào từng túi đậu, dùng bông hẹ buộc miệng nhẹ tay. Phi thơm tỏi, xào cải thìa với chút hạt nêm chay.', 'Làm xốt: hòa 1 chén nước với 1 muỗng canh dầu hào chay, 2 muỗng canh nước tương, 1/2 muỗng canh đường, 1/2 muỗng cà phê hạt nêm chay, 1 muỗng canh tương ớt rồi đun sôi. Hạ lửa, cho 1/2 muỗng canh nước bột năng vào khuấy sệt, thêm 1/2 muỗng cà phê dầu mè.', 'Cho túi đậu vào xốt kho 5 phút rồi tắt bếp. Lót cải thìa ra dĩa, xếp đậu lên và rưới xốt.', 'Mẹo: Khoét ruột đậu thật mỏng phía trên cho túi đẹp; hạ lửa khi cho bột năng để xốt không vón.']),
    'dau_hu_chien_sa_ot': ('Đậu hũ chiên khứa xéo, ướp sả ớt hành băm với nghệ rồi áp chảo vàng hai mặt, thơm sả, chấm nước tương.',
        ['Khứa xéo 3 đường trên mỗi miếng đậu hũ chiên, không cắt đứt.', 'Băm nhỏ sả, ớt, hành boa-rô; trộn với 1/2 muỗng cà phê muối, 1/2 muỗng cà phê bột nghệ, 1/2 muỗng cà phê bột ngọt. Ướp đậu hũ với hỗn hợp này 15 phút.', 'Đun nóng ít dầu, chiên đậu hũ đến khi vàng đều hai mặt rồi gắp ra dĩa.', 'Cho phần sả ớt hành còn lại vào chảo chiên thơm, rải lên mặt đậu. Ăn nóng với cơm, chấm nước tương với ớt lát.', 'Mẹo: Ướp càng lâu đậu càng đậm vị; bột nghệ cho màu vàng đẹp.']),
    'dau_hu_chien_xot_ca': ('Đậu hũ chiên nhồi nhân đậu trắng, nấm, bún tàu, dưa cải, chiên sơ rồi rim trong xốt cà chua dưa kiệu.',
        ['Nấm mèo ngâm mềm, thái sợi nhỏ. Bún tàu ngâm mềm, cắt khúc 2cm. Hành boa-rô cắt nhỏ, để riêng cọng và lá. Nấm hương ngâm mềm, luộc sơ, cắt hạt lựu. Dưa cải xả nước lạnh, vắt khô, thái sợi. Cà chua băm nhuyễn. Đậu hũ trắng trụng nước nóng, để ráo.', 'Xào thơm phần lá hành boa-rô với nấm mèo, nấm hương và dưa cải, để nguội làm nhân rau.', 'Xẻ đôi đậu hũ chiên, múc ra khoảng một nửa phần ruột cho vào tô, thêm đậu hũ trắng và 2 muỗng canh bột năng, tán nhuyễn. Trộn thêm bún tàu, nhân rau, nêm 1 muỗng cà phê bột ngọt, 1 muỗng cà phê nước tương, 2 muỗng cà phê đường, 1 muỗng cà phê muối, 1/2 muỗng cà phê tiêu.', 'Nhồi nhân vào đậu hũ rồi chiên sơ.', 'Làm xốt: phi thơm dưa kiệu với phần hành boa-rô còn lại, cho cà chua vào xào ráo, thêm 1 chén nước nấu đến khi cà mềm. Nêm 1 muỗng cà phê bột ngọt, 1 muỗng cà phê nước tương, 1/2 muỗng cà phê muối, 2 muỗng cà phê đường.', 'Cho đậu hũ vào xốt rim 15 phút, lật cho hai mặt thấm đều. Bày ra dĩa, ăn với cơm, chấm nước tương.', 'Mẹo: Xào nhân trước cho thơm; bột năng hút nước trong đậu giúp nhân kết dính.']),
    'dau_hu_hap_la_han': ('Đậu hũ non xếp xen thịt nguội chay, nấm đông cô, gừng, cải thìa, rưới xốt dầu hào chay rồi hấp, thanh nhẹ.',
        ['Cắt đậu hũ miếng 3x5cm, dày 1cm. Thịt nguội chay cắt cùng cỡ.', 'Nấm đông cô bỏ chân, rửa nước muối, chần sơ rồi ngâm nước lạnh. Luộc cải thìa trong nước có chút muối và dầu ăn, ngâm chung với nấm, sau đó chẻ đôi theo chiều dọc.', 'Pha xốt: 1,5 muỗng canh dầu hào chay, 1/2 muỗng canh nước tương, 1/3 muỗng cà phê tiêu, 1 muỗng cà phê đường, 1/2 muỗng canh dầu mè, 1,5 nước lọc và 1,5 muỗng cà phê bột năng, khuấy đều.', 'Xếp xen kẽ đậu hũ, thịt nguội chay, nấm, gừng lên dĩa, cải thìa vòng quanh. Rưới xốt, rắc kỉ tử rồi hấp cách thủy 10 phút.', 'Ăn nóng, chấm nước tương với ớt lát.', 'Mẹo: Gừng làm cân bằng vị và thêm thơm; đậu hũ non rất hợp để hấp.']),
    'dau_hu_hap_tom': ('Trứng gà đánh tan trộn tôm, đậu hũ, nấm, cà rốt, đậu Hà Lan, chia chén hấp, phết lòng đỏ, mềm mịn.',
        ['Đập trứng ra chén, giữ riêng 2 lòng đỏ đánh tan; phần còn lại khuấy tan.', 'Trộn tôm với đậu Hà Lan, nấm, cà rốt, đậu hũ; ướp 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê dầu mè, 1/2 muỗng cà phê tiêu, 1/3 muỗng cà phê đường.', 'Đổ trứng đã đánh vào hỗn hợp, trộn đều rồi chia ra 6 chén nhỏ, đem hấp.', 'Khi trứng gần chín, thấm khô nước đọng trên mặt bằng khăn giấy, phết lòng đỏ lên và hấp tiếp, mở hé nắp cho trứng chín và giữ màu tươi. Ăn với cơm trắng.', 'Mẹo: Để nguyên liệu thật ráo cho trứng không bị loãng; thường xuyên xả hơi nước khi hấp để trứng không rỗ.']),
    'dau_hu_hap_trung': ('Trứng và đậu hũ non hấp cách thủy, rưới xốt thịt bằm cà rốt sánh nhẹ, mềm mịn dễ ăn.',
        ['Chần đậu hũ non qua nước sôi, cắt hạt lựu. Cà rốt cắt hạt lựu. Băm nhuyễn hành tím, tỏi. Hòa bột bắp với 2 muỗng canh nước. Hành lá cắt nhỏ.', 'Phi thơm hành tỏi băm với 1 muỗng canh dầu, múc ra chén.', 'Cho vào tô trứng, đậu hũ, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê dầu hành tỏi phi, 1 muỗng cà phê nước tương, 1/2 muỗng cà phê đường, tiêu, 1 muỗng cà phê rượu sake và 50ml nước, khuấy đều.', 'Đổ hỗn hợp vào khuôn sứ sâu lòng, hấp cách thủy lửa vừa 15-17 phút.', 'Làm xốt: cho 1 muỗng cà phê dầu hành tỏi vào chảo, xào thịt đến tái, thêm cà rốt, hành lá, 1 muỗng cà phê hành tỏi phi, 1/2 muỗng cà phê dầu hào, 1/2 muỗng cà phê đường, 1 muỗng cà phê hạt nêm, xào cho thịt chín. Thêm 50ml nước đun sôi, cho bột bắp vào nấu đến khi sánh, rắc chút tiêu.', 'Rưới xốt lên mặt trứng đậu đã hấp, trang trí ngò rí và ớt sợi.', 'Mẹo: Chần đậu cho sạch và dai hơn; rượu sake khử mùi tanh trứng; chỉnh lượng nước và trứng để có độ mềm vừa ý.']),
    'dau_hu_nhoi_hat_sen': ('Đậu hũ chiên nhồi ruột đậu, nấm đông cô, hạt sen, áp chảo rồi rim trong xốt cà chua, mặn ngọt bùi.',
        ['Cắt đôi đậu hũ, dùng muỗng lấy phần ruột trắng ra, vắt ráo nước bằng vải mùng.', 'Nấm đông cô ngâm nở, thái sợi nhỏ, giữ lại nước ngâm. Hạt sen luộc chín, đập dập một nửa, để nguyên một nửa. Cà chua băm nhỏ. Boa-rô thái mỏng, phi vàng một nửa.', 'Trộn ruột đậu với nấm, hạt sen đập dập, boa-rô phi, nêm 1 muỗng cà phê hạt nêm chay, chút tiêu, 1/2 muỗng canh dầu điều rồi nhồi vào đậu hũ.', 'Áp chảo mặt có nhân để định hình.', 'Phi thơm phần boa-rô còn lại, cho cà chua vào xào, nêm 1,5 muỗng cà phê hạt nêm chay, 1/2 muỗng cà phê màu điều, 2 muỗng cà phê đường, 1/2 muỗng cà phê bột ngọt. Đổ khoảng nửa chén nước ngâm nấm, cho đậu hũ và hạt sen nguyên hạt vào rim lửa nhỏ cho thấm.', 'Gắp ra dĩa, rắc tiêu và ngò rí.', 'Mẹo: Vắt ráo ruột đậu giúp nhân dai và kết dính tốt.']),
    'dau_hu_nhoi_tom_chien': ('Đậu hũ khoét lỗ nhồi tôm, nấm mèo, gừng, mè, lăn bột chiên giòn rồi chiên vàng, ăn kèm rau và tương cà.',
        ['Cắt mỗi miếng đậu hũ làm 3, chần sơ nước sôi, khoét một ô chữ nhật ở giữa, múc phần ruột ra, chừa thành và đáy. Vắt ráo phần ruột, bóp nhuyễn.', 'Tôm cắt hạt lựu nhỏ, nấm mèo và hành ngò cắt nhỏ. Rau mầm rửa để ráo, cà bi cắt đôi, dưa leo thái lát mỏng 3 ly.', 'Trộn tôm với ruột đậu, nấm mèo, hành ngò; nêm 1/2 muỗng cà phê hạt nêm, 1/4 muỗng cà phê tiêu, 1 muỗng cà phê gừng băm, 1 muỗng canh mè rang. Đắp nhân vào đậu, nén chặt.', 'Đun nóng dầu, lăn đậu qua bột chiên giòn khô rồi chiên đến khi vàng, vớt ra để ráo.', 'Xếp ra dĩa với rau mầm, cà bi, dưa leo; ăn kèm tương cà và xốt mayonnaise.', 'Mẹo: Chần và vắt ráo ruột đậu giúp nhân dai; lớp bột tẩm cho màu đẹp và thơm.']),
    'dau_hu_xao_nam': ('Đậu hũ non lăn bột chiên vàng, rim xốt nước dừa mật ong với nấm bào ngư, đông cô và rau củ, rắc hạt điều.',
        ['Đậu Hà Lan, bắp non cắt xéo làm đôi; cà rốt tỉa hoa, thái lát; nấm bào ngư cắt miếng vừa ăn. Luộc sơ đậu Hà Lan, bắp non, cà rốt trong nước sôi.', 'Cắt đậu hũ dày 1,5-2cm, lăn qua bột mì rồi chiên vàng vừa.', 'Pha xốt: 2 muỗng canh nước tương, 1,5 muỗng canh dầu hào chay, 1,5 muỗng canh mật ong, 1/2 muỗng cà phê đường, 1 muỗng cà phê sa tế, 1 muỗng cà phê hạt nêm chay và 1 chén nước dừa tươi.', 'Phi thơm boa-rô với 2 muỗng canh dầu điều, cho nấm và rau củ vào xào cùng 3 muỗng canh xốt, rồi trút ra.', 'Đổ phần xốt còn lại vào chảo, cho đậu hũ vào rim 2-3 phút, thêm nấm và rau củ nấu 1-2 phút đến khi xốt hơi sánh. Cho 2 muỗng cà phê nước bột năng và 1/2 muỗng cà phê dầu mè vào.', 'Bày ra dĩa, rắc hạt điều rang, trang trí cải xoong và ớt sợi, chấm kèm nước tương.', 'Mẹo: Phi boa-rô trước khi xào rau cho thơm béo; rim đậu trước để đậu thấm gia vị.']),
    'dau_que_xao_thit': ('Đậu que và cà rốt xào với thịt nạc dăm ướp tỏi, cuối cùng đảo thêm chút xốt mayonnaise cho béo thơm.',
        ['Thái mỏng thịt, ướp 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu và tỏi băm cho thấm.', 'Đậu que cắt khúc, cà rốt thái sợi, hành lá và ngò rí cắt nhỏ.', 'Phi thơm tỏi, xào thịt, rồi cho cà rốt và đậu que vào, nêm 1,5 muỗng cà phê hạt nêm và 4 muỗng canh nước, xào đến khi đậu chín.', 'Thêm 1 muỗng canh xốt mayonnaise, đảo nhanh rồi tắt bếp. Múc ra dĩa, rắc hành ngò, ăn nóng với cơm.', 'Mẹo: Cho mayonnaise vào là đảo nhanh rồi tắt bếp để giữ mùi thơm; xào cà rốt trước rồi mới đến đậu que cho chín đều.']),
    'dau_tron_xa_lach': ('Đậu trắng, đậu thận, đậu Hà Lan và bắp trộn xốt mayonnaise tương cà mật ong, bày với xà lách và trứng luộc.',
        ['Luộc chín đậu Hà Lan. Đậu thận trút ra rổ cho ráo, rồi trụng đậu trắng và đậu thận qua nước sôi.', 'Luộc chín trứng gà, bóc vỏ, cắt múi cau.', 'Pha xốt: 3 muỗng canh xốt mayonnaise, 2 muỗng canh tương cà, 1/2 muỗng canh tương ớt, 1/2 muỗng canh nước cốt chanh, 1/2 muỗng canh mật ong, trộn đều.', 'Trộn các loại đậu với xốt. Lót xà lách quanh dĩa, cho đậu vào giữa, xếp trứng thành vòng giữa đậu và rau. Dùng làm món khai vị.', 'Mẹo: Mật ong làm xốt ngon ngọt hơn; luộc trứng 10 phút là chín tới, 8 phút lòng đào, 3-5 phút la-cốt.']),
    'dau_dua_xao_la_chanh': ('Đậu đũa xào với ức gà ướp lá chanh băm, nêm nước mắm, rắc lá chanh thái sợi thơm nồng.',
        ['Lá chanh thái sợi, giữ lại một ít băm nhuyễn. Đậu đũa bỏ đầu đuôi, cắt khúc 5cm.', 'Thái mỏng thịt gà, ướp 1 muỗng canh hành tỏi băm, 1/3 muỗng canh tiêu, 1/3 muỗng canh đường, 1/2 muỗng canh hạt nêm và lá chanh băm, sau đó rắc chút bột năng.', 'Phi thơm hành tỏi, xào gà chín, cho đậu đũa vào cùng khoảng 5 muỗng canh nước để đậu chín hẳn.', 'Nêm 1 muỗng canh nước mắm, 1/2 muỗng cà phê đường, đảo đều rồi tắt bếp. Rắc lá chanh sợi lên, ăn nóng với cơm.', 'Mẹo: Xếp chồng lá chanh rồi cuộn tròn để thái được sợi nhỏ; rắc bột năng sau khi ướp giúp thịt giữ ngọt.']),
    'dau_dua_xao_tom': ('Đậu đũa chần sơ xào cùng tôm sú phi sả ớt và thơm chín, vị chua ngọt nhẹ, ăn với cơm.',
        ['Tôm bóc vỏ, chừa đuôi, xẻ lưng, ướp 1/4 muỗng cà phê tiêu, 1/2 muỗng cà phê hạt nêm, 1 muỗng cà phê tỏi băm.', 'Sả thái lát, ớt hiểm băm nhỏ, thơm bỏ lõi cắt lát. Đậu đũa cắt khúc 5cm, chần trong nước sôi có chút muối khoảng 2 phút, vớt ra để ráo.', 'Phi thơm sả với 1/2 muỗng cà phê ớt băm, cho tôm vào xào vừa chín rồi trút ra.', 'Phi thơm 1 muỗng canh tỏi, cho đậu đũa vào, nêm 1/2 muỗng cà phê muối, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê bột ngọt, 3 muỗng canh nước, xào đến khi đậu vừa chín.', 'Cho thơm và tôm vào đảo đều, tắt bếp. Múc ra dĩa, rắc tiêu, ngò rí, chấm nước tương với ớt.', 'Mẹo: Chần đậu đũa trước để khi xào chín đều, dễ thấm và giữ màu xanh.']),
    'dau_dua_xao_tom_thit': ('Đậu đũa xào trộn xốt mayonnaise tiêu dầu mè, phủ thịt xay xào tôm khô và ớt, đậm đà.',
        ['Đậu đũa cắt khúc 5cm; hành lá, ngò rí cắt khúc.', 'Ướp thịt xay với 1 muỗng canh hành tỏi băm, 1 muỗng canh nước mắm, 1/2 muỗng canh đường và 1 muỗng canh nước.', 'Pha xốt: 2 muỗng canh xốt mayonnaise, 1/3 muỗng canh tiêu, 1/2 muỗng canh dầu mè, trộn đều.', 'Phi thơm hành tỏi, cho đậu đũa vào đảo, thêm 1/2 chén nước xào đến khi chín. Tắt bếp, trộn xốt vào rồi trút ra dĩa.', 'Tiếp tục phi tỏi, ớt băm, cho thịt và tôm khô vào xào chín, thêm hành lá rồi tắt bếp. Rải tôm thịt lên đậu đũa, trang trí ngò rí, ăn với cơm.', 'Mẹo: Thêm nước khi ướp giúp thịt mềm, không vón cục; tôm khô giã nhỏ dễ quyện với thịt.']),
    'ba_chi_chien_gion_mam_thom': ('Ba chỉ luộc rồi thái lát, ướp sả, tẩm bột chiên giòn ngập dầu, chấm mắm thơm chua ngọt cay.',
        ['Luộc ba chỉ vừa chín trong nước có chút muối, thái lát dày 4 ly, ướp 1 muỗng canh sả băm 10 phút.', 'Để riêng 3 muỗng canh bột chiên giòn khô, phần còn lại pha với nước.', 'Làm mắm thơm: đun 1 chén nước thơm với 1 muỗng canh đường đến khi sôi nhẹ và đường tan, tắt bếp, thêm 3 muỗng canh nước mắm. Để nguội rồi cho ớt băm và thơm hạt lựu vào.', 'Lăn thịt qua bột khô rồi nhúng vào bột ướt. Chiên ngập dầu nóng đến khi vàng giòn, vớt ra để ráo.', 'Bày thịt ra dĩa với dưa leo, rau thơm, chấm mắm thơm.', 'Mẹo: Chọn ba chỉ da mỏng, ít mỡ, nạc mỡ dính nhau; tẩm bột khô trước bột ướt giúp bột bám đều và giòn lâu.']),
    'ba_chi_chien_rieng_me': ('Ba chỉ ướp nước riềng và mẻ, tẩm bột chiên giòn cùng riềng sợi, chấm nước mắm chua ngọt, thơm chua nhẹ.',
        ['Cắt ba chỉ miếng con chì, chần qua nước sôi có 1 muỗng cà phê đường.', 'Ướp thịt với 1 muỗng canh nước cốt riềng và 1 muỗng canh mẻ trong 5 phút. Cà bi cắt đôi.', 'Áo riềng sợi qua một ít bột tẩm khô chiên giòn, chiên vàng giòn. Tẩm bột vào thịt rồi chiên chín giòn, vớt ra giấy thấm dầu.', 'Pha nước chấm: 1 muỗng canh đường, 1 muỗng canh nước mắm, 1 muỗng canh nước cốt chanh với tỏi ớt băm.', 'Bày thịt ra dĩa, rắc ớt sợi và riềng chiên, kèm cải xoong, cà bi và nước mắm pha.', 'Mẹo: Chần thịt trước giúp thịt chín đều, không khô; chọn mẻ trắng, thơm, chua vừa; áo bột cho riềng để riềng giòn thơm.']),
    'ba_chi_xien_que_chien_gion': ('Ba chỉ luộc nước dừa với sả và quế hồi, xiên que, tẩm bột chiên giòn có mè đen, chiên vàng cùng hành tây.',
        ['Hành tây cắt khoanh. Sả đập dập, cắt khúc 5cm. Rang thơm quế, hồi, đinh hương rồi xay nhuyễn.', 'Cho vào nồi nước dừa, sả, 1 muỗng canh gia vị thơm, 1/2 muỗng cà phê muối, 1/2 muỗng canh mật ong, 2 muỗng canh nước tương, 1 muỗng canh hạt nêm. Thả thịt vào từ lúc nước còn lạnh, luộc lửa vừa 10 phút đến khi vừa chín, vớt ra để nguội.', 'Cắt thịt khối vuông, xiên vào que tre, chừa khoảng cách nhỏ.', 'Để riêng 2 muỗng canh bột chiên giòn khô, phần còn lại pha nước theo hướng dẫn cho sệt, trộn thêm 2 muỗng canh mè đen.', 'Lăn xiên thịt qua bột khô, nhúng bột ướt rồi chiên ngập dầu đến giòn, vớt ráo. Hành tây cũng tẩm bột khô, bột ướt rồi chiên giòn.', 'Xếp ra dĩa, ăn kèm salad, dưa leo, rau thơm và xốt mayonnaise.', 'Mẹo: Chọn thịt có mỡ xen để chiên không bị khô; luộc trong nước dừa giúp thịt mềm thơm; mè trong bột thêm vị và màu.']),
    'ba_roi_chien_sa_ot': ('Ba rọi ướp sả tỏi ớt và nước mắm nhiều giờ, chiên rám rồi om lửa nhỏ, thái lát rắc sả ớt phi thơm cay.',
        ['Băm nhuyễn tỏi và sả; ớt bỏ hạt, băm nhỏ.', 'Ướp ba rọi với 1/2 muỗng cà phê muối, 1 muỗng cà phê nước mắm, 1/2 muỗng cà phê hạt nêm và 2/3 lượng sả tỏi ớt băm, để 4 giờ cho thấm.', 'Đun nóng ít dầu, gạt bỏ sả tỏi ớt bám trên thịt, chiên rám hai mặt. Thêm 1/2 chén nước, đậy nắp, để lửa liu riu cho thịt chín.', 'Mở nắp chiên thêm cho vàng đều hai mặt, vớt ra để nguội. Dùng chảo khác phi thơm phần sả tỏi ớt còn lại.', 'Thái thịt dày khoảng 0,3cm, xếp ra dĩa và rải sả tỏi ớt phi lên trên.', 'Mẹo: Ướp đủ 4 giờ để thịt hơi lên men chua, ăn ngon hơn.']),
    'ba_roi_kho_gung': ('Ba rọi rút sườn ướp giấm, kho lửa nhỏ với gừng non, tỏi và tiêu trắng trong caramel dầu điều, thơm cay ấm.',
        ['Cắt ba rọi miếng vừa ăn, ướp 1 muỗng canh nước tương, 1 muỗng canh hạt nêm, 3 muỗng canh giấm gạo, 1/2 muỗng canh muối trong 15 phút.', 'Gừng non thái lát vừa, tỏi đập nhẹ, đầu hành lá cắt khúc 5cm.', 'Thắng 1 muỗng canh đường với 2 muỗng canh dầu điều thành caramel, cho gừng tỏi vào xào thơm rồi cho thịt vào xào săn.', 'Đổ nước xăm xắp mặt thịt, thêm 1 muỗng cà phê tiêu trắng, kho nhỏ lửa đến khi thịt mềm. Thêm đầu hành, đảo đều rồi tắt bếp.', 'Múc ra dĩa, rắc mè rang, ăn nóng.', 'Mẹo: Giấm giúp thịt kho giòn và thơm; dùng gừng non cho giòn và thơm dịu.']),
    'ba_roi_kho_mang': ('Ba rọi kho cùng măng, trứng cút chiên và đậu hũ trong caramel dầu điều, mặn ngọt đậm đà ăn với cơm.',
        ['Thái ba rọi dày 1cm, ướp 1 muỗng cà phê tiêu, 1 muỗng cà phê bột ngọt, 1 muỗng canh nước mắm, 1 muỗng canh tỏi băm, 2 muỗng canh hành tím băm trong 15 phút.', 'Cắt măng miếng 3cm, ngâm nước nóng 15 phút rồi xả nước lạnh, để ráo. Hành lá cắt khúc; ớt sừng bỏ hạt, cắt miếng. Hòa 1 muỗng canh hạt nêm với 1 chén nước.', 'Chiên vàng trứng cút trong dầu nóng, vớt ra để ráo.', 'Đun 1 muỗng canh đường với 2 muỗng canh dầu điều thành caramel, cho thịt và măng vào xào thơm, đổ chén nước hạt nêm vào kho nhỏ lửa khoảng 7 phút.', 'Thêm trứng cút, đậu hũ, kho thêm 5 phút. Tắt bếp, cho hành lá, ớt sừng vào đảo đều. Ăn với cơm, dưa leo hoặc dưa chua.', 'Mẹo: Thắng caramel với dầu điều để nước kho lên màu đẹp; dùng nước hạt nêm thay nước dùng cho món đậm vị.']),
    'ba_roi_nuong_me_rau_cu': ('Ba rọi nguyên miếng ướp mè, dầu hào, tỏi, nướng nồi chiên không dầu cùng bắp, măng tây, cà chua bi, chấm xốt tỏi.',
        ['Để nguyên miếng ba rọi, dùng nĩa xăm nhẹ. Trộn 1 muỗng cà phê mè đen, 1 muỗng cà phê mè trắng, 1 muỗng cà phê dầu hào, 2 muỗng cà phê dầu điều, 1 muỗng cà phê hành băm, 1 muỗng cà phê tỏi băm, 1 muỗng cà phê nước tương, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt; ướp thịt 20-30 phút.', 'Bắp cắt khúc 2cm, luộc chín trong nước có chút hạt nêm. Măng tây gọt sơ vỏ, cắt khúc 5-6cm, chần với nước có chút hạt nêm. Cà chua bi chẻ đôi.', 'Nướng thịt trong nồi chiên không dầu ở 160 độ khoảng 15 phút.', 'Lật thịt, cho rau củ vào, quét chút dầu ăn, rắc lá basil khô, nướng thêm 15 phút.', 'Làm xốt chấm: trộn 1/2 muỗng cà phê tiêu, 1/3 muỗng cà phê bột ngọt, 1 muỗng cà phê đường, 1 muỗng canh dầu ăn, 1/2 muỗng cà phê tương cà, 2 muỗng canh nước tương, 1/2 muỗng canh tương ớt, 2 muỗng canh nước, 1 muỗng canh tỏi băm rồi đun sôi.', 'Thái thịt mỏng, xếp ra dĩa cùng rau củ nướng, chấm xốt.', 'Mẹo: Xăm thịt giúp gia vị ngấm sâu; dầu ăn giúp tinh dầu basil tỏa thơm.']),
    'ba_roi_nuong_rieng': ('Ba rọi thái sợi ướp sữa đặc, cuộn riềng và hành tây, xiên nướng lò, cuốn rau thơm chấm mắm tôm tắc.',
        ['Thái ba rọi thành sợi mỏng dài, ướp 1 muỗng canh hành tím băm, 1/2 muỗng canh tỏi băm, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê nước mắm, 1 muỗng canh sữa đặc trong 15 phút.', 'Hành tây cắt múi cau nhỏ, riềng thái sợi.', 'Trải thịt ra, đặt riềng và hành tây lên rồi cuộn lại, xiên que xen kẽ với hành tây.', 'Làm nóng lò, nướng xiên thịt khoảng 10 phút đến khi chín vàng thơm.', 'Pha 1/2 chén mắm tôm với 1 muỗng cà phê bột ngọt, 1 muỗng canh đường, 1 muỗng cà phê rượu trắng, 1/2 muỗng canh tỏi băm; khi ăn vắt tắc vào khuấy cho sủi bọt.', 'Bày thịt lên mẹt lót lá chuối với rau ăn kèm, cuốn thịt với rau rồi chấm mắm tôm.', 'Mẹo: Để thịt trong ngăn đông cho cứng, dễ thái đều; cuộn riềng và hành tây bên trong giúp thịt chín đều và thơm.']),
    'bach_tuoc_nhung_la_me': ('Bạch tuộc nhúng nồi nước lá me non xào thơm và sả, chua dịu, cuốn bánh tráng rau thơm chấm muối ớt chanh sả.',
        ['Làm sạch bạch tuộc. Lá me non bỏ cuống, vò dập. Thơm, sả, hành tím thái mỏng. Ớt sừng cắt lát, ngò gai cắt khúc 1cm.', 'Phi thơm hành tím và 2/3 lượng sả với 2 muỗng canh dầu, cho thơm và lá me vào xào thơm.', 'Đổ 3 chén nước, nêm 1 muỗng cà phê bột canh, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê đường, 1 muỗng cà phê nước mắm, sau cùng thả ớt sừng và ngò gai.', 'Làm muối chấm: xay nhuyễn phần sả còn lại với 3 tép tỏi, 4 lá chanh, 2 muỗng canh đường, 2 muỗng canh nước chanh, 5 trái ớt sim xanh và 1 muỗng canh bột canh.', 'Nhúng bạch tuộc vào nước lá me cho chín, cuốn bánh tráng với rau thơm, chấm muối ớt chanh sả.', 'Mẹo: Xào kỹ sả và thơm để nước nhúng dậy mùi.']),
    'bach_tuoc_sot_cajun': ('Bạch tuộc nấu với bắp Mỹ, hành tây trong xốt cajun bơ, nước cam và tương cà, sánh, cay nồng.',
        ['Làm sạch bạch tuộc, chần sơ trong nước sôi có rượu và gừng, để ráo, cắt miếng vừa ăn. Bắp cắt khúc 2cm, hành tây cắt múi cau, cam vắt lấy nước.', 'Đun chảy 25g bơ, phi thơm 1/2 muỗng canh tỏi, thêm 2 muỗng canh bột cajun, 2 muỗng canh tương cà, 1 muỗng canh đường, 1 muỗng cà phê bột ớt, 1/2 muỗng canh hạt nêm, đảo đều.', 'Đổ nước cam và 1/2 chén nước lọc vào, cho bắp nấu khoảng 5 phút. Thêm hành tây và bạch tuộc, nấu lửa vừa đến khi bạch tuộc chín thì tắt bếp.', 'Gắp bạch tuộc ra riêng. Phi thơm tỏi với phần bơ còn lại, đổ nước xốt vào đảo đều, thêm nước bột năng cho sánh.', 'Đổ xốt ra dĩa, xếp bạch tuộc lên, rắc ớt bột và tỏi phi, ăn nóng.']),
    'bach_tuoc_xao_chua_cay': ('Bạch tuộc ướp sa tế, giấm, gừng, xào cùng thơm, ớt chuông, cần tây và hành tây, chua cay nhẹ.',
        ['Sả đập dập, cắt khúc. Hành lá cắt khúc. Thơm, ớt chuông cắt miếng; hành tây cắt múi cau; cần tây thái lát.', 'Làm sạch bạch tuộc, cắt miếng vừa ăn, ướp 1 muỗng cà phê rượu trắng, 1 muỗng canh sa tế, 1 muỗng cà phê gừng băm, 1 muỗng cà phê hạt nêm, 1,5 muỗng canh giấm gạo, 1 muỗng canh nước tương.', 'Phi thơm sả và tỏi, xào bạch tuộc vừa chín rồi trút ra.', 'Phi tỏi, xào thơm, cần tây, ớt chuông, nêm 1 muỗng cà phê hạt nêm, 1/2 muỗng canh nước tương, 1 muỗng cà phê đường đến khi rau vừa chín. Cho hành tây và bạch tuộc vào đảo đều, tắt bếp.', 'Bày ra dĩa, rắc hành lá, ăn với cơm hoặc nhâm nhi, chấm nước tương với ớt.', 'Mẹo: Sơ chế bạch tuộc với giấm hoặc nước vo gạo cho sạch nhớt, bớt tanh.']),
    'bach_tuoc_xao_rau_muong': ('Bạch tuộc ướp gừng, dầu điều xào săn rồi trộn với rau muống xào, nêm xốt giấm rượu dầu hào chua ngọt.',
        ['Bạch tuộc bỏ mắt, làm sạch, ướp 1 muỗng canh gừng băm, 1 muỗng canh hành tỏi băm, 1 trái ớt hiểm đập dập, 1/2 muỗng canh giấm gạo, 1 muỗng canh rượu trắng, 1/2 muỗng canh dầu hào, 1 muỗng canh dầu điều, 2 muỗng cà phê hạt nêm.', 'Rau muống nhặt sạch, cắt khúc 4cm. Pha xốt: 1 muỗng canh giấm gạo, 1 muỗng canh rượu trắng, 3 muỗng cà phê đường, 1/2 muỗng canh dầu hào.', 'Phi thơm hành tỏi với 1 muỗng canh dầu, xào săn bạch tuộc, nêm một nửa xốt rồi trút ra.', 'Xào rau muống với 1 muỗng canh dầu và hành tỏi, nêm nửa xốt còn lại, đợi 3-4 phút cho rau thấm. Cho bạch tuộc vào đảo đều, tắt bếp.', 'Múc ra dĩa, rắc tiêu, ăn nóng với cơm.', 'Mẹo: Rượu trắng khử mùi tanh và thêm hương; chọn bạch tuộc da còn nguyên, thịt săn và trong.']),
    'bach_tuoc_xao_ruou_gung': ('Bạch tuộc ướp rượu gừng và giấm, xào lửa lớn với riềng, gừng sợi, hành lá, thơm nồng ấm bụng.',
        ['Hành lá cắt khúc 3cm. Riềng, gừng, ớt sừng thái sợi. Ngâm gừng sợi với 4 muỗng canh rượu trắng 30 phút.', 'Chần bạch tuộc qua nước sôi có chút giấm gạo, cắt miếng vừa ăn.', 'Ướp bạch tuộc với 1,5 muỗng cà phê hạt nêm, 2 muỗng cà phê đường, 1/2 muỗng cà phê tiêu, 1 muỗng canh rượu ngâm gừng, 1,5 muỗng canh giấm gạo và 1,5 muỗng canh nước tương.', 'Phi thơm riềng và gừng sợi với dầu, cho bạch tuộc vào xào lửa lớn đến khi vừa chín. Thêm hành lá, ớt sợi, đảo đều rồi tắt bếp.', 'Múc ra dĩa, rắc tiêu, trang trí ngò rí, chấm nước tương với ớt.', 'Mẹo: Chần giúp bạch tuộc sạch, săn, dễ cắt; ướp rượu để khử mùi và thêm hương.']),
    'banh_canh_ca_loc': ('Bánh canh bột gạo nấu nước dùng xương gà, tôm khô, củ cải, thả cá lóc phi lê ướp gia vị, ăn kèm rau đắng.',
        ['Củ cải và cà rốt tỉa hoa, thái lát dày 3 ly. Ớt sừng thái lát, hành ngò cắt nhỏ.', 'Cắt riêng đầu cá; phần thân lọc phi lê, thái lát mỏng 4 ly. Chần xương cá cùng xương gà để nấu nước dùng.', 'Nấu xương gà với 2,5 lít nước, tôm khô rang, hành tím và gừng nướng khoảng 30 phút. Cho củ cải, cà rốt vào nấu thêm 30 phút rồi vớt xương gà ra.', 'Trộn 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 1 muỗng canh hành tỏi phi; dùng một nửa ướp đầu cá, nửa còn lại ướp phi lê.', 'Đun sôi lại nước dùng, thả đầu và đuôi cá vào, nêm 1 muỗng cà phê bột ngọt, 1 muỗng canh hạt nêm, 1 muỗng cà phê muối, 1 muỗng canh đường. Cá chín thì vớt ra.', 'Cho bánh canh vào nấu vừa mềm, thả phi lê cá vào nấu chín, thêm hành ngò, hành tỏi phi rồi tắt bếp.', 'Lót giá, rau đắng, rau má vào tô, múc bánh canh lên, rắc hành tỏi phi, gừng sợi, hành ngò. Ăn kèm ớt băm, chanh, nước mắm. Mẹo: ướp cá trước cho đậm vị; nấu bánh canh vừa mềm, đừng để bở.']),
    'dau_bap_kho_nuoc_tuong': ('Đậu bắp chiên săn kho nồi đất với bắp non, chả lụa chay, sả và nước dừa, nêm nước tương, mặn ngọt sánh.',
        ['Cắt chả lụa chay cỡ bằng bắp non. Đậu bắp bỏ cuống, để nguyên trái. Sả cắt khúc 4cm, đập dập. Boa-rô thái lát. Ớt sừng cắt khúc xéo, ớt hiểm đập dập.', 'Đun nóng 2 muỗng canh dầu trong nồi đất, phi thơm boa-rô rồi vớt ra để riêng.', 'Chiên đậu bắp lửa vừa, thêm bắp non xào khoảng 2 phút, rồi cho sả và 1/2 chén nước dừa vào.', 'Nêm 1 muỗng canh đường, 2 muỗng canh nước tương, 1 muỗng cà phê hạt nêm chay, 1/3 muỗng canh bột ngọt; thêm ớt và chả lụa, đun liu riu đến khi nước cạn sánh, rau củ thấm vị thì tắt bếp.', 'Múc ra dĩa, rắc tiêu, boa-rô phi, ngò rí, ăn nóng với cơm.', 'Mẹo: Chọn đậu bắp non, trái nhỏ, xanh sáng, bẻ đuôi thấy giòn; chiên săn trước khi kho để đậu dai.']),
    'dau_bap_nhoi_cha_ca_chien': ('Đậu bắp khoét ruột nhồi chả cá thác lác quết hành thì là, nhúng bột chiên giòn, chấm xốt mayonnaise tương ớt.',
        ['Chẻ đôi đậu bắp, khoét bỏ ruột, ngâm nước muối loãng. Băm nhuyễn cọng hành lá và thì là.', 'Quết cá thác lác cho dẻo cùng 1 muỗng canh cọng hành, 1 muỗng canh thì là, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê nước mắm.', 'Nhồi cá vào đậu bắp, lăn qua một lớp bột khô. Pha 1/2 gói bột chiên giòn với nước theo hướng dẫn rồi áo đều quanh đậu bắp.', 'Đun dầu sôi, chiên đậu bắp lửa vừa đến khi vàng mặt ngoài, vớt ra dĩa.', 'Pha xốt: trộn 1 muỗng canh tương ớt với 2 muỗng canh xốt mayonnaise. Ăn kèm xà lách, cà chua.', 'Mẹo: Quết cá thật kỹ cho dai; ít cá thì quết trong chén bằng muỗng; tăng lửa lớn trước khi vớt để đậu ráo dầu.']),
    'dau_hu_don_tom_kho_chao': ('Đậu hũ chiên dồn nhân tôm và giò sống, kho với chao trắng và nước tương đến khi sệt, béo mặn đậm vị.',
        ['Đập dập tôm rồi băm nhuyễn, trộn với giò sống, ướp 1/2 muỗng cà phê hạt nêm, 1/3 muỗng cà phê bột ngọt, chút tiêu và hành lá cắt khúc. Ớt hiểm đập dập.', 'Cắt đôi đậu hũ, rạch nhẹ lấy bớt ruột, nhồi nhân vào rồi chiên sơ, để ráo.', 'Pha xốt kho: 1/2 nước pha với 1 muỗng canh đường, 3 viên chao trắng, 1/2 chén nước tương và 1/2 chén nước lọc.', 'Kho đậu hũ trong xốt cùng ớt đến khi nước sệt lại, nêm nếm vừa ăn, tắt bếp rồi thêm hành lá. Ăn với cơm trắng.', 'Mẹo: Tán nhỏ chao trước khi pha để xốt mịn; đập dập tôm trước khi băm cho nhân dai.']),
    'dau_hu_nuong_giay_bac': ('Đậu hũ non chiên bột kẹp rau củ, nấm linh chi, rưới xốt dầu hào và thịt cua, gói giấy bạc nướng lò.',
        ['Thái lát hành boa-rô và cà rốt.', 'Cắt đậu hũ miếng vuông 5cm, nhúng qua nửa gói bột chiên giòn pha với 60ml nước, chiên non rồi vớt ra để ráo.', 'Chần thịt cua trong nước có chút rượu trắng và 2 lát gừng đập dập, trộn với ít tiêu.', 'Làm xốt: phi thơm tỏi, cho 1 chén nước dùng, 2 muỗng cà phê dầu hào, 1/2 muỗng cà phê bột ngọt, 1/3 muỗng cà phê muối, nấu lửa nhỏ. Cho ít bột năng cho sánh rồi thêm 1 muỗng cà phê dầu mè.', 'Trải giấy bạc, xếp một lớp rau củ, một lớp đậu hũ, rồi thêm rau củ lên trên. Rưới xốt, rải thịt cua, gói kín và nướng lò 10 phút. Ăn nóng.', 'Mẹo: Áo bột giúp đậu ngoài hơi dai, trong mềm; lót rau củ quanh đậu để không dính giấy bạc.']),
    'dau_hu_xot_me_mayonnaise': ('Đậu hũ trắng chiên giòn phủ xốt mayonnaise nước tương mè rang và rau củ xào gừng, béo thơm.',
        ['Cà rốt thái sợi. Nấm mèo ngâm nở, thái sợi. Hẹ cắt khúc 5cm. Rang vàng mè trắng rồi giã dập. Ớt hiểm bỏ hạt, băm nhỏ.', 'Lăn đậu hũ qua bột tẩm khô chiên giòn, chiên vàng, vớt ra để ráo.', 'Phi thơm gừng và ớt, xào cà rốt, nấm mèo, nêm 1/2 muỗng cà phê hạt nêm, 1/3 muỗng cà phê tiêu. Tắt bếp rồi cho hẹ vào đảo đều.', 'Pha xốt: 2 muỗng canh xốt mayonnaise, 1 muỗng canh nước tương và 2/3 lượng mè rang.', 'Cắt mỗi miếng đậu làm 3, xếp ra dĩa, rưới xốt, phủ rau củ xào, rắc mè còn lại, ngò rí, ớt sợi. Ăn nóng với cơm.', 'Mẹo: Làm sạch mè trước khi rang để không lẫn sạn; chọn đậu hũ trắng, mịn và mềm.']),
    'dau_hu_xot_nam': ('Đậu hũ chiên rưới xốt năm loại nấm xào bơ, nêm nước tương, dầu mè, sánh nhẹ.',
        ['Cắt đậu hũ miếng vừa ăn, chiên sơ lại. Rửa sạch các loại nấm, cắt nhỏ. Băm nhỏ ớt và boa-rô.', 'Đun nóng 1 muỗng canh bơ, phi thơm boa-rô, cho nấm và ớt băm vào xào.', 'Nêm 1 muỗng cà phê bột ngọt, 1 muỗng canh nước tương, 1 muỗng cà phê dầu mè. Nấm vừa chín thì thêm 3 muỗng cà phê nước lọc và nước bột năng.', 'Rưới xốt nấm lên đậu hũ, thêm ớt, hành lá, ăn nóng với cơm.', 'Mẹo: Dùng bơ cho món thơm hơn; không xào nấm quá lâu kẻo mất giòn ngọt và ra nhiều nước.']),
    'dau_rong_xao_trung': ('Đậu rồng xào cà rốt cùng cật heo ướp hành tỏi, đảo thêm lòng đỏ trứng vịt, giòn ngọt.',
        ['Đậu rồng nhặt rửa, cắt xéo. Cà rốt thái sợi dài 4cm. Hành lá, ngò rí cắt nhỏ. Đánh tan lòng đỏ trứng vịt với ít tiêu.', 'Làm sạch cật heo, khứa ca rô rồi cắt miếng dày 2cm, ướp 1/2 muỗng canh hạt nêm, 1/4 muỗng canh tiêu, 1 muỗng canh hành tỏi băm cho thấm.', 'Phi thơm 1 muỗng canh hành tỏi, xào cật với 1 muỗng canh rượu trắng và chút nước đến khi vừa chín, trút ra dĩa.', 'Thêm 1 muỗng canh dầu, phi hành tỏi, xào đậu rồng và cà rốt, nêm 1 muỗng canh hạt nêm. Rau vừa chín thì cho cật vào, đổ lòng đỏ trứng và chút nước, đảo đến khi trứng chín rồi tắt bếp.', 'Múc ra dĩa, rắc hành ngò, tiêu; chấm nước tương với ớt lát.', 'Mẹo: Chọn đậu rồng non, xanh sáng, rìa nhiều nếp, trái thẳng; rửa cật qua rượu trắng để khử mùi.']),
    'dau_tron_dau_giam_xot_me_rang': ('Đậu trắng, đậu gà, bắp, hành tây, cà chua trộn ức gà áp chảo cắt hạt lựu, rưới xốt mè rang thanh nhẹ.',
        ['Rửa sạch đậu trắng, đậu gà, bắp hạt, để ráo. Ngò rí cắt nhỏ.', 'Cho đậu, bắp và hành tây vào thau, ướp 1 muỗng cà phê muối rồi chắt ráo nước.', 'Ướp ức gà với 1/2 muỗng cà phê muối và chút tiêu, áp chảo hai mặt với 1 muỗng canh dầu ô liu. Để nguội rồi cắt hạt lựu.', 'Trộn đều tất cả nguyên liệu, cho ra dĩa. Rưới 2 muỗng canh xốt mè rang lên, khi ăn trộn đều.', 'Mẹo: Chỉ ướp trước đậu, bắp, hành cho món thấm dịu; ngâm hành tây trong nước để bớt hăng.']),
    'banh_mi_xiu_mai': ('Xíu mại thịt xay giò sống củ sắn hấp chín rồi nấu trong xốt cà chua, ăn với bánh mì, dưa leo, ngò.',
        ['Củ sắn gọt vỏ, thái sợi, luộc chín, để nguội rồi vắt ráo, cắt ngắn. Hành lá cắt nhỏ, đầu hành đập dập băm nhỏ. Cà chua bỏ hạt, băm nhuyễn.', 'Trộn thịt xay, giò sống, củ sắn, 2 muỗng cà phê cọng ngò băm, 2 muỗng canh hành tây băm, hành phi, đầu hành, hành lá, trứng và 1 muỗng canh bột năng. Nêm 1/2 muỗng cà phê muối, 1 muỗng cà phê đường, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê nước tương, 1/2 muỗng cà phê tiêu, quết dẻo rồi để tủ lạnh 15 phút.', 'Vo viên cỡ trái tắc, xếp vào xửng hấp 10 phút tính từ khi nước sôi.', 'Làm xốt: phi thơm đầu hành và 1 muỗng canh hành tây băm với dầu điều, xào chín cà chua, thêm 2 muỗng canh tương cà, 1 chén nước, nêm 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê muối, 1 muỗng cà phê nước tương. Nấu nhỏ lửa đến khi cà nhừ.', 'Cho xíu mại vào xốt nấu 5 phút, thêm 1 muỗng cà phê bột năng hòa nước và 1/2 muỗng cà phê dầu mè.', 'Chia xíu mại ra chén, rắc ngò, ăn cùng bánh mì, dưa leo, ớt sừng, chấm nước tương.', 'Mẹo: Hành phi trong nhân giúp xíu mại thơm; dùng nước hấp xíu mại nấu xốt cho ngọt hơn.']),
    'bao_tu_ca_basa_chien_xot_me': ('Bao tử cá basa ướp ớt bột, tẩm bột chiên giòn, rưới xốt me chua ngọt cay, ăn kèm cải mầm và cà rốt.',
        ['Chần bao tử cá qua nước sôi, để ráo, ướp 2 muỗng canh nước cốt hành tỏi, 1 muỗng canh ớt bột, 1 muỗng canh nước mắm, 1 muỗng cà phê tiêu trong 15 phút.', 'Làm xốt me: cho 100g nước me, 1/2 muỗng cà phê bột ngọt, 3 muỗng canh đường, 1 muỗng canh tương ớt, 1,5 muỗng canh nước mắm vào chảo nhỏ, nấu lửa nhỏ đến khi trong và sánh. Tắt bếp, thêm 1 muỗng canh xốt mận, 1 muỗng canh ớt băm, 1 muỗng canh tỏi phi.', 'Để riêng 2 muỗng canh bột chiên giòn khô, phần còn lại pha nước cho sánh vừa.', 'Lăn bao tử cá qua bột khô, nhúng bột ướt rồi chiên vàng, vớt ra để ráo.', 'Lót cải mầm, cà rốt sợi ra dĩa, xếp cá lên, rưới xốt me, rắc rau răm và mè rang. Ăn với cơm.', 'Mẹo: Chần bao tử cho giòn; lớp bột khô giúp bột ướt bám chắc.']),
    'bao_tu_ca_basa_xao_bac_ha': ('Bao tử cá basa ướp nghệ xào lửa lớn với bạc hà, nghệ tươi, ớt, rau om, ngò gai và đậu phộng.',
        ['Bạc hà tước vỏ, thái xéo mỏng, bóp muối rồi vắt ráo. Nghệ thái lát mỏng. Rau om, ngò gai cắt khúc. Ớt hiểm đập dập.', 'Làm sạch bao tử cá, để ráo, ướp 1 muỗng canh hành tỏi băm, 1/2 muỗng canh bột nghệ, 1 muỗng canh bột ngọt, 1/2 muỗng canh tiêu, 1/3 muỗng canh nước mắm, 1 muỗng canh hạt nêm.', 'Phi thơm hành tỏi, xào bao tử cá lửa lớn đến khi săn.', 'Cho ớt, nghệ lát và bạc hà vào xào khoảng 2 phút rồi tắt bếp. Trộn thêm rau om, ngò gai, đậu phộng.', 'Múc ra dĩa, trang trí rau om.', 'Mẹo: Bột nghệ cho màu vàng tươi và mùi thơm nhẹ; xào lửa lớn để bao tử săn và thơm.']),
    'bao_tu_ca_kho_tieu': ('Bao tử cá basa kho cùng ba rọi, tiêu đen, ớt hiểm, nước dừa và nước tương đến sánh, cay nồng đưa cơm.',
        ['Bóp bao tử cá với ít muối và giấm gạo, rửa sạch, để ráo.', 'Ba rọi thái miếng dày 2mm, bản 2cm. Ớt hiểm đập dập. Hành lá cắt khúc 3cm, để riêng đầu và lá.', 'Xào ba rọi với 2 muỗng canh dầu điều cho ra mỡ. Cho đầu hành, ớt, tiêu vào xào thơm, thêm bao tử cá xào săn.', 'Nêm 4 muỗng canh nước tương, 1 muỗng cà phê đường, 1 muỗng cà phê bột ngọt, 2/3 muỗng cà phê nước màu. Rót từ từ nước dừa vào kho đến khi bao tử và thịt thấm, nước sánh lại. Tắt bếp, thêm hành lá.', 'Ăn với cơm và rau ghém.', 'Mẹo: Nước tương và nước dừa giúp món lên màu đẹp; xào săn bao tử trước khi kho để giữ độ giòn.']),
    'bao_tu_khia_tieu_xanh': ('Bao tử heo ướp ngũ vị, xào tiêu xanh rồi hầm áp suất với nước dừa xiêm, mềm, ngọt thanh, thơm tiêu.',
        ['Áp chảo bao tử heo, cạo sạch nhớt, rửa lại bằng nước muối, để ráo rồi cắt đôi.', 'Ướp bao tử với 1 muỗng canh tỏi băm, 1/4 muỗng cà phê ngũ vị hương, 1 muỗng cà phê tiêu sọ, 2 muỗng cà phê hạt nêm, 1 muỗng canh đường. Lấy nước dừa; tiêu xanh đập dập.', 'Phi thơm tỏi, xào thơm bao tử, thêm màu hạt điều và tiêu xanh trộn đều.', 'Cho nước dừa vào nồi, thêm nước cho đủ 700ml, nêm 1 muỗng cà phê hạt nêm, cho bao tử vào nấu nồi áp suất 15 phút đến khi mềm.', 'Thái bao tử miếng vừa ăn, xếp ra dĩa, ăn với bánh mì hoặc cơm.', 'Mẹo: Nước dừa xiêm cho vị ngọt thanh; đập dập tiêu xanh trước khi nấu để thơm hơn.']),
    'bao_tu_kho_dua_cai_trung_cut': ('Bao tử heo xào săn rồi kho cùng dưa cải, trứng cút và nước dừa trong nồi áp suất, vị mặn ngọt hơi cay.',
        ['Làm sạch bao tử, cắt miếng 3x4cm, ướp với 1/2 muỗng canh nước tương, 1/2 muỗng canh hành tỏi băm, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê đường, 1/2 muỗng cà phê hạt nêm.', 'Cắt dưa cải miếng 3x4cm. Luộc trứng cút, bóc vỏ. Chặt dừa lấy nước. Đập dập ớt hiểm, cắt lát ớt sừng, cắt khúc hành ngò.', 'Trong nồi áp suất, phi 1 muỗng canh hành tỏi băm với 2 muỗng canh dầu ăn, cho bao tử vào xào lửa lớn đến khi săn. Thêm dưa cải, xào chung 2 phút.', 'Cho 4 muỗng canh nước tương, 2 chén nước dừa, trứng cút, ớt hiểm và 1 muỗng canh dầu điều vào, đậy nắp kho đến khi bao tử, dưa cải mềm và trứng thấm. Thêm hành ngò rồi tắt bếp.', 'Múc ra dĩa, rắc ớt cắt lát và tiêu, ăn cùng cơm.', 'Mẹo: Lộn trái bao tử, chà muối với giấm (hoặc phèn chua) 2 lần, rửa sạch rồi áp chảo mặt trong đến khi nổi màng trắng và rửa bỏ màng này. Xào trước khi kho giúp bao tử giòn và thơm.']),
    'bao_tu_kho_xot_cay': ('Bao tử heo ướp cay, xào với gừng và hoa xuyên tiêu rồi kho nước dừa đến sệt, vị cay tê đậm đà.',
        ['Rửa sạch bao tử, để ráo, cắt miếng vừa ăn. Ướp với 2 muỗng cà phê bột ngọt, 1 muỗng cà phê tiêu sọ bể, 2 muỗng canh đường, 1 muỗng canh dầu hào, 1 muỗng canh giấm gạo, 2 muỗng canh ớt hiểm băm, 3 muỗng canh nước tương; trộn đều, để 20 phút.', 'Đập dập hành tím và tỏi.', 'Đun nóng dầu, phi thơm tỏi, hành tím và gừng băm, thêm hoa xuyên tiêu. Cho bao tử vào xào đến khi săn và rám mặt.', 'Rót nước dừa vào từ từ, kho lửa vừa đến khi bao tử mềm và nước sánh lại. Thêm dầu điều, đảo đều, tắt bếp rồi cho đầu hành lá vào.', 'Múc ra dĩa, rắc hành lá cắt nhỏ, ăn nóng với cơm trắng.', 'Mẹo: Xào rám mặt bao tử cho thơm; đổ nước dừa từ từ khi kho để bao tử mềm mà vẫn giòn.']),
    'bao_tu_xao_dong_co': ('Bao tử heo luộc mềm xào với nấm đông cô, cà rốt, cần tây, hành tây, sốt hơi sánh, vị mặn ngọt thơm gừng.',
        ['Rửa sạch bao tử, cạo bỏ nhớt, luộc chín mềm, để ráo rồi cắt miếng tam giác. Ướp với 1 muỗng cà phê tỏi băm, 1 muỗng cà phê gừng xắt sợi, 2 muỗng canh nước tương, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê đường, chút dầu mè, 1,5 muỗng cà phê hạt nêm.', 'Ngâm nở nấm đông cô, luộc trong nước có 1 muỗng cà phê hạt nêm. Cà rốt cắt lát tỉa hoa, chần sơ cùng nấm, rồi ngâm cả hai vào nước lạnh.', 'Cắt khúc cần tây, cắt múi cau hành tây, xắt khoanh ớt, xắt sợi gừng. Hòa 1 muỗng canh bột năng với ít nước.', 'Phi thơm tỏi, cho bao tử và nấm vào xào, thêm gừng sợi và cà rốt đảo đều. Đổ nước bột năng vào khuấy, rồi cho cần tây, hành tây, ớt, gừng và 1 muỗng cà phê dầu mè, đảo đều và tắt bếp.', 'Bày ra dĩa, ăn nóng với cơm, chấm thêm nước tương nếu thích.', 'Mẹo: Luộc nấm đông cô với chút hạt nêm cho nấm đậm vị hơn.']),
    'bap_bo_kho_chua_ngot': ('Bắp bò hầm mềm trong nước dừa với sả, nêm chao, giấm và đường, rắc đậu phộng và rau răm, vị chua ngọt béo.',
        ['Cắt bắp bò khối vuông 4cm, ướp với 1/2 muỗng cà phê muối, 1/3 muỗng cà phê tiêu, 1 muỗng cà phê tỏi trong 30 phút.', 'Cắt nhuyễn rau răm. Đập dập sả, cắt khúc. Giã nhuyễn đậu phộng.', 'Cho thịt và sả vào nồi nước dừa, nấu đến khi thịt thật mềm (nồi áp suất khoảng 20 phút).', 'Thêm chao, 2 muỗng cà phê gừng băm, 1 muỗng canh đường, 2 muỗng canh giấm gạo, đậu phộng và ớt băm, nấu sôi rồi tắt bếp, cho rau răm vào.', 'Múc thịt ra dĩa, rắc rau răm và đậu phộng lên trên, ăn nóng.', 'Mẹo: Nước dừa cho vị ngọt tự nhiên, chao tạo mùi riêng; tắt bếp rồi mới thả rau răm để giữ màu và mùi thơm.']),
    'bap_bo_kho_thom': ('Bắp bò kho nước dừa với thơm, củ sen, cà chua bi, thoảng mùi hồi quế, vị mặn ngọt chua nhẹ.',
        ['Chần nhanh bắp bò trong nước sôi có rượu trắng và ít gừng sợi, vớt ra cắt miếng 4x3cm. Ướp với 1 muỗng cà phê bột ngọt, 1,5 muỗng cà phê muối, 1,5 muỗng canh đường, 2 muỗng canh nước tương, 1 muỗng canh rượu trắng, 1 muỗng canh tỏi băm, 1 muỗng cà phê ớt bột.', 'Cắt củ sen lát dày 7 li, ngâm nước muối. Cắt thơm rẻ quạt, khứa chữ thập cà chua bi, đập dập và cắt khúc sả. Rang thơm hoa hồi, quế chi.', 'Đun nóng dầu điều trong nồi áp suất, phi 1 muỗng canh gừng sợi, cho bò vào xào săn rồi đổ nước dừa vào kho 15 phút.', 'Mở nắp, thêm củ sen và hành tím kho 5 phút. Cho ớt sừng, thơm vào kho không đậy nắp khoảng 10 phút, sau cùng thêm cà chua bi kho 5 phút, nêm lại rồi tắt bếp.', 'Bày ra đĩa, rắc tiêu và ngò rí, ăn với cơm nóng.', 'Mẹo: Chần bò trước khi cắt giúp miếng thịt giữ dáng; kho cùng thơm giúp bò mau mềm và thơm hơn.']),
    'bap_bo_ngam_giam': ('Bắp bò luộc nước dừa với gia vị thơm, ngâm giấm đường phèn ba ngày, thái mỏng cuốn bánh tráng, vị chua ngọt thanh.',
        ['Rang thơm quế chi và đinh hương. Đập dập gừng, hành tím rồi nướng áp chảo. Băm nhỏ đường phèn.', 'Rửa bắp bò, lạng bớt gân và mỡ thừa, luộc trong nước dừa nêm 1 muỗng cà phê hạt nêm khoảng 1 tiếng, rồi thả tỏi, quế chi, gừng, hành tím vào. Khi bò mềm, vớt ra ngâm ngay vào nước lạnh cho nguội hẳn.', 'Nấu sôi 300ml giấm gạo với 300g đường phèn và 1 muỗng cà phê muối đến khi đường tan, tắt bếp để nguội.', 'Xếp bắp bò, ớt hiểm và tỏi vào hũ, đổ nước giấm đường vào, ngâm khoảng 3 ngày là ăn được.', 'Thái bò lát mỏng, bày ra dĩa, ăn với bánh tráng, bún, rau sống và nước mắm chua ngọt.', 'Mẹo: Luộc bò thật mềm thì khi ngâm mau thấm; đường phèn cho nước ngâm vị ngọt dịu.']),
    'bap_bo_nhung_mam_ruoc': ('Bắp bò thái mỏng nhúng nồi nước dùng mắm ruốc kiểu bún bò, ăn với bún, mồng tơi, mướp và nấm.',
        ['Thái bắp bò lát mỏng, xếp ra đĩa. Gọt vỏ mướp, cắt miếng vừa ăn. Nhặt lá mồng tơi, rửa sạch. Cắt gốc nấm linh chi, rửa sạch.', 'Phi thơm 1 muỗng canh hành tím băm với 1 muỗng canh dầu ăn, đổ 1,5 lít nước và 1 muỗng cà phê mắm ruốc vào, nấu sôi và hớt bọt.', 'Nêm 2 muỗng cà phê đường, 1/2 muỗng cà phê bột ngọt, 4 muỗng canh gia vị nêm sẵn bún bò Huế, 1 muỗng canh dầu điều, nấu sôi cho tan. Tắt bếp, thêm hành lá, ớt sừng và tiêu.', 'Dọn bắp bò, rau và nồi nước nhúng ra bàn, ăn kèm bún.', 'Mẹo: Cho mắm ruốc vào lúc nước còn nguội để nước dùng không bị nồng.']),
    'bap_bo_xao_dau_rong': ('Bắp bò xào tái lửa lớn đặt trên đậu rồng xào thơm, cà chua, ngò om, rắc mè rang, vị ngọt thơm lạ miệng.',
        ['Ướp bắp bò với 1 muỗng cà phê hạt nêm, 1/4 muỗng cà phê tiêu, 1/4 muỗng cà phê bột ngọt, 1 muỗng cà phê bột năng và ít nước, trộn đều để 5 phút.', 'Phi vàng tỏi với 2 muỗng canh dầu, múc riêng ra một nửa dầu tỏi.', 'Cho đậu rồng, thơm, cà chua, hành tây và 3 muỗng canh nước vào chảo, nêm 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt, 1/4 muỗng cà phê tiêu, 1/2 muỗng cà phê đường, 1/2 muỗng canh nước bột năng, 1 muỗng cà phê nước mắm. Xào nhanh lửa lớn, thêm ngò om và ớt sừng rồi trút ra dĩa.', 'Đun nóng phần dầu tỏi còn lại, xào bò nhanh tay lửa lớn đến khi chín tái, rưới 1 muỗng canh rượu trắng cho thơm.', 'Đặt bò lên dĩa đậu rồng, xếp lá húng lủi quanh dĩa và rắc mè rang.', 'Mẹo: Ướp bò với bột năng để thịt không khô; thơm và ngò om tạo mùi thơm mới cho món xào.']),
    'bap_bo_xao_sa_ot_com_chay': ('Bắp bò thái mỏng ướp cà ri, xào sả ớt lửa lớn, ăn kèm cơm cháy giòn rưới mỡ hành, vị cay thơm.',
        ['Để bắp bò vào ngăn đá 15 phút rồi thái mỏng. Ướp với 1/3 muỗng cà phê ngũ vị hương, 1/3 muỗng cà phê bột cà ri, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng canh hạt nêm, 1 muỗng canh dầu điều, 1 muỗng canh sả băm, 1 muỗng canh tỏi băm.', 'Làm cơm cháy: đun 1 muỗng cà phê dầu, dàn mỏng cơm và ép nhẹ cho dính, chiên vàng một mặt rồi lật mặt kia, phết mỡ hành lên.', 'Đun nóng dầu, chiên sả bào đến vàng giòn, vớt ra. Phi thơm ớt, tỏi, sả băm.', 'Cho bò vào xào nhanh lửa lớn đến khi vừa chín, nêm lại cho vừa, thêm sả chiên, đầu hành lá và ớt sừng sợi, đảo đều rồi tắt bếp.', 'Bày bò ra dĩa, rắc tiêu, ăn với cơm cháy.', 'Mẹo: Làm cơm cháy khi cơm còn nóng cho dễ kết dính; xào bò lửa lớn để thịt không dai và không ra nước.']),
    'bap_bo_xao_xot_tieu_xanh': ('Bắp bò thái mỏng xào nhanh với tiêu xanh, ớt chuông, thơm và cần tây, nêm dầu hào, vị cay thơm mặn ngọt.',
        ['Thái mỏng bắp bò, ướp với 1 muỗng canh dầu ăn, 1 muỗng canh dầu hào, 1 muỗng canh nước tương trong 10 phút.', 'Đập dập tiêu xanh. Cắt ớt chuông hình thoi, thơm rẻ quạt, cần tây cắt xéo, hành lá cắt khúc, hành tím cắt đôi.', 'Đun nóng dầu, xào tiêu xanh, ớt chuông, thơm, cần tây, hành tím đến vừa chín, thêm hành lá đảo đều rồi trút ra.', 'Phi thơm tỏi, xào nhanh bắp bò, cho rau đã xào vào lại. Nêm 1 muỗng canh dầu điều, 1 muỗng canh bột ngọt, 1 muỗng canh nước tương, 1 muỗng canh dầu hào, đảo đều.', 'Trút ra dĩa, rắc tiêu sọ, ăn nóng với cơm trắng.', 'Mẹo: Dùng bắp rùa cho thịt giòn; xào rau trước để món không bị ra nước.']),
    'bap_cai_cuon_thit_kho_bo': ('Lá bắp cải cuộn nhân bò xay, tép mỡ, nấm mèo, áp chảo rồi om với nước mắm và bơ, vị béo mặn ngọt.',
        ['Tách lá bắp cải, cắt bỏ phần cọng cứng, chần sơ qua nước sôi. Cắt nhỏ hành lá, ngò rí.', 'Làm nhân: trộn bò xay, tép mỡ, cà rốt, nấm mèo, đầu hành lá, ngò rí, hành tím băm; nêm 1 muỗng cà phê hạt nêm, 1 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, ít tiêu, thêm 1 trứng vịt đánh tan, trộn đều.', 'Trải lá bắp cải, cho 1 muỗng canh nhân vào, gập hai đầu và cuộn tròn chặt tay.', 'Đun nóng dầu, áp chảo sơ các cuộn. Cho 1/2 chén nước, 1 muỗng canh nước mắm, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê đường vào chảo, om lửa nhỏ khoảng 10 phút.', 'Thêm bơ vào cho chảy, nấu tiếp 5 phút rồi tắt bếp, rắc hành lá, ngò rí. Bày ra dĩa ăn với cơm.', 'Mẹo: Trộn tép mỡ vào nhân cho béo; cuộn đều và chặt tay để cuộn đẹp, không bung.']),
    'bap_cai_tim_xao_hai_san': ('Tôm và mực xào nhanh cùng bắp cải tím, giá, cà chua, hành tây và cần, vị ngọt giòn thanh.',
        ['Bóc vỏ tôm, bỏ đầu và chỉ lưng, chừa đuôi, rửa qua nước pha 1/2 muỗng cà phê muối. Làm sạch mực, cắt sợi vừa ăn.', 'Ướp tôm, mực với 1 muỗng canh hạt nêm, 1/2 muỗng canh tiêu, 1 muỗng canh bột năng.', 'Xắt sợi bắp cải tím, hành tây sợi 0,5cm, cà chua bỏ ruột cắt sợi 3cm, ớt cắt lát, đập dập tỏi.', 'Phi thơm tỏi, xào hải sản nhanh lửa lớn, thêm chút rượu và ít nước. Khi hải sản săn, cho hành tây vào đảo đều rồi múc ra.', 'Xào giá với 1/2 muỗng cà phê tiêu, rồi xào bắp cải tím với 1/2 muỗng cà phê muối, tiêu, đường và chút nước, thêm cà chua. Cho hải sản và giá vào lại đảo đều, tắt bếp, thêm cần và chút giấm gạo. Ăn với cơm nóng.', 'Mẹo: Ướp hải sản với bột năng để giữ nước ngọt khi xào.']),
    'bap_non_xao_muc_cay': ('Mực khía caro xào lửa lớn với bắp non, cà rốt, sa tế và tương ớt, vị cay ngọt giòn.',
        ['Bỏ ruột mực, khía caro mặt thịt, cắt miếng 4cm. Ướp với 1 muỗng canh hạt nêm, 1 muỗng cà phê nước mắm, 1/2 muỗng canh hành tỏi băm, 1 muỗng canh sa tế.', 'Cắt xéo bắp non, cà rốt cắt que 4cm, hành lá cắt khúc, ớt hiểm đập dập. Chần bắp non và cà rốt trong nước có 1/2 muỗng canh muối, thả vào nước lạnh rồi để ráo.', 'Pha hỗn hợp xào: 1 muỗng canh đường, 1 muỗng canh bột ngọt, 1 muỗng canh tương ớt, 1 muỗng canh nước mắm.', 'Phi thơm gừng, ớt hiểm và 1 muỗng canh hành tỏi băm với 2–3 muỗng canh dầu. Xào mực vừa săn, cho bắp non, cà rốt vào, rồi đổ hỗn hợp xào, đảo đều tay. Thêm ớt sừng băm, ớt sừng cắt quả trám và hành lá.', 'Bày ra đĩa, rắc ngò rí và tiêu, ăn với cơm nóng.', 'Mẹo: Chần bắp non, cà rốt cho xào nhanh và giữ màu; xào mực lửa lớn để mực không dai, không ra nước.']),
    'bap_xao_ngu_sac': ('Hạt bắp Mỹ xào với tôm khô, đậu cô ve, nấm mèo, thêm bơ và hành lá, vị ngọt béo nhiều màu.',
        ['Lột vỏ bắp, bẻ đôi, dựng đứng trên thớt và dùng dao cắt dọc lấy hạt. Tước xơ đậu cô ve, cắt hạt lựu.', 'Ngâm mềm tôm khô. Ngâm mềm nấm mèo, cắt nhỏ. Băm đầu hành trắng, cắt nhỏ phần lá. Rửa ngò rí, để ráo.', 'Phi thơm đầu hành, cho tôm khô vào xào chín, thêm bắp, đậu cô ve và nấm mèo, nêm 1 muỗng cà phê hạt nêm; nếu khô thì thêm khoảng 2 muỗng canh nước.', 'Khi rau củ chín, cho hành lá và 1 muỗng cà phê bơ vào đảo đều.', 'Múc ra dĩa, rắc ngò rí, ăn nóng.', 'Mẹo: Cắt hạt bằng dao để bỏ phần mày cứng; dùng bắp Mỹ cho ngọt giòn, nếu dùng bắp nếp thì luộc qua trước. Xào tôm khô với dầu từ đầu cho thơm và hết tanh.']),
    'be_chao': ('Thịt bê ướp sả gừng chiên vàng, trộn lá chanh, rắc sả gừng giòn, chấm xốt tương bần chua ngọt.',
        ['Băm nhuyễn 2 cây sả, 2 cây còn lại thái lát mỏng. Nửa củ gừng băm, nửa cắt sợi. Cắt sợi lá chanh.', 'Cắt thịt bê thành cọng nhỏ, ướp với 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê nước mắm, 1 muỗng canh sả băm, 1 muỗng canh gừng băm.', 'Đun nóng dầu, chiên vàng giòn gừng sợi và sả lát, vớt ra. Chiên thịt bê đến khi chín vàng, vớt ráo dầu, trộn ngay với 1/3 lượng lá chanh.', 'Làm xốt: phi thơm 1 muỗng cà phê mỗi loại tỏi băm, sả băm, ớt băm; thêm 1/3 chén nước, 1 muỗng cà phê giấm gạo, 1 muỗng canh tương bần, 1 muỗng cà phê đường, đun sôi rồi hạ lửa, cho 1 muỗng canh nước bột năng vào cho hơi sánh, tắt bếp.', 'Bày thịt ra dĩa, rắc lá chanh, sả gừng chiên lên, kèm dưa leo và rau om, chấm với xốt tương bần.', 'Mẹo: Chiên thịt khi dầu thật nóng và chiên nhanh để thịt không dai, không ngấm dầu; trộn lá chanh lúc thịt còn nóng cho thơm.']),
    'be_hap_bia': ('Thịt bê thui ướp sả, hấp nhanh với bia và đầu hành, rắc mè rang, chấm nước tương gừng chua cay.',
        ['Thái lát bê thui, ướp với 1/2 muỗng cà phê tiêu, 1 muỗng cà phê hạt nêm, 2 muỗng canh dầu ăn, sả bào và nước bột năng trong 10 phút. Băm nhuyễn gừng chua.', 'Pha nước chấm: hòa 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê đường, 1 muỗng canh giấm gạo, 2 muỗng canh tương ớt, 4 muỗng canh nước tương, 2 muỗng canh gừng chua băm.', 'Cho bê vào chảo, xếp đầu hành lên trên, đổ bia vào, đậy nắp hấp khoảng 5 phút đến khi thịt chín, rắc hành tây và ớt lên.', 'Bày ra dĩa, rắc mè rang, chấm với nước tương gừng và ăn cùng rau thơm, khế, chuối chát.', 'Mẹo: Ướp chút nước bột năng giữ ngọt thịt; hấp bằng bia cho thịt mềm và thơm.']),
    'be_thau': ('Bê thui thái mỏng trộn khế, chuối chát, kiệu, rau răm với nước trộn chua ngọt, rắc mè, ăn kèm bánh tráng.',
        ['Cắt bê thui miếng 2x5cm dày 2mm, kiệu cắt lát mỏng 2mm. Chuối chát bào vỏ, cắt lát xéo dày 2mm, ngâm nước pha cốt chanh cho trắng rồi để ráo.', 'Khế bỏ hạt, cắt lát xéo 2x5cm dày 2mm, dùng khăn sạch vắt nhẹ bớt nước chua.', 'Phi vàng tỏi trong dầu, cho bê vào, nêm 1 muỗng cà phê bột ngọt, 1/2 muỗng cà phê muối, trộn đều.', 'Pha nước trộn: 2 muỗng canh đường, 3 muỗng canh giấm gạo, 2 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 1 muỗng canh tỏi ớt băm, 1 muỗng cà phê nước mắm, 1 muỗng canh nước cốt chanh.', 'Trộn nhẹ tay các nguyên liệu với nước trộn, rau răm cắt nhỏ, thêm 1 muỗng canh nước cốt chanh và 1 muỗng cà phê nước mắm. Bày ra đĩa, rắc mè, trang trí khế và ớt sợi, ăn với bánh tráng nướng.', 'Mẹo: Vắt bớt nước khế cho vị chua ngọt cân bằng; trộn bê với tỏi phi khi còn nóng để thấm và không ra nước.']),
    'be_thui_xao_sa_te': ('Bê thui thái mỏng xào nhanh lửa lớn với ớt chuông, hành tây và sa tế, rắc mè, ngò, vị cay thơm.',
        ['Cắt ớt chuông và hành tây miếng vuông 3cm, cắt nhỏ ngò rí.', 'Thái bê lát mỏng 3mm, ướp với 1 muỗng cà phê hạt nêm, 1 muỗng cà phê tỏi băm, 1/3 muỗng cà phê tiêu.', 'Phi thơm hành tỏi, xào ớt chuông và hành tây, rồi cho bê vào xóc nhanh tay trên lửa lớn, nêm 1/2 muỗng canh sa tế, đảo đều và tắt bếp.', 'Bày ra dĩa, rắc mè và ngò rí, ăn nóng với cơm, chấm nước tương.', 'Mẹo: Chọn bê da mỏng, phần mông hoặc đùi; không xào lâu kẻo thịt dai.']),
    'bi_ngoi_hap_xot_nam': ('Khoanh bí ngòi nhồi chả cá thác lác và trứng cút, hấp chín rồi rưới xốt nấm dầu hào, vị ngọt thanh.',
        ['Cắt bí ngòi khúc 2,5cm, bỏ ruột. Ngâm nở nấm hương, một nửa cắt hạt lựu, nửa còn lại cắt sợi. Cắt đôi nấm linh chi. Luộc trứng cút, bóc vỏ. Cắt nhỏ hành lá.', 'Trộn cá thác lác với nấm hương hạt lựu, hành lá, 1/3 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, ít tiêu.', 'Rắc chút bột năng khô vào lòng bí, nhồi nhân vào, ấn một quả trứng cút lên trên. Hấp cách thủy 15 phút tính từ khi nước sôi, giữ lại nước trong dĩa.', 'Làm xốt: phi thơm tỏi, xào chín hai loại nấm, nêm 1,5 muỗng canh dầu hào, 1/2 muỗng cà phê bột ngọt, ít tiêu, thêm 1/2 chén nước hấp bí, đun sôi. Cho 1/2 muỗng cà phê ớt sừng băm và ít nước bột năng cho sánh.', 'Xếp bí ra đĩa, rưới xốt nấm lên, ăn nóng.', 'Mẹo: Dùng nước hấp bí làm xốt cho thơm; ấn chặt trứng vào nhân để giữ dáng.']),
    'bi_ngoi_xao_hai_san': ('Bí ngòi xanh vàng xào với tôm, mực, cà chua, hành tây, sốt hơi sánh, vị ngọt nhẹ thơm gừng.',
        ['Bỏ chỉ lưng tôm. Khứa caro mực, cắt miếng vừa ăn. Ướp tôm mực với 1 muỗng cà phê gừng sợi, 1 muỗng cà phê tỏi băm, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê giấm gạo.', 'Khứa nhẹ bí ngòi rồi cắt miếng vừa ăn. Cắt múi cau cà chua, hành tây; cắt khúc hành ngò.', 'Phi thơm gừng sợi và tỏi, xào tôm mực nhanh đến vừa chín rồi trút ra.', 'Thêm dầu, xào bí ngòi (cho bí xanh trước, bí vàng sau), cà chua, hành tây; nêm 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê đường, 1/4 muỗng cà phê muối, 1/2 muỗng canh nước tương. Khi rau vừa chín, cho tôm mực vào, thêm 1 muỗng cà phê nước bột năng cho sánh, tắt bếp, nêm 1/3 muỗng cà phê dầu mè.', 'Múc ra đĩa, rắc tiêu, hành lá, ngò rí, ăn kèm nước tương và ớt.', 'Mẹo: Khứa nhẹ thân bí để bí thấm và giòn hơn.']),
    'bi_nhoi_thit_kho': ('Khoanh bí Nhật nhồi thịt heo, giò sống, nấm mèo, chiên rám rồi kho nước tương lửa nhỏ, vị mặn ngọt mềm.',
        ['Trộn giò sống, thịt heo xay, nấm mèo và cà rốt; nêm 1/2 muỗng cà phê mỗi loại hành tím băm, đường, bột ngọt, hạt nêm và 1/3 muỗng cà phê tiêu, để thấm.', 'Gọt vỏ bí, cắt khoanh 3cm, bỏ ruột rồi nhồi nhân vào. Cắt khúc hành lá, cắt xéo ớt sừng 3cm.', 'Đun nóng dầu, chiên rám mặt bí. Đổ nước ngập mặt bí, nêm 1 muỗng cà phê bột ngọt và 5 muỗng canh nước tương.', 'Kho lửa nhỏ đến khi nước cạn, bí mềm; thêm ớt sừng, rắc hành lá rồi tắt bếp. Ăn nóng với cơm.', 'Mẹo: Chiên bí trước để bí thấm hơn; chỉ kho đến khi bí vừa mềm, nhân chín để bí không nát.']),
    'bi_do_hap_hai_san': ('Quả bí đỏ khoét ruột làm nồi, đựng tôm mực xào nấm, củ năng rồi hấp chín, vị ngọt bùi thanh.',
        ['Tỉa răng cưa phần trên quả bí để làm nắp, moi hết ruột.', 'Bóc vỏ tôm, chẻ lưng, bỏ đuôi. Khứa vảy rồng mực, cắt miếng. Ướp tôm mực với 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1,5 muỗng canh dầu hào.', 'Ngâm nở nấm hương, thái mỏng, giữ nước ngâm. Cắt khối củ năng, cắt quả trám ớt sừng, cắt nhỏ ngò gai.', 'Phi thơm hành tỏi, xào sơ nấm hương, cho tôm mực vào xào săn, nêm 1/2 muỗng cà phê hạt nêm, thêm 1 chén nước ngâm nấm, nấu đến khi nấm mềm. Cho củ năng, bí đỏ miếng, nấm linh chi, ớt sừng vào nấu 5–10 phút, nêm lại rồi tắt bếp.', 'Hấp quả bí trước 15 phút, rồi cho phần xào vào, đậy nắp bí, hấp tiếp 10 phút đến khi bí vừa chín. Thêm ngò gai và ớt sừng, ăn nóng.', 'Mẹo: Hấp vỏ bí trước rồi mới cho nhân vào để mọi thứ chín đều.']),
    'bi_xanh_nhoi_suon_hap': ('Khoanh bí đao nhồi sườn non bọc giò sống, hấp cách thủy rồi rưới xốt dầu hào, vị ngọt thanh.',
        ['Gọt vỏ bí, cắt khoanh 3cm, múc bỏ ruột. Chặt sườn khúc dài bằng khoanh bí.', 'Luộc sườn vừa chín với phần bí thừa trong ít nước, nêm 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt, 1/3 muỗng cà phê tiêu và hành tím nướng đập dập.', 'Rắc chút bột năng khô vào lòng bí. Trộn nấm hương với giò sống, bọc quanh thân sườn (chừa hai đầu) rồi nhồi vào bí cho đầy.', 'Xếp bí vào dĩa cùng ít cọng ngò và gừng sợi, hấp cách thủy 15 phút tính từ khi nước sôi.', 'Làm xốt: lấy nước hấp bí và nước luộc sườn, thêm 1 muỗng cà phê dầu hào, 1/2 muỗng cà phê bột ngọt, đun sôi, cho nước bột năng, 1/2 muỗng cà phê dầu mè, 1 muỗng cà phê ớt băm, khuấy đến khi sánh. Rưới lên bí, ăn với cơm.', 'Mẹo: Chọn sườn non dày thịt, xương nhỏ cho mau mềm; nấu xốt bằng nước hấp và nước luộc sườn cho đậm vị.']),
    'bi_xanh_tiem_tu_hai': ('Khoanh bí xanh đựng cá chẻm, tôm, cua, sò điệp, tiềm trong nước dùng xương gà và nấm, vị ngọt thanh.',
        ['Cho bọng gà vào 1,5 lít nước nguội nấu làm nước dùng. Cắt nhỏ hành lá, cà rốt, gừng cho vào túi vải, thả vào nồi cùng nấm hương.', 'Bóc vỏ tôm, bỏ chỉ lưng. Rửa cá chẻm, để ráo, lạng bỏ phần gân máu, thái lát mỏng. Ngâm mềm sò điệp khô, xé sợi. Cắt bí xanh khoanh, khoét bỏ ruột.', 'Ướp cá và tôm với 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê hạt nêm, 1 muỗng canh nước bột năng, 1/2 muỗng canh dầu mè.', 'Vớt nấm, túi gia vị và bọng gà ra khỏi nồi, nêm nước dùng thêm 1 muỗng cà phê muối, 2 muỗng cà phê hạt nêm.', 'Cho cá, tôm, nấm, cua và sò điệp vào khoanh bí, đặt vào thố, rót nước dùng vào, đậy nắp tiềm 15 phút. Thêm chút gừng, ăn với cơm nóng.', 'Mẹo: Chọn sò điệp khô ráo nhưng không cứng; cho thố vào tiềm khi nước đã sôi để bí giòn, không bở.']),
    'bo_ap_chao_chanh_day': ('Lõi vai bò Mỹ phết xốt chanh dây nước dừa, áp chảo tái, ăn kèm cà rốt và bí ngòi, vị chua ngọt.',
        ['Cắt lõi vai bò dày 1cm thành 4 miếng, ướp với 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê hạt nêm, 1 muỗng canh tỏi băm, 1 muỗng canh dầu ăn.', 'Làm xốt: đun 1 chén nước dừa với 1 muỗng cà phê hạt nêm và 4 muỗng canh đường đến sôi, làm sánh bằng nước bột năng, thêm 1/2 chén nước chanh dây rồi tắt bếp. Cho 1 muỗng cà phê tương ớt, ớt băm và cọng ngò băm vào.', 'Phết một nửa xốt lên hai mặt bò.', 'Cắt cà rốt khúc 10cm, chẻ tư, tỉa quả trám rồi luộc chín. Chần sơ bí ngòi trong nước có chút muối.', 'Áp chảo bò đến khi vừa chín tới và xém hai mặt, lấy ra. Cho rau củ vào chảo xốc sơ, rắc chút muối. Bày bò với rau củ và rưới phần xốt còn lại.', 'Mẹo: Không áp chảo bò quá chín để thịt giữ độ mềm.']),
    'bo_cau_quay_nuoc_dua': ('Bồ câu ướp hành tỏi ngũ vị hương, chiên sơ rồi quay với nước dừa đến bóng thấm, vị mặn ngọt thơm.',
        ['Đập dập hành lá rồi băm nhuyễn cho ra nước.', 'Cắt chân bồ câu, ướp với 1 muỗng cà phê hành lá băm, 1 muỗng cà phê tỏi băm, 2 muỗng cà phê hành tím băm, 1/2 muỗng cà phê ngũ vị hương, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê hạt nêm và 1 muỗng cà phê nước tương trong khoảng 30 phút.', 'Chiên sơ bồ câu, chắt bớt dầu, rồi đổ nước dừa vào chảo quay từ từ đến khi thấm.', 'Chặt đôi bồ câu, bày ra dĩa, ăn với cơm nóng.', 'Mẹo: Ướp gia vị cả bên trong bụng để khi quay không bị cháy; không cần đường vì nước dừa đã ngọt.']),
    'bo_chien_mot_nang': ('Thịt bò thái con chì tẩm bột chiên giòn, chiên vàng, trộn lá chanh, ăn cùng sả và lá lốt chiên, chấm tương ớt.',
        ['Thái bò phi lê thành cọng nhỏ, trộn với 1/2 muỗng cà phê ngũ vị hương rồi lăn qua bột chiên giòn. Trộn sả với 1 muỗng canh bột chiên giòn.', 'Đun nóng dầu, chiên giòn lá lốt, vớt ra giấy thấm dầu. Tiếp tục chiên giòn sả.', 'Chiên bò ở lửa vừa đến khi chín vàng, vớt ra để ráo dầu.', 'Cho bò còn nóng vào tô, trộn đều với lá chanh thái chỉ. Bày ra dĩa cùng ớt sừng, lá lốt và sả chiên, ăn kèm dưa leo, cà chua, chấm tương ớt.', 'Mẹo: Lăn bò qua bột giúp thịt không khô và thấm vị; trộn lá chanh lúc thịt còn nóng để lá bám vào thịt.']),
    'bo_cuon_nam_kim_cham': ('Thịt bò và ba rọi xông khói cuộn nấm kim châm, rau củ, áp chảo vàng, rưới xốt mayonnaise tương ớt.',
        ['Thái bò lát 0,5cm, dần mỏng, ướp với 1 muỗng cà phê đường, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê nước tương, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê tỏi băm, 1 muỗng cà phê dầu ăn.', 'Cắt sợi ớt chuông xanh, đỏ và hành tây dài 6cm. Cắt cần tây dài bằng nấm. Rửa nấm kim châm, tách nhỏ.', 'Trải ba rọi xông khói, xếp bò, nấm, cần tây, ớt chuông, hành tây lên trên rồi cuộn chặt.', 'Áp chảo các cuộn đến khi vàng đều. Trộn 2 muỗng canh xốt mayonnaise với 1 muỗng canh tương ớt làm xốt.', 'Xếp cuộn ra dĩa, rưới xốt lên, ăn nóng.', 'Mẹo: Ba rọi xông khói đã mặn nên ướp bò nhạt tay; dầu ăn trong phần ướp giúp bò mềm, không khô.']),
    'bo_cuon_nam_xot_tieu': ('Lát bò cuộn bò băm và nấm kim châm, bọc mỡ chài chiên vàng, rưới xốt bơ tương cà tiêu đen.',
        ['Thái bò lát 5mm, đập mỏng, cắt miếng vuông 7cm; phần thịt dư băm nhỏ. Xào sơ hành tây, trộn với thịt băm, 2 muỗng canh xốt mayonnaise và 1 muỗng cà phê hạt nêm.', 'Cắt gốc nấm kim châm, rửa sạch, để ráo. Cắt mỡ chài miếng vuông 9cm.', 'Trải mỡ chài, rắc mỏng bột chiên giòn vị bơ, đặt miếng bò lên, rắc thêm lớp bột mỏng. Cho 1 muỗng cà phê thịt băm và vài cọng nấm, cuộn tròn miếng bò rồi gói mỡ chài lại.', 'Đun nóng ít dầu, chiên cuộn thịt chín vàng, vớt ráo.', 'Làm xốt: đun chảy bơ, cho 4 muỗng canh tương cà, 1 muỗng canh nước tương, 1/2 chén nước dùng, 1 muỗng cà phê đường, 1/2 muỗng cà phê hạt nêm, thêm 1 muỗng canh bột năng pha loãng cho sệt, tắt bếp rắc tiêu đen. Rưới lên thịt, ăn với khoai tây chiên và salad.', 'Mẹo: Lớp bột mỏng giúp thịt thấm vị và cuộn chặt hơn; bơ tươi làm xốt thơm.']),
    'bo_cuon_rau_cu': ('Ba chỉ bò cuộn ớt chuông, bí ngòi, hành tây xào, áp chảo với hương thảo, chấm xốt nước tương vang đỏ.',
        ['Ướp ba chỉ bò với ít muối, tiêu. Cắt sợi mỏng ớt chuông, cắt cọng dài bí ngòi, thái mỏng hành tây.', 'Xào nhanh rau củ trên lửa lớn, nêm 1/3 muỗng cà phê hạt nêm, ít tiêu, tắt bếp rồi trộn với 1 nhánh hương thảo băm.', 'Làm xốt: hòa 1 muỗng cà phê đường, 1 muỗng canh giấm gạo, 3 muỗng canh nước tương, 1 muỗng canh rượu vang đỏ. Phi thơm 1 nhánh hương thảo, đổ hỗn hợp vào, đun nhỏ lửa đến khi hơi sệt, thêm ớt băm, để nguội.', 'Trải thịt bò, cho rau củ vào cuộn tròn. Áp chảo với ít dầu cùng nhánh hương thảo còn lại đến khi chín tới.', 'Bày ra dĩa, chấm với xốt nước tương.', 'Mẹo: Xào rau lửa lớn cho giòn ngọt; áp chảo cuộn bò kỹ để thơm và lên màu đẹp.']),
    'bo_cuon_xot_la_que': ('Lát bò phết xốt lá quế hạt điều phô mai, cuộn ba rọi muối rồi chiên vàng, vị béo thơm thảo mộc.',
        ['Thái bò lát, đập mỏng 3mm, ướp với ít mù tạt và ít hạt nêm.', 'Làm xốt: xay nhuyễn 30g hạt điều, lá quế, 1 muỗng cà phê tỏi băm, 1/2 muỗng cà phê muối, 10g phô mai bột và 3 muỗng canh dầu ăn.', 'Phết xốt lên miếng bò, cuộn tròn, quấn ba rọi muối bên ngoài và ghim tăm ở mép.', 'Chiên lửa vừa đến khi cuộn vừa chín, vàng đều.', 'Rút tăm, xếp ra đĩa, ăn với muối tiêu chanh.', 'Mẹo: Thoa chút nước lên mặt thịt để búa không dính khi đập; xay lá quế bằng máy sinh tố cho thơm hơn.']),
    'bo_kho_dua_kieu': ('Bắp bò ướp cà ri nghệ sa tế, kho cùng dưa kiệu và sữa tươi trong nồi áp suất, vị béo chua cay.',
        ['Thái bắp bò lát dày 1cm, ướp với hành tím băm, 1 muỗng cà phê bột ngọt, 2 muỗng cà phê hạt nêm, 2 muỗng cà phê bột cà ri, 2 muỗng cà phê bột nghệ, 1 muỗng cà phê sa tế, 1 muỗng cà phê nước mắm. Cắt nhỏ ngò gai.', 'Cho bò vào nồi áp suất xào săn, thêm dưa kiệu và sữa tươi không đường.', 'Đậy nắp nấu khoảng 10 phút, tắt bếp ủ thêm 5 phút.', 'Mở nắp, nêm lại cho vừa, thêm ngò gai. Ăn nóng với cơm hoặc bánh mì.', 'Mẹo: Sữa tươi giúp nước kho béo và dịu vị; xào săn bò trước khi kho cho thơm.']),
    'bo_kho_khoai_so': ('Thịt cổ bò ướp nghệ rượu vang, kho nước dừa với khoai sọ áp chảo và boa-rô đến sền sệt, vị ngọt béo.',
        ['Cắt bò miếng vừa ăn, ướp với 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê tỏi băm, 1 muỗng cà phê hạt nêm, 1 muỗng canh bột nghệ, 1 muỗng canh rượu vang.', 'Luộc chín khoai sọ, bóc vỏ, cho vào chảo cùng boa-rô và chút dầu, lăn đều đến vàng thơm.', 'Phi thơm tỏi, xào săn bò, đổ nước dừa vừa ngập thịt, đậy vung kho lửa nhỏ đến khi nước còn một nửa.', 'Cho khoai sọ, boa-rô vào, nêm 1 muỗng canh tương cà (ketchup) và 1 muỗng canh rượu vang đỏ, kho tiếp đến khi nước sền sệt. Thêm ngò gai, ăn nóng với cơm.', 'Mẹo: Chọn thịt cổ, vai hoặc hông sườn có gân mỡ cho món kho ngon hơn; áp chảo khoai sọ giúp thơm và săn.']),
    'bo_kho_nuoc_dua': ('Bắp bò kho nước dừa với cà ri, sốt cà, quế hồi đinh hương và cà rốt, nước sánh, ăn kèm bánh mì.',
        ['Cắt bò miếng 4cm, ướp với 1/2 muỗng canh đường, 1,5 muỗng canh hạt nêm, 1/2 muỗng cà phê muối, 1 muỗng cà phê bột cà ri, 1/4 muỗng cà phê ngũ vị hương, 2 muỗng canh hành tỏi băm.', 'Rang thơm quế, hồi, đinh hương. Đập dập, cắt khúc gừng và sả. Cà rốt tỉa hoa, cắt dày 1,5cm. Hành tây nửa thái mỏng, nửa cắt múi cau.', 'Trong nồi áp suất, phi sả và hành tỏi với 2 muỗng canh dầu, xào săn bò. Thêm 3 muỗng canh sốt cà chua đặc và 1/2 muỗng cà phê bột cà ri, xào thơm lửa vừa.', 'Cho quế hồi đinh hương, 2 chén nước dừa và thêm nước xâm xấp mặt thịt, nêm 1 muỗng cà phê muối. Đậy nắp nấu khoảng 15 phút.', 'Mở nắp, thêm cà rốt nấu đến khi chín và bò mềm, cho hành tây múi cau, khuấy nước bột năng cho sánh.', 'Múc ra đĩa sâu, rắc hành tây, ngò gai, húng quế; ăn với bánh mì và muối tiêu chanh.', 'Mẹo: Rang quế hồi, đinh hương trước để mùi thơm dịu và đặc trưng.']),
    'bo_la_lot_mayonnaise': ('Lát bò cuộn nhân thịt xay trộn sả và xốt mayonnaise, bọc lá lốt chiên ít dầu, ăn với bún và rau sống.',
        ['Thái mỏng bò, ướp với 1/2 muỗng cà phê hạt nêm và 1 muỗng cà phê tỏi băm. Rửa lá lốt, để ráo. Băm nhỏ hành tây.', 'Phi thơm sả, ớt và hành tây rồi để nguội.', 'Trộn phần phi vào thịt xay, nêm 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê nước mắm, 1 muỗng cà phê đường, 1/2 muỗng cà phê tiêu, 2 muỗng canh xốt mayonnaise, để thấm.', 'Đặt nhân lên lát bò, cuộn lại, bọc lá lốt bên ngoài (mặt bóng quay ra ngoài) rồi ghim tăm.', 'Chiên các cuộn trên chảo ít dầu, lửa vừa đến khi chín. Ăn cùng bún, rau sống, dưa leo, đậu phộng, mỡ hành và nước mắm pha.', 'Mẹo: Chiên lửa vừa để cuộn chín đều mà vẫn giữ mùi lá lốt.']),
    'bo_luc_lac_mayo': ('Bò phi lê cắt khối xào tái với tiêu, tỏi, rượu Brandy, trộn rau củ và chút xốt mayonnaise, vị mặn ngọt béo.',
        ['Cắt hành tây, ớt chuông miếng 2cm; cà chua bỏ hạt, cắt vuông 2cm. Vắt nước tỏi băm, giữ riêng phần xác.', 'Cắt bò khối 2cm, ướp với 2 muỗng cà phê hạt nêm, 1 muỗng canh nước tỏi, 1/2 muỗng canh nước tương, 1/2 muỗng canh dầu ăn.', 'Phi thơm tỏi, xào nhanh cà chua, hành tây, ớt chuông rồi trút ra.', 'Ở chảo khác, phi thơm tiêu và tỏi, cho bò vào xào, rưới chút rượu Brandy, xào nhanh đến khi tái. Nêm 1 muỗng canh tương ớt, 1 muỗng canh tương cà, 1 muỗng canh nước tương, 2 muỗng cà phê đường, đảo nhanh.', 'Cho rau củ và 1 muỗng canh xốt mayonnaise vào đảo đều. Ăn với cơm, khoai tây chiên hoặc bánh mì.', 'Mẹo: Ướp bằng nước tỏi giúp thịt thơm, lên màu đẹp mà không bị cháy; chút rượu khi xào làm dậy mùi.']),
    'bo_nau_pate_tieu_xanh': ('Bắp bò hầm nước dừa với cà chua, cà rốt, khoai tây, thêm pate gan xào bơ và tiêu xanh, ăn với bánh mì.',
        ['Cắt bò khối 3cm, ướp với 2 muỗng canh hành tỏi băm, 1 muỗng cà phê muối, 1 muỗng canh đường, 1 muỗng cà phê mỗi loại tiêu, ngũ vị hương, bột ngọt, hạt nêm, nước tương, để 30 phút.', 'Cắt khối cà rốt. Khoai tây cắt khối 2cm, chiên sơ. Hành tây cắt hạt lựu 1cm. Đập dập tiêu xanh, tán nhuyễn pate, cắt nhỏ ngò gai.', 'Trong nồi áp suất, phi hành tỏi với 2/3 lượng tiêu xanh, xào săn bò, đổ nước dừa và 5 muỗng canh cà chua hộp vào, đậy nắp nấu khoảng 10 phút rồi tắt bếp.', 'Mở nắp, thêm cà rốt nấu không đậy nắp 2 phút, rồi cho khoai vào nấu đến khi rau củ mềm.', 'Ở chảo riêng, xào phần tiêu xanh còn lại với hành tây, cho pate và nửa chén nước vào tán nhuyễn, thêm bơ cho tan. Trút vào nồi bò, đảo đều, nêm lại rồi tắt bếp.', 'Múc ra tô, rắc ngò gai, ăn với bánh mì, rau thơm và muối tiêu chanh hoặc muối ớt chanh.', 'Mẹo: Xào pate với bơ trước khi cho vào nồi để món thơm hơn; chỉ hầm bò vừa mềm để giữ vị thịt.']),
    'bo_ne_hoa_thien_ly': ('Bò thái mỏng ướp mayonnaise nước tương, xào nhanh trên đĩa gang nóng với bơ, bông thiên lý và ớt sừng.',
        ['Thái mỏng bò, ướp với 1 muỗng canh nước tỏi, 1 muỗng canh hành tím băm, 1,5 muỗng canh xốt mayonnaise, 1 muỗng canh nước tương, 1/2 muỗng canh đường, 2 muỗng cà phê bột ngọt trong 10 phút.', 'Rửa bông thiên lý, để ráo. Bỏ hạt ớt sừng, cắt hình thoi.', 'Đun nóng đĩa gang ở lửa vừa, cho hành tỏi băm và bơ vào xào thơm.', 'Cho bò vào xào sơ trên lửa lớn, thêm bông thiên lý và ớt sừng xào đến khi chín.', 'Ăn ngay trên đĩa gang với bánh mì hoặc cơm.', 'Mẹo: Đĩa gang phải thật nóng để bò không ra nước và bông thiên lý vẫn xanh giòn; có thể dùng chảo hoặc thay bông thiên lý bằng khổ qua bào.']),
    'bo_nuong_sa_te': ('Thăn bò áp chảo, phết sữa đặc và sa tế sả ớt tự làm, nướng lò trên lớp sả, thái lát ăn với bánh mì.',
        ['Ướp bò với 1/2 muỗng canh nước tương, 1/2 muỗng canh nước mắm, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê bột ngọt trong 30 phút. Đập dập sả cây, xé sợi.', 'Làm sa tế: đun nóng dầu, xào thơm sả băm, tỏi, hành tím, ớt băm, thêm 1 muỗng cà phê ớt bột và cọng ngò rí, khuấy đều rồi để nguội.', 'Áp chảo khối bò cho săn mặt, phết 1 muỗng canh sữa đặc rồi phủ sa tế quanh thịt.', 'Lót sả xé sợi lên khay, đặt bò lên, nướng lò 180°C trong 15 phút đến khi chín. Để nguội rồi thái lát.', 'Xếp ra dĩa cùng xà lách, cà chua, ăn với bánh mì và nước tương.', 'Mẹo: Áp chảo nhanh giữ nước ngọt và tạo mùi thơm; sữa đặc giúp gia vị bám vào thịt.']),
    'bo_ping_pong': ('Viên bò xay bọc trứng cút, lăn bột và cốm dẹp rồi chiên vàng, chấm xốt mè nước tương tắc chua ngọt.',
        ['Chiên sơ cốm dẹp, vớt ra giấy thấm dầu. Đánh tan trứng gà. Đập dập tiêu xanh. Giã sơ mè rang.', 'Trộn bò xay, giò sống, thịt ba chỉ, củ năng, cà rốt, hành tây, tiêu xanh, hành phi; nêm 1/4 muỗng cà phê muối, 1 muỗng canh đường, 1 muỗng cà phê dầu mè, 1 muỗng cà phê bột ngọt, 1/2 muỗng canh nước tương. Để 15 phút rồi chia 8 phần.', 'Bọc mỗi phần thịt quanh một trứng cút, vo tròn, để tủ lạnh 15 phút. Lăn qua bột mì, nhúng trứng rồi lăn cốm dẹp.', 'Pha xốt: khuấy 3 muỗng canh mè rang, 1 muỗng canh ớt sừng băm, 1 muỗng canh cọng ngò băm, 1/2 muỗng canh đường, 2 muỗng canh nước tắc, 1 muỗng canh tương ớt, 3 muỗng canh nước tương.', 'Đun nóng dầu, chiên viên bò đến chín vàng, vớt ráo. Cắt đôi, xếp ra dĩa, chấm xốt.', 'Mẹo: Thêm ba chỉ cho viên mềm béo; để tủ lạnh cho viên định hình, không bể khi lăn bột.']),
    'bo_tiem_trai_dua': ('Bắp bò tiềm trong trái dừa xiêm với táo tàu, kỷ tử, đảng sâm, bạch quả, vị ngọt thanh thơm thuốc bắc.',
        ['Thái mỏng bắp bò, chần qua nước sôi rồi rửa sạch. Ngâm nở táo tàu, rửa sạch. Lột vỏ bạch quả, luộc chín.', 'Pha nước tiềm: 1 chén nước dừa, 1/2 chén nước lạnh, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê muối.', 'Chia đều nguyên liệu vào 2 trái dừa đã chặt nắp, rót nước tiềm vào cách miệng 0,5cm, đậy nắp lại.', 'Hơ trái dừa trên bếp cho vỏ cháy sém, rồi chưng cách thủy khoảng 45 phút đến khi bò mềm.', 'Đặt dừa lên dĩa, nhúng ít xà lách xoong vào cho chín, ăn nóng với cơm.', 'Mẹo: Chần bò giúp nước tiềm thơm hơn; đốt vỏ dừa trước để rút ngắn thời gian tiềm và vỏ có màu đẹp.']),
    'bo_xao_kho_qua_bap_cai_tim': ('Bò thái mỏng xào tái rồi đảo cùng khổ qua, bắp cải tím, hành tây, rắc mè, vị đắng nhẹ mặn ngọt.',
        ['Thái mỏng bò, ướp với 1 muỗng canh hành tỏi băm, 1 muỗng canh dầu hào, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê tiêu.', 'Cắt bắp cải tím miếng 2,5x4cm. Chẻ đôi khổ qua, bỏ hạt, thái lát dày 2 li. Cắt múi cau hành tây.', 'Phi thơm hành tỏi, xào bò lửa lớn đến khi tái rồi trút ra.', 'Đun nóng dầu, cho chút nước xào bò vào, xào bắp cải tím và hành tây, nêm 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê muối, rồi cho khổ qua vào xào nhanh.', 'Cho bò và ớt sừng sợi vào xóc đều, tắt bếp, thêm hành lá. Múc ra dĩa, rắc mè, chấm nước tương.', 'Mẹo: Cho khổ qua vào sau cùng để giữ độ giòn.']),
    'bo_xao_lan': ('Bò ướp cà ri sả và xốt mayonnaise, xào với nấm mèo, miến, hành tây, cần tàu, vị cay thơm béo nhẹ.',
        ['Thái mỏng bò, ướp với 1 muỗng canh xốt mayonnaise, 1 muỗng canh bột cà ri, 1 muỗng canh mỗi loại hành tím, tỏi, sả băm, 1/2 muỗng canh bột ngọt, 1 muỗng canh hạt nêm.', 'Ngâm nở nấm mèo, cắt sợi. Ngâm nở bún tàu, cắt ngắn. Cắt múi cau hành tây, cần tàu khúc 3cm, ớt sừng cắt sợi.', 'Phi thơm hành tím, tỏi, sả; cho bò vào xào săn, rồi thêm hành tây và nấm mèo xào sơ.', 'Cho bún tàu, ớt sợi, cần tàu vào, nêm 1,5 muỗng canh đường, 1,5 muỗng canh xốt mayonnaise, 1 muỗng canh nước mắm; khi rau vừa chín thì tắt bếp.', 'Bày ra dĩa, rắc tiêu, ăn nóng.', 'Mẹo: Xào bò nhanh tay để thịt mềm; chọn bún tàu đậu xanh cho dai giòn.']),
    'bo_xao_nam_mo': ('Bò thái mỏng xào dầu ô liu với nấm mỡ, bông cải xanh trắng và ớt chuông, rắc mè, vị ngọt thanh.',
        ['Thái bò mỏng ngang thớ, ướp với 1/2 muỗng cà phê hạt nêm, 1/4 muỗng cà phê muối, ít tiêu, 1,5 muỗng canh dầu ô liu và hành tỏi băm.', 'Thái mỏng nấm mỡ, cắt bông cải miếng 3cm, ớt chuông cắt quả trám, hành tây múi cau. Chần bông cải chín khoảng một nửa rồi ngâm nước đá.', 'Phi hành tỏi với 2 muỗng canh dầu ô liu, xào nhanh bò đến khi tái rồi trút ra.', 'Thêm dầu và hành tỏi, xào nhanh nấm và bông cải, chắt nước xào bò vào, nêm 1 muỗng cà phê hạt nêm, thêm hành tây và ớt chuông.', 'Khi rau gần chín, cho bò vào trộn đều rồi tắt bếp. Bày ra dĩa, rắc mè, ăn kèm nước tương và ớt.', 'Mẹo: Xào riêng rau và thịt để mỗi thứ chín vừa, không mềm nhũn hay dai.']),
    'bo_xao_ot_kho': ('Thăn bò dần mềm cắt khối, xào với ớt khô, gừng, hành tím và ớt chuông trong dầu điều, vị cay mặn ngọt.',
        ['Băm tỏi, một nửa vắt lấy nước, nửa giữ lại. Gừng thái lát mỏng 1mm cạnh 2cm. Ớt chuông cắt vuông 2cm. Ngâm mềm ớt khô, bỏ cuống. Hành tím bóc vỏ, cắt tư.', 'Lạng gân thăn bò, bọc trong vải mùng và dần bằng búa cho mềm, cắt khối 2cm.', 'Ướp bò với 1 muỗng cà phê hạt nêm, 2 muỗng canh nước tương, 1 muỗng canh giấm gạo, 1 muỗng canh đường, 1 muỗng canh nước tỏi, ít tiêu, ít nước bột năng và ít dầu ăn.', 'Đun nóng dầu điều, xào thơm ớt khô, gừng, hành tím và tỏi băm. Cho bò vào xào nhanh, thêm ớt chuông xào chín, nêm 1 muỗng cà phê hạt nêm rồi tắt bếp.', 'Bày ra đĩa, rắc ngò, ăn với cơm, chấm thêm nước tương tùy thích.', 'Mẹo: Dần thịt qua vải mùng để thịt mềm mà không nát; phi gia vị trước cho mùi thơm thấm đều.']),
    'bo_xot_vang': ('Nạm bò ướp rượu vang, nấu cùng cà chua, bơ, khoai tây, cà rốt trong nồi áp suất, ăn với bánh mì hoặc bánh phở.',
        ['Chần nạm bò qua nước sôi có gừng đập dập, cắt miếng vuông 2cm. Ướp với 1 muỗng canh tỏi băm, 1/2 muỗng cà phê hạt nêm, 1 muỗng cà phê đường, 1 muỗng cà phê ngũ vị hương, 4 muỗng canh rượu vang trong 30 phút.', 'Cắt múi cau cà chua, băm nhỏ hành tây, cắt khối khoai tây và cà rốt, cắt ngò gai khúc 2cm.', 'Đun nóng dầu trong nồi áp suất, phi thơm hành tây, xào cà chua tươi và cà chua hộp đến khi mềm. Cho bơ vào, rồi cho bò vào xào săn.', 'Thêm 4 muỗng canh rượu vang, đổ nước ngập thịt, đậy nắp nấu 7 phút.', 'Mở nắp, nêm 1 muỗng canh hạt nêm, 1/2 muỗng cà phê muối, 1/2 muỗng canh đường, 1 muỗng cà phê tiêu hạt. Cho cà rốt, khoai tây vào nấu đến khi thịt mềm, thêm ngò gai rồi tắt bếp. Ăn nóng với bánh mì hoặc bánh phở.', 'Mẹo: Xào bò với rượu vang để rượu thấm vào thịt; cho bơ sau cà chua để giữ mùi thơm của bơ.']),
    'bong_cai_tron_tom': ('Bông cải, cà rốt luộc giòn trộn tôm xào sả ớt và xốt mayonnaise, thêm húng lủi, sả phi và chanh, vị béo chua nhẹ.',
        ['Bông cải tách miếng nhỏ, rửa sạch; cà rốt tỉa hoa, thái lát mỏng. Luộc cả hai trong nước pha chút muối, vớt ra ngâm nước đá cho nguội rồi để ráo.', 'Hành tây thái sợi mỏng, ướp chút đường; chanh thái lát; húng lủi thái nhỏ. Ướp tôm với 1/2 muỗng cà phê hạt nêm, 1/3 muỗng cà phê tiêu, 1 muỗng cà phê tỏi băm cho thấm.', 'Phi thơm 1 muỗng canh sả băm với 1 muỗng cà phê ớt băm, cho tôm vào xào chín rồi trút ra dĩa để nguội.', 'Trộn bông cải, cà rốt, hành tây, tôm và húng lủi với 3 muỗng canh xốt mayonnaise.', 'Bày ra dĩa, rắc sả phi lên trên và vắt thêm một miếng chanh.', 'Mẹo: Chỉ luộc rau củ vừa chín tới để còn giòn, không bở; vắt chanh sau cùng để salad chua nhẹ và dậy mùi.']),
    'bong_thien_ly_xao_hai_san': ('Bông thiên lý xào nhanh với tôm, mực ướp bột năng và hành tây, vị ngọt thanh, hải sản mềm.',
        ['Lặt bỏ cọng cứng ở chùm bông thiên lý, rửa sạch, để ráo; hành tây thái lát. Tôm bóc vỏ, bỏ đầu, bỏ chỉ lưng; mực rửa sạch, khứa caro mặt trong.', 'Ướp tôm và mực với 1 muỗng cà phê hành tím băm, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu và 1 muỗng cà phê bột năng.', 'Phi tỏi thơm, xào tôm mực trên lửa lớn, thêm chút rượu trắng; khi vừa chín cho hành tây vào đảo đều rồi múc ra.', 'Xào bông thiên lý, nêm 1/2 muỗng cà phê muối, rưới chút nước cho bông chín đều; trút hải sản vào đảo nhanh rồi tắt bếp.', 'Múc ra dĩa, rắc tiêu, ớt sợi, ngò rí, bày cà chua cắt múi cau; ăn với cơm, chấm nước tương với ớt lát.', 'Mẹo: Áo chút bột năng khi ướp giúp hải sản giữ nước ngọt, không dai khô; khứa caro mặt trong để mực cong đẹp và mềm.']),
    'bong_thien_ly_xao_tom': ('Bông thiên lý và giá xào với tôm ướp hành tím, rắc hành phi, vị ngọt nhẹ, giòn.',
        ['Tôm làm sạch, ướp 1/2 muỗng canh hạt nêm, chút tiêu và 1 muỗng canh hành tím băm cho thấm. Lặt và rửa sạch bông thiên lý, giá.', 'Phi thơm phần hành tím còn lại, cho tôm vào xào rồi trút ra dĩa.', 'Thêm dầu vào chảo, xào bông thiên lý, cho 2 muỗng canh nước, nêm 1 muỗng canh hạt nêm; cho giá và tôm vào đảo đều rồi tắt bếp.', 'Bày ra dĩa, rắc tiêu và hành phi; chấm nước tương với ớt lát hoặc tương ớt.', 'Mẹo: Chọn bông thiên lý non, nhiều búp và xào thật nhanh tay để bông giữ độ giòn.']),
    'bun_gao_xao_ga': ('Bún gạo xào cùng thịt đùi gà, hành tây, cà rốt, cải bó xôi và xốt dầu hào tương ớt, đậm vị.',
        ['Gà cắt nhỏ, ướp với 1 muỗng canh hành tỏi băm, 1/2 muỗng cà phê hạt nêm và chút tiêu.', 'Hành tây cắt múi cau, cà rốt bào mỏng rồi cắt đôi, cải bó xôi cắt khúc 7cm. Ngâm bún gạo trong nước lạnh khoảng 15 phút, vớt ra để ráo.', 'Pha xốt xào gồm 1 muỗng cà phê hạt nêm, 1/3 muỗng cà phê bột ngọt, 1 muỗng canh dầu hào, 1 muỗng canh tương ớt và chút tiêu.', 'Phi thơm 1 muỗng canh hành tỏi băm, cho gà vào xào săn, thêm hành tây xào đến khi vừa chín tới.', 'Cho cà rốt, cải bó xôi, bún gạo và xốt vào đảo đều rồi tắt bếp. Ăn nóng, kèm nước tương và ớt lát tùy thích.', 'Mẹo: Bún xào đạt khi sợi thấm gia vị, khô ráo mà không bở nát, rau củ giữ được màu.']),
    'bun_gao_xao_long_nghe': ('Bún gạo xào lòng non chần giấm với nghệ, hẹ, nấm hương và hành tây, lòng giòn, thơm nghệ.',
        ['Lòng heo rửa sạch, chần qua nước sôi có chút giấm gạo và muối, vớt ra xả nước, ngâm đá lạnh rồi cắt miếng vừa ăn.', 'Ngâm bún gạo trong nước ấm, cắt sơ, trộn với chút dầu ăn. Hẹ cắt khúc 5cm, hành tây cắt múi cau, nghệ thái sợi; nấm hương ngâm nở, khứa hình chữ thập trên mũ nấm.', 'Phi thơm hành tỏi và nghệ với 2 muỗng canh dầu, cho lòng vào xào, nêm 1,5 muỗng cà phê hạt nêm, 1 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, thêm chút nước rồi trút lòng ra, giữ lại nước xào.', 'Xào nấm hương, hành tây và hẹ; khi vừa chín cho bún vào đảo, nêm 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt cùng phần nước xào lòng, xào đến khi ráo nước rồi cho lòng vào lại, tắt bếp.', 'Bày ra dĩa, rắc ngò rí và tiêu, ăn nóng kèm nước tương và ớt lát.', 'Mẹo: Chần lòng với chút giấm cho lòng trắng, giòn, bớt mùi; xào lòng nhanh tay vì để lâu sẽ dai.']),
    'bun_gao_xao_rau_cu': ('Bún gạo xào chay với nấm rơm, đậu hũ, gà chay chiên giòn và rau củ, rưới nước tương chanh, rắc đậu phộng.',
        ['Ngâm bún gạo cho mềm, vớt ráo, trộn với 1 muỗng canh nước tương. Đậu hũ cắt sợi; cải ngọt, cần tàu cắt khúc; cà rốt thái sợi; gà chay xé sợi. Nấm rơm chẻ đôi, ướp 1/4 muỗng cà phê hạt nêm và 1/4 muỗng cà phê đường.', 'Đun nóng dầu, chiên giòn đậu hũ và gà chay, vớt ra để nguội.', 'Pha nước tương: 2 muỗng canh đường, 3 muỗng canh nước tương, 2 muỗng canh nước đun sôi để nguội, 1 muỗng canh nước cốt chanh, 1 muỗng cà phê ớt băm.', 'Phi thơm hành boa-rô, xào chín nấm rơm với chút nước, rồi thêm cà rốt, cải ngọt, giá và rưới thêm ít nước.', 'Cho bún vào trộn đều, tiếp theo là đậu hũ và gà chay; nêm 1/3 muỗng cà phê muối, 1/2 muỗng cà phê đường, 1/3 muỗng cà phê bột ngọt, 1 muỗng canh nước tương, nếm lại cho vừa.', 'Bày ra dĩa, rắc đậu phộng rang, rưới nước tương pha, trộn đều và ăn liền.', 'Mẹo: Bún chỉ ngâm mềm, không luộc để khỏi nát; chiên trước đậu hũ và gà chay cho săn, hơi giòn.']),
    'bun_gao_xao_thap_cam': ('Bún gạo xào jambon, chả lụa, nấm đông cô, cà rốt, bông hẹ, rắc trứng vịt tráng sợi, chấm nước tương.',
        ['Ngâm bún gạo trong nước ấm 5 phút, vớt ráo, cắt ngắn bớt. Hành tây, cà rốt, jambon, chả lụa, nấm đông cô thái sợi; bông hẹ cắt khúc 5cm; ớt một phần băm, phần còn lại thái sợi và thái lát; hành ngò thái nhỏ.', 'Đánh tan trứng vịt với 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê rượu trắng, 1 muỗng cà phê nước, 1/2 muỗng cà phê bột năng; tráng thật mỏng rồi thái sợi.', 'Phi thơm tỏi, cho cà rốt, nấm đông cô, chả lụa, jambon cùng 1 chén nước dùng; nêm 2 muỗng cà phê hạt nêm, 1 muỗng cà phê đường, 1/2 muỗng cà phê bột ngọt và xào trên lửa lớn.', 'Cho bún, bông hẹ, hành tây vào đảo nhanh, thêm dầu mè rồi tắt bếp.', 'Pha nước chấm: 3 muỗng canh nước tương, 1 muỗng cà phê nước, 1 muỗng cà phê giấm gạo, 1 muỗng cà phê đường, 1 muỗng cà phê tỏi ớt băm.', 'Bày bún ra dĩa, rắc trứng sợi, hành ngò, ớt sợi và tiêu; chấm nước tương với ớt lát.', 'Mẹo: Ngâm bún bằng nước ấm, không trụng để sợi dai; rượu trắng làm trứng bớt tanh, bột năng giúp trứng dai và dễ tráng mỏng.']),
    'bun_gao_xao_thit_bo': ('Bún gạo xào thịt bò thái mỏng với nấm đông cô, cà rốt, bông hẹ, cần tàu, vị mặn ngọt nước tương.',
        ['Ngâm bún gạo trong nước ấm khoảng 15 phút cho mềm, vớt ráo. Bò thái lát mỏng, ướp 1 muỗng canh tỏi băm, 1 muỗng cà phê đường, 1/2 muỗng cà phê bột ngọt, 1 muỗng canh nước tương, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê bột năng.', 'Nấm đông cô thái lát mỏng; bông hẹ, cần tàu cắt khúc 4cm. Khuấy đều hỗn hợp gia vị gồm 1 muỗng canh đường, 1/2 muỗng cà phê bột ngọt, 2 muỗng canh nước tương, 2 muỗng canh nước.', 'Phi tỏi trong dầu nóng, xào bò thật nhanh rồi trút ra.', 'Thêm dầu, phi tỏi, xào nhanh cà rốt và nấm, rồi cho bông hẹ, cần tàu, ớt sừng; nêm 2 muỗng canh hỗn hợp gia vị và cho bún vào trộn nhanh.', 'Đổ phần gia vị còn lại, xào thêm 2 phút, cho bò vào trộn đều rồi tắt bếp. Múc ra dĩa, thêm ngò rí, rắc tiêu.', 'Mẹo: Ngâm bún bằng nước nóng để sợi dai, không bở.']),
    'ca_ap_chao_vi_sa_te': ('Phi lê cá điêu hồng ướp sa tế, tương ớt, dầu mè rồi áp chảo vàng, chấm muối ớt xanh, cay thơm.',
        ['Hành tây băm nhỏ, ớt chuông xanh cắt nhỏ.', 'Ướp cá với 30g hành tây băm, 1 muỗng canh tỏi băm, 1 muỗng canh đường, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê dầu mè, 2 muỗng canh sa tế, 1 muỗng canh tương ớt, 1 muỗng canh dầu ăn; để 10 phút.', 'Làm nóng chảo, áp chảo cá đến khi chín vàng.', 'Làm muối ớt xanh: xay nhuyễn 4 trái ớt xiêm, 1/4 trái ớt chuông xanh, 1 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 1 muỗng canh đường, vắt thêm 1 miếng chanh.', 'Bày cá ra dĩa, ăn với rau sống, chấm muối ớt xanh.', 'Mẹo: Tương ớt giúp gia vị bám và thấm vào cá; áp chảo lửa vừa để cá vàng đều mà không cháy.']),
    'ca_basa_chien_gion': ('Cá basa cắt thanh xát thì là, lăn bột mì, trứng, bột xù chiên giòn, chấm xốt mayonnaise thì là.',
        ['Đập dập thì là rồi xát lên cá. Cắt cá thành thanh to cỡ ngón tay, nêm 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê nước chanh.', 'Lăn cá qua một lớp bột mì mỏng, nhúng vào trứng đã đánh tan rồi lăn qua bột xù.', 'Thả cá vào chiên khi dầu vừa sôi.', 'Làm xốt chấm: trộn 3 muỗng canh xốt mayonnaise với 1 muỗng canh thì là.', 'Mẹo: Xát thì là giúp cá bớt tanh và thơm hơn; áo lớp bột mì mỏng để cá không bị cứng sau khi chiên.']),
    'ca_basa_chien_gion_vi_chanh': ('Cá basa ướp tỏi, lá chanh, nhúng bột chiên giòn rồi chiên vàng, chấm xốt mayonnaise xí muội chanh muối.',
        ['Lá chanh một nửa thái sợi, một nửa thái nhỏ. Cắt cá thành thanh dày 5–6cm.', 'Ướp cá với 1 muỗng canh tỏi băm, 1/3 muỗng canh tiêu, 1/2 muỗng canh nước cốt chanh, 1/3 muỗng canh lá chanh thái nhỏ; để ngăn mát khoảng 10 phút.', 'Pha xốt chấm: 2 muỗng canh xốt mayonnaise, 1 muỗng canh tương xí muội, 1/2 muỗng canh vỏ chanh muối băm, 1/2 muỗng canh lá chanh sợi.', 'Pha bột chiên giòn với lượng nước theo hướng dẫn trên bao bì. Đun nóng dầu, nhúng cá qua bột rồi chiên vàng giòn, vớt ra để ráo.', 'Ăn kèm cải xoong, cà chua bi và hành tây trộn dầu giấm.', 'Mẹo: Cắt cá thành que theo chiều dọc cho đều miếng; nước cốt chanh và lá chanh giúp cá bớt tanh, thơm hơn.']),
    'ca_basa_cuon_tia_to': ('Cá basa chiên giòn cuộn lá tía tô với dưa leo, cà rốt, đinh lăng, mayonnaise và thính, chấm nước mắm chua ngọt.',
        ['Cắt cá thành miếng ngang 2cm, dài khoảng 8cm, ướp 1/3 muỗng canh tiêu, 1/2 muỗng canh hạt nêm, 1 muỗng canh hành băm.', 'Trụng sơ hành lá. Dưa leo cắt que 1cm; cà rốt thái sợi, ngâm giấm đường.', 'Chiên cá vàng giòn, vớt ra để ráo dầu và để nguội.', 'Trải lá tía tô, xếp cà rốt, dưa leo, 1 nhánh lá đinh lăng rồi đặt cá lên; phết xốt mayonnaise, rắc thính, cuộn tròn và buộc bằng cọng hành lá.', 'Pha nước mắm chua ngọt: 2 muỗng canh nước mắm, 3 muỗng canh nước đun sôi để nguội, 1 muỗng canh đường, 1 muỗng cà phê nước cốt chanh, 1 muỗng cà phê tỏi ớt băm. Bày cuốn ra dĩa, chấm nước mắm.', 'Mẹo: Ướp cá vừa phải để khi chiên không bị cháy; chọn lá tía tô to, lành lặn cho cuốn đẹp.']),
    'ca_bong_lau_kho_to': ('Cá bông lau kho tộ cùng thịt ba chỉ bằng nước tương, tiêu, ớt đến khi sệt, mặn ngọt đậm đà.',
        ['Cá làm sạch, cắt khúc dày khoảng 2cm; ba chỉ rửa sạch, thái miếng mỏng.', 'Ướp cá và thịt với 1 muỗng cà phê hành tím tỏi ớt băm, 1 muỗng canh hạt nêm, 1 muỗng cà phê tiêu, 2 muỗng canh đường, 1 muỗng cà phê bột ngọt, 3 muỗng canh nước tương; để 30 phút.', 'Cho cá, thịt và chút dầu vào nồi, đun đến khi cá săn thì đổ nước sôi ngập mặt cá, hạ nhỏ lửa, nếm và nêm lại.', 'Kho lửa nhỏ tới khi nước gần cạn, thêm hành lá, tiêu rồi tắt bếp. Ăn nóng với cơm.', 'Mẹo: Kho bằng nước tương cho màu nâu vàng đẹp mà không cần nước màu; thêm chút mỡ cá cho béo thơm; dùng nước sôi để cá không tanh.']),
    'ca_bop_chien_gion_xot_chanh': ('Cá bớp ướp chanh vàng, tẩm bột chiên giòn hai lớp, ăn với rau sống và xốt mayonnaise chanh.',
        ['Dưa leo cắt khúc 3cm, chẻ dọc 8; cà chua bỏ hạt, thái mỏng; xà lách cắt vừa ăn; húng lủi rửa, để ráo. Bào lấy 1 muỗng cà phê vỏ chanh, phần còn lại vắt lấy nước.', 'Cá thái lát dày 1cm, ướp 1 muỗng canh nước cốt chanh vàng và 1 muỗng cà phê tiêu xay.', 'Pha xốt chanh: hòa 1/2 muỗng cà phê đường, 1 muỗng cà phê nước mắm, 1/2 muỗng cà phê nước cốt chanh với 1 muỗng canh nước lọc, thêm 2 muỗng canh xốt mayonnaise và 1 muỗng cà phê vỏ chanh, khuấy đều.', 'Pha 2 muỗng canh bột chiên giòn với 50ml nước thành hỗn hợp hơi sánh, phần bột còn lại để khô. Nhúng cá qua bột ướt, lăn qua bột khô rồi chiên vàng trong dầu nóng, vớt ra để ráo.', 'Xếp cá cùng xà lách, cà chua, dưa leo, húng lủi; rưới ít xốt lên, phần còn lại để chấm.', 'Mẹo: Ướp chanh để cá thơm, khử tanh; tẩm bột ướt rồi bột khô giúp lớp vỏ bám chắc và giòn xốp.']),
    'ca_bop_chien_gion_xot_man': ('Cá bớp tẩm bột chiên giòn, rắc gừng và húng chiên, chấm xốt mận chua ngọt nấu với hành tỏi.',
        ['Cắt cá miếng dày 1cm, ướp 2 muỗng canh nước hành tỏi, 1/2 muỗng canh nước cốt chanh trong 5 phút rồi tẩm bột tẩm khô chiên giòn.', 'Gừng và ớt thái sợi nhỏ. Tán đều 3 muỗng canh xốt mận với 3 muỗng canh nước.', 'Đun dầu, chiên đọt húng lủi và gừng, vớt ra giấy thấm dầu. Cho cá vào chiên chín vàng, vớt ra để ráo.', 'Làm xốt: đun nóng 2 muỗng canh dầu, phi thơm xác hành tỏi, cho xốt mận vào, nêm 1/2 muỗng canh đường, 1 muỗng canh nước mắm, 1/2 muỗng cà phê hạt nêm, đun sôi rồi đổ ra chén, rắc chút ớt bột.', 'Bày cá ra dĩa, rắc ớt sợi, gừng sợi, húng chiên; chấm cá với xốt mận.', 'Mẹo: Chiên gừng và húng trước cho dầu thơm rồi mới chiên cá; tán xốt mận với nước trước để xốt mịn, không phải nấu lâu nên giữ được mùi.']),
    'ca_bop_kho_thit_ba_roi': ('Cá bớp xóc nước đường rồi kho nhỏ lửa cùng thịt ba rọi, dầu điều, thêm chút mayonnaise, mặn ngọt béo.',
        ['Ướp cá với 1 muỗng canh hành tỏi băm, 1/3 muỗng cà phê tiêu, 1 muỗng cà phê đường, 1 muỗng canh nước mắm cho thấm.', 'Ba rọi thái mỏng, ướp 1 muỗng canh hành tỏi băm, 1/3 muỗng cà phê hạt nêm, 1/3 muỗng cà phê tiêu, 1/3 muỗng cà phê đường. Ớt thái sợi, hành lá cắt khúc 3cm.', 'Cho dầu và 1 muỗng canh đường vào chảo thắng đến khi hơi vàng, thêm 2 muỗng canh dầu điều và 1/2 chén nước; cho cá vào xóc trên lửa lớn rồi gắp ra.', 'Xào chín thịt, cho cá vào lại, thêm 1 chén nước, kho nhỏ lửa cho thấm.', 'Cuối cùng cho 1 muỗng canh xốt mayonnaise, ớt và hành lá. Ăn nóng với cơm, kèm ớt lát.', 'Mẹo: Xóc cá với nước đường giúp thịt săn, thấm vị; mayonnaise cho vị ngọt dịu, cá mềm mướt. Cá bớp ít xương nên trẻ nhỏ dễ ăn.']),
    'ca_bung_thit_heo': ('Canh cà bung nấu thịt ba chỉ ướp nghệ với cà tím, cà chua, đậu hũ chiên, giấm và tía tô, chua nhẹ.',
        ['Ba chỉ rửa sạch, cắt con chì, ướp 1 muỗng canh nghệ băm, 1 muỗng canh hành tím tỏi băm, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê hạt nêm.', 'Cà tím chẻ tư, cắt khúc 3cm, ngâm nước muối loãng. Cà chua cắt múi cau, đậu hũ chiên cắt khối vuông, tía tô thái sợi.', 'Phi thơm 1 muỗng canh hành tím tỏi băm, xào thịt săn, cho cà chua, đậu hũ, cà tím và 1,5 muỗng cà phê đường vào xào cùng.', 'Đổ 1 lít nước, đun sôi; nêm 2 muỗng canh hạt nêm, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê muối, 2 muỗng canh giấm gạo, 1 muỗng canh nước mắm.', 'Tắt bếp, cho tía tô vào. Múc ra tô, ăn nóng với cơm.', 'Mẹo: Cho tía tô sau cùng để giữ mùi; dùng nghệ tươi thay bột nghệ cho nước canh trong và thơm hơn.']),
    'ca_chep_nau_bung': ('Canh cá chép chiên sơ nấu mẻ, riềng với chuối xanh, đu đủ, khế, cà chua, bạc hà, chua thanh thơm tía tô.',
        ['Cá chép làm sạch, cắt 3 khúc. Hành lá cắt khúc; đầu hành và riềng đập dập, nhét một nửa vào bụng cá, nửa còn lại để riêng. Ướp cá với 1 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt.', 'Bạc hà thái xéo mỏng, bóp chút muối, xả sạch, vắt ráo. Chuối xanh gọt vỏ, cắt khúc 4cm, chẻ dọc 4–6 miếng, ngâm nước muối rồi để ráo; đu đủ cắt giống chuối, ngâm cả hai vào nước nghệ.', 'Khế cắt lát ngang dày 3 li, tía tô thái sợi, ớt sừng thái lát, ớt hiểm đập dập, cà chua cắt múi cau.', 'Chiên sơ hai mặt cá. Đun sôi 1,2 lít nước, cho cơm mẻ, phần riềng còn lại, ớt hiểm, 1/2 muỗng canh đường, 1/2 muỗng canh bột ngọt, 1,5 muỗng canh muối rồi thả cá vào nấu sôi lại.', 'Cho chuối và đu đủ vào nấu đến khi vừa chín, thêm cà chua, khế, nêm 1 muỗng canh nước mắm; cho bạc hà vào đảo nhanh rồi tắt bếp.', 'Múc ra tô, thêm hành lá, tía tô, vài lát ớt sừng; ăn nóng với cơm, chấm nước mắm nguyên chất với ớt.', 'Mẹo: Chiên sơ cá giúp thịt săn, thơm, ngấm gia vị; cho mẻ vào nồi trước khi thả cá để khử tanh.']),
    'ca_chep_nau_rieng_me': ('Cá chép áp chảo nấu nước dùng gà với riềng, nghệ, mẻ, su hào, cần nước, chua nhẹ, ăn kèm bún.',
        ['Cá chép cắt khúc dày 3cm, áp chảo vàng mặt. Cà chua cắt múi cau, hành tím thái lát, ớt hiểm đập dập, cơm mẻ tán nhuyễn; su hào cắt con chì dài 3cm, cần nước cắt khúc 3cm.', 'Đun nóng 2 muỗng canh dầu, xào thơm hành tím, nghệ và riềng; thêm cà chua rồi đổ nước dùng gà vào đun sôi.', 'Nêm 1 muỗng cà phê bột ngọt, 1 muỗng canh hạt nêm, 1 muỗng cà phê muối, 1,5 muỗng canh nước mắm và cơm mẻ.', 'Cho cá và su hào vào nấu chín, cuối cùng thêm cần nước cùng rau nêm (hành, thì là, ớt sừng), đun sôi lại rồi tắt bếp.', 'Múc ra tô, ăn kèm bún.', 'Mẹo: Xào kỹ riềng và nghệ cho màu đẹp, thơm; chọn mẻ màu trắng ngà, chua vừa.']),
    'ca_chien_gion_xot_chanh_ot': ('Cá bớp ướp chanh thì là, nhúng bột chiên giòn, ăn với xốt tương cà mật ong nước dừa và húng lủi chiên.',
        ['Cá cắt khối vuông khoảng 2cm, ướp 1 muỗng canh nước cốt chanh, 1 muỗng canh hành tỏi băm, 1 muỗng canh thì là băm, 1/2 muỗng cà phê tiêu.', 'Pha bột chiên giòn theo hướng dẫn trên bao bì.', 'Làm xốt: phi tỏi, cho 2 muỗng canh xốt tương cà, 1 muỗng canh mật ong, 1 chén nước dừa, nêm 1 muỗng cà phê hạt nêm, 1/2 muỗng canh nước chanh và chút nước bột năng; đun sôi, thêm 1/2 muỗng cà phê ớt bột paprika, trộn đều rồi tắt bếp.', 'Đun nóng dầu, chiên lá húng lủi rồi vớt ra. Nhúng cá vào bột đã pha, chiên vàng giòn, vớt ra để ráo.', 'Bày cá và húng chiên ra dĩa, rưới xốt quanh dĩa.', 'Mẹo: Chanh và thì là giúp cá hết tanh, thơm; ớt bột paprika tạo hương vị riêng cho món.']),
    'ca_chien_hoa_cuc': ('Phi lê cá lóc khứa caro, nhúng trứng lăn bột chiên nở như bông cúc, rưới xốt chua ngọt với ớt chuông.',
        ['Hành tây, ớt Đà Lạt thái sợi dày 0,7cm; đánh tan trứng; vắt lấy nước cốt hành và tỏi.', 'Nghiêng dao khứa caro trên phi lê cá lóc, cắt thành 3 miếng vuông, ướp 1,5 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê nước hành và 1 muỗng cà phê nước tỏi.', 'Cho bột chiên giòn vào túi nilon; nhúng cá qua trứng rồi bỏ vào túi lắc cho bột bám đều, giũ bớt bột thừa và chiên vàng.', 'Phi thơm hành tỏi băm, xào ớt Đà Lạt và hành tây, nêm 1/3 muỗng cà phê hạt nêm rồi trút ra.', 'Làm xốt chua ngọt: khuấy 1/2 chén nước dừa, 1 muỗng canh giấm gạo, 1 muỗng canh đường, 1 muỗng cà phê hạt nêm, chút dầu điều, 1 muỗng canh xốt cà hộp. Phi hành tỏi, đổ xốt vào nấu sánh, cho ớt và hành tây vào, thêm chút bột năng pha nước, sôi lại thì tắt bếp.', 'Xếp cá ra dĩa, rưới xốt lên, ăn nóng.', 'Mẹo: Chọn cá thịt dày, còn da; nghiêng dao khi khứa caro để miếng cá nở ra như bông cúc.']),
    'ca_cam_chien_gion_la_que': ('Cá cam ướp chanh tiêu, tẩm bột chiên giòn trộn lá quế, chiên vàng, chấm mayonnaise tương ớt lá quế.',
        ['Cắt phi lê cá cam thành khúc 5–7cm, ướp 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê bột ngọt, 1 muỗng canh nước cốt chanh.', 'Pha 1/2 gói bột chiên giòn với 70ml nước, trộn thêm 1 muỗng canh lá quế thái sợi.', 'Lăn cá qua lớp bột chiên giòn khô, nhúng vào bột ướt rồi chiên vàng trong dầu nóng, vớt ra để ráo.', 'Pha xốt: 2 muỗng canh xốt mayonnaise, 1 muỗng canh tương ớt, 1 muỗng cà phê lá quế băm.', 'Xếp xà lách, cà chua, dưa leo ra dĩa, đặt cá lên, chấm với xốt.', 'Mẹo: Chanh và tiêu giúp cá bớt tanh; lá quế trộn vào bột cho cá có mùi thơm riêng.']),
    'ca_chien_ngam_nuoc_tuong': ('Cá thu lăn bột mì chiên vàng rồi ngâm trong xốt nước tương giấm đường với rau củ thái sợi, chua ngọt.',
        ['Cá thu làm sạch, cắt miếng dày 1cm, ướp 2 muỗng cà phê hạt nêm, 1/3 muỗng cà phê tiêu, 1 muỗng cà phê nước mắm, 1 muỗng cà phê tỏi băm. Hành tây, cà rốt, cần tây, ớt sừng thái sợi.', 'Lăn cá qua bột mì rồi chiên chín vàng, vớt ra để ráo.', 'Pha xốt: trộn 4,5 muỗng canh nước tương, 6 muỗng canh giấm gạo, 3 muỗng canh đường, 12 muỗng canh nước lọc; cho rau củ thái sợi vào.', 'Xếp cá vào tô xốt, ngâm 30 phút là ăn được.', 'Mẹo: Cho cá vào xốt khi còn nóng để thấm nhiều hơn; chọn cá thu tươi màu trắng hồng; áo bột mì sau khi ướp để cá giòn mà không khô.']),
    'ca_chien_xot_me': ('Cá basa lăn bột năng chiên giòn, đảo cùng xốt me thắng caramel với hành tây, ớt, chua ngọt.',
        ['Thấm khô cá, cắt miếng dài 6cm, rộng 2cm, ướp 1 muỗng cà phê hạt nêm và chút tiêu trong 15 phút. Hành tây cắt hạt lựu, ớt cắt hình thoi, hành lá cắt 1cm.', 'Dầm me với 1 chén nước nóng, lọc lấy nước.', 'Làm xốt me: xào thơm hành tây, cho 1 muỗng canh đường vào thắng thành caramel, đổ nước me vào nấu nhỏ lửa đến khi sệt; nêm 1/2 muỗng nước mắm và 1 muỗng cà phê hạt nêm.', 'Lăn cá qua bột năng, chiên ngập dầu đến vàng, vớt ra để ráo.', 'Xào thơm ớt và hành lá, đổ xốt me vào đun sôi, cho cá vào đảo đều rồi tắt bếp. Bày ra dĩa, rắc ngò rí, ăn với cơm và chấm nước tương.', 'Mẹo: Thắng caramel lửa nhỏ, vừa tới là được; thấm khô cá để chiên giòn hơn.']),
    'ca_chim_chien_gion': ('Cá chim tẩm bột chiên giòn hai mặt, ăn kèm khoai tây, cà chua bi, đậu bi nướng phủ mayonnaise.',
        ['Cá chim rửa sạch, để hơi ráo, khứa dọc hai bên. Khoai tây cắt sợi, ngâm nước rồi rửa lại; cà chua bi cắt đôi; đậu bi rửa, để ráo; lá húng quế cắt đôi.', 'Xếp khoai tây, cà chua, đậu bi vào khay, rắc chút muối và ớt bột, nướng trong lò đến khi vừa chín.', 'Lấy khay ra, thêm lá quế cắt nhỏ, bắt xốt mayonnaise lên mặt rồi nướng thêm 2 phút.', 'Tẩm cá một lớp mỏng bột tẩm khô chiên giòn, chiên vàng đều hai mặt.', 'Bày cá ra dĩa, ăn kèm rau củ nướng.', 'Mẹo: Rắc cả bột tẩm khô vào bụng cá để cá đậm vị và giòn hơn.']),
    'ca_chim_chien_xot_thom': ('Cá chim chiên giòn đặt trên xốt thơm chua ngọt xào cà chua, hành tây, nấm đông cô và nấm linh chi.',
        ['Cá làm sạch, khứa vài đường trên thân, xát với rượu và gừng giã nát cho thơm.', 'Thơm, cà chua, hành tây cắt hạt lựu; nấm đông cô thái lát mỏng, nấm linh chi chẻ đôi theo chiều dọc; hành lá, ngò rí thái nhỏ. Pha 1 muỗng cà phê bột năng với 2 muỗng canh nước.', 'Đun nóng dầu, tẩm cá qua bột tẩm khô chiên giòn, chiên chín vàng rồi vớt ra để ráo.', 'Làm xốt: phi thơm hành tỏi, xào thơm, cà chua và hành tây; nêm 2 muỗng cà phê hạt nêm, 1 muỗng cà phê giấm gạo, 2 muỗng cà phê đường, 1/3 muỗng cà phê tiêu, 1 muỗng cà phê tương ớt, thêm 1/2 chén nước lọc.', 'Cho nấm vào xào chín, thêm ớt băm và nước bột năng cho xốt sánh, tắt bếp.', 'Đổ xốt ra dĩa, đặt cá lên, rắc ngò rí, ăn nóng.', 'Mẹo: Xát gừng rượu giúp cá thơm; bột năng làm xốt sánh, bám vào cá. Chọn cá mắt trong, mang đỏ, thân còn nhớt.']),
    'ca_chim_kho_gung_ot': ('Cá chim trắng chiên vàng rồi rim nhỏ lửa với gừng sợi, ớt sừng, tương ớt và nước tương, cay ấm.',
        ['Cá chim làm sạch, khứa vài đường, ướp 1/2 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1 muỗng canh nước cốt gừng, 1 muỗng canh rượu trắng.', 'Ớt sừng, hành boa-rô cắt khúc 3cm; gừng thái sợi.', 'Đun nóng dầu, chiên cá vàng hai mặt. Đổ 1 chén nước sôi, nêm 1 muỗng canh đường, 2 muỗng canh tương ớt, 1 muỗng canh rượu, 4 muỗng canh nước tương.', 'Cho ớt, gừng, hành boa-rô vào, rim nhỏ lửa, thỉnh thoảng múc nước kho rưới lên cá đến khi nước sánh lại.', 'Bày ra dĩa, ăn nóng với cơm.', 'Mẹo: Chiên cá trước cho thịt săn chắc; kho bằng nước tương và tương ớt cho màu nâu đẹp, vị hài hòa.']),
    'ca_chim_rim_gung_toi': ('Cá chim chiên sơ rồi rim với gừng tỏi trong xốt nước tương dầu hào, mặn ngọt, thơm gừng.',
        ['Cá chim làm sạch, khứa hai mặt, ướp 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu. Gừng, tỏi thái lát mỏng; ớt sừng thái sợi; hành lá cắt khúc ngắn.', 'Pha nước xốt: khuấy tan 1 muỗng cà phê đường, 2 muỗng canh nước tương, 1,5 muỗng canh dầu hào, 1/3 muỗng cà phê tiêu, 1/2 muỗng cà phê hạt nêm với 1 chén nước.', 'Đun nóng dầu, chiên cá khoảng 3 phút, lật đều đến khi vàng, vớt ra để ráo.', 'Phi thơm gừng tỏi, đổ nước xốt vào đun sôi, cho cá vào, rưới xốt lên mặt cá, rim nhỏ lửa khoảng 5 phút; thêm hành lá, ớt rồi tắt bếp.', 'Lót xà lách xoong ra dĩa, đặt cá lên, ăn nóng với cơm.', 'Mẹo: Chiên lửa vừa để cá chín đều bên trong; có thể thay bằng cá bạc má, cá thu hay cá điêu hồng.']),
    'ca_chua_nhoi_dau_hu': ('Cà chua nhồi đậu hũ quết với nấm, bún tàu, củ năng, chiên rám rồi om xốt cà nước dừa sánh.',
        ['Cà chua rửa sạch: 1 trái băm nhỏ, 4 trái cắt đôi, khoét ruột để làm xốt, bỏ hạt. Đậu hũ vắt ráo, quết dai.', 'Nấm ngâm nở, thái sợi, ướp 1/2 muỗng cà phê tiêu; bún tàu ngâm mềm, cắt nhỏ; cà rốt thái sợi; củ năng cắt nhỏ, vắt bớt nước; hành boa-rô thái nhỏ. Hòa bột bắp với chút nước; chặt dừa lấy nước.', 'Phi thơm hành boa-rô rồi vớt hành ra; xào sơ nấm, củ năng, cà rốt, bún tàu, nêm 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê tiêu, chút muối.', 'Trộn nhân gồm đậu hũ, hỗn hợp vừa xào, 1 muỗng cà phê hành phi, 1 muỗng cà phê bột bắp, nêm 1/3 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1/3 muỗng cà phê tiêu.', 'Rắc chút bột bắp vào lòng cà chua, nhồi nhân rồi chiên rám mặt.', 'Xào cà chua băm, nêm 2 muỗng canh xốt cà hộp, 1 muỗng canh dầu điều, 1 muỗng cà phê đường, 1 muỗng cà phê nước tương, 1 muỗng cà phê bột ngọt, 1/2 muỗng cà phê muối. Cho cà chua và 1 chén nước dừa vào, đậy nắp đun nhỏ lửa, thêm từ từ nước bột bắp đến khi xốt sánh. Ăn nóng với cơm.', 'Mẹo: Vắt thật khô nguyên liệu trước khi trộn để nhân dai; rắc bột vào lòng cà giúp nhân không tách khỏi vỏ.']),
    'ca_chua_nhoi_thit_ghe': ('Cà chua nhồi giò sống và thịt ghẹ với nấm mèo, bún tàu, áp chảo rồi nấu xốt cà sánh.',
        ['Cà chua rửa sạch: 1 trái băm nhỏ, 4 trái cắt đôi, khoét ruột để làm xốt, bỏ hạt.', 'Ngâm thịt ghẹ trong nước gừng 15 phút, trụng sơ qua nước sôi rồi vắt ráo. Nấm mèo ngâm nở, thái sợi, ướp chút tiêu; bún tàu ngâm nở, cắt ngắn; pha 1 muỗng canh bột bắp với ít nước.', 'Trộn nhân gồm giò sống, thịt ghẹ, nấm mèo, bún tàu, hành tây hạt lựu, 1 muỗng canh bột bắp, 1 muỗng canh hành tỏi băm, 1/3 muỗng canh tiêu, 1/2 muỗng canh bột ngọt.', 'Rắc chút bột bắp vào lòng cà chua, nhồi nhân rồi chiên rám mặt.', 'Xào cà chua băm với 1/4 muỗng canh đường, 1/4 muỗng canh muối khoảng 2 phút, nêm 1 muỗng canh dầu điều, 1 muỗng canh bột ngọt, 2,5 muỗng canh nước tương.', 'Xếp cà chua nhồi vào xốt, thêm 1 chén nước, nấu đến khi nhân chín kỹ, nhớ trở cho đều; thêm từ từ nước bột bắp đến khi xốt sánh rồi tắt bếp. Ăn nóng với cơm.', 'Mẹo: Bột bắp rắc trong lòng cà giúp nhân bám chắc; áp chảo mặt nhân trước cho thơm mà trái cà không bị nhũn.']),
    'ca_com_chien_gion': ('Cá cơm ướp chanh tỏi tẩm bột chiên giòn cùng hành tây, lót lá cải bẹ xanh chiên, chấm mayonnaise xí muội.',
        ['Cá cơm đã bỏ đầu; hành tây cắt khoanh tròn; lá cải bẹ xanh thái sợi ngang dày 0,7cm.', 'Ướp cá với nước chanh và nước tỏi 10 phút, trộn với 2 muỗng canh bột chiên giòn. Phần bột còn lại pha nước, nhúng cá qua bột ướt; hành tây cũng tẩm bột như cá.', 'Đun nóng dầu, chiên lá cải vừa chín rồi vớt ra để ráo cho giòn; tiếp đến chiên giòn hành tây, sau cùng chiên giòn cá.', 'Pha nước chấm: 2 muỗng canh xốt mayonnaise, 1 muỗng canh tương xí muội, 1 muỗng cà phê ớt hiểm băm.', 'Lót cải chiên dưới dĩa, xếp cá và hành lên trên, ăn nóng; cũng có thể làm món ăn chơi.', 'Mẹo: Chanh và tỏi vừa khử mùi cá vừa giúp bột bám; chiên cải nhanh để giữ màu; chọn cải bẹ lá dày sẽ ngon hơn.']),
    'ca_com_chien_gion_xot_tieu': ('Cá cơm tẩm bột chiên giòn, đảo nhanh với xốt mayonnaise nước mắm tiêu, bày trên xà lách.',
        ['Xà lách rửa sạch, xếp ra dĩa. Pha xốt: trộn 1 muỗng cà phê nước mắm, 1 muỗng cà phê đường, 1/3 muỗng cà phê tiêu, 1 muỗng canh xốt mayonnaise.', 'Tẩm cá với 1/2 gói bột chiên gà giòn, chiên chín vàng, vớt ra để ráo.', 'Cho cá vào chảo nhỏ, thêm xốt, đảo nhanh cho xốt bám rồi tắt bếp.', 'Xếp cá lên dĩa xà lách, ăn nóng.', 'Mẹo: Đảo cá với xốt thật nhanh để cá giữ độ giòn; chọn cá cơm tươi có màu trắng đục.']),
    'ca_com_than_chien_ca_ri': ('Cá cơm than ướp bột cà ri, lăn bột mì mè đen chiên giòn với lá cà ri, chấm nước mắm me chua ngọt.',
        ['Cá cơm than bỏ đầu, ruột, ngâm nước muối, chà rửa sạch, để ráo. Ướp với 1/2 muỗng canh bột cà ri, 1 muỗng cà phê hạt nêm, 1 muỗng canh nước cốt chanh, 1 trái ớt hiểm băm, rồi trộn thêm lòng trắng trứng.', 'Trộn 100g bột mì với 1/2 muỗng canh mè đen để lăn cá trước khi chiên.', 'Pha nước chấm: đun sôi 3 muỗng canh nước me đặc, 2 muỗng canh đường thốt nốt, 2 muỗng canh nước cho tan; thêm 2 muỗng canh nước mắm và nước bột năng (1 muỗng cà phê bột năng hòa 2 muỗng canh nước), tắt bếp, để nguội rồi cho tỏi ớt băm.', 'Đun nóng dầu, chiên lá cà ri trước rồi vớt ra; tiếp tục chiên cá đã lăn bột, vớt ra để ráo.', 'Bày rau mầm và cá chiên riêng trên dĩa, rắc lá cà ri chiên lên cá, kèm chén nước mắm me.', 'Mẹo: Đun me với đường trước rồi mới thêm nước mắm để giữ mùi; không đặt cá lên rau để rau tươi, vỏ bột không mềm; thiếu lá cà ri có thể dùng húng quế.']),
    'ca_dieu_hong_xien_que_chien_la_chanh': ('Cá điêu hồng ướp lá chanh, xiên que xen hành tây, nhúng bột chiên giòn, rắc lá chanh chiên, chấm mayonnaise tương ớt.',
        ['Ướp cá với 1 muỗng canh nước chanh, 1 muỗng canh nước hành tỏi, 1 muỗng cà phê lá chanh băm, 1/3 muỗng cà phê tiêu trong 5 phút.', 'Tẩm cá với 1 muỗng canh bột chiên giòn, xiên vào que xen kẽ với hành tây.', 'Pha phần bột còn lại với 130ml nước, nhúng xiên cá qua bột ướt.', 'Đun nóng dầu, chiên 2 muỗng canh lá chanh thái sợi trước, rồi chiên xiên cá đến vàng đều; cắm cà chua bi lên đầu que.', 'Pha nước chấm: 2 muỗng canh xốt mayonnaise với 1 muỗng canh tương ớt. Bày cá ra dĩa, rắc lá chanh chiên, rưới 1 muỗng canh xốt mayonnaise, ăn kèm xà lách, dưa leo.', 'Mẹo: Lấy nước hành tỏi bằng cách xay hành tỏi rồi vắt lấy nước; chọn lá chanh Thái bánh tẻ, không quá non hay quá già.']),
    'ca_gay_chien_xot_chanh_sa': ('Cá gáy chiên vàng, rưới xốt chanh sả ớt chua ngọt với lá chanh Thái, trang trí mayonnaise cay.',
        ['Ướp cá gáy với chút tiêu, muối, ớt bột và 1 muỗng cà phê nước cốt chanh. Lá chanh thái sợi thật nhỏ.', 'Đun nóng dầu, chiên cá vàng hai mặt rồi xếp ra dĩa.', 'Dùng chảo vừa chiên, phi thơm sả, xào ớt, thêm 2 muỗng canh nước, 1/2 muỗng cà phê đường, 1/4 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê nước mắm, 1,5 muỗng cà phê đường, 1 muỗng canh nước cốt chanh; đảo tan, nếm chua ngọt nhẹ, cho lá chanh vào rồi tắt bếp.', 'Trộn 3 muỗng canh xốt mayonnaise, 1 muỗng canh tương ớt, 1/2 muỗng cà phê ớt bột, cho vào túi bắt xốt.', 'Rưới xốt chanh sả lên cá, bắt xốt mayonnaise trang trí, thêm vài ngọn húng quế, ăn kèm dưa leo.', 'Mẹo: Ớt bột và chanh giúp cá hết tanh, lên màu đẹp; lá chanh Thái tạo mùi thơm cho món.']),
    'ca_hap_nuoc_tuong': ('Cá điêu hồng hấp gừng hành, chan xốt nước tương dầu mè, rưới dầu nóng, ăn kèm cải thìa xào tỏi.',
        ['Cá làm sạch, khứa 2 đường dọc sống lưng, bỏ hết màng đen trong bụng; chà với giấm gạo và 1 muỗng cà phê muối rồi rửa lại.', 'Cải thìa cắt gốc, ngâm nước muối loãng 15 phút, xả sạch, để ráo. Hành lá cắt khúc 5cm, ớt sừng thái sợi; gừng nửa thái sợi, nửa thái lát; ngò tách thân và lá, rễ đập dập.', 'Xát cá với 1 muỗng cà phê tiêu, 1 muỗng cà phê muối. Gác 3 chiếc đũa lên dĩa, đặt cá lên, phủ hành lá, gừng, ớt rồi hấp 15–17 phút.', 'Làm xốt: pha 1 chén nước với 5 muỗng canh nước tương, 1 muỗng cà phê đường, 1/2 muỗng canh hạt nêm, đun sôi, thêm rễ ngò và 1/2 muỗng canh dầu mè rồi tắt bếp.', 'Trụng cải thìa trong nước sôi có 1/2 muỗng cà phê muối, ngâm nước lạnh, để ráo; phi tỏi rồi xào nhanh cải, nêm 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu.', 'Bày cá ra dĩa, xếp hành, ớt, gừng, ngò, cải quanh cá; chan xốt và rưới dầu nóng lên cá. Ăn với cơm, chấm nước tương.', 'Mẹo: Khứa dọc sống lưng để cá thấm vị, dễ gỡ thịt; đặt cá trên đũa để chắt bỏ nước hấp, cá không tanh.']),
    'ca_ho_kho_hanh_gung': ('Cá hố chiên vàng rồi kho nhỏ lửa với hành, gừng sợi, ớt, tương ớt và giấm đến khi sệt, cay ấm.',
        ['Đầu hành băm nhỏ, lá hành thái nhỏ; gừng thái sợi; ớt sừng cắt khúc 2cm; ớt hiểm đập dập.', 'Cá hố cắt khúc 4–5cm, ướp 1/2 muỗng cà phê muối, 1/2 muỗng cà phê đường, 1 muỗng cà phê bột ngọt, 2 muỗng canh nước mắm.', 'Đun nóng dầu trong chảo chống dính, chiên cá vàng hai mặt rồi đổ 1 chén nước sôi, nêm 1 muỗng canh giấm gạo, 1 muỗng cà phê đường, cho đầu hành, ớt sừng, ớt hiểm vào.', 'Kho lửa nhỏ đến khi nước gần cạn, thêm 1 muỗng canh tương ớt, 1/2 muỗng cà phê tiêu và gừng sợi, kho tiếp đến khi sệt thì tắt bếp.', 'Bày cá ra dĩa với xà lách, dưa leo, cà chua; ăn nóng với cơm.', 'Mẹo: Chiên cá trước khi kho cho thơm; giấm gạo vừa tạo vị vừa khử tanh.']),
    'ca_hoi_chien_mam_dua': ('Cá hồi cắt quân cờ chiên giòn, chấm nước mắm dừa cô đặc, ăn với khổ qua sống trộn dầu giấm.',
        ['Cá hồi bỏ da, cắt quân cờ, ướp 1/2 muỗng cà phê cọng ngò băm và 1/2 muỗng cà phê nước cốt chanh. Ớt sừng: 1 trái thái lát, 1 trái băm nhỏ.', 'Khổ qua thái lát mỏng, xếp ra dĩa cùng húng quế, húng lủi rồi cất ngăn mát tủ lạnh.', 'Pha nước dầu giấm: 2 muỗng canh giấm gạo, 2 muỗng canh đường, 2 muỗng canh nước, chút muối và tiêu, khuấy tan.', 'Pha nước chấm: 1 chén nước dừa, 3 muỗng canh đường, 3 muỗng canh nước mắm, đun lửa nhỏ cho cô lại còn khoảng 1 chén; để nguội rồi thêm 2 muỗng canh nước cốt chanh, tỏi và ớt băm.', 'Lăn cá với 1/2 gói bột tẩm khô chiên giòn, chiên ngập dầu lửa lớn đến vàng giòn, vớt ra để ráo.', 'Xếp cá ra dĩa, bày khổ qua và chén nước chấm xung quanh, trang trí ớt lát; khi ăn rưới dầu giấm lên khổ qua và rau thơm.', 'Mẹo: Khổ qua để lạnh ăn sống giòn hơn; chiên cá lửa to cho vỏ giòn mà bên trong vẫn ngọt.']),
    'ca_hoi_chien_sot_chanh': ('Cá hồi còn da áp chảo giòn với bơ, rưới xốt chanh vàng mật ong sánh, chua ngọt thơm bơ.',
        ['Khứa các đường song song trên da cá, tẩm 1/2 gói bột tẩm khô chiên giòn quanh miếng cá.', 'Chanh cắt 3 lát, phần còn lại bào lấy 1 muỗng cà phê vỏ và vắt lấy 3 muỗng canh nước cốt.', 'Đun nóng 3 muỗng canh dầu, áp chảo mặt da trước cho sém, lật lại áp mặt thịt đến vừa chín. Chắt bỏ dầu, thêm 1 muỗng canh bơ lạt cho thơm rồi gắp cá ra; cho 3 lát chanh vào áp chảo hơi sém.', 'Làm xốt: pha 3 muỗng canh nước cốt chanh với 3 muỗng canh nước, 1 muỗng canh mật ong, 1 muỗng cà phê đường, 2 muỗng cà phê nước bột năng, 1 muỗng cà phê hạt nêm; khuấy trên bếp đến khi sánh, thêm 1 muỗng canh bơ lạt, tắt bếp rồi cho vỏ chanh bào vào.', 'Rưới xốt ra dĩa, đặt cá lên với mặt da phía trên, thêm 3 lát chanh.', 'Mẹo: Khứa da để cá thấm bột, chiên ngon hơn; cho bơ vào sau khi chiên để giữ mùi bơ.']),
    'ca_hoi_kho_nuoc_tuong': ('Cá hồi áp chảo dầu điều rồi kho liu riu với nước tương giã gừng hành thì là, thêm măng tây.',
        ['Măng tây cắt khúc 6cm; thì là cắt khúc.', 'Giã nhuyễn 5 đầu hành lá, 1 miếng gừng cỡ ngón tay, 1/3 trái ớt sừng, 2 muỗng canh cọng thì là; thêm 1,5 muỗng canh đường, 1 muỗng cà phê bột ngọt, 4 muỗng canh nước tương, 4 muỗng canh nước, đun nóng cho tan.', 'Đun nóng 2 muỗng canh dầu điều, áp chảo cá cho săn hai mặt rồi gắp ra; cho măng tây vào chảo đảo sơ.', 'Cho cá và hỗn hợp gia vị vào nồi, kho liu riu 4 phút cho thấm, rồi thêm măng tây và thì là.', 'Bày ra dĩa, ăn nóng với cơm.', 'Mẹo: Đun gia vị trước cho tan đều, dậy mùi; áp chảo cá giúp mặt cá săn, vàng sém đẹp.']),
    'ca_hoi_ngu_sac': ('Cá hồi ướp thì là chanh áp chảo bơ, đặt trên khoai tây, bông cải, ớt chuông xào, chấm nước tương mù tạt.',
        ['Cá hồi cắt 4 lát dày khoảng 1,5cm. Bông cải cắt miếng 3cm, ớt chuông cắt hình thoi 2cm, khoai tây cắt tam giác 3cm; thì là băm nhỏ, để riêng cọng và lá.', 'Ướp cá với 1 muỗng canh hành tỏi băm, 1 muỗng cà phê cọng thì là băm, 1/2 muỗng canh nước cốt chanh, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu. Pha nước chấm: 2 muỗng canh nước tương với 1/2 muỗng cà phê mù tạt xanh.', 'Đun sôi nước với chút nước bột năng và muối, luộc khoai tây vừa chín, chần bông cải, vớt ra để ráo.', 'Áp chảo khoai tây với ít dầu đến vàng mặt, cho bông cải vào xào nhanh, thêm ớt chuông, nêm 1 muỗng cà phê hạt nêm, 1 muỗng cà phê thì là, 1 muỗng cà phê dầu hào.', 'Đun nóng ít dầu với 1 muỗng canh bơ, áp chảo cá lửa lớn đến vàng sém hai mặt, đặt lên phần rau củ. Ăn nóng với nước chấm.', 'Mẹo: Bột năng trong nước luộc giúp khoai áp chảo giòn hơn; cá hồi chỉ áp chảo vừa chín, giữ phần giữa còn hồng và ngọt.']),
    'ca_hoi_xot_cay': ('Cá hồi tẩm bột chiên giòn, rưới xốt cay xào cà chua, hành tây, tương ớt và ớt hiểm.',
        ['Cá hồi rửa sạch, để ráo, cắt miếng vuông 2,5cm. Cà chua, hành tây cắt hạt lựu; ngò rí thái nhuyễn; ớt hiểm đập dập.', 'Cho cá vào tô cùng 1/2 gói bột tẩm khô chiên giòn, xóc đều cho bột bám, chiên vàng trong dầu nóng rồi vớt ra để ráo.', 'Làm xốt cay: phi thơm 1 muỗng cà phê tỏi băm, xào mềm hành tây và cà chua; nêm 1 muỗng canh tương ớt, 1 muỗng canh nước tương, 2 muỗng cà phê đường, 1 muỗng cà phê giấm gạo, 1/2 muỗng cà phê tiêu và ớt đập dập.', 'Thêm 1 muỗng canh nước, nấu đến khi cà mềm, rắc ngò rí rồi tắt bếp.', 'Xếp cá ra dĩa, rưới xốt cay lên, ăn với đồ chua và cơm nóng.', 'Mẹo: Sau khi tẩm bột, để cá 2–3 phút cho thấm rồi mới chiên, cá đậm vị và không bị khô.']),
    'ca_hu_kho_xot_tuong': ('Cá hú ướp xốt tương, lót lá trà xanh dưới nồi rồi kho lửa nhỏ không đậy nắp, mặn ngọt, ít tanh.',
        ['Ớt một ít thái sợi, một ít băm; hành lá một ít băm, một ít cắt khúc 3cm. Lá trà xanh rửa sạch, để ráo.', 'Ướp cá với đầu hành băm, ớt băm, đường, muối, tiêu và 2–3 muỗng xốt tương, trộn đều, để 30 phút.', 'Lót lá trà xanh dưới đáy nồi, xếp cá lên trên.', 'Kho lửa lớn, trở cá khi thịt đã săn, thêm chút nước rồi hạ nhỏ lửa, kho không đậy nắp.', 'Cuối cùng thêm chút dầu ăn, hành và tiêu. Múc ra dĩa, ăn với cơm nóng.', 'Mẹo: Chọn cá thịt chắc, mắt trong; vị chát của trà xanh giúp khử tanh cho cá.']),
    'ca_dieu_hong_chien_xot_chanh_day': ('Cá điêu hồng khứa caro ướp paprika, tẩm bột chiên ngập dầu, rưới xốt chanh dây chua ngọt sánh.',
        ['Khứa caro hai mặt thịt cá. Lọc chanh dây lấy 1 chén nước cốt; hành tây cắt hạt lựu.', 'Trộn 1/2 muỗng cà phê ớt bột paprika với 1/2 muỗng cà phê tiêu xay, xoa đều lên cá; tẩm 1 gói bột tẩm khô chiên giòn đều hai mặt.', 'Chiên ngập dầu đến khi cá vàng đều hai mặt, vớt ra để ráo.', 'Làm xốt: phi thơm hành tím bào, cho hành tây, nước chanh dây và 1/2 chén nước vào; nêm 1 muỗng canh đường, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê muối, nếm vừa ăn, làm sánh bằng bột năng pha nước, cuối cùng thả ớt sừng thái lát.', 'Bày cá ra dĩa, rưới xốt chanh dây, thêm hành ngò và ớt lát; ăn với cơm hoặc ăn chơi.', 'Mẹo: Ớt bột giúp cá lên màu và thơm; khi lọc chanh dây để lại ít hạt cho món đẹp mắt.']),
    'ca_dieu_hong_chien_xot_tac': ('Phi lê cá điêu hồng lạng mỏng chiên giòn, ăn với salad rau củ rưới xốt nước mắm tắc chua ngọt.',
        ['Lóc phi lê cá, lạng thành miếng mỏng 0,3cm. Dưa leo cắt khoanh, xà lách cắt vừa ăn, bắp cải tím và cà rốt thái sợi nhuyễn.', 'Vắt tắc lấy 2 muỗng canh nước, vỏ tắc thái sợi nhuyễn.', 'Pha xốt: đun sôi 3 muỗng canh đường với 3 muỗng canh nước mắm, để nguội, thêm 2 muỗng canh nước tắc, 1 muỗng cà phê vỏ tắc, 1 muỗng canh ớt băm.', 'Đun nóng dầu, tẩm cá qua bột tẩm khô chiên giòn, chiên vàng giòn rồi vớt ra để ráo.', 'Xếp cá ra dĩa, bày rau xung quanh, rưới xốt tắc lên rau; ăn cá kèm salad.', 'Mẹo: Lát cá mỏng tẩm bột khô chiên sẽ vàng đẹp, giòn lâu, không khô; vỏ tắc tạo mùi thơm riêng cho xốt.']),
    'ca_dieu_hong_kho_tuong_ban': ('Cá điêu hồng và thịt ba chỉ kho tương bần trong nồi đất lót riềng, thêm trà xanh, sả phi, đậm đà.',
        ['Ba chỉ cắt miếng cỡ ngón tay; cá cắt đôi; đầu hành băm, lá hành cắt khúc.', 'Ướp cá và thịt với 1/2 muỗng cà phê hạt nêm, 1 muỗng canh đầu hành băm, 2 muỗng canh tương bần, 1/2 muỗng cà phê tiêu, 1,5 muỗng canh nước mắm, 1 muỗng canh đường, 2 muỗng canh nước nghệ trong 10 phút.', 'Riềng và ớt sừng thái lát, ớt hiểm đập dập. Sả non thái xéo, chiên qua dầu cho giòn thơm.', 'Lót riềng dưới đáy và quanh thành nồi đất, xếp cá và thịt vào, thêm dầu điều và ớt hiểm. Kho lửa lớn cho cá săn, đổ nước trà xanh vào kho đến khi cá chín, thấm vị và nước sánh lại.', 'Rưới dầu và sả phi lên, rắc tiêu, thêm hành lá và ớt lát. Ăn nóng với cơm.', 'Mẹo: Chọn sả non để chiên giòn mà không xơ; tương bần cho món vị đậm và mùi thơm riêng.']),
    'ca_dieu_hong_kho_tuong_hot': ('Cá điêu hồng ướp nước tương, kho nhỏ lửa với tương hột, gừng, tỏi ớt; mặn ngọt, thơm gừng.',
        ['Gừng cắt lát dày khoảng 2 li, hành lá cắt sợi, tương hột băm nhỏ. Cá làm sạch, khứa hai đường dọc thân rồi cắt đôi.', 'Ướp cá với 1/2 muỗng canh tiêu sọ bể và 2 muỗng canh nước tương trong 15 phút.', 'Phi thơm tỏi, ớt, gừng với dầu nóng, cho cá vào chiên săn hai mặt rồi thêm tương hột.', 'Xếp gừng lát xuống đáy, đặt cá lên trên, đổ 2 chén nước sôi, hạ lửa. Nêm 1/2 muỗng canh đường, 1/2 muỗng canh bột ngọt.', 'Kho nhỏ lửa tới khi cá chín, thấm vị thì tắt bếp, rắc hành lá và hành phi. Ăn với cơm trắng, trang trí ngò rí.', 'Mẹo: Ướp cá với nước tương và tiêu cho thơm; lót gừng dưới đáy nồi để cá không dính khi kho.']),
    'ca_dieu_hong_nuong_rau_ram': ('Cá điêu hồng ướp rau răm, riềng, nghệ, ớt, gói lá chuối nướng lò; thơm cay, chấm nước mắm me.',
        ['Băm nhuyễn lá rau răm, giữ riêng phần cọng. Trộn rau răm, ớt hiểm với 2 muỗng canh hành tỏi băm, 1/2 muỗng canh bột nghệ, 10g riềng, 1 muỗng canh ớt bột, 2 muỗng canh nước mắm, 1/2 muỗng canh hạt nêm, 1/2 muỗng cà phê bột ngọt và chút dầu.', 'Khứa xéo hai bên thân cá, xoa hỗn hợp ướp, để 15 phút cho thấm.', 'Pha nước chấm: khuấy tan 2 muỗng canh nước mắm, 1 muỗng canh nước me, 2 muỗng canh nước lọc, 2 muỗng canh đường, rắc ớt tỏi giã lên trên.', 'Trải giấy bạc (mặt sáng xuống dưới), lót lá chuối (mặt mờ xuống dưới), xếp cọng rau răm rồi đặt cá lên, đổ phần ướp còn lại vào và gói kín.', 'Nướng lò 180°C trong 15 phút. Ăn nóng với bún, bánh tráng, rau sống, chấm nước mắm me.', 'Mẹo: Lá chuối cho cá mùi thơm dân dã; khứa xéo thân cá giúp thấm vị và trông đẹp hơn.']),
    'ca_dieu_hong_xot_hat_luu': ('Phi lê cá điêu hồng tẩm bột chiên giòn, rưới xốt cà chua, thơm, xốt mận chua ngọt.',
        ['Lóc hai miếng phi lê, giữ lại đầu và xương. Mỗi miếng phi lê cắt dọc thành 4 miếng, đặt dao nghiêng 45 độ cho miếng to bản, trộn với 1 muỗng canh muối và 1 muỗng canh tiêu.', 'Làm xốt: phi tỏi, ớt băm, gừng, cà chua với dầu điều cho thơm, đổ nước thơm vào đun lửa nhỏ. Nêm 1 muỗng canh nước mắm, 1 muỗng canh tương ớt, 4 muỗng canh xốt mận, 1 muỗng canh hạt nêm, khuấy đều rồi tắt bếp.', 'Cho thơm, ớt sừng hạt lựu và hành lá vào xốt.', 'Chiên đầu và xương cá trong dầu nóng tới khi vàng giòn. Pha bột chiên giòn theo hướng dẫn trên gói, nhúng phi lê qua bột rồi chiên vàng, để ráo dầu.', 'Đặt đầu và xương giữa đĩa, xếp thịt cá hai bên, rưới xốt, trang trí ngò rí và ớt sợi. Ăn với cơm trắng.', 'Mẹo: Dùng thơm chín cho xốt ngọt thơm; cắt nghiêng dao để miếng cá to bản, chiên giòn hơn.']),
    'ca_dieu_hong_xot_ngu_sac': ('Phi lê cá điêu hồng chiên giòn, chan xốt cà chua ớt chuông dầu hào, ăn cùng cải chíp luộc.',
        ['Lóc hai miếng phi lê, để đầu và xương liền nhau. Khứa hoa trên phi lê rồi cắt miếng vừa ăn. Pha bột chiên giòn với nước theo tỷ lệ trên bao bì.', 'Luộc cải chíp trong nước sôi có chút hạt nêm và dầu ăn tới khi vừa chín, vớt ra ngâm nước lạnh. Cà chua, ớt xanh, ớt đỏ cắt hình thoi; hành lá, thì là cắt nhỏ.', 'Hòa 1 muỗng canh bột bắp với 1 chén nước nguội. Trộn sẵn chén gia vị: 1 muỗng canh dầu hào, 2 muỗng canh nước tương, 1 muỗng canh tương cà, 1,5 muỗng canh hạt nêm, 1 muỗng canh đường.', 'Làm xốt: phi tỏi với 2 muỗng canh dầu, cho cà chua rồi ớt vào xào nhanh, thêm chén gia vị và từ từ nước bột cho sánh. Tắt bếp, rắc tiêu, hành lá, thì là.', 'Nhúng phi lê qua bột, chiên vàng rồi để ráo. Phết phần bột còn lại lên đầu và xương cá, chiên vàng giòn.', 'Lót cải chíp và thì là dọc đĩa bầu dục, đặt xương cá ở giữa, xếp phi lê lên trên rồi chan xốt, ăn nóng.', 'Mẹo: Chọn cà chua chín cho xốt màu đẹp, chua dịu; cho bột bắp từ từ để xốt sánh vừa phải.']),
    'ca_keo_chien_cham_tuong_ban': ('Cá kèo tẩm bột chiên giòn, ăn với rau lang luộc chấm tương bần xào sả tỏi, mè rang.',
        ['Ướp cá kèo với 1 muỗng cà phê tiêu và 1 muỗng canh nước cốt chanh. Đọt rau lang ngắt khúc, rửa sạch, ngâm nước muối loãng rồi để ráo.', 'Nấu tương: phi tỏi, sả, ớt băm với dầu, nêm 1/2 muỗng cà phê bột ngọt, 1 muỗng canh đường, 2 muỗng canh giấm gạo và tương bần, khuấy đều. Tắt bếp, thêm 2 muỗng canh mè rang.', 'Đun sôi nước với 1 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 1 muỗng canh dầu ăn, luộc rau lang chín rồi vớt ra để ráo.', 'Xiên que dọc thân cá. Đun dầu xâm xấp mình cá, lăn cá qua bột tẩm khô chiên giòn, chiên lửa vừa tới khi chín; vặn lửa lớn rồi mới vớt ra, để ráo dầu.', 'Bày cá ra đĩa, ăn với cơm trắng, rau lang luộc chấm tương bần.', 'Mẹo: Luộc rau có gia vị và dầu giúp rau xanh bóng, đậm vị; chiên với dầu xâm xấp để cá giòn ngoài.']),
    'ca_keo_kho_khe': ('Cá kèo kho nước màu với khế chua, ớt, hành lá; vị mặn ngọt chua nhẹ.',
        ['Làm sạch cá kèo với giấm và muối, cắt bỏ đuôi, vây, miệng. Ướp với 1/4 muỗng cà phê tiêu, 1 muỗng cà phê hạt nêm, 1 muỗng canh đường, 1 muỗng canh nước mắm, 1 muỗng canh hành tỏi băm.', 'Ớt sừng và hành lá cắt khúc, ớt hiểm đập dập.', 'Thắng 2 muỗng canh dầu với 1 muỗng cà phê đường thành màu caramel, cho cá vào xóc đều. Thêm 1 muỗng canh dầu điều, ớt sừng, ớt hiểm, 1/2 chén nước sôi rồi cho khế vào.', 'Kho lửa nhỏ tới khi nước hơi cạn, nêm thêm 1 muỗng canh đường và 1 muỗng canh nước mắm. Cho hành lá, đảo đều rồi tắt bếp. Ăn nóng với cơm.', 'Mẹo: Dùng cá kèo còn sống cho thịt ngon, dai nhẹ; chọn khế chua để món có vị riêng.']),
    'ca_keo_kho_rau_ram': ('Cá kèo ướp nước màu, nước mắm, kho niêu đất lót rau răm; mặn ngọt, thơm cay.',
        ['Làm sạch cá kèo, cắt đôi. Băm đầu hành lá, đập dập ớt, cắt nhỏ rau răm.', 'Ướp cá với 1 muỗng canh nước màu, 1 muỗng cà phê muối, 1,5 muỗng canh nước mắm, 1 muỗng canh đường, 1 muỗng cà phê tiêu, 1 muỗng canh đầu hành băm, ớt, 1 muỗng canh rau răm và 1 muỗng cà phê bột ngọt, để 20 phút.', 'Lót rau răm dưới nồi đất, xếp cá lên rồi bắc bếp. Để lửa to tới khi sôi thì hạ nhỏ, thêm 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu, 1 muỗng canh dầu ăn.', 'Kho đến khi cá chín, nước còn ít thì rắc thêm rau răm và tiêu, tắt bếp.', 'Để nguyên trong nồi đất, ăn với cơm nóng, dưa leo và rau sống.', 'Mẹo: Giữ lại bụng cá vì tuy hơi đắng nhưng rất béo; lót rau răm giúp thơm và chống dính nồi.']),
    'ca_kho_chuoi_xanh': ('Cá cam kho với chuối xanh, thịt ba chỉ, riềng trong nước trà xanh; đậm đà, thơm riềng.',
        ['Cá cam cắt khúc 2cm, ướp 1,5 muỗng canh hạt nêm, chút muối, 1/3 muỗng canh tiêu, 5 muỗng cà phê đường, 2 muỗng canh nước mắm, 1 muỗng canh hành tím băm, 2 trái ớt hiểm đập dập.', 'Thịt ba chỉ cắt miếng vuông, ướp 1/2 muỗng canh hạt nêm, 1/3 muỗng canh muối, 1/2 muỗng canh nước mắm, 1/4 muỗng canh tiêu, 1 muỗng canh hành tím băm.', 'Chuối cắt lát xéo dày 1cm, ngâm nước muối loãng rồi chần qua nước sôi. Riềng cắt lát, đầu hành lá đập dập.', 'Thắng 2 muỗng canh dầu với 2 muỗng canh đường tới màu vàng nhạt, chiên cá vàng rồi gắp ra; cho thịt vào xào săn.', 'Lót lá trà xanh đáy nồi, xếp riềng, rồi xếp xen chuối, thịt, cá. Đổ nước trà xanh xâm xấp mặt cá, thêm đầu hành, đậy nắp kho lửa nhỏ tới khi nước còn 1/3.', 'Cho 1 muỗng canh xốt mayonnaise, đảo đều rồi tắt bếp. Rắc tiêu, ăn với xà lách, dưa leo.', 'Mẹo: Nước trà xanh khử tanh và tăng mùi thơm; chiên cá qua nước màu cho cá săn và lên màu đẹp.']),
    'ca_kho_quet': ('Cá lóc, cá cơm khô, tôm khô rim mặn ngọt với tiêu ớt, rắc tóp mỡ; chấm rau củ luộc.',
        ['Rửa sơ khô cá cơm, chiên nhanh cho vàng rồi để ráo. Cá lóc cắt miếng 1,5cm, chiên săn lửa vừa. Tôm khô ngâm mềm rồi giã nát.', 'Mỡ heo cắt hạt lựu; đập dập ớt xiêm và tiêu xanh; cắt nhỏ hành lá.', 'Rim mỡ heo lửa vừa trong chảo nhỏ tới khi tóp khô lại, cho 2 tép tỏi đập dập vào cho thơm rồi vớt tóp ra.', 'Pha chén gia vị: 3 muỗng canh đường, 4 muỗng canh nước mắm, 2 muỗng canh nước lọc, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê tiêu, 5 muỗng canh nước tương, 1 muỗng cà phê tiêu sọ đập dập.', 'Phi hành tỏi băm bằng mỡ heo, xào tôm khô rồi cho cá lóc vào. Đổ chén gia vị vào nấu sôi, thêm ớt xiêm, cá cơm, tiêu xanh, rim lửa nhỏ tới khi sệt lại, cho hành lá rồi tắt bếp.', 'Múc ra đĩa, rắc hành phi và tóp mỡ, ăn với cơm và rau củ luộc.', 'Mẹo: Thêm tỏi vào lúc rim mỡ cho mỡ thơm hơn; nước tương giúp món lên màu đẹp.']),
    'ca_la_lot_chien_me': ('Chả cá thác lác trộn lá lốt, nấm mèo xiên que, nhúng bột mè chiên giòn, chấm mayonnaise tương ớt.',
        ['Lá lốt cắt nhỏ. Trộn mè trắng với mè đen. Ngâm nở nấm mèo, cắt nhỏ, lấy khoảng 2 muỗng canh.', 'Trộn cá thác lác với giò sống, nấm mèo, ớt sừng băm, lá lốt, chút tiêu, 1 muỗng cà phê nước mắm, 1 muỗng cà phê mè trắng, 1 muỗng cà phê mè đen rồi quết dẻo.', 'Múc khoảng 2 muỗng canh cá nặn bám vào một đầu que tre, chừa khoảng 3cm làm tay cầm.', 'Pha bột: 1 gói bột chiên giòn với 1 muỗng cà phê dầu ăn, 1 muỗng cà phê nước cốt chanh, 150ml nước và phần mè còn lại. Nhúng que cá qua bột, chiên vàng rồi để ráo.', 'Trộn 2 muỗng canh xốt mayonnaise với 1 muỗng canh tương ớt làm xốt chấm. Bày cá cùng rau thơm, xà lách, ăn nóng.', 'Mẹo: Nêm nước mắm vào cá cho thấm đều; nặn cá vào que giúp nhúng bột dễ hơn.']),
    'ca_lang_kho_chuoi_va_tai_chua': ('Cá lăng và ba chỉ kho niêu với chuối xanh, tai chua, nghệ, riềng trong nước trà xanh.',
        ['Cá lăng cắt khúc, thịt ba chỉ cắt thỏi cỡ ngón tay.', 'Ướp cá và thịt với nước riềng, nước nghệ, 1 muỗng cà phê ớt bột, 1/2 muỗng cà phê muối, 1,5 muỗng cà phê bột ngọt, 1,5 muỗng canh đường, 1 muỗng cà phê nước màu, 3 muỗng canh nước mắm trong khoảng 10 phút.', 'Chuối cắt thỏi, ngâm nước có chút muối và nước cốt chanh.', 'Lót đáy niêu bằng riềng, gừng lát, tai chua và lá trà xanh; xếp xen kẽ cá, thịt và chuối.', 'Đổ nước trà xanh nóng xâm xấp mặt cá, đun sôi thì hớt bọt rồi hạ lửa liu riu tới khi nước cạn. Thêm tiêu, hành lá, ăn nóng với cơm.', 'Mẹo: Nước trà xanh khử mùi cá; lót riềng và lá trà để cá thịt không nát, không dính đáy niêu.']),
    'ca_lang_kho_cu_nen': ('Cá lăng và ba chỉ kho với củ nén, thơm, nước dừa, tiêu đen; đậm đà, thơm cay.',
        ['Cá cắt khúc dày 2cm, thịt cắt cỡ ngón tay. Ướp chung với 1 muỗng canh hành tỏi băm, 1/2 muỗng canh đường, 3 muỗng canh nước mắm, 1 muỗng canh muối, 1 muỗng canh bột ngọt, 2 muỗng canh dầu điều, 1 muỗng canh củ nén đập dập trong 10 phút.', 'Thơm cắt lát dày 5 li. Ớt sừng cắt hình thoi, ớt hiểm đập dập, hành lá cắt khúc.', 'Thắng 1 muỗng canh dầu với 2 muỗng canh đường, phi 1 muỗng canh củ nén, cho cá và thịt vào kho cho săn.', 'Thêm thơm, ớt, tiêu đen đập dập và 1/2 chén nước dừa. Kho lửa liu riu, không đậy nắp, thỉnh thoảng trở cá tới khi nước sánh vừa.', 'Tắt bếp, rắc hành lá và ớt sừng. Ăn với cơm nóng, rau và dưa.', 'Mẹo: Cá lăng nhiều nhớt nên chà bằng chanh hoặc giấm, cạo da và xả nước lạnh nhiều lần; kho không đậy nắp thì cá săn nhưng cần trở cho đều vị.']),
    'ca_lang_kho_nghe': ('Cá lăng và ba chỉ ướp nghệ, kho nước dừa với nghệ tươi, ớt; vàng đẹp, đậm đà.',
        ['Rửa cá, bỏ phần chỉ máu bên trong. Thịt ba rọi cắt quân cờ. Hành lá: phần xanh cắt nhỏ, phần đầu trắng đập dập cùng ớt hiểm.', 'Khuấy đều 3 muỗng canh nước nghệ, 2 muỗng canh nước mắm, 1 muỗng canh dầu điều, 1/2 muỗng cà phê muối, 2 muỗng cà phê đường, 1 muỗng canh bột ngọt, 1 muỗng canh hạt nêm; ướp cá và thịt 15 phút.', 'Phi thơm hành tím, nghệ lát, ớt hiểm, đầu hành; cho thịt vào xào tới khi ra mỡ, rồi thêm cá, trở hai mặt cho săn.', 'Đổ nước dừa vào từ từ, kho lửa vừa tới khi cá thịt chín và nước sánh. Cho ớt bột, kho thêm 5 phút rồi tắt bếp, rắc hành lá.', 'Ăn nóng với cơm trắng và rau ghém.', 'Mẹo: Xào ba chỉ trước cho săn và ra mỡ; pha xốt ướp trước để cá thấm đều.']),
    'ca_lang_nuong_thi_la': ('Phi lê cá lăng ướp gừng, ớt paprika, nướng lò trên lá chuối phủ thì là, hành; chấm muối ớt xanh.',
        ['Cọng thì là đập dập, lá thì là cắt khúc. Hành tây cắt sợi.', 'Khứa caro miếng phi lê, ướp với 1/2 muỗng canh nước cốt gừng, 1 muỗng canh nước hành tỏi, 1/3 muỗng cà phê ớt paprika, 2 muỗng cà phê hạt nêm, 1 muỗng cà phê nước mắm, 1 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1/4 muỗng cà phê tiêu, 2 muỗng canh dầu ăn trong 15 phút.', 'Đặt lá chuối lên khay, rải một nửa rau gia vị (thì là, hành tây, hành tím, ớt sừng, gừng, đầu hành), đặt cá lên rồi phủ nửa còn lại.', 'Rắc 1/2 muỗng cà phê ớt paprika và 1 muỗng canh rượu trắng lên mặt. Nướng trong lò đã làm nóng khoảng 10 phút tới khi chín.', 'Ăn nóng với muối ớt xanh.', 'Mẹo: Rau gia vị lót và phủ giúp cá thơm; rưới rượu trắng trước khi nướng để dậy mùi.']),
    'ca_loc_chien_mam_sa': ('Cá lóc cắt khoanh chiên giòn, rưới mỡ hành, chấm nước mắm sả chanh; ăn với rau sống.',
        ['Bào lấy 1/2 muỗng cà phê vỏ chanh rồi cắt chanh thành miếng. Cá lóc rửa qua rượu trắng, lau khô, cắt khoanh dày 1cm, ướp với nước hành tỏi.', 'Nước mắm sả: cho 2/3 chén nước, 4 muỗng canh đường, 2 muỗng canh nước mắm, 2 muỗng cà phê bột ngọt vào chảo nhỏ đun tan đường, để nguội. Vắt 2 miếng chanh, thêm 3 muỗng canh sả băm, 1 muỗng canh tỏi ớt băm và vỏ chanh bào.', 'Lăn cá qua bột tẩm khô chiên giòn, chiên trong dầu nóng tới khi chín rồi vớt ra.', 'Làm mỡ hành: cho hành lá vào chén với chút muối, chút bột ngọt, chan 2 muỗng canh dầu nóng vừa chiên cá.', 'Xếp cá ra đĩa, rưới mỡ hành, ăn với nước mắm sả và rau sống.', 'Mẹo: Nước hành tỏi giúp cá thơm; chiên lửa vừa để vỏ vàng mà thịt vẫn mọng.']),
    'ca_loc_dong_kho_nghe': ('Cá lóc đồng ướp nghệ, kho nồi đất với củ nén, sả, ớt bột và nước dừa; thơm cay, sánh.',
        ['Làm sạch cá lóc, để ráo, cắt đôi, khứa ngang 3 đường trên thân.', 'Khuấy 2 muỗng canh nước nghệ với 1 muỗng canh đường, 1 muỗng canh bột ngọt, 1,5 muỗng canh hạt nêm, 3 muỗng canh nước mắm; trộn cá vào, để 20 phút.', 'Làm nóng dầu trong nồi đất, phi 1 muỗng canh củ nén và 1 muỗng canh sả, rồi thêm đầu hành, nghệ lát, ớt bột xào thơm.', 'Đổ nước dừa vào đun sôi, cho cá vào kho lửa vừa 30–40 phút tới khi nước sánh.', 'Tắt bếp, rắc tiêu bể và ngò gai. Ăn với cơm trắng và rau ghém.', 'Mẹo: Khứa ngang thân cá cho thấm vị; lót nghệ lát dưới đáy nồi để không cháy khét.']),
    'ca_loc_phi_le_xot_gung': ('Phi lê cá lóc tẩm bột chiên giòn, chấm hoặc rưới xốt gừng nước tương dầu hào sánh nhẹ.',
        ['Cắt phi lê cá lóc thành miếng xéo dày 1cm, ướp với nước hành tỏi và 1/2 muỗng canh tiêu xay.', 'Làm xốt: phi hành tỏi băm và gừng sợi trong dầu nóng, thêm 2 muỗng canh nước tương, 1 muỗng canh tương ớt, 1 muỗng canh dầu hào, 1 muỗng canh đường, 1/2 muỗng canh bột ngọt.', 'Đổ 1/2 chén nước dùng đã hòa 1 muỗng cà phê bột bắp vào, đun sôi tới khi xốt sệt lại.', 'Lăn từng miếng cá qua bột chiên gà giòn, chiên vàng giòn trong dầu nóng rồi để ráo.', 'Bày rau ăn kèm ra đĩa, xếp cá lên, rưới hoặc chấm xốt gừng, trang trí ngò rí và ớt sợi. Ăn với cơm trắng.', 'Mẹo: Ướp nước hành tỏi để cá thơm mà không bị cháy khi chiên; phi gừng sợi cho xốt dậy mùi gừng.']),
    'ca_ngu_kho_nuoc_mia': ('Cá ngừ áp chảo rồi kho với ba chỉ, thơm và nước mía; ngọt dịu, mặn mà, không cần thêm đường.',
        ['Cá cắt lát, xoa đều hai mặt với 1 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê tiêu, để khoảng 5 phút.', 'Thịt ba chỉ cắt cỡ ngón tay, thơm cắt miếng dày 0,7cm, hành lá cắt khúc. Giã nát 3 đầu hành, 1 trái ớt sừng, 1 trái ớt hiểm.', 'Đun nóng 2 muỗng canh dầu, áp chảo cá lửa hơi to cho săn và hơi vàng, gắp vào nồi kho.', 'Xào nhanh thịt trong chảo, trộn với hỗn hợp hành ớt giã, nêm 2 muỗng canh nước mắm, 1 muỗng canh hành tỏi băm, 2 muỗng canh dầu điều.', 'Cho thịt vào nồi cá cùng thơm và nước mía. Kho lửa to lúc đầu cho săn, rồi hạ lửa tới khi chín, thấm và nước hơi sánh. Rắc hành lá, ăn nóng với cơm.', 'Mẹo: Trộn thịt với hành ớt giã trên chảo nóng cho nhanh thấm; kho bằng nước mía thì không cần nêm đường.']),
    'ca_nuc_chien_xot_me_wasabi': ('Cá nục ướp gừng chiên giòn, ăn kèm cải thảo, cà rốt, rau mầm, chấm xốt mè wasabi nước tương.',
        ['Gừng cắt lát, giã lấy nước, giữ xác gừng để nhét vào bụng cá. Lá cải thảo cắt sợi, ngâm nước đá cho giòn. Cà rốt cắt sợi. Rửa sạch rau mầm, rau răm, để ráo.', 'Khứa xéo nhiều đường trên thân cá nục, ướp với 2 muỗng canh nước cốt gừng và 1/2 muỗng cà phê tiêu.', 'Cho cá vào hộp, thêm bột tẩm khô chiên giòn rồi lắc đều. Chiên cá vàng trong dầu nóng, để ráo.', 'Pha xốt: khuấy 2 muỗng cà phê wasabi, 1 muỗng cà phê nước cốt chanh, 3 muỗng canh nước tương, 1 muỗng canh dầu mè, 2 muỗng canh mè rang giã.', 'Bày cá cùng cải thảo, cà rốt, rau mầm, rau răm, ớt sợi; chấm cá và rau với xốt mè wasabi.', 'Mẹo: Xác gừng trong bụng cá giúp thơm từ bên trong; ngâm cải thảo nước lạnh cho giòn ngon.']),
    'ca_nuc_kho_kieu_nhat': ('Cá nục chiên sơ rồi kho nước tương, giấm, đường với gừng, tỏi, ớt; mặn ngọt chua nhẹ.',
        ['Cá nục cắt đôi. Ớt sừng cắt khúc 2cm. Tỏi và ớt hiểm đập dập. Gừng cắt lát rồi đập dập.', 'Ướp cá với ớt sừng, ớt hiểm, tỏi, gừng, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê hạt nêm, 3 muỗng cà phê đường, 1 muỗng canh dầu điều, 2 muỗng canh nước tương.', 'Pha nước kho: 1 muỗng cà phê bột ngọt, 2 muỗng canh đường, 2 muỗng canh giấm gạo, 4 muỗng canh nước tương.', 'Chiên sơ cá trong dầu nóng cho săn, đổ nước kho, 1 chén nước nóng và gừng vào. Đậy nắp, kho nhỏ lửa tới khi cá chín thì tắt bếp.', 'Ăn nóng với cơm.', 'Mẹo: Chiên trước giúp cá chắc, không nát; giấm giúp khử tanh.']),
    'ca_nuc_kho_ruc': ('Cá nục kho rục với cà chua, cà paste, hành tây và nước dừa đến khi mềm xương; chua ngọt đậm.',
        ['Làm sạch cá nục, cắt đôi. Cà chua bỏ hạt cắt hạt lựu, hành tây cắt hạt lựu nhỏ.', 'Phi thơm tỏi, xào hành tây tới khi vừa chín, cho cà chua vào xào nhừ.', 'Thêm cà paste, đảo tới khi hỗn hợp chuyển màu sậm rồi đổ nước dừa vào.', 'Nêm 1/4 muỗng cà phê muối, 1/4 muỗng cà phê tiêu, 1/2 muỗng cà phê ớt bột, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê hạt nêm, 2 muỗng canh đường, 2 muỗng canh nước mắm, nếm lại cho vừa.', 'Xếp cá vào, đậy kín nắp, kho lửa nhỏ 45 phút đến 1 tiếng tới khi cá rục. Ăn nóng với cơm, xà lách, rau sống, giá.', 'Mẹo: Kết hợp cà chua tươi với cà paste cho màu đẹp và vị ngon hơn.']),
    'ca_nuc_kho_top_mo': ('Cá nục kho nhỏ lửa với tóp mỡ, gừng, hành tím, ớt hiểm; mặn ngọt, béo thơm.',
        ['Bỏ mang và ruột cá nục, rửa với nước muối loãng. Mỡ heo cắt hạt lựu vừa; gừng và hành tím cắt lát.', 'Ướp cá với 1/2 muỗng cà phê bột ngọt, 1,5 muỗng canh nước mắm, 1 muỗng canh đường cát, 1 muỗng canh tương ớt, 1/4 muỗng cà phê tiêu xay.', 'Cho dầu vào nồi, rang 50g mỡ heo tới khi vàng thì vớt ra. Dùng dầu đó phi hành tím và gừng cho vàng.', 'Cho cá đã ướp, tóp mỡ, 2 trái ớt hiểm, 1/2 muỗng canh dầu điều và 1 chén nước nóng vào, đậy nắp kho nhỏ lửa 15 phút.', 'Múc ra đĩa, rắc chút tiêu xay và hành lá cắt nhỏ.', 'Mẹo: Chọn cá vừa, da sáng, mắt trong, mang đỏ, thịt đàn hồi; kho đảo nhẹ, ít trở để cá không nát; gừng giúp khử tanh.']),
    'ca_nuc_xot_thom': ('Cá nục tẩm bột chiên giòn, đặt trên xốt thơm chua ngọt sánh với hành ngò, ớt.',
        ['Làm sạch cá, bỏ ruột, khứa hai đường song song hai bên bụng, để ráo. Đầu hành đập dập nhét vào bụng cá cùng chút tiêu; lá hành và ngò rí cắt nhỏ.', 'Nửa trái thơm cắt hạt lựu nhỏ, nửa còn lại vắt lấy nước. Hòa 1 muỗng cà phê bột năng với 2 muỗng canh nước.', 'Lăn cá qua bột tẩm khô chiên giòn cho bột bám cả vào khe khứa. Chiên lửa vừa tới khi vàng và chín đều bên trong, để ráo dầu.', 'Làm xốt: phi 1 muỗng cà phê hành tím băm, xào sơ thơm, nêm 1/2 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, thêm 2/3 chén nước thơm.', 'Cho nước bột năng vào cho xốt sệt, thêm hành lá, ngò rí, ớt băm, đảo đều rồi tắt bếp.', 'Đổ xốt ra đĩa, xếp cá lên trên, ăn nóng với cơm.', 'Mẹo: Đầu hành và tiêu trong bụng cá giúp khử tanh; tẩm bột cả vào khe khứa và chiên lửa vừa để cá chín đều.']),
    'ca_nuong_ca_ri': ('Cá điêu hồng ướp xốt cà ri nước cốt dừa, sả ớt, nướng lò gói lá chuối; cuốn bánh tráng, bún.',
        ['Làm sạch cá, khứa hai đường sâu dọc theo sống lưng.', 'Phi hành tím, tỏi, ớt, sả băm và một nửa lá cà ri trong dầu nóng. Nêm 1/2 muỗng cà phê muối, 1 muỗng canh đường, 1 muỗng canh bột ngọt, 2 muỗng canh nước mắm.', 'Tắt bếp rồi mới cho 2 muỗng cà phê bột nghệ, 1 muỗng canh bột cà ri và 1 chén nước cốt dừa, khuấy đều.', 'Thoa xốt khắp bụng và lưng cá, ướp 20 phút.', 'Trải giấy bạc, lót lá chuối (nên dùng 2 miếng), rải nửa lá cà ri còn lại, đặt cá và xốt lên. Nướng lò 215°C trong 20 phút.', 'Ăn nóng với bánh tráng, bún, rau sống và nước mắm chua ngọt.', 'Mẹo: Khứa sâu ở lưng cho cá nhanh chín, thấm vị; cho nước cốt dừa sau khi tắt bếp để không bị vón.']),
    'ca_nuong_cham_muoi_ot_xanh': ('Cá điêu hồng ướp ớt tỏi, nướng giấy bạc, cuốn cải xanh chấm muối ớt xanh sữa đặc.',
        ['Khứa vài đường xéo trên cá. Cải xanh bỏ cọng, lấy lá. Hành tây thái mỏng, ngâm nước đá rồi để ráo. Ớt chuông bỏ ruột; ớt sừng bỏ hạt, cắt khúc 3cm.', 'Giã nhuyễn 3 trái ớt xiêm xanh, ớt sừng và 5 tép tỏi, xoa lên cá cùng 1 muỗng cà phê hạt nêm, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê dầu điều, 1 muỗng canh tương ớt; để 10 phút.', 'Xốt muối ớt xanh: xay mịn 1/2 muỗng canh đường, 1/2 muỗng cà phê muối, 2 trái ớt xiêm còn lại, 1 muỗng canh ớt chuông xanh, 1/2 muỗng cà phê bột ngọt, 1 muỗng canh nước cốt chanh, 2 muỗng canh sữa đặc.', 'Bọc cá bằng giấy nến rồi thêm lớp giấy bạc, nướng lò 220°C trong 20–25 phút.', 'Trải lá cải, cho thịt cá, hành tây, cà rốt ngâm chua lên, cuộn lại, chấm xốt muối ớt xanh.', 'Mẹo: Ớt chuông xanh giúp muối ớt xanh đẹp và bớt cay; nướng lò than thì cá thơm hơn.']),
    'ca_nuong_muoi_ot': ('Cá tai tượng ướp thính bánh tráng mè, muối ớt, gói lá sen nướng lò rồi nướng lửa cho thơm.',
        ['Nướng vàng bánh tráng mè rồi giã thành thính. Giã nát ớt sừng và ớt hiểm.', 'Làm sạch cá, khứa hai bên thân. Ướp với 2 muỗng canh thính, 1 muỗng cà phê muối hột, 1 muỗng cà phê ớt bột, ớt giã, 1 muỗng cà phê bột ngọt, 2 muỗng canh xốt mayonnaise.', 'Dưa leo và cà chua cắt lát. Lau sạch lá sen, để ráo.', 'Gói cá trong lá sen, bọc giấy nhôm, nướng lò 250°C khoảng 20 phút.', 'Khi cá vừa chín, mở giấy và nướng tiếp trực tiếp trên bếp gas cho cá ráo, thơm. Ăn với xà lách, dưa leo, cà chua, chấm muối ớt chanh.', 'Mẹo: Chọn ớt hiểm vừa chuyển màu cho cay thơm; thính bánh tráng giúp cá ráo và thơm khi nướng.']),
    'ca_nuong_pa_pinh_top': ('Cá rô phi xẻ lưng nhồi mắc khén, sả, húng, ớt rồi nướng lò kiểu Tây Bắc; chấm chẩm chéo.',
        ['Làm sạch cá, xẻ dọc lưng làm đôi, lóc bỏ xương sống và xương sườn, khứa 2 đường chéo mặt ngoài.', 'Rang thơm hạt mắc khén rồi giã bể. Giã nhuyễn ớt sừng.', 'Trộn hành tím, húng lủi, húng quế, sả với 1 muỗng cà phê mắc khén, 2 muỗng cà phê bột canh, 1/2 muỗng cà phê bột ngọt, 1 muỗng canh ớt sừng.', 'Nhồi một nửa hỗn hợp vào bụng cá, xoa nửa còn lại bên ngoài. Nướng lò 250°C khoảng 20 phút tới khi da vàng.', 'Chẩm chéo: trộn 1 muỗng canh bột canh, 1/2 muỗng cà phê mắc khén, 1 muỗng cà phê ớt sừng, 1 muỗng canh rau gia vị lấy từ bụng cá, vắt 1 trái tắc.', 'Ăn cá với xà lách, rau thơm, dưa leo, chấm chẩm chéo.', 'Mẹo: Rang mắc khén trước khi dùng để dậy mùi đặc trưng.']),
    'ca_nuong_thao_moc': ('Phi lê cá tầm ướp thảo mộc giã, chanh, dầu olive, nướng lò cùng măng tây, cà rốt; ăn với salad.',
        ['Giã nhuyễn 1/2 muỗng cà phê đường, 1/4 muỗng cà phê ớt bột, chút tiêu, 1 muỗng canh rosemary, 1/2 muỗng canh oregano, 1/3 muỗng canh lá thyme, 1/2 muỗng canh muối hồng, 1 muỗng cà phê hạt nêm.', 'Thêm 1 muỗng cà phê nước cốt chanh và 1 muỗng canh dầu olive vào phần thảo mộc, ướp cá 10 phút. Trộn măng tây, cà rốt bi, chanh vàng với dầu olive và chút muối.', 'Làm nóng lò 250°C. Trải giấy bạc, rắc ít muối hồng và vài cọng thảo mộc tươi, đặt cá lên, nướng 15 phút.', 'Xếp rau hai bên cá, nướng thêm 7 phút. Trộn xà lách thập cẩm với xốt dầu giấm.', 'Bày cá ra đĩa, trang trí lá hương thảo, ăn nóng với salad.', 'Mẹo: Lót thảo mộc dưới cá cho thơm và chống dính; thêm dầu olive sau khi giã để tinh dầu thảo mộc tan đều.']),
    'ca_ri_hai_san': ('Cá chẽm, tôm, mực nấu cà ri với sả, nước dừa, nước cốt dừa, hành tây; béo thơm, ăn với bánh mì.',
        ['Ướp cá chẽm với 1/2 muỗng cà phê hạt nêm, 1/3 muỗng cà phê bột cà ri, lăn qua bột mì rồi chiên sơ, để ráo.', 'Ướp tôm với 1/2 muỗng cà phê hạt nêm, 1/3 muỗng cà phê bột cà ri, chao qua dầu rồi vớt ra. Ướp mực với 1 muỗng cà phê bột cà ri, 1 muỗng cà phê bột ngọt, 2 muỗng canh cà ri dầu.', 'Phi sả, hành tỏi băm và lá cà ri, cho mực vào xào săn.', 'Đổ nước dão dừa và thêm 1 chén nước, nấu sôi rồi cho tôm, cá vào nấu vừa chín. Nêm 1 muỗng canh cà ri dầu, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê đường.', 'Cho hành tây và nước cốt dừa, đun sôi lại rồi tắt bếp. Ăn với bánh mì.', 'Mẹo: Cho cá vào sau cùng để không nát; chao tôm cá qua dầu cho thơm hơn.']),
    'ca_ri_to_ong': ('Tổ ong bò xào săn nấu cà ri với khoai tây chiên, nước dừa, sữa; béo cay, chấm mắm me, ăn bánh mì.',
        ['Khoai tây cắt khối 3cm, ngâm nước muối loãng, để ráo, ướp 1/2 muỗng cà phê bột cà ri và 1/2 muỗng cà phê hạt nêm.', 'Chà tổ ong với gừng và rượu cho hết mùi, rửa sạch, chần qua nước sôi rồi chà muối thêm lần nữa. Cắt miếng, ướp 1/2 muỗng cà phê đường, 1 muỗng cà phê tỏi băm, 1 muỗng cà phê bột cà ri, 2 muỗng cà phê hạt nêm.', 'Ớt hiểm đập dập, ớt sừng cắt hình thoi. Chiên khoai trong dầu ngập tới khi vàng, để trên giấy thấm dầu.', 'Phi tỏi, ớt băm và lá cà ri, cho tổ ong vào xào săn. Đổ 2/3 chén nước dão dừa, nấu sôi khoảng 5 phút.', 'Thêm khoai, ớt hiểm, ớt sừng, nấu thêm 5 phút; cho nước cốt dừa và sữa tươi rồi tắt bếp.', 'Pha nước mắm me: 1,5 muỗng canh đường, 2 muỗng canh nước mắm, 2 muỗng canh nước me, tỏi ớt băm. Múc cà ri ra tô, ăn với rau răm, bánh mì.', 'Mẹo: Chiên khoai trước để khoai không nát; cho nước cốt dừa và sữa ở cuối để thơm béo, không vón.']),
    'ca_ro_kho_to': ('Cá rô và ba chỉ ướp nước màu, nước mắm, kho tộ nhỏ lửa; mặn ngọt đậm, ăn với dưa giá.',
        ['Làm sạch cá, rạch giữa bụng khoảng 2/3 chiều dài. Thịt ba chỉ thái mỏng. Đầu hành đập dập rồi băm, ớt hiểm đập dập.', 'Ướp cá và thịt với 1 muỗng canh đường, 2 muỗng canh nước mắm, 1 muỗng cà phê nước màu, 1 muỗng canh đầu hành băm, 1 muỗng cà phê muối, 1 muỗng cà phê bột ngọt và 1 trái ớt, để 30 phút.', 'Cho vào nồi đất, kho tới khi cá săn thì đảo nhẹ, thêm ít nước nóng rồi kho nhỏ lửa cho chín và thấm.', 'Khi nước sánh lại thì tắt bếp, rắc tiêu và hành lá.', 'Ăn với cơm trắng và dưa giá (cà rốt, giá, hẹ trộn đường và giấm gạo).', 'Mẹo: Chọn cá còn sống cho thịt ngọt; cá có trứng thì rạch dọc bụng để trứng chín đều; kho lửa lớn cho săn rồi trở mặt, để nhỏ lửa 20–30 phút.']),
    'ca_ro_phi_chien_xot_ca': ('Cá rô phi tẩm bột chiên vàng, đặt trên xốt cà chua nấu nấm mèo, hành tây; chua ngọt cay nhẹ.',
        ['Khứa xéo 2 đường mỗi bên thân cá, ngâm 15 phút trong nước lạnh pha 1 muỗng cà phê muối và nước cốt chanh, rồi để ráo.', 'Hành tây cắt múi cau, hành lá cắt khúc 3cm, nấm mèo ngâm nở cắt sợi bản 1cm.', 'Làm xốt: phi đầu hành và tỏi với dầu điều, xào cà chua cho ráo. Thêm 1 chén nước, nêm 1 muỗng cà phê hạt nêm, 2 muỗng cà phê đường, 1 muỗng canh nước mắm, 2 muỗng canh tương ớt.', 'Cho nấm mèo và hành tây vào nấu nhỏ lửa tới khi cà chua mềm, thêm hành lá rồi tắt bếp.', 'Lăn cá qua bột tẩm khô chiên giòn, chiên vàng trong dầu nóng.', 'Đổ xốt ra đĩa, đặt cá lên, trang trí hành ngò, ăn nóng với cơm và rau.', 'Mẹo: Ngâm cá nước muối chanh giúp săn, hết tanh; tương ớt cho xốt màu đẹp và sánh tự nhiên.']),
    'ca_ro_phi_kho_la_lot': ('Cá rô phi và ba chỉ kho nước dừa, cuối cùng thêm lá lốt; đậm đà, thơm mùi lá lốt.',
        ['Khứa xéo cá, thịt ba chỉ cắt con chì. Ướp cá và thịt với 1 muỗng cà phê bột ngọt, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 3 muỗng canh nước mắm, 1 muỗng canh hành tỏi băm.', 'Lá lốt cắt khúc 2cm, ớt hiểm đập dập.', 'Ram thịt ba chỉ trong dầu nóng cho xém mặt, thêm 1 muỗng canh đường đảo cho lên màu.', 'Cho hành tỏi băm, ớt hiểm và cá vào xóc đều, đổ 1/2 lít nước dừa, kho lửa nhỏ.', 'Khi nước cạn còn hơi sệt, cho lá lốt và hành lá vào đảo đều. Rắc tiêu, ăn với cơm trắng.', 'Mẹo: Xào ba chỉ trước cho săn, ra bớt mỡ; cho lá lốt sau cùng để giữ màu và mùi thơm.']),
    'ca_saba_kho_ca_xot_mayonnaise': ('Cá saba kho với cà chua băm, hành tím, cuối cùng trộn xốt mayonnaise cho sánh béo.',
        ['Hành lá cắt nhỏ, đầu hành băm. Hành tím cắt lát. Băm nhỏ 2 trái cà chua, trái còn lại bỏ hạt thái lát mỏng. Rửa xà lách, rau thơm; dưa leo thái lát.', 'Làm sạch cá, cắt đôi, ướp 1 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê ớt băm, đầu hành băm và cho tiêu vào bụng cá.', 'Phi hành tím với dầu ăn và dầu điều, xào cà chua băm, cho cá vào trở hai mặt cho săn.', 'Thêm 1 chén nước ấm, nêm 1 muỗng canh nước mắm, 1 muỗng canh đường, nấu lửa nhỏ 10 phút cho nước sánh.', 'Tắt bếp, cho 2 muỗng canh xốt mayonnaise vào đảo đều. Ăn với cơm, rau sống, dưa leo, cà chua.', 'Mẹo: Tiêu trong bụng cá giúp bớt tanh; cho cá vào săn trước khi thêm nước để không bể; mayonnaise giúp nước kho sánh, màu đẹp.']),
    'ca_tai_tuong_hap_xi_dau': ('Cá tai tượng ướp gừng rượu, hấp chín, rưới dầu hành và xốt nước tương xì dầu gừng ớt.',
        ['Gừng: một nửa băm, một nửa cắt sợi. Ớt sừng cắt sợi, hành lá chẻ nhỏ. Làm sạch cá, khứa vài đường trên thân.', 'Ướp cá với 1 muỗng canh gừng băm, chút tiêu, 1 muỗng canh rượu trắng, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt khoảng 15 phút.', 'Pha xốt: 1/2 muỗng canh hạt nêm, 1 muỗng cà phê đường, 1 muỗng cà phê bột ngọt, 3 muỗng canh nước tương, 1 muỗng canh hắc xì dầu, 1 muỗng canh rượu trắng, 1/2 chén nước, 1/2 muỗng cà phê bột năng.', 'Hấp cá trong xửng nước sôi khoảng 20 phút, gắp ra khay.', 'Phi một nửa hành lá trong dầu, múc riêng 2 muỗng canh dầu. Cho phần hành còn lại, gừng, ớt vào xào thơm, đổ xốt vào đun sôi rồi tắt bếp.', 'Đặt khay cá lên bếp, rưới 2 muỗng canh dầu nóng rồi chan xốt, đun liu riu. Ăn với cơm.', 'Mẹo: Rưới dầu nóng lên cá sau khi hấp cho săn và thơm; lau khô cá trước khi ướp để bớt tanh.']),
    'ca_tam_bot_cay_chien_gion': ('Cá basa cắt thanh tẩm bột tempura lá chanh ớt, chiên giòn cùng hành tây; chấm xốt mayonnaise mù tạt.',
        ['Thấm ráo cá basa, cắt thanh 2x5cm. Khuấy nước hành tỏi, nước gừng, nước chanh với 1 muỗng cà phê bột ngọt, 1 muỗng canh nước mắm; ướp cá 15 phút.', 'Hành tây cắt khoanh: vòng to để chiên, vòng nhỏ băm nhuyễn. Lá chanh băm nhuyễn.', 'Trộn bột tempura với lá chanh và ớt bột, tẩm đều cá và khoanh hành tây.', 'Chiên cá vàng trong dầu nóng, để ráo; chiên tiếp hành tây cho giòn rồi để lên giấy thấm dầu.', 'Xốt chấm: khuấy 1 muỗng cà phê mù tạt vàng, 1 muỗng canh sữa đặc, 1 muỗng canh hành tây băm, 3 muỗng canh xốt mayonnaise. Bày cá và hành tây ra đĩa, chấm xốt.', 'Mẹo: Nước chanh và gừng giúp khử tanh; băm nhuyễn lá chanh để khi chiên không cháy mà vẫn thơm.']),
    'ca_thu_chien_gion_xot_chanh_day': ('Cá thu ướp mù tạt, tẩm bột chiên giòn, ăn với xốt chanh dây xào dưa leo, cà chua, hành tây.',
        ['Ướp cá thu với 1 muỗng canh mù tạt vàng. Dưa leo và cà chua bỏ ruột cắt hạt lựu nhỏ, hành tây cắt hạt lựu, hành ngò cắt nhỏ. Lọc chanh dây lấy nước, giữ 1 muỗng cà phê hạt.', 'Làm xốt: phi hành tỏi băm, xào hành tây, dưa leo, cà chua cho thơm, đổ nước chanh dây và 1/2 chén nước vào.', 'Nêm 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1 muỗng canh đường, 1 muỗng canh nước mắm, khuấy tan và nếm lại; thêm hành ngò, tiêu rồi tắt bếp.', 'Đun nóng 5 muỗng canh dầu. Tẩm hai mặt cá với nửa gói bột tẩm khô chiên giòn, chiên vàng đều rồi để ráo.', 'Xếp cá ra đĩa, ăn với xốt chanh dây và cơm trắng.', 'Mẹo: Mù tạt vàng giúp khử tanh; bột tẩm khô giúp đỡ văng dầu và cá không bị khô.']),
    'ca_thu_chien_nghe': ('Cá thu ướp nghệ áp chảo giòn, ăn với gỏi xoài xanh húng lủi và nước mắm chua ngọt thính.',
        ['Ướp cá thu với 2 muỗng canh nước nghệ và 1/2 muỗng cà phê tiêu, lăn sơ qua bột tẩm khô chiên giòn.', 'Xoài bào sợi 2mm. Một trái ớt sừng băm, một trái cắt sợi. Cọng ngò rí cắt nhỏ.', 'Pha nước mắm: 4 muỗng canh đường, 2 muỗng canh nước mắm, 2 muỗng canh giấm gạo, 1 muỗng cà phê ớt bột, 2 muỗng canh cọng ngò, 1 muỗng canh hành tím lát, thính gạo và 1 muỗng canh ớt băm.', 'Trộn xoài, hành tím, ớt sợi với 1 muỗng cà phê đường, để 5 phút rồi thêm húng lủi.', 'Tẩm cá qua bột thêm lần nữa, áp chảo lửa vừa tới khi chín vàng, để ráo.', 'Chan nước mắm ra đĩa, đặt cá lên, thêm gỏi xoài và húng lủi.', 'Mẹo: Nghệ giúp khử tanh; tẩm bột hai lần để cá thấm vị và giòn mặt.']),
    'ca_thu_kho_ca_tim': ('Cá thu và ba chỉ ướp sa tế, kho caramel với cà tím, chút giấm; cay nhẹ, mặn ngọt.',
        ['Ướp cá thu với 1 muỗng canh hành tím băm, 3 đầu hành đập dập, 1 muỗng canh bột ngọt, 1/3 muỗng canh tiêu, 2 muỗng canh sa tế, 3 muỗng canh nước mắm.', 'Thịt ba rọi thái mỏng, ướp 1/2 muỗng cà phê hạt nêm, 1/3 muỗng canh tiêu, 1 muỗng canh hành tím băm, 1 muỗng canh sa tế, 1/2 muỗng canh đường.', 'Cà tím cắt khúc, ngâm nước vắt chút chanh. Hành lá cắt khúc.', 'Thắng 3 muỗng canh dầu với 1 muỗng canh đường thành caramel, phi hành tím, xào săn thịt rồi cho cá vào xóc đều.', 'Thêm 1 chén nước sôi, 1 muỗng canh giấm gạo và cà tím, kho lửa nhỏ tới khi nước hơi sệt. Cho ớt và hành lá rồi tắt bếp, ăn nóng với cơm.', 'Mẹo: Cắt cà tím khúc lớn để không nát; giấm giúp khử tanh và tăng vị.']),
    'ca_thu_kho_nuoc_tuong': ('Cá thu ướp nước tương, rượu, gừng, chiên vàng rồi rim với xốt nước tương ngọt đến sệt.',
        ['Nửa củ gừng thái lát đập dập, nửa còn lại giã vắt lấy nước. Ớt đập dập, cắt đôi. Đầu hành băm, lá hành cắt nhỏ.', 'Ướp cá với 2 muỗng canh nước tương, 1 muỗng canh rượu, 1 muỗng canh đường, 1 muỗng cà phê nước gừng, 1/2 muỗng cà phê tiêu, đầu hành và ớt.', 'Pha xốt: 3 muỗng canh nước tương, 2 muỗng canh rượu, 1,5 muỗng canh đường, 1/2 chén nước nóng.', 'Phi gừng lát, cho cá vào chiên vàng hai mặt, đổ xốt vào rim tới khi cá chín và nước sệt lại.', 'Múc ra đĩa, rắc tiêu, ăn nóng với cơm.', 'Mẹo: Gừng và rượu giúp khử tanh; dùng nước nóng khi kho; chọn cá thịt hồng sẫm, chắc, da ánh xanh.']),
    'ca_thu_kho_rieng': ('Cá thu ướp mayonnaise nước mắm, kho với riềng, ớt trong nước trà xanh; thơm riềng, béo nhẹ.',
        ['Ớt hiểm đập dập, riềng thái lát mỏng.', 'Trộn 1 muỗng canh xốt mayonnaise, 2 muỗng canh nước mắm, 1 muỗng cà phê đường, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu; ướp cá 30 phút.', 'Đun 1 muỗng canh dầu với 1 muỗng canh đường tới màu nâu nhạt, cho riềng và ớt vào chiên sơ, rồi xếp cá vào cho săn mặt.', 'Đổ nước trà xanh nóng vào, kho lửa vừa tới khi gần cạn. Thêm 1 muỗng canh xốt mayonnaise, đảo đều, rắc tiêu.', 'Múc ra đĩa, ăn nóng với cơm.', 'Mẹo: Trộn gia vị với mayonnaise trước khi ướp cho thấm đều; cá thu ít mỡ nên mayonnaise giúp cá bóng và béo hơn.']),
    'ca_thu_nhat_kho_me': ('Cá thu Nhật kho nước dừa với nước cốt me, gừng, ớt; chua ngọt mặn hài hòa.',
        ['Cá rửa sạch, cắt khúc, ướp 1 muỗng canh hành tỏi băm, 1/2 muỗng cà phê tiêu, 1 muỗng canh đường, 1/2 muỗng cà phê bột ngọt, 4 muỗng canh nước mắm và 2 trái ớt hiểm đập dập.', 'Hành lá cắt khúc, ớt sừng cắt sợi.', 'Phi thơm hành tỏi, cho cá vào xóc đều. Thêm 1 muỗng canh dầu điều, 1 chén nước dừa xiêm và 1/2 chén nước cốt me.', 'Kho lửa nhỏ tới khi cá chín và nước còn một nửa. Cho gừng sợi, ớt sừng, đầu hành, rồi nêm thêm 1/2 muỗng cà phê bột ngọt, đảo đều và tắt bếp.', 'Ăn với cơm trắng.', 'Mẹo: Ướp cá với nước mắm trước cho thấm vị; xóc cá với dầu và hành phi để cá săn, thơm.']),
    'ca_thu_nhat_kho_nuoc_dua': ('Cá thu Nhật kho nước dừa với cà chua, thơm, sa tế; ngọt dịu, hơi cay.',
        ['Làm sạch cá, cắt 3 khúc, ướp 1 muỗng cà phê hạt nêm, 2 muỗng canh nước mắm, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê đường, 1 muỗng cà phê sa tế, đầu hành đập dập và 1 muỗng canh hành tím băm.', 'Cà chua cắt múi cau, thơm cắt miếng, ớt hiểm đập dập, hành lá cắt khúc 2–3cm.', 'Phi 1 muỗng canh hành tím băm, cho cá vào xóc cho thấm.', 'Phi hành tím, xào cà chua và thơm tới khi cà hơi mềm, cho cá và nước dừa vào. Nêm 1 muỗng cà phê hạt nêm, 1 muỗng canh nước mắm.', 'Kho nhỏ lửa tới khi nước gần cạn thì tắt bếp. Rắc tiêu và hành lá, ăn nóng với cơm.', 'Mẹo: Nhét đầu hành vào bụng cá cho thơm; xóc cá trước khi kho để thấm gia vị.']),
    'ca_thu_nuong_ot_xanh': ('Phi lê cá thu ướp ớt xanh, tiêu xanh, tỏi, nướng lò trên lá chuối, lá chanh; chấm mắm sữa tắc.',
        ['Rửa phi lê, thấm khô, khứa nhẹ hai đường trên mặt thịt.', 'Giã nhuyễn ớt xanh, để riêng 1/2 muỗng canh. Giã tiếp tiêu xanh, tỏi, hành tím, thêm 2 muỗng canh nước mắm, 1 muỗng cà phê đường, 2 muỗng cà phê bột ngọt, khuấy tan rồi ướp cá 20 phút.', 'Gấp giấy bạc thành khay vừa miếng cá, lót lá chuối, rải lá chanh, đặt cá với mặt da bên dưới, rưới chút dầu.', 'Nướng lò 250°C khoảng 10 phút tới khi cá vàng chín.', 'Mắm sữa: khuấy 1 muỗng canh nước mắm, 2 muỗng canh sữa đặc, 2 muỗng canh nước tắc, 1/2 muỗng canh ớt xanh giã, 1 muỗng cà phê mè rang. Để cá nguyên khay giấy bạc, ăn nóng với cơm, rau sống.', 'Mẹo: Khứa nhẹ mặt cá cho thấm; sữa đặc giúp nước chấm ngọt béo lạ miệng.']),
    'ca_thu_rim_nuoc_tra_xanh': ('Cá thu ướp riềng sợi, chiên săn trong nước màu rồi rim với nước trà xanh đến sệt.',
        ['Riềng gọt vỏ, cắt sợi nhỏ. Lá trà rửa sạch, vò nát, chế nước sôi khoảng 3 phút rồi bỏ nước đầu; chế nước sôi lần hai, để 10 phút, chắt lấy 1 chén.', 'Ướp cá với 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê hành tím băm và riềng sợi, để khoảng 10 phút.', 'Thắng 2 muỗng canh dầu điều với 2 muỗng canh đường tới khi vàng và sủi bọt to, cho cá vào chiên săn hai mặt.', 'Thêm 1 muỗng canh nước mắm, hạ lửa nhỏ cho cá thấm.', 'Đổ nước trà xanh vào, rim tới khi nước sệt lại thì tắt bếp. Ăn với cơm nóng.', 'Mẹo: Thắng nước màu lửa vừa, thấy sủi bọt to là được; vị chát của trà giúp khử tanh.']),
    'ca_tim_hap_nuoc_tuong_toi': ('Cà tím hấp mềm, bóc vỏ, rưới nước tương tỏi gừng, dầu mè, rắc mè rang và hành lá.',
        ['Rửa cà tím, để ráo. Băm nhuyễn tỏi, gừng, ớt; cắt nhỏ hành lá.', 'Hấp cà tím tới chín, lấy ra bóc vỏ, cắt miếng vừa ăn.', 'Phi tỏi, gừng, ớt, thêm 1 muỗng canh giấm gạo, 1 muỗng cà phê đường, 2 muỗng canh nước tương, 1 muỗng canh dầu mè, đun sôi rồi tắt bếp.', 'Xếp cà tím ra đĩa, rưới nước tương, rắc mè rang và hành lá, ăn nóng.', 'Mẹo: Chọn cà tím dài, đều trái, vỏ láng, không sâu héo; cà dài mềm thơm hơn cà tròn.']),
    'ca_tim_nhoi_thit_ap_chao': ('Cà tím khoét ruột nhồi thịt xay lá lốt, áp chảo vàng rồi rưới xốt nước tương sánh, mặn ngọt thơm.',
        ['Cắt bỏ cuống cà tím, bổ đôi theo chiều dọc rồi nạo bỏ ruột bằng muỗng. Thái sợi lá lốt; hòa 1 muỗng cà phê bột năng với chút nước.', 'Trộn thịt xay, giò sống và lá lốt, nêm 1 muỗng cà phê hạt nêm, 1/3 muỗng cà phê tiêu, để ngấm. Rắc chút tiêu, hạt nêm và ít bột năng khô vào lòng cà rồi nhồi thịt vào.', 'Làm nóng ít dầu, đặt mặt thịt úp xuống chảo trước, áp chảo đến khi cà vàng mặt thì gắp ra để ráo.', 'Làm xốt: phi thơm tỏi băm với hành tây, ớt sừng; thêm 2 muỗng canh nước tương, 1 chén nước, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê đường, 1 muỗng cà phê muối, đun tan rồi cho nước bột năng vào cho sánh.', 'Bày cà ra dĩa, rưới xốt lên, rắc ngò rí, ăn cùng cơm trắng.', 'Mẹo: rắc bột năng vào lòng cà giúp nhân bám chắc, không bong khi áp chảo; lá lốt làm món thơm và đẹp hơn.']),
    'ca_tim_nhoi_thit_kho': ('Cà tím chẻ khúc nhồi thịt gừng, chiên sơ rồi kho nước tương tương cà với ớt, đậm đà hơi cay.',
        ['Ướp thịt xay với giò sống, 1 muỗng canh hành tỏi băm, 1/2 muỗng cà phê gừng băm, 1/2 muỗng cà phê hạt nêm, 1/3 muỗng cà phê bột ngọt, 1/4 muỗng cà phê đường và chút tiêu cho ngấm.', 'Cà tím cắt khúc 5cm, chẻ làm 6 nhưng chừa phần gốc khoảng 2cm; ngâm nước muối loãng 10 phút rồi để ráo. Nhồi thịt vào cà; hành lá cắt khúc.', 'Chiên cà trong dầu nóng đến vàng mặt, vớt ra cho ráo dầu.', 'Pha nước kho: hòa 1 muỗng cà phê đường, 1 muỗng cà phê bột ngọt với 1/2 chén nước tương, 1/2 chén nước và 1 muỗng canh tương cà.', 'Xếp cà vào nồi cùng 2 trái ớt hiểm, đổ nước kho vào, đun sôi đến khi cạn còn một nửa. Thêm 1 muỗng canh dầu điều, hành lá, gừng lát, đảo đều rồi tắt bếp; ăn với cơm.', 'Mẹo: ngâm nước muối giúp cà bớt chát và không bị thâm; gừng trộn trong nhân giúp dậy mùi.']),
    'ca_tim_nuong_mayonnaise': ('Cà tím nướng bóc vỏ, phủ thịt xay xào trộn mayonnaise béo nhẹ, rưới nước mắm chua ngọt tỏi ớt.',
        ['Ướp thịt nạc xay với 1/2 muỗng cà phê hạt nêm, 1/3 muỗng cà phê tiêu, 1 muỗng cà phê đầu hành lá băm và 1 muỗng canh nước. Rửa cà tím để ráo; hành lá thái nhỏ.', 'Lấy nĩa châm quanh trái cà, nướng lửa nhỏ, xoay đều đến khi chín thì lột vỏ, cắt miếng vừa ăn, xếp ra dĩa.', 'Phi thơm hành tím, xào thịt chín, cho hành lá vào đảo, tắt bếp rồi trộn thêm 1 muỗng canh xốt mayonnaise.', 'Pha nước mắm: hòa 1 muỗng canh đường, 1 muỗng canh nước mắm, 1/2 muỗng canh nước cốt chanh, 1/2 chén nước, thêm tỏi ớt băm.', 'Rải thịt lên cà, rưới nước mắm quanh dĩa, rắc ngò rí, ăn với cơm nóng.', 'Mẹo: châm nĩa giúp cà chín đều bên trong; mayonnaise cho vị béo mà không cần nhiều dầu.']),
    'ca_tim_xao_tom_thit': ('Tôm sú, ba chỉ xào cùng cà tím, cà chua bi, tía tô và lá lốt, chua nhẹ thơm mùi rau.',
        ['Tôm sú bỏ đầu, bóc vỏ chừa đuôi, xẻ lưng; ba chỉ thái miếng nhỏ. Ướp tôm và thịt với 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê bột nghệ, 1/4 muỗng cà phê tiêu, 1 muỗng canh hành tỏi băm.', 'Cà tím bào bớt vỏ, chẻ tư, cắt khúc 3cm, ngâm nước pha chút giấm gạo. Cà chua bi bổ đôi; tía tô, lá lốt thái nhỏ; ớt hiểm đập dập.', 'Đun sôi nước với 1 muỗng cà phê hạt nêm và 1 muỗng cà phê bột nghệ, trụng nhanh cà tím rồi vớt ra để ráo.', 'Phi thơm 1 muỗng canh hành tỏi băm, cho ba chỉ vào xào săn, hạ lửa xào đến khi thịt ra mỡ và hơi xém cạnh; thêm tôm, tăng lửa xào chín rồi trút ra.', 'Thêm chút dầu, xào cà chua với cà tím, cho 1 chén nước nhỏ, 1/2 muỗng cà phê đường, 1 muỗng canh giấm gạo, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt, xào lửa lớn đến khi cà vừa chín.', 'Trút tôm thịt vào lại, thêm ớt, tía tô, lá lốt, đảo đến khi chín đều thì tắt bếp. Rắc tiêu, ăn nóng với cơm.', 'Mẹo: xào ba chỉ trước cho săn và ra mỡ giúp món thơm, đậm vị hơn.']),
    'ca_tram_kho_khe': ('Cá trắm kho cùng ba chỉ, khế chua, riềng và nước trà xanh lửa liu riu, chua mặn đậm đà.',
        ['Thái thịt ba chỉ miếng chữ nhật, ướp 1/2 muỗng cà phê đường, 1/2 muỗng cà phê tiêu, 1 muỗng canh nước mắm, 1/2 muỗng cà phê bột ngọt.', 'Khế: lấy 1 trái thái nhỏ, vắt lấy 2 muỗng canh nước; phần còn lại cắt lát dày khoảng 7mm.', 'Cá làm sạch, ướp với 1 muỗng cà phê muối, 2 muỗng canh nước mắm, 1 muỗng canh đường, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng canh hạt nêm, 1 muỗng canh hành tím băm, 1/2 muỗng cà phê nước màu, 1/2 muỗng cà phê tiêu và 2 muỗng canh nước khế.', 'Phi dầu điều với riềng lát cho thơm, cho thịt vào xào săn.', 'Lót riềng dưới đáy nồi, xếp cá xen kẽ với thịt, khế lát và ớt hiểm. Đun sôi 2 phút cho cá săn rồi lật mặt.', 'Đổ nước trà xanh nóng ngập cá, đậy nắp; sôi lại thì hạ lửa liu riu đến khi nước kho sệt, cá chín ngấm. Tắt bếp, rắc hành lá và tiêu, ăn nóng với cơm.', 'Mẹo: nước khế giúp cá chua nhẹ, bớt tanh và săn thịt; kho lửa nhỏ, đậy nắp để cá chín kỹ, không khô và thấm đều.']),
    'ca_trung_cham_tuong_me': ('Cá trứng lăn bột chiên giòn, chấm xốt me bơ đậu phộng tương ớt Hàn, ăn kèm rau sống.',
        ['Băm nhuyễn tỏi và lõi sả. Ngâm cá trứng khoảng 5 phút trong ít nước đá pha nước tắc vừa ngập, rồi rửa lại nước lạnh, để ráo, thấm khô.', 'Đun dầu nóng vừa, khoảng 140°C. Cho cá vào tô cùng 1 gói bột tẩm khô chiên giòn, lắc cho bột bám đều.', 'Thả cá vào chiên đến khi chín vàng đều, vớt ra giấy thấm dầu.', 'Pha xốt chấm: khuấy đều 1 muỗng canh tương ớt Hàn Quốc, 1 muỗng canh bơ đậu phộng, 1 muỗng canh nước me, 1 muỗng canh nước mắm, 2 muỗng canh nước lọc, 1 muỗng cà phê tỏi băm, 1 muỗng cà phê sả băm, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê đường.', 'Ăn nóng, chấm cá với xốt cùng rau ghém.', 'Mẹo: dùng lõi sả non để nước chấm thơm mà không xơ; ngâm nước tắc giúp cá bớt tanh; lắc cá trong tô giúp bột bám nhanh, đều.']),
    'ca_trung_chien_bo_toi': ('Cá trứng tẩm bột chiên vàng, xóc với bơ tỏi, ớt sừng và vỏ chanh, thơm béo giòn.',
        ['Bào nhuyễn vỏ chanh Mỹ rồi vắt lấy nước. Ướp cá trứng với 1 muỗng canh nước cốt chanh và 1 muỗng canh tỏi băm.', 'Đun nóng dầu, lăn từng con cá qua bột chiên gà giòn rồi chiên đến khi chín vàng, vớt ra để ráo dầu.', 'Ở chảo khác, phi thơm tỏi với bơ, cho đầu hành và ớt sừng vào đảo.', 'Thêm cá và vỏ chanh vào xóc đều, rắc chút muối rồi trút ra dĩa. Ăn nóng với muối tiêu chanh.', 'Mẹo: vỏ chanh Mỹ cho màu đẹp và mùi thơm nhẹ; xóc cá với bơ tỏi giúp món dậy mùi.']),
    'ca_trung_chien_gion': ('Cá trứng nhúng bột chiên giòn có mè đen, ăn cùng lá húng chiên, rau mầm và xốt mayonnaise tương ớt.',
        ['Áo cá với 2 muỗng canh bột chiên giòn. Phần bột còn lại pha nước theo tỉ lệ ghi trên gói, thêm ít mè đen rang. Lặt lấy lá to của rau húng lủi.', 'Cho 1/2 lít dầu vào chảo, đun nóng, chiên lá húng lủi đến khi xanh giòn rồi vớt ra để ráo.', 'Nhúng cá qua bột đã pha nước, chiên đến khi giòn và chín hẳn, vớt ra giấy thấm dầu.', 'Bày cá cùng rau mầm và lá húng chiên; rưới hỗn hợp xốt mayonnaise với tương ớt theo tỉ lệ 2:1, rắc mè đen, ớt sợi, kèm một miếng chanh.', 'Mẹo: chiên lá húng trước cho dầu thơm rồi mới chiên cá; ăn kèm rau sống, rau thơm cho đỡ ngán.']),
    'ca_xao_can_toi': ('Cá lóc phi lê ướp thì là, xào săn cùng cần tây, ớt chuông, bắp non, đậu Hà Lan, giòn ngọt.',
        ['Cá lóc phi lê cắt miếng dày 5mm, dài 4cm; ướp với chút hành tím, tiêu, hạt nêm, gừng băm, đường, giấm gạo và thì là băm, trộn thêm ít bột năng, để 20 phút.', 'Ớt chuông cắt dài, hành tây thái mỏng, cần tây cắt xéo, boaro bổ đôi cắt khúc 4cm. Cà rốt tỉa hoa cắt khoanh; nấm mèo ngâm nở cắt khúc 3cm; hành lá, thì là cắt khúc.', 'Chần bắp non, đậu Hà Lan, cà rốt trong nước sôi có chút muối, vớt ra thả ngay vào nước đá cho giữ màu.', 'Phi thơm tỏi và gừng, cho cá vào xào săn rồi trút ra riêng.', 'Phi tiếp hành tỏi, xào lần lượt ớt chuông, hành tây, cần tây, boaro, nấm mèo cùng chút nước dùng; thêm đậu Hà Lan, bắp non, cà rốt, nêm chút muối, hạt nêm, tiêu và 1 muỗng cà phê giấm gạo, đảo đều.', 'Múc cá và rau ra dĩa, rắc ngò rí, ớt, tiêu, ăn nóng.', 'Mẹo: thịt cá dễ nát nên xào lửa lớn, nhanh tay; ướp chút giấm giúp giảm tanh; chần rau củ với muối để giữ màu.']),
    'ca_xao_la_que': ('Cá điêu hồng phi lê tẩm bột chiên giòn, xóc cùng lá quế, thì là, ớt sừng, thơm nồng.',
        ['Cá điêu hồng lọc phi lê, cắt miếng khoảng 2x4cm, ướp với 1/2 muỗng cà phê bột nghệ.', 'Lá quế cắt đôi; thì là và hành lá cắt khúc 3cm; ớt sừng bỏ hạt, cắt hình thoi.', 'Áo cá với 1 gói bột chiên gà giòn, chiên ngập dầu đến khi vàng chín, vớt ra để ráo.', 'Phi thơm 1 muỗng cà phê tỏi băm, xào lá quế, ớt sừng, hành lá; cho cá vào xóc đều cùng 2 muỗng canh nước.', 'Cuối cùng thêm thì là, đảo nhẹ rồi tắt bếp, ăn nóng.', 'Mẹo: bột nghệ giúp cá lên màu đẹp, thơm và bớt tanh; có thể đổi sang loại cá phi lê khác.']),
    'cai_bo_xoi_xao_thit': ('Cải bó xôi xào nhanh với thịt heo, cà rốt, rắc mè rang, chấm nước tương củ cải mài.',
        ['Thái mỏng thịt heo, ướp 1 muỗng cà phê hành tỏi băm, 1 muỗng canh củ cải trắng mài, 1/2 muỗng canh hạt nêm và chút tiêu.', 'Cải bó xôi cắt khúc 5cm, cà rốt thái sợi.', 'Pha nước chấm: 1/3 chén nước tương, 1 muỗng canh củ cải trắng mài và 1 muỗng canh mè rang giã nhuyễn.', 'Phi thơm hành tỏi, xào thịt săn, cho cà rốt và cải bó xôi vào, thêm 1 muỗng canh nước, nêm 1 muỗng canh nước tương và 1/2 muỗng canh hạt nêm rồi tắt bếp.', 'Cho ra dĩa, rắc mè rang, chấm kèm nước tương đã pha.', 'Mẹo: cải bó xôi rất mau chín, đừng xào lâu; giã dập mè cho nước chấm béo thơm.']),
    'cai_ngong_tron_ga_xe': ('Cải ngồng luộc giòn xếp dưới gà xé, cà rốt, hành tây trộn xốt mayonnaise mè, chua ngọt béo.',
        ['Luộc chín ức gà rồi xé sợi. Cà rốt thái sợi, trộn 1/2 muỗng cà phê đường rồi vắt ráo. Hành tây cắt ngang dày 2mm, trộn 1 muỗng cà phê đường để 15 phút, vắt ráo.', 'Chừa phần hoa cải ngồng đẹp để trang trí; phần còn lại tước xơ, luộc trong nước sôi có muối, xả nước lạnh, để ráo, cắt khúc 5cm và xếp lên dĩa.', 'Pha xốt: trộn 3 muỗng canh xốt mayonnaise vị ngọt dịu, 1 muỗng canh mè trắng rang giã nhuyễn, mỗi thứ 1 muỗng cà phê dầu hào, tương ớt, tương cà, giấm gạo, dầu mè và 1/3 muỗng cà phê muối.', 'Trộn gà, cà rốt, hành tây với xốt rồi đặt lên trên cải ngồng.', 'Rắc 1 muỗng canh mè rang, trang trí húng lủi, ớt sợi và hoa cải ngồng.', 'Mẹo: cắt ngang củ hành tây để bớt hăng; rang và giã mè giúp món thơm mùi mè.']),
    'cai_thao_goi_tom_thit': ('Lá cải thảo gói nhân thịt tôm củ năng, hấp chín, chấm xốt cà chua sánh, ngọt thanh.',
        ['Băm nhỏ tôm, trộn với thịt, 1/2 muỗng canh muối, 1 muỗng cà phê đầu hành băm, 1 muỗng canh đường, 1 muỗng canh bột ngọt, 1 muỗng canh dầu mè, 1/2 muỗng canh tiêu; nắm nhân quật mạnh xuống thau cho dai.', 'Chần sơ cải thảo, để ráo. Hành lá thái nhỏ; hòa 1 muỗng canh bột năng với chút nước.', 'Trộn củ năng, hành lá vào nhân cùng 1,5 muỗng canh bột năng và 2 muỗng canh tỏi phi, nhồi đều; chia viên nhỏ và gói bằng lá cải thảo.', 'Xếp các gói vào xửng, hấp chín khoảng 15 phút.', 'Làm xốt: phi thơm hành tây với 1 muỗng canh dầu, xào cà chua đến cạn nước; thêm 2 muỗng canh xốt cà, 4 muỗng canh nước, 1 muỗng canh dầu mè, 1/3 muỗng canh muối, 1/2 muỗng canh bột ngọt, 1/2 muỗng cà phê đường, cuối cùng cho 1 muỗng canh nước bột năng, nêm lại rồi tắt bếp.', 'Bày cải ra dĩa, chấm với xốt.', 'Mẹo: chần nhanh cải rồi nhúng nước đá để lá tươi, không nhũn; tỏi phi giúp nhân thơm mà không hăng.']),
    'cai_thao_xao_so_diep': ('Cải thảo, cà rốt, đậu Hà Lan xào cùng sò điệp và gừng, nêm nước tương, sánh nhẹ, ngọt thanh.',
        ['Chần sơ sò điệp trong nước sôi có ít gừng đập dập, vớt ra để ráo rồi trộn với 1 muỗng cà phê bột năng.', 'Cải thảo cắt sợi xéo dày 1cm, cà rốt thái sợi, đậu Hà Lan cắt xéo, gừng thái sợi thật nhỏ.', 'Phi thơm ít tỏi băm và gừng sợi với 2 muỗng canh dầu, cho sò điệp vào xào lửa lớn rồi trút ra.', 'Thêm 2 muỗng canh dầu, phi 1 muỗng canh tỏi băm, xào đậu Hà Lan, cà rốt, cải thảo; nêm 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1/4 muỗng cà phê muối và 1,5 muỗng canh nước tương.', 'Khi rau chín, trút sò điệp vào trộn đều, thêm chút nước bột năng cho sánh rồi tắt bếp. Bày ra dĩa, rắc ngò rí và tiêu.', 'Mẹo: chần sò và phi gừng để bớt tanh; xào sò nhanh trên lửa lớn để sò không teo, không chảy nước.']),
    'cai_thao_xao_tim_heo': ('Tim heo thái mỏng xào lửa to cùng cải thảo, nấm đông cô, cà chua bi, chấm nước tương ớt.',
        ['Tim heo làm sạch, thái lát mỏng, ướp 1/4 muỗng cà phê tiêu, 1 muỗng cà phê hành tỏi băm, 1/2 muỗng cà phê hạt nêm.', 'Cải thảo cắt xéo khúc 2cm, nấm đông cô thái sợi, cà bi bổ đôi, hành ngò cắt khúc.', 'Phi thơm hành tỏi, xào tim heo lửa to đến gần chín, thêm chút nước rồi cho nấm, cuống cải, lá cải và cà chua bi vào đảo.', 'Nêm 1 muỗng cà phê hạt nêm, đảo đều, tắt bếp, rắc tiêu và hành ngò. Ăn nóng, chấm nước tương với ớt lát.', 'Mẹo: cắt nấm vừa miếng, đừng nhỏ quá kẻo nhũn; chọn tim heo hồng tươi, bóng, đủ lớn.']),
    'cai_thao_xao_tom_kho': ('Cải thảo xào với tôm khô, ba rọi, nấm mèo và cà rốt, giòn ngọt, đậm vị biển.',
        ['Ngâm tôm khô trong 1 chén nước ấm khoảng 80°C chừng 15 phút cho mềm, vớt ra giã sơ.', 'Cải thảo bỏ bớt lá, cắt khúc 3cm; cà rốt thái lát mỏng; nấm mèo ngâm nở, cắt khúc 2cm; ba rọi thái sợi nhỏ; hành lá cắt khúc.', 'Phi thơm tỏi với 2 muỗng canh dầu, xào ba rọi ra mỡ rồi cho tôm khô vào, nêm 2 muỗng cà phê giấm gạo.', 'Cho cải thảo, cà rốt, nấm mèo vào xào cùng 2 muỗng canh nước; nêm 2 muỗng cà phê hạt nêm, 1 muỗng cà phê bột ngọt, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê nước mắm.', 'Rau vừa chín thì thả hành lá, đảo đều, tắt bếp. Bày ra dĩa, trang trí ớt sừng sợi, ăn nóng.', 'Mẹo: chút giấm gạo giúp rau giòn và món thêm đậm đà.']),
    'cai_thia_xao_nam_dong_co_thit_cua': ('Cải thìa xào nhanh, phủ nấm đông cô và thịt cua nấu xốt dầu hào sánh, thanh ngọt.',
        ['Nấm đông cô cắt bỏ chân. Hòa 1 muỗng canh bột năng với 2 muỗng canh nước.', 'Đun sôi nồi nước có chút muối và dầu ăn, luộc sơ nấm và cải thìa rồi vớt ra; xả cải qua nước lạnh, để ráo.', 'Pha nước xốt: 1 chén nước, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê đường, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê dầu hào, 1 muỗng canh nước tương.', 'Phi thơm 1/2 muỗng canh tỏi, xào nấm, rưới 1 muỗng canh rượu trắng; đổ nước xốt vào (chừa lại 2 muỗng canh), nấu lửa vừa 5 phút, hạ nhỏ lửa rồi khuấy nước bột năng vào cho sệt. Thêm thịt cua và 1 muỗng cà phê dầu mè, đảo đều, giữ nóng.', 'Phi phần tỏi còn lại, xào nhanh cải thìa trên lửa lớn, thêm 1 muỗng canh rượu trắng và 2 muỗng canh nước xốt đã chừa, đảo đều rồi tắt bếp.', 'Xếp cải vào dĩa sâu lòng, đổ nấm thịt cua lên, trang trí ngò rí và ớt sợi.', 'Mẹo: luộc cải với chút dầu giúp rau giữ màu xanh lâu; hạ lửa trước khi cho bột năng để xốt mịn, không vón.']),
    'cai_xoong_xao_tom': ('Cải xoong xào tỏi dầu hào, phủ tôm ướp ớt bột và nấm đùi gà áp chảo, đậm đà.',
        ['Nấm đùi gà chẻ đôi, thái lát xéo; cải xoong cắt khúc 6cm; ớt sừng bỏ hạt, thái sợi.', 'Tôm bóc vỏ chừa đuôi, xẻ lưng, ướp 1/4 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê ớt bột, 1 muỗng cà phê hành tím băm, 1 muỗng cà phê ngò rí thái nhỏ.', 'Đun nóng 1 muỗng canh dầu, áp chảo tôm cho săn, thêm nấm vào xào, nêm 1/2 muỗng canh dầu hào; khi tôm và nấm chín thì trút ra dĩa.', 'Phi thơm tỏi với 2 muỗng canh dầu, cho cải xoong vào, nêm 1/3 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1 muỗng canh dầu hào; xào vừa chín thì thêm ớt sợi, nếm lại rồi tắt bếp.', 'Bày cải ra dĩa, xếp tôm và nấm lên trên, ăn nóng với cơm.', 'Mẹo: ướp tôm với chút ớt bột cho thơm lạ miệng; xào tôm ít dầu để tôm ráo và săn.']),
    'canh_bach_qua_bi_do': ('Canh chay bí đỏ, bạch quả, hạt sen, nấm hương, tàu hũ ky nấu nước dừa, ngọt bùi thanh nhẹ.',
        ['Bí đỏ cắt miếng vừa ăn, tàu hũ ky cắt khúc 2cm, cà rốt tỉa hoa, đậu Hà Lan tước chỉ hai bên. Nấm hương khô ngâm mềm, cắt bỏ chân; bạch quả dùng tăm khều bỏ tim.', 'Phi thơm hành boaro với dầu, cho tàu hũ ky và nấm hương vào xào nhanh, nêm 1/2 muỗng canh nước tương, đảo đều.', 'Đổ 2 chén nước dừa và 1 lít nước vào, nêm 1 muỗng cà phê đường, 1 muỗng cà phê bột ngọt, 1,5 muỗng canh hạt nêm nấm hương, khuấy đều rồi để lửa nhỏ.', 'Nấu đến khi bí đỏ, bạch quả, hạt sen, đậu Hà Lan, cà rốt chín mềm thì tắt bếp, thêm 1 muỗng cà phê dầu mè, đảo đều.', 'Múc ra tô, rắc ngò gai thái nhỏ, hành boaro phi và tiêu, ăn nóng với cơm trắng.', 'Mẹo: xào tàu hũ ky và nấm trước cho ngấm vị; nước dừa cho vị ngọt tự nhiên; bỏ tim bạch quả để không đắng.']),
    'canh_bap_cai_goi_thit': ('Lá bắp cải gói nhân thịt, giò sống, nấm, buộc lá hành, nấu nước hầm xương ngọt thanh.',
        ['Tách lá bắp cải, chần qua nước sôi có chút muối. Hành lá rửa sạch: đầu hành băm nhuyễn, lá hành chần sơ.', 'Nấm mèo ngâm nở, thái sợi, trộn chút tiêu; nấm hương ngâm nở, thái sợi. Cà rốt gọt vỏ: 50g tỉa hoa thái lát, 30g thái sợi. Ngò rí thái nhỏ, để riêng cọng và lá.', 'Trộn nhân: thịt xay, 1 muỗng canh cà rốt sợi, 1 muỗng canh nấm mèo, 1 muỗng canh nấm hương, 1 muỗng cà phê hành phi, 1 muỗng cà phê đầu hành, cọng ngò băm; nêm 1 muỗng cà phê hạt nêm, 1/3 muỗng cà phê muối, 1/3 muỗng cà phê tiêu; sau cùng cho giò sống vào, dàn đều bằng muỗng.', 'Đặt nhân vào lá bắp cải, gói lại, để lát cà rốt hoa lên trên và buộc bằng lá hành.', 'Đun sôi 1 lít nước hầm xương, thả các gói bắp cải vào, nêm 1 muỗng canh hạt nêm, 1/2 muỗng canh nước mắm, 1/2 muỗng cà phê tiêu, nấu đến khi chín thì tắt bếp. Múc ra tô, rắc hành ngò, ăn nóng với cơm.', 'Mẹo: chọn bắp cải Đà Lạt bắp lớn, gân nhỏ cho dễ gói; nếu không có nước hầm xương thì dùng 1,5 muỗng canh hạt nêm cho 1 lít nước.']),
    'canh_bau_nau_rieu_tep': ('Canh bầu sợi nấu riêu tép giã lọc, nêm nhạt, thêm hành phi, ngọt mát kiểu quê.',
        ['Bầu thái sợi; hành lá, ngò rí thái nhỏ.', 'Giã nhuyễn tép trong cối, thêm 1 lít nước khuấy rồi lọc bỏ xác, lấy nước.', 'Đun sôi nước tép, hạ lửa nhỏ cho riêu đóng lại, vớt riêu ra để riêng.', 'Đun sôi lại nước, cho bầu vào nấu, nêm 1 muỗng cà phê muối, 1,5 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt; trả riêu vào, để thêm 1–2 phút rồi tắt bếp.', 'Múc ra tô, rắc hành, ngò, tiêu và hành phi, ăn nóng.', 'Mẹo: chọn tép còn sống, thân trong và bóng; đổ nước từ từ và lọc vài lần để lấy hết chất ngọt của tép.']),
    'canh_bi_dao_don_thit': ('Bí đao nhồi giò sống thịt xay hấp rồi cắt khoanh, nấu canh cùng tôm và thịt viên, thanh mát.',
        ['Bí gọt vỏ, cắt ngang một đầu làm nắp, khoét bỏ ruột. Tôm bóc vỏ bỏ đuôi, xẻ lưng. Nấm mèo ngâm nở, thái sợi, trộn 1/2 muỗng cà phê tiêu. Hành lá, ngò rí thái nhỏ; hành tím và hành phi băm nhỏ; cà rốt thái sợi.', 'Làm nhân: trộn giò sống, thịt xay, nấm mèo, cà rốt, 1/2 muỗng cà phê hành tím băm, cọng ngò, 1/2 muỗng cà phê tiêu, 1,5 muỗng cà phê hạt nêm; quật nhân xuống tô cho dai.', 'Nhồi nhân đầy ruột bí và phần nắp, ghim nắp vào thân bằng tăm. Đặt lên dĩa, hấp 15 phút, để nguội rồi cắt khoanh dày 3cm. Nhân còn dư thì vo viên.', 'Đun sôi 1 lít nước, thả bí và thịt viên vào nấu đến khi bí gần chín thì cho tôm vào, nêm 2 muỗng canh hạt nêm và 1/2 muỗng cà phê bột ngọt, tắt bếp.', 'Múc ra tô, rắc tiêu, hành lá, ngò rí, ăn với cơm nóng.', 'Mẹo: làm ướt tay khi vo viên để nhân không dính; canh bí chỉ nêm hạt nêm, không dùng nước mắm để canh khỏi bị chua.']),
    'canh_bi_dao_nau_suon_non': ('Sườn non hầm lấy nước ngọt rồi nấu cùng bí đao vừa chín tới, canh trong, thanh mát.',
        ['Bí đao gọt vỏ, chẻ tư, bỏ bớt ruột, cắt miếng dày khoảng 1cm.', 'Sườn non chặt khúc 2cm, ướp 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu và ít hành tím đập dập băm nhỏ, để 15 phút.', 'Rửa sạch hành lá, ngò rí; rễ ngò rửa với nước vo gạo, đầu hành đập dập để riêng; lá hành và ngò thái nhỏ.', 'Đun sôi 1 lít nước, cho sườn và rễ ngò vào; sôi lại thì hạ lửa hầm khoảng 15 phút cho ngọt nước.', 'Thả bí vào nấu vừa chín tới, nêm 1,5 muỗng canh hạt nêm, nếm lại rồi tắt bếp. Múc ra tô, rắc hành ngò, tiêu, ăn nóng với cơm.', 'Mẹo: chọn bí già cho ngọt, bỏ bớt ruột để canh không chua; cho đầu hành và rễ ngò vào nồi hầm giúp nước dùng thơm.']),
    'canh_bi_dao_rong_bien': ('Canh bí đao nấu tôm quết vo viên và rong biển wakame, ngọt thanh, ít muối.',
        ['Bí đao gọt vỏ, chẻ tư, bỏ bớt ruột, cắt miếng dày khoảng 0,5cm.', 'Tôm bóc vỏ, lau khô, đập dập rồi băm nhỏ; ướp 1/2 muỗng cà phê hạt nêm giảm muối, 1/2 muỗng cà phê tiêu, chút hành tím đập dập băm nhỏ, quết cho dai, để 15 phút.', 'Hành lá, ngò rí thái nhỏ. Rong biển ngâm nở, vớt ra để ráo.', 'Đun sôi 1,2 lít nước, nấu bí trước; bí vừa chín thì vo tôm thành viên thả vào, sôi lại thì hạ lửa, cho rong biển vào.', 'Nêm 1,5 muỗng canh hạt nêm giảm muối, nếm vừa ăn rồi tắt bếp, thêm hành lá, ngò rí. Múc ra tô, rắc ít tiêu xay.', 'Mẹo: quết tôm trước khi vo để viên dai; cho rong biển sau cùng để khỏi nát.']),
    'canh_bi_dao_suon_non': ('Canh bí đao với sườn non hầm rễ ngò, bí vừa chín giòn ngọt, nước trong thanh mát.',
        ['Gọt vỏ bí đao, chẻ làm tư, bỏ ruột rồi cắt miếng dày chừng 1cm.', 'Chặt sườn non thành khúc 2cm, ướp 1 muỗng canh hạt nêm, 1/2 muỗng canh tiêu cùng chút hành tím đập dập băm nhỏ trong 15 phút.', 'Rửa hành lá, ngò rí; rễ ngò rửa kỹ bằng nước vo gạo, đầu hành đập dập. Lá hành và ngò rí thái nhỏ.', 'Nấu sôi 1 lít nước, thả sườn và rễ ngò vào; khi sôi lại thì vặn nhỏ lửa, hầm chừng 15 phút.', 'Cho bí vào nấu đến khi vừa chín tới, còn giòn ngọt; nêm 1,5 muỗng canh hạt nêm, nếm lại rồi tắt bếp.', 'Múc canh ra tô, rắc hành ngò và tiêu, ăn nóng cùng cơm trắng.', 'Mẹo: bí già ngọt hơn; khoét bỏ ruột để canh không chua; đầu hành và rễ ngò giúp nước hầm thơm, ngọt.']),
    'canh_bi_ngoi_nau_nam': ('Canh sườn non nấu bí ngòi, nấm đông cô, cà rốt và đậu hũ non, ngọt thanh dịu nhẹ.',
        ['Sườn non rửa sạch, chặt miếng vừa ăn, để ráo. Bí ngòi cắt miếng; cà rốt tỉa hoa thái mỏng; nấm đông cô cắt tư; đậu hũ non cắt khối vuông; hành ngò thái nhỏ.', 'Cho sườn, cà rốt, nấm đông cô vào 1,5 lít nước, nấu khoảng 10 phút.', 'Thả bí ngòi vào, nêm 2 muỗng canh hạt nêm, sau cùng cho đậu hũ.', 'Canh sôi lại thì rắc hành ngò, tiêu rồi tắt bếp. Múc ra tô, ăn nóng với cơm.', 'Mẹo: chọn bí ngòi vỏ căng bóng, xanh, cầm nặng tay; cho bí vào sau để giữ chất và không bị nhũn.']),
    'canh_bi_ngoi_quan_tom': ('Lát bí ngòi cuộn viên tôm quết, buộc lá hành, nấu canh nhanh với cà rốt, ngọt mát.',
        ['Tôm sú bỏ đầu, vỏ và đuôi, đập dập rồi quết nhuyễn với đầu hành lá băm, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê hạt nêm; vo thành viên nhỏ.', 'Bí ngòi rửa sạch, bỏ cuống, bào lát mỏng theo chiều dọc. Hành lá: một phần thái nhỏ, phần còn lại để nguyên cọng, trụng nước sôi cho mềm. Cà rốt tỉa hoa, thái mỏng.', 'Đặt viên tôm vào giữa lát bí, cuộn lại và buộc bằng cọng hành.', 'Đun sôi 1 lít nước, nêm 1,5 muỗng cà phê hạt nêm, cho cà rốt và bí cuộn tôm vào nấu khoảng 5 phút đến khi chín.', 'Múc ra tô, rắc tiêu, trang trí ngò rí, ăn với cơm.', 'Mẹo: giữ nguyên vỏ bí, bào theo chiều dài để cuộn dễ và đẹp; dùng tôm còn sống, quết sẽ dai ngon hơn.']),
    'canh_bi_do_dau_phong': ('Canh bí đỏ nấu đậu phộng giã dập và thịt viên, thêm rau om ngò gai, bùi béo ngọt.',
        ['Đậu phộng để nguyên vỏ lụa, luộc sẵn.', 'Ướp thịt nạc vai xay với 1 muỗng cà phê hạt nêm gà, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê đường, 1 muỗng cà phê hành tím băm, rồi vo viên tròn.', 'Bí đỏ gọt vỏ, cắt khối vuông bằng dao răng cưa, ướp 1 muỗng cà phê hạt nêm gà.', 'Đun sôi 1,2 lít nước, giã dập đậu phộng rồi nấu cùng thịt viên đến khi đậu mềm và nước ngọt; nêm 2 muỗng cà phê hạt nêm gà.', 'Cho bí đỏ vào nấu thêm 10 phút đến khi vừa mềm, thêm rau om, ngò gai và 1 muỗng canh nước mắm, đảo đều rồi bắc xuống. Múc ra tô, ăn nóng.', 'Mẹo: ngâm đậu phộng nước lạnh để mau mềm; chọn bí đỏ hai da cho dẻo; thịt nạc vai có chút mỡ giúp viên không khô.']),
    'canh_bi_do_dau_xanh': ('Canh bí đỏ hạt lựu nấu đậu xanh và thịt băm, thêm rau om, ngọt bùi dễ ăn.',
        ['Ướp thịt băm với 1/2 muỗng cà phê hạt nêm, 1/4 muỗng cà phê tiêu, hành tím băm.', 'Ngâm mềm đậu xanh; bí đỏ cắt hạt lựu; rau om, ngò gai thái nhỏ.', 'Đun sôi 1,5 lít nước, cho thịt băm vào, hớt bọt.', 'Thêm bí đỏ và đậu xanh, nêm 2 muỗng canh hạt nêm, 1 muỗng cà phê đường, nấu đến khi bí chín mềm thì tắt bếp, cho rau om vào.', 'Múc ra tô, ăn nóng với cơm.', 'Mẹo: có thể thay thịt bằng tôm; chọn bí hai da, trái tròn, ruột cam đỏ để canh dẻo ngon.']),
    'canh_bi_do_hanh_nhan': ('Bí đỏ nấu nước dùng xương gà với viên giò sống gắn tôm, rắc hạnh nhân, ngọt bùi thơm.',
        ['Tôm đất lột vỏ chừa đuôi, rút chỉ. Xương gà chần nước sôi, rửa lại. Bí đỏ cắt miếng 2cm, ướp 1 muỗng cà phê muối, 1 muỗng cà phê đường.', 'Trộn nhân: giò sống, cà rốt, nấm mèo, nấm hương, 1 muỗng canh đầu hành lá băm, 1 muỗng cà phê cọng ngò băm, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê hạt nêm và 20g hạnh nhân bóp vụn.', 'Vo nhân thành viên, gắn một con tôm vào mỗi viên, đuôi hướng lên.', 'Nấu 2 lít nước với xương gà, hành tím nướng và 1 muỗng canh hạt nêm trong 30 phút, rồi lọc lấy nước dùng.', 'Đun sôi nước dùng, cho bí đỏ vào nấu chín, thả viên tôm vào đến khi viên nổi lên; rắc 30g hạnh nhân còn lại, nêm 1 muỗng cà phê nước mắm rồi tắt bếp. Múc ra tô, rắc tiêu và ngò rí.', 'Mẹo: ướp bí với muối đường cho thấm vị; để viên tôm trong ngăn mát 10 phút cho định hình trước khi nấu.']),
    'canh_bi_do_rong_bien': ('Canh chay bí đỏ xào sơ, nấu với nấm kim châm, rong biển, rắc sườn chay chiên giòn.',
        ['Sườn chay rửa sạch, xé nhỏ, ướp 1/2 muỗng cà phê hạt nêm nấm hương, vắt ráo rồi chiên ngập dầu đến vàng giòn.', 'Bí đỏ cắt khối 2cm; hành boaro thái lát mỏng; nấm kim châm cắt gốc, tách nhỏ; ngò rí thái nhỏ.', 'Phi thơm hành boaro, cho bí đỏ vào xào, nêm 1/2 muỗng cà phê hạt nêm nấm hương.', 'Đổ 1,2 lít nước, đun sôi, nêm 1 muỗng cà phê hạt nêm nấm hương, 1/4 muỗng cà phê muối, 1/4 muỗng cà phê đường; nấu đến khi bí vừa chín tới.', 'Nếm lại, thả nấm kim châm và rong biển vào, sôi lại thì tắt bếp. Múc ra tô, rắc ngò rí, tiêu và sườn chay chiên lên trên.', 'Mẹo: xào bí với gia vị trước cho ngấm; cho rong biển sau cùng để không mềm nhũn.']),
    'canh_ca_chua_nau_dau': ('Canh cà chua nấu thịt viên, đậu hũ chiên và đậu que, điểm trứng cút ốp la, chua ngọt nhẹ.',
        ['Xay nhỏ thịt nạc dăm, ướp 1/3 muỗng cà phê muối, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê hành tím băm, 1/3 muỗng cà phê tiêu, rồi vo viên.', 'Đậu que cắt xéo, cà chua cắt múi, đậu hũ cắt khối vuông chiên vàng; hành lá, ngò rí cắt khúc.', 'Phi thơm hành tím, xào cà chua với 1/3 muỗng cà phê muối, 1/3 muỗng cà phê đường, thêm 1 lít nước, đun sôi rồi thả thịt viên, nấu khoảng 5 phút.', 'Cho đậu hũ và đậu que vào nấu chín tới, nêm 1 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1 muỗng cà phê nước mắm; nếm lại, rắc hành ngò rồi tắt bếp.', 'Chiên ốp la 3 quả trứng cút trong chảo nhỏ với ít dầu. Múc canh ra tô, đặt trứng lên trên.', 'Mẹo: cắt đậu que xéo, mỏng để chín đều cùng các nguyên liệu khác.']),
    'canh_ca_chua_thit_bo': ('Canh cà chua khoai tây với viên thịt bò trộn heo và ngò gai, chua ngọt, màu đỏ đẹp.',
        ['Ngò gai băm nhỏ; hành lá, ngò rí thái nhỏ; cà chua cắt múi cau; khoai tây cắt khối vuông nhỏ.', 'Trộn thịt bò với thịt heo, ướp 1 muỗng cà phê hành tím băm, ngò gai băm, 1/3 muỗng cà phê muối, 1/3 muỗng cà phê tiêu, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê bột ngọt, rồi vo viên.', 'Phi thơm hành với dầu, xào cà chua cùng 1/3 muỗng cà phê muối, 1/3 muỗng cà phê đường, trút ra tô.', 'Cho 1 lít nước và khoai tây vào nồi, nêm 1/2 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, đậy nắp nấu. Nước sôi khoảng 5 phút thì thả thịt viên, nấu đến khi chín mềm.', 'Trả cà chua vào, sôi lại thì nêm 1 muỗng canh nước mắm, thêm hành lá, ngò rí rồi tắt bếp. Ăn nóng với cơm.', 'Mẹo: trộn bò với heo cho viên thơm mà mềm; xào cà chua trước giúp canh lên màu đẹp.']),
    'canh_ca_com_la_me_dat': ('Canh cá cơm nấu sả, cà chua và lá me đất chua dịu, cay nhẹ ớt bột.',
        ['Cá cơm rửa sạch, ướp 1 muỗng cà phê bột canh và 1/3 muỗng cà phê ớt bột. Sả cắt khúc 5cm đập dập; cà chua cắt múi cau; ớt hiểm thái lát; hành lá cắt khúc 3cm.', 'Phi thơm sả với 2 muỗng canh dầu, xào sơ cà chua, nêm 1 muỗng cà phê đường, 1/2 muỗng cà phê muối.', 'Đổ 1,2 lít nước, đun sôi, nêm 1 muỗng cà phê bột canh, 1 muỗng cà phê đường rồi thả cá cơm vào.', 'Nước sôi lại thì tắt bếp, cho lá me đất vào, nêm 1/2 muỗng canh nước mắm, thêm ớt và hành lá. Múc ra tô, ăn kèm nước mắm nguyên chất với ớt lát.', 'Mẹo: chọn cá cơm còn nguyên con, da ánh bạc; tắt bếp rồi mới thả lá me để lá vừa chín, giữ màu đẹp.']),
    'canh_ca_khoai_la_giang': ('Canh chua cá khoai nấu lá giang, thơm và cà chua, thêm rau om ngò gai, chua thanh.',
        ['Cá khoai cắt khúc 5cm, ướp 1 muỗng canh hành tỏi băm, 1/4 muỗng cà phê muối, 1/4 muỗng cà phê bột ngọt, 1/2 muỗng cà phê tiêu và 1 muỗng cà phê nước cốt chanh.', 'Lá giang vò sơ; thơm thái lát; cà chua cắt múi cau; rau om, ngò gai thái nhỏ; ớt hiểm đập dập.', 'Phi thơm 1 muỗng canh hành tỏi băm, xào sơ cà chua với ít muối, đường, rồi đổ 1 lít nước vào đun sôi.', 'Thêm thơm, ớt và lá giang, nấu cho lá giang ra vị chua; nêm 1 muỗng canh muối, 2 muỗng cà phê bột ngọt, 1 muỗng canh đường, 1 muỗng canh nước mắm, nếm lại.', 'Thả cá khoai vào, canh sôi lại thì tắt bếp, thêm rau om, ngò gai. Múc ra tô, ăn với cơm trắng.', 'Mẹo: ướp chút nước cốt chanh để cá bớt tanh; chọn cá khoai trắng, bụng nhỏ, còn nguyên con.']),
    'canh_ca_loc_la_giang': ('Cá lóc xóc sả tỏi ớt rồi nấu canh chua với cà chua và lá giang, thơm cay nhẹ.',
        ['Cá rửa sạch để ráo, ướp 1 muỗng canh nước mắm và 1 muỗng cà phê bột ngọt khoảng 15 phút.', 'Cà chua cắt múi cau; lá giang vò nát; rau om, ngò gai thái nhỏ.', 'Phi thơm tỏi, sả, ớt với dầu, cho cá vào xóc cho săn rồi thêm cà chua đảo nhanh.', 'Đổ 1,2 lít nước nóng vào, nấu sôi, nêm 1 muỗng cà phê muối, 1 muỗng canh đường, 1 muỗng canh nước mắm, 1 muỗng canh giấm gạo, 1/2 muỗng canh bột ngọt.', 'Cho lá giang vào nấu thêm 5 phút rồi tắt bếp. Múc ra tô, rắc tỏi phi, rau om, ngò gai, ăn nóng.', 'Mẹo: ướp cá trước giúp đậm vị; xóc nhanh cá trước khi nấu để cá thơm và không nát.']),
    'canh_ca_nau_me': ('Cá lóc chiên vàng nấu nước mẻ pha nghệ cùng cà chua, thì là, chua dịu kiểu Bắc.',
        ['Cá cắt khúc 3cm, ướp 1/2 muỗng cà phê bột canh.', 'Cà chua: 1 quả thái nhỏ, 2 quả cắt múi cau. Hành khô thái lát mỏng; hành lá, thì là cắt khúc 2cm. Lọc mẻ lấy nước; nghệ giã dập lấy nước cốt, trộn vào nước mẻ.', 'Đun nóng dầu, chiên cá vàng hai mặt rồi gắp ra.', 'Phi hành, xào phần cà chua thái nhỏ, nêm 1/2 muỗng cà phê đường, 1/2 muỗng cà phê bột canh, rồi đổ nước mẻ và 1 lít nước lọc vào, đun sôi.', 'Cho cá chiên và cà chua múi cau vào, hạ nhỏ lửa, nêm thêm 1,5 muỗng cà phê bột canh, đun khoảng 5 phút; cuối cùng nêm 1 muỗng canh nước mắm rồi tắt bếp.', 'Múc ra tô, thêm hành lá, thì là, ăn nóng.', 'Mẹo: pha nghệ vào mẻ cho canh vàng đẹp; chiên cá trước để hết tanh và dậy mùi.']),
    'canh_ca_ro_nau_cai_be_xanh': ('Canh cải bẹ xanh nấu thịt cá rô gỡ xương, thêm gừng và hành tím, ngọt thanh ấm nhẹ.',
        ['Đun sôi khoảng 1 tô nước với 1/2 muỗng cà phê muối và chút gừng, cho cá rô vào luộc 5–7 phút. Vớt ra để nguội, gỡ lấy thịt; giữ nước luộc làm nước dùng.', 'Phi thơm hành tím, cho thịt cá vào rồi tắt bếp, nêm 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, đảo nhẹ tay.', 'Đun sôi nước luộc cá, hớt bọt, thêm chút gừng sợi, nêm 1 muỗng cà phê muối.', 'Cho cọng cải vào trước khoảng 1 phút rồi thêm lá cải; khi cải gần chín thì thả cá và gừng vào, nêm 1 muỗng cà phê bột ngọt, tắt bếp và nêm 1 muỗng canh nước mắm.', 'Múc ra tô, rắc tiêu, gừng, hành tím, ăn kèm nước mắm ớt.', 'Mẹo: cải xanh tính hàn nên thêm gừng cho cân bằng; lóc hai bên xương cá để dễ gỡ thịt; cá rô mề to, có trứng giúp canh béo ngon.']),
    'canh_cai_cau_vong_nau_cua': ('Canh cua đồng với chả cua trộn giò sống, nấm linh chi trắng và cải cầu vồng, ngọt thanh.',
        ['Phi thơm hành tím băm với 1 muỗng canh dầu, để riêng cả dầu lẫn hành phi. Đầu hành lá đập dập, thái nhỏ; cải cầu vồng cắt khúc 2cm; nấm tách nhỏ.', 'Hòa cua xay từ từ với 1,3 lít nước rồi lọc lấy nước cua.', 'Đun sôi nước cua, hạ lửa để riêu nổi lên, tắt bếp, cho dầu hành phi vào rồi vớt riêu ra.', 'Làm chả cua: trộn riêu với giò sống, đầu hành lá, hành phi, 1/3 muỗng cà phê tiêu, quết cho dai.', 'Đun sôi lại nước cua, múc từng muỗng chả thả vào nồi cùng nấm; khi chả nổi thì cho cải cầu vồng vào nấu chín, nêm 1 muỗng cà phê hạt nêm, 1/3 muỗng cà phê muối, 1/2 muỗng cà phê đường, 1 muỗng cà phê nước mắm, nếm lại. Múc ra tô, ăn nóng với cơm.', 'Mẹo: trộn giò sống giúp chả cua giữ hình; nước cua sôi thì giảm lửa để riêu không vỡ.']),
    'canh_cai_chua_nau_ca_com': ('Canh cải chua xào cà chua, ớt bột rồi nấu với cá cơm, chua cay nhẹ, đưa cơm.',
        ['Cà chua cắt múi cau; cải chua cắt khúc 1cm; rau om, ngò gai thái nhỏ; ớt hiểm đập dập.', 'Cho 2 muỗng canh dầu và 1 muỗng canh ớt bột vào chảo, phi thơm hành tím, xào sơ cà chua rồi thêm cải chua xào cùng.', 'Đổ 1 lít nước, nấu sôi, thả cá cơm vào; nêm 1/2 muỗng canh hạt nêm, 1 muỗng canh nước mắm, 1,5 muỗng canh bột ngọt, 1 muỗng canh muối và cho ớt hiểm vào.', 'Canh sôi lại thì thêm rau om, ngò gai rồi tắt bếp. Múc ra tô, ăn nóng với cơm.', 'Mẹo: cá cơm chín rất nhanh, sôi là tắt bếp để giữ vị ngọt; chọn cải chua vừa phải để canh thơm ngon.']),
    'canh_cai_goi_thit_ga_nam_huong': ('Lá cải thảo gói nhân gà, thịt heo, nấm hương, buộc lá hành, nấu cùng bắp Mỹ, ngọt dịu.',
        ['Nấm hương ngâm nở, băm nhỏ. Trộn thịt nạc dăm, ức gà xay với nấm hương, cà rốt, hành lá thái nhỏ; ướp 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê đường, 1 muỗng cà phê hành băm, 1/3 muỗng cà phê tiêu. Bắp Mỹ cắt khúc 2cm.', 'Đun sôi 1 lít nước, chần lá cải thảo rồi vớt ra; cho bắp vào nồi nấu chín.', 'Trải lá cải ra dĩa, đặt nhân vào, gói thành khối vuông và buộc chữ thập bằng lá hành.', 'Thả các gói cải vào nồi, nấu lửa nhỏ khoảng 5 phút, nêm 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê nước mắm; thêm ngò rí, đảo nhẹ rồi bắc xuống.', 'Múc ra tô, rắc tiêu, ăn nóng.', 'Mẹo: chọn lá cải lớn cho dễ gói; pha thêm thịt nạc dăm để nhân mềm, không khô.']),
    'canh_chua_dau_ca_hoi': ('Canh chua đầu cá hồi nấu nước me, măng chua và cà chua, thêm tỏi phi, chua ngọt béo.',
        ['Đầu cá hồi rửa sạch, chặt miếng, ướp 1 muỗng cà phê muối, 1 muỗng canh nước mắm, 1/3 muỗng cà phê tiêu, 2 trái ớt hiểm đập dập khoảng 15 phút.', 'Phi thơm 2 muỗng canh tỏi băm với 2 muỗng canh dầu; lấy 1/2 muỗng canh tỏi phi trộn vào cá. Phần tỏi còn lại dùng xào sơ cà chua băm rồi trút ra.', 'Măng chua rửa sạch, vắt ráo, phi tỏi xào sơ cho thơm. Rau om, ngò gai rửa sạch, thái nhỏ.', 'Đun sôi 1,5 lít nước, cho cá và 3 muỗng canh nước me vào; sôi lại thì hớt bọt, nấu thêm 3–5 phút.', 'Nêm 1 muỗng cà phê muối, 1 muỗng canh đường, 2 muỗng canh nước mắm, 2 muỗng canh bột ngọt; cho cà chua và măng chua vào, nếm chua ngọt vừa ăn, sau cùng thêm cà chua băm đã xào.', 'Múc ra tô, rắc rau om, ngò gai, ăn nóng với cơm hoặc bún; chấm cá với nước mắm ớt.', 'Mẹo: nấu cá sôi 3–5 phút cho ngọt nước; tỏi phi giúp cá bớt tanh; chọn đầu cá ánh bạc, mắt trong, thịt hồng cam.']),
    'canh_chua_bap_cai_tim': ('Canh chua tép nấu bắp cải tím, thơm, cà chua và nước me, chua ngọt giòn mát.',
        ['Tép rửa sạch, để ráo. Bắp cải bỏ lõi, cắt hình quả trám khoảng 2cm; cà chua cắt múi cau; thơm bỏ lõi, thái lát; hành tím thái mỏng; rau om, ngò gai cắt khúc ngắn; ớt thái lát.', 'Phi thơm hành tím với 2 muỗng canh dầu, cho tép vào xào rồi thêm thơm, cà chua đảo đều.', 'Đổ 1,2 lít nước, đun sôi, nêm 1/2 chén nước cốt me, 3,5 muỗng canh đường, 1 muỗng canh muối, 1,5 muỗng canh bột ngọt, 1 muỗng canh nước mắm.', 'Cho bắp cải vào nấu vừa chín, thêm rau om, ngò gai, ớt và 2 muỗng canh tỏi phi rồi tắt bếp. Ăn nóng, kèm nước mắm ớt.', 'Mẹo: phi hành tím kỹ để át mùi tanh của tép; nêm xong mới cho bắp cải để cải còn giòn.']),
    'canh_chua_ca': ('Canh chua cá nấu thơm, cà chua, bạc hà, đậu bắp, giá với gia vị lẩu Thái, chua nhẹ.',
        ['Cá cắt khúc vừa ăn; cà chua cắt múi cau; thơm, bạc hà, ngò gai, rau om thái lát mỏng; đậu bắp bỏ đầu, cắt xéo.', 'Phi thơm 1 muỗng canh hành tỏi băm, xào sơ cà chua rồi đổ 1,5 lít nước, đun sôi.', 'Thả thơm và cá vào nấu chín, nêm 4 muỗng canh gia vị nêm sẵn lẩu Thái, 1,5 muỗng canh đường, nếm cho chua nhẹ.', 'Cho bạc hà, đậu bắp, giá vào; sôi lại thì nêm 1,5 muỗng canh nước mắm, thêm rau om, ngò gai rồi tắt bếp.', 'Múc ra tô, rắc tỏi phi, ăn nóng.']),
    'canh_chua_ca_loc': ('Canh chua cá lóc nấu me với đậu bắp, bạc hà, thơm, cà chua, giá, rắc tỏi phi.',
        ['Cá lóc rửa sạch, ướp 1 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê ớt băm cho ngấm.', 'Đậu bắp, bạc hà tước xơ, rửa sạch, cắt xéo; cà chua cắt múi cau; thơm, ớt thái lát, thơm trộn với 1/2 muỗng cà phê muối và đường. Rau om, ngò gai thái nhỏ. Dầm me lấy nửa chén nước.', 'Xóc sơ cá với dầu và gia vị. Phi thơm tỏi, sả băm, xào cá cho săn rồi trút ra.', 'Đun sôi 1,5 lít nước cùng nước me, thả cá vào nấu chín, hớt bọt; thêm đậu bắp, thơm, cà chua, giá.', 'Tắt bếp, cho bạc hà vào, nêm 1 muỗng cà phê đường trước rồi 2 muỗng cà phê muối, 1/2 muỗng canh nước mắm. Múc ra tô, thêm rau om, ngò gai, ớt lát và tỏi phi, ăn nóng.', 'Mẹo: xào sơ cá với gia vị để hết tanh; khi làm cá nhớ bỏ 2 vảy to dưới vây mang, tim cá và gân máu dọc xương sống; canh chua không nên cho hành để giữ mùi đặc trưng.']),
    'canh_chua_ca_mien_nam': ('Canh chua cá kiểu miền Nam với thơm, cà chua, bạc hà, rau om, nêm gia vị lẩu Thái.',
        ['Cá rửa sạch, để ráo. Cà chua cắt múi cau; thơm cắt hình rẻ quạt; bạc hà thái lát mỏng; rau om, hành lá thái nhỏ.', 'Phi thơm hành tím với dầu, xào sơ cà chua, thêm 1,7 lít nước và đun sôi.', 'Cho cá và thơm vào, nước sôi lại thì hớt bọt, đun thêm khoảng 5 phút.', 'Nêm 4 muỗng canh gia vị nêm sẵn lẩu Thái, 1 muỗng cà phê bột ngọt, nếm chua nhẹ vừa miệng; thêm 2 muỗng canh nước mắm, hành lá, rau om rồi tắt bếp.', 'Ăn nóng với cơm hoặc bún, chấm nước mắm ớt tùy thích.']),
    'canh_chua_ca_nau_mang': ('Canh chua cá bớp hoặc cá đuối nấu măng chua và cà chua, chua nhẹ, thơm ngò gai.',
        ['Rửa sạch cá bớp (hoặc cá đuối), để ráo. Cà chua cắt múi cau; hành lá, ngò gai cắt nhỏ.', 'Măng chua rửa sạch, cắt miếng vừa ăn, luộc lửa nhỏ khoảng 10 phút rồi vớt ra xả nước lạnh, để ráo.', 'Phi hành tím với dầu ăn cho thơm, cho cà chua và măng vào xào sơ. Đổ 1,7 lít nước vào đun sôi.', 'Thả cá vào, chờ sôi lại thì hớt bọt, nấu thêm khoảng 5 phút. Nêm 4 muỗng canh gia vị nêm sẵn lẩu Thái, 2 muỗng cà phê bột ngọt, nếm cho chua nhẹ vừa miệng.', 'Thêm 2 muỗng canh nước mắm, rắc hành lá, ngò gai, tỏi phi rồi tắt bếp. Ăn nóng với cơm hoặc bún, chấm nước mắm ớt nếu thích.']),
    'canh_chua_dua_cai': ('Canh sườn non nấu dưa cải chua và cà chua, vị chua dịu, thơm rau om ngò gai.',
        ['Sườn non rửa sạch, chặt miếng vừa ăn, chần qua nước sôi rồi để ráo. Dưa cải chua rửa sạch, cắt miếng, để ráo. Cà chua cắt múi cau; rau om, ngò gai cắt nhỏ.', 'Phi hành tím với dầu ăn cho thơm, cho cà chua và sườn vào xào sơ.', 'Đổ 1,7 lít nước vào, đun sôi khoảng 10 phút. Cho dưa cải vào, nêm 4 muỗng canh gia vị nêm sẵn lẩu Thái.', 'Khi nước sôi lại, nêm 2 muỗng canh nước mắm, thả rau om, ngò gai rồi tắt bếp. Ăn nóng với cơm hoặc bún.']),
    'canh_chua_hai_san': ('Canh chua tôm mực kiểu Thái với sả, riềng, nghệ, nước cốt dừa, cà tím và nấm rơm, ăn với bún.',
        ['Nấm rơm cắt đôi, cà tím cắt xéo. Sả đập dập; riềng, nghệ thái lát rồi đập dập. Tôm rửa, để ráo; mực khứa xéo, cắt miếng vừa ăn.', 'Hòa 1/2 gói gia vị nêm sẵn lẩu Thái với 2 muỗng canh nước lọc.', 'Đun nóng dầu, xào thơm riềng, nghệ, sả rồi cho phần gia vị lẩu đã pha vào xào cùng. Đổ thêm 1 lít nước, đun sôi.', 'Cho tôm, mực vào, nêm 1 muỗng canh nước mắm và 1/2 muỗng cà phê đường. Canh sôi lại thì thả cà tím, nấm rơm.', 'Thêm 5 muỗng canh nước cốt dừa và lá chanh, khuấy đều, để sôi lại rồi tắt bếp. Múc ra tô, ăn nóng với bún.', 'Mẹo: Xào gia vị lẩu trước giúp canh thơm và lên màu đẹp hơn.']),
    'canh_chua_mang': ('Canh chua cá điêu hồng chiên sơ nấu măng chua, cà chua và giấm, thơm lá lốt, rau răm.',
        ['Cá làm sạch, cắt đôi, để ráo, ướp 1 muỗng cà phê muối cùng đầu hành và ớt giã nhuyễn; xát kỹ cả đầu, thân và trong bụng cá. Chiên sơ cá cho vừa săn mặt.', 'Cà chua bỏ cuống, cắt múi cau. Lá lốt, rau răm thái nhuyễn; ớt cắt lát; tỏi đập dập, băm nhỏ. Măng rửa sạch, vắt ráo, cắt khúc ngắn, trộn với dầu và tỏi.', 'Phi tỏi đến khi vàng thơm thì tắt bếp, cho măng vào cùng 1/2 muỗng cà phê bột ngọt và muối, đảo đều.', 'Đun sôi nước, cho măng và cá vào, rồi thêm cà chua. Nêm 1 muỗng cà phê đường, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê muối, 1/2 muỗng cà phê nước mắm, 2 muỗng canh giấm gạo; nấu 10 phút.', 'Cuối cùng thả rau răm, lá lốt, ớt lát. Ăn với cơm hoặc bún, kèm chén nước mắm ớt.', 'Mẹo: Rửa cá bằng nước pha giấm cho bớt mùi tanh, mùi bùn. Trộn măng với gia vị lúc đã tắt lửa để măng giữ độ giòn.']),
    'canh_chua_muc': ('Canh chua mực nấu thơm, cà chua, nước me và cọng súng, vị chua ngọt, mực giòn.',
        ['Mực làm sạch, khứa vảy rồng, cắt miếng, ướp 1/3 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê hành tỏi băm cho thấm.', 'Cà chua cắt múi cau, thơm thái lát mỏng. Cọng súng tước vỏ, bào mỏng, ngâm nước muối loãng. Rau thơm cắt nhỏ, ớt đập dập.', 'Phi thơm hành tỏi, xào mực cho săn rồi trút ra đĩa. Phi tiếp hành tỏi, xào cà chua với thơm khoảng 3 phút đến khi săn lại.', 'Đổ 1,2 lít nước nấu sôi, nêm 2 muỗng canh nước me, 2 muỗng canh đường, 1 muỗng canh muối, 1 muỗng canh bột ngọt, 2 muỗng canh nước mắm; thêm ớt đập dập.', 'Cho mực trở lại nồi, sau đó thả cọng súng, tỏi phi kèm dầu, rau om, ngò gai rồi tắt bếp. Ăn nóng với cơm trắng.', 'Mẹo: Cọng súng dễ đổi màu nên cho vào sau cùng; không nấu mực lâu để mực chín tới, còn giòn.']),
    'canh_chua_thit_bam': ('Canh chua thịt băm nấu cà chua, chan lên giá đỗ và rau thơm, làm nhanh.',
        ['Cà chua bổ múi cau, giá đỗ nhặt sạch. Hành củ, tỏi, hành hoa, ngò om, ngò gai thái nhỏ hết.', 'Phi hành tỏi thơm, cho thịt băm vào xào rồi thêm cà chua đảo đến khi chín.', 'Đổ 1 lít nước vào đun sôi, hớt bọt, nêm 4 muỗng canh gia vị nêm sẵn lẩu Thái, để sôi lại thì tắt bếp.', 'Cho giá và rau thơm vào tô, múc canh đang nóng lên trên. Ăn với cơm trắng.']),
    'canh_chua_tom_nuoc_trong': ('Canh chua tôm nước trong, lọc bằng lòng trắng trứng, nấu cà chua và thơm, chua ngọt thanh.',
        ['Rang đầu và vỏ tôm trong chảo sâu lòng, không dùng dầu. Thêm 1,5 lít nước, nấu lửa nhỏ 10 phút, lọc lấy nước rồi để nguội.', 'Cà chua: 1 quả cắt 6 múi cau, 1 quả bỏ hạt thái nhỏ. Thơm: một nửa thái nhỏ, nửa còn lại cắt miếng 3cm. Ngò gai, rau om: một nửa thái nhuyễn, phần còn lại cắt nhỏ.', 'Xào thơm hành tím với dầu ăn, cho cà chua và thơm thái nhỏ vào xào đến khi trong, rồi để nguội 10 phút.', 'Đánh tan lòng trắng trứng trong nồi 3 lít. Cho vào tôm, phần cà chua thơm đã xào, ngò gai rau om thái nhuyễn, 1/2 muỗng canh bột canh, 1/2 muỗng canh đường và nước tôm, khuấy đều.', 'Bắc lên lửa lớn, gần sôi thì hạ lửa, để sôi lăn tăn khoảng 10 phút. Nêm 4 muỗng canh giấm gạo, 1 muỗng canh nước mắm cho vừa chua ngọt mặn. Lọc tách riêng nước và cái; ép phần riêu tôm thành bánh, để nguội.', 'Khi ăn, đun nóng nước canh, cho cà chua múi và thơm miếng vào nấu chín. Xếp giá vào tô, chan canh, thêm riêu tôm và rau thơm cắt nhỏ. Ăn nóng với cơm.', 'Mẹo: Rang khô đầu vỏ tôm để nước dùng thơm, không ngấy; cho lòng trắng và nấu từ nước lạnh để canh trong; xào cà chua thơm trước cho canh đậm vị, đẹp màu.']),
    'canh_chua_tom_rau_muong': ('Canh chua tôm băm nấu cà chua và rau muống, chua nhẹ, rắc tỏi phi.',
        ['Tôm thẻ bóc vỏ, đập dập rồi băm nhỏ. Cà chua cắt múi cau. Rau muống nhặt, rửa sạch, cắt khúc; rau om, ngò gai cắt nhỏ.', 'Phi thơm hành tỏi băm, cho cà chua và tôm vào xào sơ.', 'Đổ 1,5 lít nước đun sôi, nêm 4 muỗng canh gia vị nêm sẵn lẩu Thái và 1,5 muỗng canh đường, nếm cho chua nhẹ.', 'Thả rau muống vào nấu chín, thêm 1,5 muỗng canh nước mắm, rau om, ngò gai rồi tắt bếp.', 'Múc ra tô, rắc tỏi phi lên mặt, ăn nóng.']),
    'canh_chua_trai_tac': ('Canh chua cá điêu hồng áp chảo nấu nước cốt tắc, cà chua, đậu bắp và bạc hà, chua thơm.',
        ['Cá điêu hồng cắt 3 khúc, ướp 1/2 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê tỏi băm cho thấm.', 'Cà chua cắt múi cau; bạc hà, đậu bắp thái xéo mỏng; rau om, ngò gai cắt nhỏ; ớt hiểm đập dập.', 'Áp chảo sơ cá. Phi thơm 1 muỗng canh tỏi băm với 2 muỗng canh dầu ăn, cho cà chua vào xào sơ, đổ 1,5 lít nước đun sôi.', 'Cho cá và nước cốt tắc vào, nêm 1 muỗng cà phê bột ngọt, 2 muỗng cà phê muối, 3 muỗng canh đường. Thêm ớt, đậu bắp, bạc hà; sôi lại thì nêm 3 muỗng canh nước mắm.', 'Cuối cùng cho rau om, ngò gai, vỏ tắc thái nhuyễn rồi tắt bếp. Ăn nóng với cơm hoặc bún.', 'Mẹo: Ướp cá trước giúp cá đậm vị; vỏ tắc tạo mùi thơm riêng cho món canh.']),
    'canh_cu_qua_nau_tom': ('Canh tôm viên nấu bí xanh, củ cải, cà rốt thái sợi, thơm húng quế, vị ngọt thanh.',
        ['Bí xanh, củ cải trắng, cà rốt thái sợi nhỏ, để riêng từng loại. Húng quế cắt khúc 0,5cm.', 'Tôm đập dập, băm nhỏ, ướp ít tiêu, 1 muỗng cà phê hành tím băm, 1/3 muỗng cà phê muối. Chia đôi, một nửa vo thành viên nhỏ.', 'Phi thơm hành tím, xào săn nửa phần tôm chưa vo viên, đổ 1 lít nước vào nấu sôi.', 'Cho cà rốt nấu khoảng 2 phút, tiếp đến tôm viên và củ cải nấu 2 phút, rồi thêm bí xanh. Nêm 1 muỗng canh hạt nêm, 1/3 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt.', 'Rau củ vừa chín thì thả húng quế, tắt bếp. Ăn nóng với cơm.', 'Mẹo: Cho từng loại vào theo thứ tự để chín đều; xào tôm trước cho tôm săn và nước canh ngọt hơn.']),
    'canh_dua_leo_nhoi_thit': ('Canh dưa leo khoét ruột nhồi thịt heo, giò sống, miến và nấm mèo, nấu cùng cà rốt, thanh mát.',
        ['Dưa leo rửa sạch, bào sơ vỏ, cắt khúc 3cm, khoét bỏ ruột. Cà rốt tỉa hoa, thái lát. Bún tàu, nấm mèo cắt nhỏ. Hành lá cắt khúc 3cm, ngò rí cắt nhỏ.', 'Trộn thịt heo, giò sống, bún tàu, nấm mèo với 1 muỗng cà phê hành tím băm, 1/2 muỗng cà phê hạt nêm và ít tiêu. Nhồi hỗn hợp vào lòng các khúc dưa leo.', 'Đun sôi 1,2 lít nước, nêm 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê muối, 1 muỗng cà phê bột ngọt. Cho cà rốt và dưa leo nhồi vào nấu chín rồi tắt bếp.', 'Múc ra tô, rắc tiêu, hành, ngò; ăn với cơm.', 'Mẹo: Khoét sạch ruột dưa để nhân bám chắc; chọn quả vừa, thẳng, vỏ xanh cho canh đẹp mắt.']),
    'canh_ga_cai_bo_xoi': ('Canh cánh gà nấu gừng với cải bó xôi và cà rốt, nước trong, ngọt nhẹ.',
        ['Chần cánh gà qua nước sôi có gừng đập dập và 1/2 muỗng cà phê muối, chặt khúc vừa ăn, ướp 1 muỗng cà phê hạt nêm.', 'Cải bó xôi cắt khúc 4cm, cà rốt tỉa hoa thái lát, gừng thái lát đập dập, hành lá cắt khúc.', 'Cho cánh gà và gừng vào 1,2 lít nước nấu chín. Thêm cà rốt nấu khoảng 5 phút rồi cho cải bó xôi vào nấu chín.', 'Nêm 1 muỗng canh hạt nêm, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt rồi tắt bếp. Múc ra tô, rắc tiêu, ăn nóng với cơm.', 'Mẹo: Chần cánh gà với gừng và muối giúp gà thơm, bớt mùi.']),
    'canh_ga_chien_ngu_coc': ('Cánh gà ướp chanh, tẩm bột chiên giòn và ngũ cốc rồi chiên vàng, chấm xốt sữa chua tương ớt.',
        ['Cán vụn ngũ cốc. Cọng ngò rí thái nhuyễn, ấn dẹp.', 'Cánh gà cắt 3 phần, xăm đều bằng nĩa, ướp 1 muỗng canh hành tỏi băm, 1 muỗng cà phê hạt nêm, 1 muỗng canh nước mắm, ít tiêu, 1 muỗng canh nước cốt chanh, 2 muỗng canh nước cốt hành tím, để 30 phút.', 'Chia bột chiên giòn làm 3: một phần trộn với ngũ cốc, một phần hòa với 70ml nước, phần còn lại để khô.', 'Lăn cánh gà lần lượt qua bột khô, bột ướt rồi hỗn hợp ngũ cốc; chiên trong chảo dầu đến khi vàng, vớt ra để ráo dầu.', 'Làm xốt chấm: trộn 1 muỗng canh sữa chua, 1 muỗng canh tương ớt, 1 muỗng canh cọng ngò rí. Ăn nóng cùng xốt.', 'Mẹo: Dùng loại ngũ cốc không vị; loại có vị dễ làm gà chiên bị cháy.']),
    'canh_ga_cuon_cai_thao': ('Canh gà cuộn cải thảo và cà rốt, phết giò sống, nấu trong nước dùng gà, nước trong vị thanh.',
        ['Lạng mỏng đều má đùi gà, ướp 1 muỗng cà phê hành tím băm, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê bột ngọt, 1/3 muỗng cà phê tiêu.', 'Cà rốt cắt 4 thanh vuông 0,5cm, dài 6cm; phần còn lại tỉa hoa. Cải thảo lấy lá xanh để cuốn, phần cọng cắt miếng để nấu. Chần mềm cà rốt và lá cải.', 'Cuộn 3 lá cải quanh một thanh cà rốt. Trải miếng gà, phết lớp giò sống, rắc ít bột năng, đặt cuộn cải vào giữa rồi cuốn gà lại, buộc chỉ cotton bên ngoài.', 'Đun sôi 1,5 lít nước dùng, cho cuộn gà vào, nêm 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê hạt nêm, 1 muỗng cà phê muối, 1 muỗng cà phê đường. Gà vừa chín thì vớt ra.', 'Cho cà rốt lát rồi cọng cải thảo vào nấu chín, nêm thêm 1/2 muỗng canh nước mắm, tắt bếp, thả hành ngò.', 'Gà nguội bớt thì bỏ chỉ, cắt khoanh, xếp vào tô, chan canh, rắc tiêu. Ăn nóng với cơm, kèm nước mắm nguyên chất và ớt lát.', 'Mẹo: Chọn lá cải phía ngoài mềm, xanh để dễ cuốn; chỉ phết giò sống thật mỏng để kết dính.']),
    'canh_ga_la_e': ('Canh gà ta nấu măng tươi và lá é, ướp ớt xanh, thêm nước cốt chanh, cay thơm lạ miệng.',
        ['Giã 1 muỗng cà phê bột canh với 5 trái ớt xanh và 1 muỗng cà phê hành tỏi băm. Gà chặt miếng, ướp với hỗn hợp này.', 'Lá é nhặt rửa, để riêng vài đọt non trang trí. Măng luộc với ít muối hột, vớt ra ép bớt nước.', 'Phi thơm hành tỏi băm, xào gà săn, đổ 1,5 lít nước dùng gà vào đun sôi, hớt bọt thật kỹ.', 'Cho măng vào, nêm 1 muỗng cà phê đường, 1 muỗng cà phê bột canh, nấu đến khi gà mềm. Nêm 1 muỗng canh nước mắm, thả lá é đảo đều, tắt bếp rồi thêm 2 muỗng canh nước cốt chanh.', 'Múc ra tô, rắc tỏi phi, ớt đỏ thái lát và vài lá é. Ăn với cơm hoặc bún.', 'Mẹo: Ướp gà hơi đậm để sau khi nấu thịt vẫn vừa vị; lá é trắng cho mùi thơm đặc trưng.']),
    'canh_ga_dui_trong': ('Cánh gà tạo hình dùi trống, ướp hành tỏi chanh, lăn bột xù chiên vàng, chấm xốt mayonnaise tương ớt.',
        ['Giã nhuyễn hành, tỏi, vắt lấy nước. Lá chanh thái nhuyễn, chanh vắt lấy nước cốt, trứng đánh tan.', 'Khứa nhẹ giữa hai khớp cánh gà, bẻ cho xương lộ ra, tuốt dồn thịt về một đầu rồi cắt rời; làm tương tự với khớp còn lại.', 'Ướp gà với nước hành tỏi, 2 muỗng cà phê hạt nêm, 1 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê nước cốt chanh trong 10–15 phút.', 'Đun nóng dầu. Lăn cánh gà qua bột mì, nhúng trứng, lăn bột xù rồi chiên vàng, vớt ra để ráo. Bọc giấy bạc phần xương.', 'Pha xốt: trộn 4 muỗng canh xốt mayonnaise, 1 muỗng canh tương ớt, 2 muỗng canh tương cà và lá chanh thái nhuyễn. Xếp gà ra đĩa, ăn cùng xốt và xà lách trộn.', 'Mẹo: Thêm chút nước cốt chanh khi ướp giúp gà thơm hơn.']),
    'canh_ga_la_que': ('Canh gà ta xào sả ớt rồi nấu nước dừa, thêm giấm và rau quế, cay thơm, ăn kèm bún.',
        ['Gà chặt miếng, ướp 1/2 muỗng canh hạt nêm gà, để 15 phút. Hành tây cắt múi cau, hành lá và rau quế cắt khúc, ớt xanh đỏ đập dập.', 'Đun nóng dầu, xào thơm 1 muỗng canh tỏi băm, 1 muỗng canh sả băm cùng ớt, cho gà vào xào đến khi săn và hơi sém vàng.', 'Thêm hành tây đảo nhanh, đổ nước dừa và 1 lít nước lọc vào nấu sôi. Nêm 1 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 2 muỗng canh giấm gạo.', 'Hớt bọt, hạ lửa nhỏ nấu đến khi gà chín. Thả rau quế, hành lá, tắt bếp rồi nêm 2 muỗng canh nước mắm.', 'Múc ra tô, rắc ngò gai và tỏi phi; ăn với bún tươi và nước mắm ớt.', 'Mẹo: Xào gà thật kỹ cho săn, thấm vị; nêm nước mắm sau cùng để canh đậm đà.']),
    'canh_ga_mang_chua': ('Canh má đùi gà xào săn nấu măng chua, vị chua dịu, thơm hành lá ngò gai.',
        ['Má đùi gà chặt miếng to, ướp 1 muỗng cà phê hành tím băm, 1 muỗng cà phê hạt nêm gà, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê nước mắm, 1/2 muỗng cà phê tiêu.', 'Măng chua sơ chế kỹ, rửa sạch, vắt ráo, cắt miếng, ướp 1/2 muỗng cà phê hạt nêm gà và 1/2 muỗng cà phê đường. Ớt cắt khoanh; hành lá, ngò gai cắt nhỏ.', 'Phi hành tím với dầu điều, cho gà vào xào săn, tiếp đến măng xào cho thấm.', 'Đổ 1 lít nước, chờ sôi nêm thêm 1 muỗng cà phê hạt nêm gà, nấu lửa nhỏ 15 phút cho gà và măng mềm. Thêm 1 muỗng canh nước mắm, hành lá, ngò gai rồi tắt bếp. Ăn nóng với cơm hoặc bún.', 'Mẹo: Ướp và xào măng trước giúp vị canh hài hòa.']),
    'canh_ga_mang_chua_la_giang': ('Canh gà ta nấu măng chua, cà chua và lá giang, chua thanh, thêm ớt hiểm.',
        ['Măng chua rửa cho bớt chua, cắt vừa ăn. Cà chua cắt múi cau, lá giang vò sơ, ớt hiểm đập dập.', 'Gà chặt miếng, ướp 1 muỗng canh hành tím băm, 1/2 muỗng canh hạt nêm trong 10 phút.', 'Phi hành tím thơm, cho gà vào đảo nhanh rồi tắt bếp. Đun sôi 1,5 lít nước, thả gà vào nấu chín.', 'Lần lượt cho măng, cà chua, lá giang, ớt hiểm; nêm 1/2 muỗng canh đường, 1 muỗng canh hạt nêm, 2 muỗng canh nước mắm, nếm vừa thì tắt bếp.', 'Múc ra tô, thêm ngò gai, rau om; ăn với cơm hoặc bún, kèm nước mắm ớt.', 'Mẹo: Đảo nhanh gà với hành giúp thịt săn, thấm; vò lá giang trước khi nấu để canh chua thanh.']),
    'canh_ga_moc_vien': ('Canh gà ta nấu củ sen, củ từ, táo đỏ, đậu phộng và mọc viên nấm, vị ngọt bùi.',
        ['Ướp gà với 1 muỗng cà phê hạt nêm giảm muối. Đun 1,5 lít nước, cho gà vào nấu chín.', 'Trộn giò sống với nấm hương băm, mộc nhĩ, cà rốt, 1 muỗng cà phê cọng ngò băm, 1/4 muỗng cà phê tiêu, vo thành viên tròn.', 'Cho củ sen, nấm hương cắt đôi, táo đỏ, đậu phộng vào nồi canh. Nêm 1 muỗng canh hạt nêm giảm muối, 1 muỗng cà phê đường, nếm vừa ăn.', 'Thêm củ từ và mọc viên, nấu 5 phút đến khi mọc chín, nêm 1 muỗng canh nước mắm. Tắt bếp, múc ra, rắc hành ngò và tiêu.', 'Mẹo: Mua sẵn đậu phộng luộc rồi lấy hạt để tiết kiệm thời gian.']),
    'canh_ga_nam_mo': ('Canh gà cuộn cà rốt, bông cải phết giò sống, nấu nấm mỡ và rau củ, nước trong thanh nhẹ.',
        ['Má đùi gà rút xương, giữ da, lạng mỏng đều; ướp 1 muỗng canh hành tím băm, 1/4 muỗng cà phê muối, 1/4 muỗng cà phê bột ngọt, chút tiêu.', 'Cà rốt cắt 4 que, phần còn lại cắt miếng. Bông cải: cọng cắt 4 que giống cà rốt, phần bông cắt miếng. Nấm mỡ thái lát.', 'Trải miếng gà, phết giò sống, đặt que cà rốt và bông cải lên, cuộn tròn rồi buộc chỉ.', 'Đun sôi nước dùng gà, nêm 1 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê đường. Thả cuộn gà vào nấu chín, vớt ra, để nguội bớt, bỏ chỉ và cắt khoanh dày 1,5cm.', 'Cho cà rốt, nấm, bông cải vào nồi nấu chín, nêm 1 muỗng canh nước mắm, thêm ngò rí.', 'Múc canh ra tô, xếp khoanh gà lên, rắc tiêu, hành, ngò. Ăn với cơm nóng, kèm nước mắm nguyên chất và tiêu.', 'Mẹo: Giữ da gà để khoanh cắt đẹp; chỉ phết lớp giò mỏng là đủ kết dính.']),
    'canh_ga_nau_bong_cai': ('Canh thịt gà xào săn nấu bông cải trắng, bông cải xanh và cà rốt trong nước dùng xương gà.',
        ['Gà lóc lấy thịt, cắt khối vuông, ướp 1 muỗng canh hành tím băm, 1/2 muỗng cà phê tiêu, 2 muỗng cà phê hạt nêm. Phần xương đem nấu nước dùng.', 'Bông cải trắng và xanh cắt thành búp nhỏ; cuống gọt vỏ, cắt xéo. Cà rốt cắt miếng, hành lá cắt khúc 3cm, ngò rí cắt nhỏ.', 'Đun nóng dầu, phi hành thơm, xào gà săn rồi cho vào nồi nước dùng. Thêm cà rốt nấu 2–3 phút, cho cuống bông cải vào nấu gần chín, rồi đến phần bông.', 'Nêm 1 muỗng cà phê hạt nêm, 1 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê nước mắm; cuối cùng thả hành lá và ít tiêu.', 'Múc ra tô, rắc ngò rí và tiêu, ăn nóng.', 'Mẹo: Tiếp tục hớt bọt sau khi cho gà vào để nước canh trong.']),
    'canh_ga_nau_khoai_mon': ('Canh đùi gà nấu khoai môn chiên sơ và cà rốt trong nước dùng gà, béo bùi.',
        ['Đùi gà chặt miếng, ướp 1/2 muỗng cà phê muối, 1/4 muỗng cà phê đường, 1/4 muỗng cà phê bột ngọt, 1/2 muỗng cà phê tiêu, 1 muỗng canh nước cốt hành tím.', 'Khoai môn cắt khối, chiên sơ. Cà rốt tỉa hoa, thái lát dày 1cm. Hành lá, ngò rí cắt nhỏ.', 'Phi thơm 1 muỗng canh hành tím băm, xào gà săn, đổ nước dùng vào nấu khoảng 5 phút.', 'Thêm cà rốt và khoai môn, nấu đến khi mềm. Nêm 1/2 muỗng cà phê muối, 1/4 muỗng cà phê đường, 1/2 muỗng cà phê bột ngọt, cho hành tây, nếm vừa rồi tắt bếp.', 'Múc ra tô, rắc hành ngò và tiêu, ăn nóng với cơm.', 'Mẹo: Chọn khoai môn củ thẳng, nhiều bột, ít mắt; dùng gà mái dầu canh sẽ ngon hơn.']),
    'canh_ga_nau_khoai_tay': ('Canh đùi gà nấu khoai tây, cà rốt, hành tây với tiêu xanh đập dập, ấm thơm.',
        ['Đùi gà chặt nhỏ, ướp 1 muỗng canh hành tím băm, 1 muỗng canh hạt nêm, ít tiêu và 1 nhánh tiêu xanh đập dập.', 'Khoai tây cắt khối 4cm, cà rốt cắt miếng, hành tây cắt múi cau, hành ngò thái nhỏ.', 'Phi thơm hành tím, xào gà săn, đổ 1 lít nước và cho cà rốt vào nấu sôi 2–3 phút.', 'Nêm 1 muỗng canh hạt nêm, thêm khoai tây và 1 nhánh tiêu xanh đập dập, nấu đến khi gần chín.', 'Cho hành tây và ít muối, nếm vừa rồi tắt bếp, rắc hành ngò. Ăn nóng.', 'Mẹo: Cánh và đùi gà hợp nhất cho món này; tiêu xanh đập dập làm canh thơm hơn.']),
    'canh_ga_thuoc_bac': ('Gà ta hầm thuốc bắc với củ sen, hạt sen và cà rốt khoảng 1 tiếng, nước ngọt thơm mùi thuốc.',
        ['Gà làm sạch, để ráo, chặt miếng vừa ăn. Củ sen rửa sạch bùn, gọt vỏ, ngâm nước pha chút chanh rồi thái khoanh.', 'Cà rốt tỉa hoa, thái khoanh dày 3–4mm. Hành lá thái nhỏ.', 'Cho vào 2 lít nước 4 muỗng canh hạt nêm, 1 muỗng canh đường, 1/2 muỗng cà phê bột ngọt và thuốc bắc, rồi thả gà cùng các nguyên liệu còn lại vào.', 'Hầm khoảng 1 tiếng đến khi nước rút còn chừng 1,5 lít. Ăn nóng với cơm.', 'Mẹo: Dùng gà ta hầm ngon hơn; nêm nhạt vừa phải để giữ mùi thuốc bắc. Thuốc bắc mua ở siêu thị hoặc tiệm thuốc bắc.']),
    'canh_ga_tu_quy': ('Canh gà ta hầm nước dừa với đậu ngự, đậu phộng, đậu đỏ, đậu trắng, cà rốt và nấm đông cô.',
        ['Gà ta rửa sạch, chặt nhỏ. Luộc đậu ngự và đậu phộng 30 phút, sau đó bóc vỏ đậu ngự. Vo sạch đậu đỏ, đậu trắng.', 'Cà rốt cắt miếng dày 0,5cm. Nấm đông cô rửa sạch, bỏ chân, khứa hình chữ thập.', 'Cho các loại đậu vào nồi cùng nước dừa và nước (tổng khoảng 2 lít) đun sôi, rồi cho gà vào hầm lửa nhỏ 20 phút.', 'Thêm cà rốt, nấm, nấu tiếp 10 phút. Nêm 4 muỗng cà phê hạt nêm, 1/2 muỗng cà phê muối, 1/3 muỗng cà phê bột ngọt rồi tắt bếp.', 'Múc ra tô, rắc hành lá, ngò rí; chấm kèm nước mắm ớt.', 'Mẹo: Nấu đậu từ nước nguội để đậu chín đều, mềm; ngâm đậu phộng trước 3 tiếng cho mềm hơn.']),
    'canh_ga_xao_ot_xiem': ('Cánh gà luộc nghệ rồi xào ớt xiêm ngâm giấm với cà rốt, nấm mèo, cay nồng đậm vị.',
        ['Cánh gà chặt miếng. Hành lá: phần xanh cắt khúc 3cm, đầu trắng băm nhỏ. Nấm mèo ngâm mềm, cắt nhỏ. Cà rốt tỉa hoa, thái lát mỏng.', 'Luộc gà trong 1 lít nước có 1 muỗng cà phê muối, 2 muỗng cà phê nước giấm ngâm ớt và 1/3 muỗng cà phê bột nghệ đến gần chín, vớt ra để ráo. Ướp gà với 1/4 muỗng cà phê hạt nêm gà.', 'Phi thơm đầu hành, cho ớt vào xào dậy mùi, thêm gà và cà rốt xào chín, rồi cho nấm mèo vào xào lửa vừa.', 'Nêm 1/2 muỗng cà phê hạt nêm gà, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê nước mắm, đảo đều đến khi chín thì tắt bếp.', 'Cho ra đĩa, rắc hành lá, rau om, ngò gai; ăn nóng với cơm.', 'Mẹo: Luộc gà với giấm ớt, muối, nghệ giúp gà đẹp màu, thấm vị và giữ ẩm; xào ớt thơm trước rồi mới cho nguyên liệu khác. Chọn cánh nhỏ để thấm vị.']),
    'canh_gan_bo_cai_chua': ('Canh gân bò xào săn nấu cải chua, cà chua và ớt hiểm, chua cay, gân mềm giòn.',
        ['Gân bò ngâm với gừng và rượu trắng, rửa sạch, để ráo, cắt miếng. Cà chua cắt múi cau, ớt hiểm đập dập, ngò gai thái nhỏ.', 'Phi tỏi với dầu cho thơm, cho gân bò vào xào thật săn, rồi thêm cà chua, ớt hiểm, cải chua xào đến khi săn.', 'Đổ 1,5 lít nước nấu sôi, nêm 2 muỗng canh đường, 1/2 muỗng canh bột ngọt, 2 muỗng canh hạt nêm, nấu đến khi gân bò mềm.', 'Tắt bếp, nêm 2 muỗng canh nước mắm. Múc ra tô, thêm ngò gai, ớt lát; ăn nóng với cơm trắng.', 'Mẹo: Rửa gân với gừng rượu cho thơm; xào gân thật săn để khi ăn mềm giòn, không ngán.']),
    'canh_he_nau_thit': ('Canh hẹ nấu thịt nạc băm, tim heo và đậu hũ trắng, nhẹ nhàng, thơm mùi hẹ.',
        ['Đậu hũ cắt miếng vuông, rửa qua nước sôi. Hẹ cắt khúc 3cm, ngò rí thái nhuyễn.', 'Thịt nạc băm nhỏ, tim heo rửa sạch thái mỏng; ướp với 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê nước mắm, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê hạt nêm và hành tím băm.', 'Phi hành tím, cho thịt và tim vào xào săn.', 'Đun sôi nước, cho đậu hũ, thịt và tim vào nấu chín, nêm muối, nước mắm, bột ngọt, hạt nêm vừa ăn. Thả hẹ vào rồi tắt bếp.', 'Múc ra tô, rắc ngò rí và tiêu, ăn nóng.', 'Mẹo: Rửa đậu hũ bằng nước nóng cho hết vị chua; canh vừa sôi là tắt bếp để hẹ không bị hăng.']),
    'canh_hao_thanh_mat': ('Canh hàu sữa nấu củ cải, bí ngòi, cà rốt, nấm kim châm và gừng, vị ngọt thanh.',
        ['Hàu ướp 1 muỗng cà phê hạt nêm và 1/2 muỗng cà phê ớt bột. Củ cải cắt khối vuông dày 1cm; bí ngòi, cà rốt bổ đôi rồi thái lát 1cm. Hành lá thái nhỏ.', 'Đun sôi 1,2 lít nước với 5 lát gừng, cho củ cải và cà rốt vào nấu chín, rồi thêm bí ngòi.', 'Cho hàu và nấm kim châm vào, nêm 1/2 muỗng canh hạt nêm, 1/2 muỗng cà phê muối, 1/2 muỗng canh bột ngọt, 1/3 muỗng cà phê đường, 1/2 muỗng canh nước mắm.', 'Để sôi lại, thả hành lá rồi tắt bếp. Ăn nóng với cơm trắng.', 'Mẹo: Ướp hàu với ớt bột để thơm và bớt tanh; cho nguyên liệu theo thứ tự để chín đều.']),
    'canh_ghe_cu_sen_chua_cay': ('Canh ghẹ nấu củ sen, ngó sen, nấm rơm, thơm và củ thì là với gia vị lẩu kim chi, chua cay.',
        ['Ghẹ làm sạch, chặt đôi. Phi hành tỏi rồi đảo ghẹ qua cho thơm; sau đó xào nhanh nấm rơm đã sơ chế.', 'Củ sen thái lát mỏng, ngó sen cắt khúc 4cm, cà chua bi bổ đôi, thơm cắt rẻ quạt, hành tây thái sợi dọc. Hành lá, thì là cắt khúc; ớt đập dập; củ thì là thái sợi, giữ lá để trang trí.', 'Đun sôi 1,5 lít nước với gia vị nêm sẵn lẩu kim chi, cho củ sen và nấm rơm nấu 5 phút, rồi thả ghẹ vào nấu chín.', 'Thêm ngó sen, cà chua, thơm, củ thì là, hành tây; nêm 1 muỗng canh nước mắm và ớt hiểm đập dập.', 'Múc canh ra, thêm rau nêm và ớt. Ăn với cơm, chấm nước mắm ớt.', 'Mẹo: Nấu củ sen và nấm với gia vị lẩu trước cho chín và thấm; chọn ghẹ có phần ức cứng, chắc tay (không ấn vào yếm) là ghẹ chắc thịt.']),
    'canh_ga_xot_nuoc_tuong': ('Cánh gà áp chảo rồi rim xốt nước tương gừng tỏi, ăn kèm dưa giá muối xổi chua ngọt.',
        ['Cánh gà cắt đôi, ướp 1/2 muỗng canh hạt nêm, 1/3 muỗng canh tiêu, 1 muỗng canh nước tương, 1 muỗng cà phê gừng băm, 1 muỗng canh tỏi băm, 1 muỗng canh rượu trắng.', 'Pha xốt: 2 muỗng canh nước tương, 1/2 muỗng cà phê hạt nêm, 1 muỗng canh đường, 1 muỗng canh gừng băm, 1 muỗng canh rượu trắng, 1 muỗng canh tương ớt.', 'Làm dưa giá: khuấy tan 2 muỗng canh giấm gạo, 1,5 muỗng canh đường với 1/2 chén nước, ngâm bắp cải, giá, hẹ, cà rốt 15 phút rồi vớt ra để ráo.', 'Áp chảo cánh gà đến khi hai mặt hơi vàng, đổ xốt vào rim đến khi gà chín.', 'Ăn nóng với cơm hoặc bún, kèm dưa giá.', 'Mẹo: Áp chảo gà vàng thơm trước khi rim giúp món ngon hơn.']),
    'canh_he_thanh_nhiet': ('Canh thịt xay xào săn nấu bông hẹ, nấm bào ngư, dưa leo và cà chua, thanh mát.',
        ['Ướp thịt với 1 muỗng cà phê hạt nêm, 1/2 muỗng canh muối, 1/2 muỗng canh tiêu, 2 muỗng canh nước lọc và gừng, trộn đều để 15 phút.', 'Bông hẹ cắt khúc 5cm, cà chua cắt múi cau. Dưa leo bổ đôi bỏ ruột, thái xéo 5mm. Nấm bào ngư rửa, cắt gốc, xé đôi.', 'Phi thơm hành tím, xào thịt săn rồi để riêng.', 'Đun sôi 1,5 lít nước, nêm 1/2 muỗng canh muối, 2 muỗng canh hạt nêm. Cho thịt, nấm, cà chua vào nấu gần chín, rồi thêm dưa leo, bông hẹ, đun sôi lại.', 'Tắt bếp, thêm 1/2 muỗng cà phê dầu mè. Múc ra tô, rắc tiêu, ăn nóng.', 'Mẹo: Thêm nước khi ướp thịt xay giúp thịt mềm, tơi sau khi xào; dưa leo làm canh thanh mát.']),
    'canh_ghe_hung_que': ('Canh chua ghẹ chiên sơ nấu nước me, thơm, cà chua, rau muống và nấm kim châm, thơm rau nêm.',
        ['Sả đập dập, cắt khúc. Cà chua cắt múi cau, thơm cắt rẻ quạt. Rau muống lấy cọng và đọt non, cắt khúc 4cm. Nấm kim châm cắt đôi; rau om, ngò gai cắt khúc 2cm.', 'Ghẹ làm sạch, cắt 4, ướp 1/4 muỗng cà phê hạt nêm và muối. Chiên sơ trong ít dầu đến khi chuyển đỏ hồng, vớt ra để ráo.', 'Đun sôi 1,5 lít nước dùng, nêm 4 muỗng canh nước me, 2 muỗng canh đường, 1 muỗng canh hạt nêm, 1/2 muỗng cà phê muối. Cho sả, ớt hiểm đập dập và ghẹ vào nấu sôi 3 phút.', 'Thêm thơm, cà chua, rau muống, nấu sôi 2 phút; cho nấm kim châm, chờ sôi lại nêm 1 muỗng canh nước mắm, thả rau nêm rồi tắt bếp. Rưới dầu tỏi phi, thêm ớt sừng thái sợi.', 'Múc ra tô, ăn nóng với cơm hoặc bún, kèm nước mắm nguyên chất và ớt lát.', 'Mẹo: Chọn ghẹ tươi, nặng tay; ấn hai bên yếm thấy cứng, đầy là ghẹ chắc thịt.']),
    'canh_hen_nau_bau': ('Canh hến xào sơ nấu bầu bào sợi và cà rốt, thêm thì là, vị ngọt mát.',
        ['Thịt hến ướp 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê bột ngọt. Phi thơm hành tím băm rồi xào sơ hến.', 'Bầu gọt vỏ, bào sợi; cà rốt bào mỏng, thái sợi; hành lá, thì là rửa sạch, cắt nhỏ.', 'Lấy phần nước trong của nước luộc hến đun sôi, cho cà rốt vào; sôi lại thì thêm bầu.', 'Bầu chín thì cho hến vào, nêm 1 muỗng cà phê muối và 1 muỗng cà phê bột ngọt, thả hành lá, thì là, tiêu rồi tắt bếp. Ăn nóng với cơm.', 'Mẹo: Chọn bầu vỏ xanh đậm có đốm trắng, quả thon ít ruột; không nấu hến lâu kẻo dai, mất ngọt.']),
    'canh_hen_nau_khe': ('Canh hến nấu khế chua, măng chua và cà chua, chua thanh, thơm thì là.',
        ['Luộc chín hến, gỡ lấy thịt; để lắng nước luộc, lấy 1 lít nước trong. Ướp thịt hến với 1 muỗng canh bột ngọt, 1 muỗng canh đường, 2 trái ớt hiểm đập dập.', 'Khế bào lát mỏng ngang quả, cà chua cắt múi cau. Măng chua rửa, ép ráo, cắt miếng. Thì là, hành lá cắt khúc.', 'Phi tỏi băm với 2 muỗng canh dầu, cho hến, măng, cà chua, khế vào xào nhanh, nêm 1 muỗng canh đường, 1 muỗng canh muối, đảo khoảng nửa phút.', 'Đổ nước luộc hến còn nóng vào nấu sôi, hạ lửa, nêm lại cho vừa. Thêm hành, thì là, ớt sừng, 1 muỗng canh nước mắm, bột ngọt và 1 muỗng canh tỏi phi.', 'Ăn nóng với cơm, kèm nước mắm ớt sừng.', 'Mẹo: Ướp hến trước cho ngọt, đậm; ngâm hến trong nước pha chút muối để nhả hết cát.']),
    'canh_khe_ca_com': ('Canh cá cơm tươi xào ớt bột nấu khế chua và cà chua, chua thanh, thơm rau răm.',
        ['Khế rửa sạch: một nửa thái sợi dày 0,5cm rồi giã sơ, nửa còn lại thái lát hình sao. Cà chua cắt múi cau, rau răm thái nhỏ.', 'Phi thơm hành tím băm, cho cá cơm vào xào sơ cùng 1 muỗng cà phê ớt bột.', 'Cá săn thì đổ 1 lít nước nấu sôi, thêm cà chua và khế nấu khoảng 3 phút.', 'Nêm 2 muỗng canh hạt nêm, 1 muỗng canh nước mắm, nếm vừa, thả rau răm rồi tắt bếp. Ăn nóng với cơm.', 'Mẹo: Chọn khế chua mọng nước để canh thanh, không chát; xào cá với ớt bột và hành giúp bớt tanh, đẹp màu.']),
    'canh_mang_ga_vien': ('Canh gà viên trộn giò sống nấu măng vàng thái sợi và hành tây, ngọt nhẹ.',
        ['Ngò rí thái nhỏ, để riêng cọng và lá. Trộn thịt gà với giò sống, ít muối, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê dầu mè; thêm cọng ngò và lòng đỏ trứng, để lạnh.', 'Vo thịt thành viên đều, cỡ 2cm.', 'Măng thái sợi nhỏ, trụng nước sôi, vắt ráo, ướp 1 muỗng cà phê hạt nêm. Hành tây thái mỏng theo chiều dọc, hành lá thái nhỏ.', 'Đun nóng 2 muỗng canh dầu, xào thơm hành tây rồi xào măng. Đun sôi 2 lít nước, thả gà viên nấu đến khi nổi lên, cho măng và hành tây vào.', 'Nêm 1/2 muỗng cà phê đường, 1 muỗng cà phê muối, 1 muỗng canh hạt nêm, 1 muỗng canh nước mắm. Tắt bếp, rắc tiêu, hành ngò. Ăn nóng với cơm, kèm nước mắm ớt.']),
    'canh_mang_gio_heo': ('Canh giò heo nấu măng tươi đến mềm, nước ngọt béo, rắc hành ngò tiêu.',
        ['Măng tươi rửa sạch, ngâm nước muối, rửa vài lần cho bớt đắng, luộc qua nước sôi rồi ngâm nước lạnh, để ráo, cắt khúc.', 'Giò heo cạo rửa sạch, cắt miếng, ướp 1 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê hạt nêm trong 15 phút. Hành ngò thái nhuyễn, ớt thái lát.', 'Đập dập hành tím, xào với ít dầu, cho giò heo vào xào săn rồi đổ 1,5 lít nước. Sôi lại thì hớt bọt.', 'Khi thịt mềm, cho măng vào nấu thêm 15–20 phút, nêm bột ngọt, nước mắm rồi tắt bếp.', 'Múc ra tô, rắc hành ngò tiêu. Ăn nóng với cơm, chấm nước mắm nguyên chất với ớt.', 'Mẹo: Chọn giò chân trước nhiều thịt hơn; nấu nửa chừng thì vớt giò ngâm nước lạnh rồi nấu tiếp để da săn, giòn, trắng.']),
    'canh_mang_kho_duoi_bo': ('Đuôi bò xào gừng với măng khô rồi hầm nồi áp suất đến mềm, nước ngọt, thơm rau răm.',
        ['Đuôi bò chặt khúc 2cm, trụng 5 phút trong nồi nước sôi có 1 muỗng cà phê muối, 3 muỗng canh nước gừng, 2 muỗng canh rượu trắng; vớt ra rửa sạch, để ráo.', 'Ướp đuôi bò với 1 muỗng cà phê muối, 1 muỗng cà phê đường, 2 muỗng cà phê hạt nêm, để 15 phút.', 'Măng khô luộc mềm, xé sợi. Hành lá, rau răm thái nhỏ; hành tím đập sơ.', 'Đun nóng 2 muỗng canh dầu, phi thơm hành tím và gừng sợi, cho đuôi bò và măng vào xào săn, nêm 1 muỗng canh hạt nêm.', 'Chuyển vào nồi áp suất cùng 2 lít nước, nấu đến khi đuôi bò mềm, nếm lại rồi tắt bếp. Múc ra tô, thêm hành lá, rau răm, tiêu; ăn với cơm trắng.', 'Mẹo: Trụng đuôi bò với muối, rượu, nước gừng để khử mùi gây; dùng đuôi bỏ da cho nước trong, vị thanh.']),
    'canh_mang_suon_la_giang': ('Canh sườn non hầm mềm nấu măng tươi, cà chua và lá giang, chua thanh.',
        ['Lá giang vò sơ, cắt nhỏ. Măng tươi luộc, bắt đầu từ nước lạnh. Cà chua cắt múi cau. Sườn chặt miếng, ướp 2 muỗng cà phê bột canh.', 'Đun nóng nồi với 1 muỗng canh dầu, phi tỏi băm, cho sườn vào đảo đến khi thơm.', 'Đổ 1,5 lít nước, sôi thì hạ lửa, nấu 25–30 phút cho sườn mềm.', 'Nêm 1,5 muỗng canh đường, 1 muỗng cà phê bột canh, rồi cho lá giang, măng, cà chua vào nấu đến khi ra vị chua. Tắt bếp, thêm 1 muỗng canh nước mắm.', 'Múc ra tô, thêm rau thơm, ớt sợi; ăn với cơm hoặc bún, kèm nước mắm ớt.', 'Mẹo: Luộc măng từ nước lạnh để giảm chất độc có trong măng; vò lá giang cho canh chua thanh.']),
    'canh_muc_nau_nuoc_dua': ('Canh mực nấu nước dừa với thơm, cà chua, ớt sừng và dầu điều, chua ngọt, hơi cay.',
        ['Mực rửa sạch, ướp 1 muỗng canh hành tím băm, 1/2 muỗng cà phê hạt nêm, 1/4 muỗng cà phê tiêu, 1/4 muỗng cà phê muối, 1/4 muỗng cà phê đường, 1/2 muỗng cà phê bột ngọt.', 'Thơm thái mỏng, trộn 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê đường, để 10 phút. Cà chua cắt múi cau; ớt sừng, hành lá cắt khúc.', 'Phi hành tím với 3 muỗng canh dầu điều, xào cà chua, nêm 1/4 muỗng cà phê muối, 1/4 muỗng cà phê đường. Thêm thơm và ớt sừng xào cho thấm.', 'Đổ nước dừa vào nấu sôi, thả mực, không khuấy. Sôi lại thì nêm 1 muỗng canh hạt nêm.', 'Thả hành lá, tắt bếp, thêm 1 muỗng canh xốt ớt cay. Ăn nóng với cơm hoặc bún.', 'Mẹo: Chọn mực tươi, thân căng tròn; ướp thơm trước giúp vị canh hài hòa.']),
    'canh_muop_huong_thit_vien': ('Canh mướp hương nấu thịt viên trộn giò sống và nấm hương, thêm miến dong, ngọt mát.',
        ['Mướp gọt vỏ, bổ đôi, cắt hình móng ngựa. Nấm hương ngâm mềm, thái nhỏ. Miến ngâm mềm. Hành lá, ngò rí thái nhỏ; đầu hành trắng băm nhuyễn.', 'Trộn thịt băm, giò sống, nấm hương, đầu hành băm với 1/2 muỗng cà phê hạt nêm, 1/3 muỗng cà phê bột ngọt, 1/2 muỗng cà phê tiêu; vo viên vừa ăn.', 'Đun sôi 1,2 lít nước, thả thịt viên nấu chín, rồi cho mướp vào, nêm 2 muỗng canh hạt nêm, 1/2 muỗng cà phê bột ngọt.', 'Canh sôi thì cho miến vào và tắt bếp ngay. Múc ra tô, rắc hành ngò; ăn với cơm.', 'Mẹo: Tắt lửa khi cho miến để miến không bở; mướp cắt xong nấu ngay kẻo bị thâm.']),
    'canh_nam_cang_cua': ('Canh càng cua bọc giò sống nấu nấm đông cô, bông cải xanh và cà rốt, nước trong ngọt.',
        ['Nấm đông cô ngâm nở, rửa sạch, luộc 5 phút trong nước có ít hạt nêm. Cà rốt tỉa hoa, thái lát dày 3mm; bông cải cắt miếng. Hành lá: đầu trắng băm, phần lá cắt khúc 2cm.', 'Càng cua ướp 1/3 muỗng cà phê tiêu, 1/2 muỗng cà phê hành tím băm. Giò sống trộn 1 muỗng cà phê đầu hành băm, 1/3 muỗng cà phê tiêu, chia 6 phần, bọc quanh càng cua, chừa đầu càng ra ngoài.', 'Đun sôi nước dùng, cho nấm, cà rốt, bông cải vào, sôi lại thì thả càng cua nấu vừa chín.', 'Nêm 1 muỗng canh hạt nêm, 1/2 muỗng cà phê đường, 1 muỗng canh nước mắm, khuấy tan, nếm vừa rồi tắt bếp, thêm hành lá.', 'Múc ra tô, rắc tiêu, ăn kèm nước mắm nguyên chất.', 'Mẹo: Ướp càng cua với tiêu và hành tím cho thơm.']),
    'canh_nam_hat_sen': ('Canh hạt sen, nấm đông cô, nấm linh chi, đậu hũ non và cà rốt, vị thanh nhẹ.',
        ['Cà rốt tỉa hoa, thái lát. Các loại nấm làm sạch, để ráo. Ngò rí thái nhỏ. Đậu hũ non cắt khối vuông 1cm.', 'Đun sôi 1 lít nước, cho hạt sen và cà rốt vào nấu khoảng 10 phút.', 'Thêm nấm và đậu hũ, nấu khoảng 5 phút cho chín. Nêm 1 muỗng canh hạt nêm nấm, 1/2 muỗng cà phê đường rồi tắt bếp.', 'Rắc tiêu và ngò rí, ăn nóng với cơm.', 'Mẹo: Dùng hạt sen tươi cho canh bùi, thơm; đậu hũ non mềm, hợp nấu canh.']),
    'canh_nam_rong_bien': ('Canh nấm hương nhồi giò sống và tôm, nấu nấm kim châm, nấm rơm, rong biển và tần ô.',
        ['Tôm chẻ lưng, bỏ chỉ, chần nước sôi rồi bóc vỏ; lấy 3 con thái hạt lựu. Nấm hương, nấm rơm ngâm nước vo gạo.', 'Nấm hương cắt chân, rửa, ép ráo, rắc ít hạt nêm, tiêu, bột bắp. Phết giò sống lên mặt nấm, đặt 1 miếng tôm vào giữa, rồi phủ thêm chút bột bắp.', 'Nấm kim châm cắt chân, tách sợi, cắt đôi. Rong biển thái sợi, cà rốt tỉa hoa thái mỏng, tần ô cắt khúc ngắn, hành lá ngò rí thái nhỏ, ớt thái lát.', 'Đun sôi nước dùng, cho cà rốt, các loại nấm và phần tôm còn lại vào, nêm 1 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt rồi tắt bếp.', 'Thả rong biển, tần ô, hành lá, ngò rí, rắc tiêu. Ăn nóng, chấm nước tương với ớt.', 'Mẹo: Rắc bột bắp hai lần để giữ nước ngọt của nấm và giò; cho rau và rong biển sau cùng để giữ màu xanh, mùi thơm.']),
    'canh_ngheu_dau_hu_chua_cay': ('Canh nghêu nấu với giò sống vo viên, đậu hũ non, cà chua bi, nêm giấm và ớt cho vị chua cay.',
        ['Cắt đôi cà chua bi, cắt đậu hũ thành khối khoảng 1cm, đập dập ớt hiểm, hành lá cắt khúc. Rễ thì là đập dập; cọng thì là đập dập rồi băm nhỏ.', 'Luộc nghêu với nước và rễ thì là đến khi chín, giữ lại nước luộc. Gỡ thịt nghêu, ướp với 1/2 muỗng canh hạt nêm và 1/4 muỗng canh tiêu.', 'Trộn giò sống với cọng thì là băm và ớt sừng băm, vo thành từng viên vừa ăn.', 'Đun sôi lại nước luộc nghêu, thả giò viên vào. Nêm 1 muỗng canh hạt nêm, 1 muỗng canh đường, 1 muỗng canh tương ớt, 2 trái ớt hiểm đập dập, 3,5 muỗng canh giấm gạo; cho đậu hũ và cà chua bi vào.', 'Canh sôi thì thả thịt nghêu, hành và thì là, đảo đều rồi tắt bếp. Nêm thêm 1 muỗng canh nước mắm, múc ra tô ăn nóng với cơm.', 'Mẹo: Chọn nghêu to, ngậm chặt miệng, cầm nặng tay, vỏ trắng sáng. Luộc nghêu kèm ít rễ thì là cho nước canh thơm hơn.']),
    'canh_ngheu_bo_xoi': ('Canh nghêu nấu rau bó xôi và đậu hũ non, nước dùng xào gừng tỏi với tương đậu nành, vị ngọt thanh.',
        ['Ngâm nghêu trong nước ấm, luộc chín rồi xối nước lạnh, gỡ lấy thịt và giữ nước luộc. Đậu hũ non cắt khối vuông; bó xôi cắt khúc 10cm, để riêng thân và lá; gừng cắt sợi, hành lá cắt nhỏ.', 'Phi thơm gừng và tỏi với dầu, cho tương đậu nành vào xào dậy mùi.', 'Đổ 1,5 lít nước cùng nước luộc nghêu vào nấu sôi. Nêm 1 muỗng canh hạt nêm, 1/2 muỗng cà phê đường, 1/3 muỗng cà phê muối, nếm lại cho vừa.', 'Thả phần thân bó xôi nấu 3 phút, rồi cho phần lá vào. Sau cùng cho đậu hũ, đảo nhẹ tay và tắt lửa.', 'Múc canh ra tô, xếp thịt nghêu lên trên, rắc tiêu và hành lá, ăn nóng với cơm.', 'Mẹo: Ngâm nghêu trong nước ấm khoảng 50 độ C để nghêu nhả sạch cát; tương đậu nành giúp canh có hương vị lạ miệng.']),
    'canh_ngheu_kim_cham': ('Canh nghêu với nấm kim châm, nấm rơm, đậu hũ non, nêm sa tế và lá tía tô, cay nhẹ thơm.',
        ['Luộc nghêu với gừng đập dập, nghêu mở miệng thì vớt ra lấy thịt. Gạn nước luộc bỏ cát, thêm nước cho đủ 1,2 lít.', 'Nấm kim châm cắt khúc 5cm, nấm rơm chần sơ, đậu hũ cắt khối 1cm, tía tô thái sợi.', 'Đun sôi nước luộc nghêu, cho nấm rơm, đậu hũ và ớt hiểm đập dập vào. Nêm 2 muỗng canh hạt nêm, 1 muỗng canh bột ngọt, 1 muỗng canh sa tế.', 'Thả thịt nghêu và nấm kim châm, cuối cùng cho tía tô rồi tắt lửa. Múc ra tô, ăn nóng với cơm.', 'Mẹo: Nấm kim châm chín rất nhanh, cho vào đảo đều là nhấc nồi ngay để nấm còn giòn. Chọn nấm rơm búp đều cỡ để chín đều.']),
    'canh_ngheu_mang_le_vi_lau_thai': ('Canh nghêu nấu măng le, nấm rơm, cà chua, sả và lá chúc, nêm gia vị lẩu Thái chua cay.',
        ['Phi thơm 3 muỗng canh hành tím, vớt hành phi trộn vào thịt nghêu cùng 1 muỗng canh gia vị lẩu Thái nêm sẵn, để thấm.', 'Măng le đã luộc thái mỏng, cà chua cắt 6 múi, thì là và hành lá cắt khúc 2cm, đập dập sả và ớt hiểm, vò sơ lá chúc.', 'Phi thơm sả, cho nấm rơm và măng le vào xào sơ. Đổ 1 lít nước đun sôi, nêm 1/2 gói gia vị lẩu Thái, nấu đến khi măng chín.', 'Cho cà chua và lá chúc vào nấu sôi, sau cùng thả nghêu, thêm thì là, hành lá rồi tắt lửa.', 'Múc ra tô, rưới dầu tỏi, ăn kèm nước mắm nguyên chất và ớt thái lát, dùng với cơm hoặc bún.', 'Mẹo: Măng le mua sẵn nên luộc lại để bớt mùi. Ướp nghêu với hành phi và chút gia vị lẩu Thái cho thịt thấm thơm; nghêu tươi giúp canh ngọt tự nhiên.']),
    'canh_ngheu_mong_toi': ('Canh nghêu nấu rau mồng tơi với sả, gừng, chút giấm, nước trong vị ngọt thanh mát.',
        ['Rửa sạch nghêu, luộc vừa chín tới, gỡ thịt ướp với 1 muỗng cà phê nước mắm và 1/2 muỗng cà phê bột ngọt. Lọc nước luộc qua rây, rót nhẹ để bỏ cát lắng đáy.', 'Đập dập sả và ớt hiểm, gừng cắt lát, hành tím đập dập rồi băm nhuyễn.', 'Phi thơm hành với dầu, cho thịt nghêu vào xào sơ rồi trút ra đĩa.', 'Đun sôi nước luộc nghêu với sả, gừng, ớt. Nêm 2 muỗng cà phê hạt nêm, 1 muỗng cà phê muối, 1 muỗng cà phê nước mắm, 1 muỗng canh giấm gạo.', 'Cho mồng tơi vào nấu chín, thả nghêu vào rồi tắt bếp. Múc ra tô, rắc tiêu, ăn nóng.', 'Mẹo: Luộc nghêu vừa chín tới để thịt mềm; chút giấm gạo giúp canh đậm đà hơn.']),
    'canh_qua_sau_nau_tom_thi_la': ('Canh tôm nấu quả sấu và cà chua, thêm thì là, hành hoa, vị chua thanh ngọt dịu kiểu Bắc.',
        ['Để riêng 3 con tôm để trang trí, số còn lại cắt hạt lựu. Băm nhỏ cà chua, cắt đôi cà chua bi, hành hoa và thì là cắt khúc 3cm, ớt sừng thái lát.', 'Đun nóng 1 muỗng canh mỡ, phi vàng 1 muỗng canh hành khô. Tắt lửa rồi cho tôm vào, nêm 1/2 muỗng cà phê hạt nêm giảm muối, thêm cà chua băm.', 'Đun 1,2 lít nước nóng, cho sấu vào nấu khoảng 2 phút đến khi chín, dầm lấy nước chua rồi bỏ vỏ và hạt.', 'Cho nước sấu và cà chua bi vào nấu chín, nêm 1/2 muỗng cà phê đường, 1/2 muỗng cà phê hạt nêm giảm muối, 1/2 muỗng cà phê bột ngọt. Thả tôm vào, nêm 1 muỗng canh nước mắm.', 'Cho hành hoa, thì là và ớt vào rồi múc ra. Ăn với cơm trắng, chấm nước mắm ớt.', 'Mẹo: Tắt lửa rồi mới cho tôm vào hành phi để tôm thơm mà không chín quá. Tùy sấu to nhỏ dùng 6–10 quả.']),
    'canh_rau_den_khoai_so': ('Canh rau dền nấu khoai sọ và tôm băm, khoai bùi dẻo, nước canh ngọt thanh.',
        ['Đập dập tôm rồi băm sơ, ướp với 1/2 muỗng cà phê hạt nêm, 1/3 muỗng cà phê đường, 1 muỗng cà phê hành băm và chút tiêu. Nhặt rau dền, khoai sọ cắt miếng vừa to.', 'Phi thơm hành băm với dầu trong nồi, vớt ra một nửa để dành. Cho tôm vào xào săn.', 'Đổ 1 lít nước nấu sôi, cho khoai vào nấu mềm, nêm 1 muỗng canh hạt nêm và 1/2 muỗng cà phê đường.', 'Khoai chín thì thả rau dền, nêm 1 muỗng cà phê nước mắm, tắt bếp và rắc phần hành phi còn lại. Ăn nóng với cơm.', 'Mẹo: Đập dập tôm trước khi băm cho canh ngọt hơn; cắt khoai miếng vừa to để ăn còn dẻo bùi.']),
    'canh_rau_ma_khoai_lang': ('Canh rau má nấu khoai lang và bò viên trộn giò sống, ngọt bùi, thanh mát.',
        ['Rau má cắt vừa, khoai lang cắt khối nhỏ ngâm nước muối loãng.', 'Trộn thịt bò xay với giò sống và hành tím băm, nêm 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê bột năng. Để 15 phút cho thấm rồi vo viên.', 'Phi thơm hành tím bào, cho khoai lang vào đảo đến khi hơi xém cạnh. Đổ nước dùng vào nấu sôi, hạ lửa nhỏ cho khoai chín.', 'Nêm 1/2 muỗng cà phê muối, 1 muỗng cà phê đường, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng canh hạt nêm. Thả bò viên nấu sôi thêm 5 phút, cho rau má vào nấu chín rồi tắt lửa.', 'Múc ra tô, rắc tiêu và gừng sợi, ăn nóng với cơm trắng.', 'Mẹo: Xào khoai xém mặt để khoai chắc và thơm; giò sống và bột năng giúp bò viên dẻo, dễ vo.']),
    'canh_rau_muong_khoai_so': ('Canh rau muống nấu khoai sọ với chả cá thác lác viên, nêm nước mắm, vị ngọt thanh.',
        ['Lặt rau muống, cắt khúc 5cm. Đầu hành trắng băm nhuyễn, lá hành và ngò rí cắt nhỏ. Ớt sừng: nửa thái lát, nửa băm. Khoai sọ gọt sạch, cắt miếng vừa ăn.', 'Ướp cá thác lác với 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê đầu hành băm, 1 muỗng cà phê ớt băm, vo thành viên nhỏ.', 'Đun sôi 1,5 lít nước, thả cá viên vào, nêm 1,5 muỗng canh hạt nêm. Cho khoai sọ vào nấu đến khi chín mềm.', 'Thêm rau muống, rau chín thì nêm 1 muỗng canh nước mắm rồi tắt bếp. Múc ra tô, rắc hành lá, ngò rí, tiêu, ăn nóng với cơm.', 'Mẹo: Luộc sơ khoai rồi mới gọt để đỡ nhớt và ngứa tay; cho rau muống sau cùng để rau vừa chín tới.']),
    'canh_rau_tap_tang': ('Canh nhiều loại rau dân dã (dền, sam, ngọn bí, bồ ngót, rau má) nấu với tôm đất giã, ngọt mát.',
        ['Rửa sạch các loại rau, vò nát bồ ngót. Đầu hành lá đập dập, băm nhỏ.', 'Rửa tôm, tách đầu và đuôi để riêng, phần mình giã nát. Ướp tôm với đầu hành, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê bột ngọt.', 'Rang khô đầu và đuôi tôm không dầu, thêm 1 tô nước nấu sôi, vớt bọt, hạ lửa 5 phút rồi lọc lấy nước.', 'Đun nước tôm sôi lại, múc từng ít tôm giã thả vào nồi. Cho các loại rau vào nấu khoảng 2 phút đến khi chín.', 'Nêm 1/2 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, tắt lửa rồi thêm 1 muỗng cà phê nước mắm. Múc ra tô, rắc tiêu, ăn nóng.', 'Mẹo: Để tôm lạnh trước khi giã cho thịt dai; dùng đầu đuôi tôm nấu nước cho canh ngọt; không xào tôm với dầu để nước canh trong và thơm.']),
    'canh_rieu_ca_chep': ('Canh riêu cá chép chiên săn nấu cà chua và nước cơm mẻ, thêm thì là, chua nhẹ, ăn với bún hoặc cơm.',
        ['Làm sạch cá, ướp chút muối. Lọc cơm mẻ lấy nước. Đập dập cọng thì là nhét vào bụng cá; thì là và hành lá còn lại cắt khúc 3cm, cà chua cắt miếng vừa ăn.', 'Chiên cá đến khi săn mặt thì gắp ra đĩa.', 'Phi thơm đầu hành, cho cà chua vào xào, nêm chút muối và đường.', 'Đun sôi nước, cho 50g nước cơm mẻ, thả cá vào nấu vừa chín tới rồi cho cà chua xào vào. Khi chín, gắp cá ra tô rồi mới thêm thì là, hành lá và ớt thái lát.', 'Múc canh ra thố, ăn kèm bún, rau ghém và nước mắm ớt; cũng có thể ăn với cơm trắng.', 'Mẹo: Nhét thì là vào bụng cá để cá thơm và không bị bể bụng khi nấu.']),
    'canh_rieu_cua': ('Canh riêu cua đồng xay với cà chua, gạch cua, nước mẻ, thì là và hành, chua thanh kiểu Bắc.',
        ['Cho cua xay vào nước lạnh, khuấy đều rồi lọc lấy 1 lít nước cua, hòa tan 1 muỗng cà phê hạt nêm vào.', 'Cà chua thái múi mỏng, thì là và hành lá cắt khúc 4cm, đầu hành băm nhỏ. Lọc cơm mẻ lấy khoảng 5–6 muỗng canh nước.', 'Phi thơm đầu hành với 1 muỗng canh dầu, cho cà chua vào xào chín rồi thêm gạch cua xào cùng.', 'Nấu nước cua đến khi sôi, cho cà chua xào vào, nêm 3 muỗng canh hạt nêm và nước mẻ. Thả thì là, hành lá rồi tắt bếp, ăn nóng với cơm trắng.', 'Mẹo: Nêm hạt nêm vào nước cua trước khi nấu cho thơm; xào cà chua mềm trước cho màu đẹp; nấu lửa lớn, khi riêu nổi thì hạ lửa để riêu đóng tảng chắc.']),
    'canh_rong_bien_hat_sen': ('Canh chay rong biển wakame với hạt sen, nấm rơm, cà rốt và gừng, vị thanh nhẹ.',
        ['Ngâm rong biển cho nở rồi để ráo. Nấm rơm cắt đôi, gừng thái lát đập dập, cà rốt tỉa hoa thái lát, ngò rí cắt nhỏ.', 'Đun sôi 1,2 lít nước, cho hạt sen và gừng vào nấu lửa nhỏ khoảng 5 phút.', 'Thêm cà rốt và nấm rơm, nêm 1,5 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1 muỗng canh nước tương, nếm lại cho vừa.', 'Thả rong biển vào rồi tắt bếp. Múc ra tô, rắc ngò rí và tiêu, ăn nóng.', 'Mẹo: Không nấu rong biển lâu kẻo bị nhũn; wakame khô có vị thanh, hợp nấu canh và lẩu.']),
    'canh_rong_bien_thit_bo': ('Canh thịt bò thái mỏng nấu bí đỏ, rong biển và nấm kim châm, ngọt bùi dễ ăn.',
        ['Thịt bò thái mỏng, ướp 1/3 muỗng cà phê bột ngọt, 1 muỗng cà phê nước tương, 1 muỗng cà phê dầu ăn. Ngâm rong biển trong nước lạnh đến khi nở, vớt ráo.', 'Bí đỏ cắt khối 2cm, nấm kim châm tách nhỏ, ngò rí cắt nhỏ.', 'Phi thơm hành tím với dầu, cho bí đỏ vào xào săn. Đổ 1,2 lít nước nấu sôi, nêm 1/2 muỗng cà phê muối, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê bột ngọt, nấu đến khi bí mềm.', 'Cho rong biển, nấm kim châm và thịt bò vào, đun sôi lại, nếm vừa rồi tắt lửa. Múc ra tô, rắc tiêu và ngò rí, ăn nóng với cơm.', 'Mẹo: Cho nấm và rong biển sau cùng để không bị nhũn; xào sơ bí cho săn mặt sẽ nhanh chín và ngon hơn.']),
    'canh_song_thuy': ('Canh chả cá thác lác và tôm nấu thơm, cà chua bi, nêm giấm và sa tế, chua cay thơm rau.',
        ['Quết cá thác lác với 1 muỗng cà phê tỏi phi băm, 1 muỗng canh dầu tỏi, 1/3 muỗng canh tiêu, 1/4 muỗng canh bột ngọt, 1/2 muỗng canh nước mắm, vo viên cỡ trứng cút.', 'Tôm bóc vỏ chừa đuôi, rút chỉ lưng, ướp 1/3 muỗng canh tiêu, 1/4 muỗng canh muối, 1/2 muỗng canh đầu hành, 1/4 muỗng canh bột ngọt.', 'Thơm cắt miếng 2cm dày 5 li, ướp 1/4 muỗng canh đường và 1/4 muỗng canh muối. Cắt nhỏ rau thơm và hành lá, đập dập ớt hiểm.', 'Đun sôi nước dùng, thêm 1/2 muỗng canh muối, cho chả cá, tôm, cà chua bi và thơm vào nấu chín.', 'Nêm 1/2 muỗng canh đường, 1 muỗng canh bột ngọt, 3 muỗng canh giấm gạo, 1 muỗng canh nước mắm, 2 muỗng canh sa tế, thêm ớt hiểm rồi tắt lửa. Múc ra tô, rắc rau thơm, tỏi phi, ăn với cơm hoặc bún.', 'Mẹo: Ướp thơm với chút đường muối trước khi nấu cho vị chua ngọt dịu; lá tần dày lá vừa làm rau nêm vừa tốt cho người ho.']),
    'canh_suon_bi_do_rong_bien': ('Canh sườn non nấu bí đỏ, lê và rong biển wakame, nước trong ngọt thanh.',
        ['Sườn non chặt miếng 2cm, ngâm nước muối rồi xả nước lạnh đến khi nước trong. Bí đỏ và lê cắt khối 1cm, ngâm rong biển cho nở. Lá hành cắt nhỏ, đầu hành đập dập băm nhuyễn.', 'Ướp sườn với 1/2 muỗng cà phê hạt nêm, 1/4 muỗng cà phê muối, 1/4 muỗng cà phê tiêu, 1/4 muỗng cà phê đường, 1/2 muỗng cà phê bột năng, 1 muỗng canh nước, 1 muỗng cà phê dầu mè; để 15 phút.', 'Xào sườn với dầu cho săn, đổ 1,5 lít nước nấu sôi rồi hạ lửa hầm đến khi sườn mềm.', 'Cho bí đỏ và lê vào nấu chín, nêm 2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê đường, nếm vừa rồi cho rong biển vào và tắt lửa.', 'Múc ra tô, rắc ngò gai và hành lá, ăn nóng với cơm, thêm nước mắm tùy khẩu vị.', 'Mẹo: Xả sườn nhiều lần đến khi nước trong để canh trong; chút dầu mè cho sườn thơm; lê giúp nước canh ngọt thanh.']),
    'canh_suon_bo_han_quoc': ('Canh sườn bò hầm củ cải trắng, táo tàu, boa rô và nấm linh chi, nêm gia vị lẩu bò đậm đà.',
        ['Sườn bò cắt miếng vừa ăn, ướp 1 muỗng cà phê hành tím băm và 1 muỗng canh gia vị lẩu bò nêm sẵn cho thấm.', 'Củ cải trắng cắt miếng vừa ăn; boa rô cắt xéo, để riêng cọng và lá; các loại nấm cắt khúc vừa ăn.', 'Đun 2 lít nước, cho sườn vào hầm 20 phút đến khi mềm.', 'Thêm củ cải, táo tàu và phần gia vị lẩu bò còn lại, nấu 10 phút. Cho boa rô và nấm vào nấu thêm 5 phút rồi tắt lửa, múc ra tô.', 'Mẹo: Chọn sườn bò non nhiều thịt, xương dẹt và nhỏ.']),
    'canh_suon_cai_chua': ('Canh sườn non nấu dưa cải chua và cà chua, gừng hành thơm, vị chua dịu đưa cơm.',
        ['Sườn non chặt miếng vừa ăn, ướp 1/2 muỗng cà phê tiêu, 1 muỗng canh hành tím băm, 1 muỗng cà phê hạt nêm cho thấm.', 'Cải chua cắt khúc 2cm, hành lá cắt khúc 3cm, cà chua cắt múi cau.', 'Rang khô hành tím và gừng đập dập, cho sườn vào xào săn. Đổ 1,5 lít nước, nấu lửa nhỏ 10 phút.', 'Cho cải chua vào, nêm 1 muỗng canh hạt nêm, 1 muỗng canh đường, nấu sôi rồi thêm cà chua nấu thật chín.', 'Thả hành lá, tắt bếp, nêm 2 muỗng canh nước mắm. Múc ra tô, ăn nóng với cơm.', 'Mẹo: Cải quá chua thì xả sạch, vắt ráo trước khi nấu; xào sườn thật săn với gia vị cho thấm.']),
    'canh_suon_cu_cai_muoi': ('Canh sườn heo hầm củ cải muối đã ngâm bớt mặn, thêm câu kỷ tử, nước trong ngọt thanh.',
        ['Sườn chặt khúc 4cm, ướp 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê hạt nêm, để 15–30 phút.', 'Củ cải muối thái lát xéo dày 2mm, ngâm nước muối loãng 3–4 tiếng cho bớt mặn, xả lại nước lạnh rồi vắt ráo. Rửa câu kỷ tử để ráo; cắt nhỏ hành lá, ngò rí, ớt sừng.', 'Đun nước ấm, cho hành tím đập dập và sườn vào nấu sôi, hạ lửa, hớt bọt kỹ và hầm khoảng 15 phút.', 'Thêm củ cải muối, ninh đến khi sườn và củ cải mềm. Nêm 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê muối, cho câu kỷ tử vào.', 'Múc ra tô, rắc hành lá, ngò rí, ăn nóng với cơm, chấm nước tương ớt.', 'Mẹo: Chọn sườn non xương nhỏ, thịt dày ít mỡ, màu hồng.']),
    'canh_suon_cu_sen_a_ti_so': ('Canh sườn non hầm củ sen, a-ti-sô, cà rốt, hành tây và hành tím nướng, ngọt thanh.',
        ['Sườn non chặt khúc 3cm, ướp 1 muỗng cà phê hạt nêm và 1/2 muỗng cà phê muối.', 'Củ sen cắt khoanh dày 3 ly, a-ti-sô rửa sạch chẻ đôi, hành tây cắt múi cau nhỏ, cà rốt tỉa hoa.', 'Đun 1,8 lít nước, cho sườn và 2 củ hành tím nướng vào nấu, nêm 1/2 muỗng cà phê muối và 1/2 muỗng canh hạt nêm.', 'Nấu 10 phút thì cho củ sen và a-ti-sô vào, nấu thêm 25 phút rồi thêm hành tây và cà rốt.', 'Khi mọi thứ mềm, nêm 1/2 muỗng canh nước mắm và tắt lửa. Múc ra tô, rắc tiêu, hành, ngò, ăn với cơm kèm chén nước mắm.', 'Mẹo: Nấu a-ti-sô khoảng 25 phút để bông mềm; chọn bông còn tươi, xanh sáng, cánh không dập héo.']),
    'canh_suon_hat_sen': ('Canh sườn non nấu hạt sen, bắp non, bông cải, cà rốt và nấm hương, ngọt nước, nhiều rau củ.',
        ['Sườn non chặt miếng 3cm, ướp 1 muỗng cà phê hạt nêm và chút tiêu.', 'Bắp non, bông cải cắt vừa ăn; cà rốt tỉa hoa thái lát; nấm hương ngâm nở, làm sạch, cắt đôi.', 'Đun sôi 1,5 lít nước, cho sườn vào, nêm 1 muỗng canh hạt nêm, nấu khoảng 15 phút.', 'Lần lượt cho bắp non, cà rốt, hạt sen, nấm hương, sau cùng là bông cải nấu vừa chín. Tắt lửa, nêm 1/2 muỗng canh nước mắm, thêm hành ngò.', 'Múc ra tô, rắc tiêu, ăn với cơm kèm nước mắm nguyên chất và ớt thái lát.', 'Mẹo: Chọn sườn dày thịt, ít mỡ, xương nhỏ nhiều sụn; hạt sen tươi ngon có màu trắng sáng, không thâm.']),
    'canh_suon_non_tao_do': ('Canh sườn non hầm táo đỏ, bắp Mỹ và cà rốt, nước dùng ngọt dịu tự nhiên.',
        ['Rửa sạch sườn, chặt khúc vừa ăn, ướp 1/3 muỗng cà phê muối và 1/2 muỗng cà phê bột ngọt.', 'Bắp cắt khúc, cà rốt tỉa hoa thái lát, hành ngò cắt nhuyễn, táo đỏ ngâm nở.', 'Hầm sườn với 1,2 lít nước. Khi sôi, cho táo đỏ, bắp và cà rốt vào, nêm 1 muỗng cà phê đường, 1 muỗng cà phê muối, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê bột ngọt.', 'Nấu đến khi rau củ chín thì tắt lửa, thêm hành ngò. Múc ra tô, ăn với cơm.', 'Mẹo: Ngâm táo đỏ trước cho sạch và nước canh không bị sẫm; ướp sườn trước cho canh đậm đà.']),
    'canh_suon_non_xuyen_tieu': ('Canh sườn non nấu thuốc bắc với táo đỏ, kỷ tử, đẳng sâm, nấm đông cô, kim châm, thơm tê xuyên tiêu.',
        ['Rửa sạch sườn, để ráo, ướp 1 muỗng cà phê hạt nêm. Nấm đông cô ngâm nở, bỏ chân, cắt đôi; đẳng sâm rửa sạch cắt đôi; nấm kim châm xé rời.', 'Làm nóng nồi, xào xuyên tiêu với 1 muỗng canh dầu điều cho thơm, cho sườn vào xào săn.', 'Đổ 1,5 lít nước, nấu sôi 10 phút và vớt bọt. Thêm đẳng sâm, kỷ tử, táo đỏ, nấm đông cô, nấu thêm 20 phút đến khi nước còn khoảng 1 lít.', 'Cho nấm kim châm vào, nêm 1/3 muỗng cà phê muối, 2 muỗng cà phê hạt nêm, 1 muỗng cà phê đường, 1 muỗng cà phê bột ngọt.', 'Múc ra tô, rắc hành ngò, ăn nóng.', 'Mẹo: Phi xuyên tiêu với dầu trước cho dậy mùi; ngâm sườn cho ra hết máu để nước canh trong.']),
    'canh_thit_bo_cai_xoong': ('Canh thịt bò băm nấu cải xoong, nêm hành phi, nấu nhanh, vị thanh mát.',
        ['Thịt bò thái lát rồi băm nhỏ. Băm hành tím phi, trộn với thịt bò, nêm 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu.', 'Đun sôi nước, cho thịt bò vào, khuấy nhẹ cho thịt tơi ra và vớt bọt.', 'Khi nước sôi mạnh, cho cải xoong vào rồi tắt lửa. Nêm 1 muỗng cà phê hạt nêm và 1 muỗng cà phê muối.', 'Múc ra tô, rắc chút tiêu lên mặt cho thơm.', 'Mẹo: Hòa chút nước vào thịt bò băm và tán đều để khi nấu thịt không bị vón cục.']),
    'canh_tom_bap_vien': ('Canh tôm bắp viên trộn giò sống, nấu với su hào, cà rốt, nấm rơm, ngọt thanh trẻ nhỏ dễ ăn.',
        ['Tôm bóc vỏ, bỏ đầu, băm nhỏ. Su hào, cà rốt gọt vỏ cắt miếng, chừa 1 muỗng canh cà rốt băm nhỏ. Bắp tách hạt băm nhỏ. Đầu hành băm, lá hành và ngò rí cắt nhỏ, nấm rơm rửa sạch cắt đôi.', 'Trộn tôm, bắp, giò sống với 2 muỗng cà phê hành lá, 2 muỗng cà phê đầu hành băm, 1 muỗng canh cà rốt băm, 1 muỗng cà phê hạt nêm, 1/4 muỗng cà phê tiêu, vo viên nhỏ.', 'Đun sôi 1 lít nước, cho cà rốt, su hào, nấm rơm vào nấu khoảng 3 phút.', 'Thả tôm viên, đợi sôi lại thì nêm 2 muỗng canh hạt nêm, 1/3 muỗng cà phê tiêu, thêm ngò rí, hành lá, nếm vừa rồi tắt bếp. Múc ra tô, rắc tiêu, ăn nóng.', 'Mẹo: Giò sống đã có sẵn vị nên chỉ cần thêm tiêu và đầu hành băm.']),
    'canh_tom_la_ot': ('Canh lá ớt nấu chả tôm sú quết dai và ớt non, ngọt thanh, thơm bùi.',
        ['Lá ớt cắt đôi, ớt non đập dập, hành lá cắt nhỏ, đầu hành băm nhuyễn.', 'Băm nhỏ tôm, chừa 4 con nguyên đuôi để trang trí. Ướp tôm băm với 1 muỗng canh đầu hành, 1/4 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt rồi quết sơ cho dai.', 'Đun sôi 1,2 lít nước dùng, cho tôm nguyên con vào, dùng muỗng múc chả tôm thả vào nồi. Nêm 1/2 muỗng cà phê đường, 1 muỗng cà phê bột ngọt, 2/3 muỗng cà phê muối; tôm chín thì vớt ra.', 'Cho lá ớt và ớt non vào nấu chín, nêm 1/2 muỗng cà phê nước mắm rồi tắt lửa. Múc ra tô, thêm hành lá, tiêu, ăn nóng.', 'Mẹo: Lau khô tôm và quết sơ sau khi băm để chả hơi giòn; chọn lá ớt bánh tẻ cho vị bùi.']),
    'canh_tom_moc_hat_sen': ('Canh mọc tôm trộn giò sống nấu hạt sen, nấm rơm, cà rốt và hành tây, ngọt thanh.',
        ['Trộn giò sống với tôm cắt hạt lựu, 1 muỗng cà phê hành tím, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê cọng ngò băm, 1 muỗng cà phê ớt băm, vo viên. Lấy giò sống bọc quanh 4 con tôm nguyên để trang trí.', 'Nấm rơm rửa sạch, khía chữ thập; cà rốt tỉa hoa cắt khoanh 5 ly; hành tây cắt hạt lựu 1,5cm.', 'Đun sôi nước dùng, nêm 1 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê hạt nêm. Cho hạt sen, cà rốt, nấm rơm vào nấu chín.', 'Thả viên mọc và hành tây vào, khi chín mềm thì tắt lửa, thêm hành ngò và 1/2 muỗng canh nước mắm.', 'Múc ra tô, rắc hành ngò và tiêu, ăn nóng kèm nước mắm tiêu.', 'Mẹo: Cắt tôm hạt lựu để ăn còn cảm nhận được miếng tôm; mọc đã đủ vị nên không cần nêm nhiều.']),
    'canh_tom_nam_mong_toi': ('Canh mồng tơi với tôm bọc giò sống, nấm bào ngư và cà chua, nêm gia vị lẩu Thái chua nhẹ.',
        ['Tách đầu tôm để riêng, thân bóc vỏ chừa đuôi rồi cắt làm 3. Nấm bào ngư tách đôi hoặc để nguyên, mồng tơi cắt khúc 3cm, cà chua cắt múi cau.', 'Ướp tôm với 1/2 muỗng cà phê gia vị lẩu Thái nêm sẵn. Trộn giò sống với 1 muỗng cà phê ngò băm, 2 muỗng cà phê hành tím băm, 1/2 muỗng cà phê tiêu; chia 9 phần, bọc quanh tôm, chừa đuôi ra ngoài.', 'Phi vàng hành tỏi băm với dầu, cho đầu tôm vào xào thơm, đổ 1 lít nước nấu sôi. Nêm 3,5 muỗng canh gia vị lẩu Thái, khuấy tan.', 'Sôi lại thì cho nấm, cà chua và tôm viên vào, nấu sôi tiếp. Cuối cùng thả mồng tơi, nêm 1/2 muỗng canh nước mắm, rau vừa chín thì tắt lửa.', 'Múc ra tô, ăn nóng với cơm.', 'Mẹo: Xào đầu tôm trước cho nước canh ngọt và thơm; nấu rau vừa chín tới để giữ màu và độ giòn.']),
    'canh_tuong_dau': ('Canh tương đậu kiểu Hàn với thịt bò xay, đậu hũ non, bí ngòi, nấm, giá và cá cơm khô, đậm vị.',
        ['Ướp thịt bò xay với 1 muỗng canh tỏi băm, 1 muỗng cà phê hạt nêm, chút tiêu, 1/3 muỗng cà phê dầu mè, 1/2 muỗng cà phê nước tương, 1 muỗng canh nước.', 'Bí ngòi thái lát, cá cơm khô rửa sạch đập dập, đậu hũ cắt khối 1–1,5cm, nấm đông cô thái lát, lá boa rô băm nhuyễn, hành tây cắt múi cau.', 'Đun sôi 1,5 lít nước, cho cá khô vào, thêm 3 muỗng canh tương đậu Hàn Quốc khuấy tan, nấu sôi 5 phút.', 'Cho nấm, bí ngòi, đậu hũ vào nấu chín, nêm 1 muỗng canh hạt nêm, 1/3 muỗng cà phê muối, 1 muỗng cà phê bột ngọt.', 'Thêm thịt bò, hành tây, giá vào nấu sôi rồi tắt lửa; cho lá boa rô, tiêu và 1 muỗng canh giấm gạo. Múc ra tô, ăn nóng với cơm trắng.', 'Mẹo: Giã cá khô trước khi nấu cho nước canh dậy mùi; cho giá sau cùng để giữ độ giòn.']),
    'canh_duoi_bo_cu_cai': ('Canh đuôi bò nấu nồi áp suất với củ cải, cà rốt, sả gừng và kỷ tử, ngọt đậm, ấm bụng.',
        ['Cạo rửa đuôi bò, chặt khúc 3cm, chần qua nước với 1 củ gừng đập dập rồi rửa lại. Ướp với 1/2 muỗng canh hạt nêm, 1 muỗng cà phê hành tím băm, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu.', 'Củ cải, cà rốt gọt vỏ, tỉa hoa, thái lát dày 3 li. Cắt nhỏ hành lá, ngò rí; sả cắt khúc đập dập; gừng băm nhỏ.', 'Phi thơm hành tím và gừng băm, cho đuôi bò vào xào thơm.', 'Đun 1 lít nước ấm trong nồi áp suất, cho đuôi bò và sả vào nấu sôi 15 phút. Thêm củ cải, cà rốt nấu đến khi mềm, cho kỷ tử vào rồi tắt bếp.', 'Nêm nước mắm vừa ăn, thêm hành lá, ngò rí. Múc ra tô, rắc tiêu, ăn nóng với cơm.', 'Mẹo: Xào đuôi bò với hành gừng cho thịt săn thơm; cho rau củ vào khi đuôi bò vừa mềm để mọi thứ chín đều.']),
    'canh_vit_khoai_so': ('Canh vịt nấu khoai sọ và cà rốt, thêm ngò gai, rau om, thịt ngọt, khoai bùi.',
        ['Làm sạch vịt, khứa vài đường trên da, áp chảo cho ra bớt mỡ. Chặt miếng vừa ăn, ướp 1 muỗng cà phê hạt nêm.', 'Khoai sọ gọt vỏ cắt miếng, cà rốt cắt miếng, ngò gai và rau om cắt nhỏ.', 'Phi thơm hành tím, cho vịt vào xào săn. Đổ 1,2 lít nước sôi, nêm 1 muỗng canh hạt nêm, nấu 15–20 phút đến khi thịt vừa chín.', 'Thêm khoai sọ và cà rốt nấu chín, tắt lửa rồi cho ngò gai, rau om.', 'Múc ra tô, rắc tiêu, ăn với cơm kèm nước mắm nguyên chất và ớt.', 'Mẹo: Áp chảo da vịt để bớt mỡ và khử mùi; xào vịt với hành tím để thịt thơm, ngọt và không nát.']),
    'canh_duoi_heo_cu_sen': ('Canh đuôi heo hầm củ sen và cà rốt với hành tím nướng, rễ ngò, nước ngọt thơm.',
        ['Đun 1 lít nước gần sôi, nêm 1 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 2 muỗng cà phê hạt nêm.', 'Củ sen gọt vỏ, cắt khoanh, ngâm nước pha 1 muỗng cà phê nước chanh. Cà rốt tỉa hoa thái mỏng, nướng vàng hành tím, đuôi heo rửa sạch chặt khúc. Hành lá cắt nhỏ; ngò rí cắt lá, giữ riêng rễ.', 'Cho đuôi heo, 2 củ hành nướng và rễ ngò vào nồi nước, hầm lửa nhỏ khoảng 10 phút.', 'Thêm 0,5 lít nước, đun sôi rồi cho củ sen và cà rốt vào nấu 10–15 phút đến khi chín. Vớt bỏ hành nướng và rễ ngò, nêm 1 muỗng canh nước mắm, thả hành lá rồi tắt bếp.', 'Múc ra tô, rắc ngò rí và tiêu, ăn nóng với cơm.', 'Mẹo: Ngâm củ sen trong nước chanh để không bị thâm; chia nước làm 2 lần giúp đuôi heo thấm vị hơn.']),
    'cat_heo_xao_bi_ngoi': ('Cật heo khứa hoa xào nhanh với bí ngòi xanh vàng và cà rốt, nêm nước mắm tỏi, giòn ngọt.',
        ['Bí ngòi rửa sạch, bỏ bớt ruột, cắt miếng vừa ăn. Cà rốt cắt sợi, ngò rí cắt nhỏ, đầu hành trắng băm nhuyễn.', 'Cật heo bổ dọc, lạng bỏ phần trắng giữa, rửa với muối, khứa xéo mặt trong rồi cắt miếng nhỏ. Ướp với 1/3 muỗng cà phê tiêu, 1/2 muỗng cà phê hạt nêm và đầu hành băm.', 'Phi thơm 1 muỗng canh tỏi băm, cho cật vào xào nhanh tay vài phút.', 'Thêm cà rốt và bí ngòi, nêm 1/2 muỗng canh nước mắm, đảo đều đến khi rau chín thì tắt bếp. Bày ra đĩa, rắc tiêu và ngò rí, ăn nóng.', 'Mẹo: Lọc sạch phần trắng và rửa cật với muối để hết mùi hôi; bí ngòi mau chín nên xào nhanh rồi tắt bếp ngay.']),
    'cha_ca_ha_noi': ('Chả cá lăng ướp riềng nghệ mẻ, nướng rồi rưới mỡ hành thì là, ăn với bún, bánh đa, mắm tôm.',
        ['Cá bỏ da, rửa sạch, thấm khô, cắt miếng dày 0,7 mm, cỡ 3x4 cm. Ướp với 1 muỗng canh nước riềng, 1 muỗng canh nước nghệ, 2 muỗng canh cơm mẻ, 1/2 muỗng canh mắm tôm, 1 muỗng cà phê bột ngọt, 1 muỗng canh nước hành tỏi, 1/2 muỗng canh nước mắm, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê mạch nha.', 'Hành lá và thì là cắt khúc 4 cm, đầu hành chẻ nhỏ. Giã nhuyễn cọng thì là, thêm 1/4 muỗng cà phê muối, 1/4 muỗng cà phê bột ngọt, trộn với hành tỏi phi và 1/2 chén mỡ.', 'Pha mắm tôm: đánh bông 2 muỗng canh mắm tôm với 2 muỗng canh nước chanh, 1 muỗng canh đường, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng canh rượu trắng.', 'Xếp cá lên vỉ nướng sơ, vừa nướng vừa phết hỗn hợp thì là tỏi cho thơm và bóng, nướng đến khoảng 60%.', 'Cho cá vào chảo đặt trên lò than nhỏ lửa, rắc hành lá và thì là lên. Đun nóng 1/2 chén mỡ với ít hành lá rồi rưới lên cá cho rau vừa chín tới.', 'Ăn kèm bún, bánh đa nướng, đậu phộng, đầu hành chẻ nhúng giấm gạo, mắm tôm pha, húng quế và rau sống.', 'Mẹo: Cắt cá đều tay để chín đều; chọn cá ít tanh, ít xương, thịt chắc như cá lăng, cá lóc bông.']),
    'cha_ca_kho_chua_cay': ('Chả cá basa chiên vàng kho với thơm, nấm rơm, nước dừa, tiêu và ớt, chua cay sánh đậm.',
        ['Vo chả cá thành viên cỡ trái tắc, ấn dẹt, chiên với ít dầu đến khi vàng mặt.', 'Nấm rơm rửa sạch, khía chữ thập trên đầu; thơm cắt rẻ quạt dày 3mm; đập dập ớt hiểm; ớt sừng và hành ngò cắt khúc.', 'Pha hỗn hợp kho: 2 muỗng canh hạt nêm, 1 muỗng canh đường, 1 muỗng canh muối, 1/2 muỗng canh bột ngọt, 3 muỗng canh nước tương, 2 muỗng canh giấm gạo.', 'Phi thơm tỏi với 2 muỗng canh dầu điều, cho thơm vào đảo, nêm 1,5 muỗng canh đường. Thêm chả cá, nấm rơm trộn đều, đổ hỗn hợp kho vào kho 2 phút.', 'Cho nước dừa, ớt hiểm, ớt sừng và tiêu vào. Sôi thì hạ lửa, kho đến khi nước hơi sánh rồi tắt bếp. Bày ra đĩa, rắc hành ngò, tiêu, ăn với cơm nóng và rau dưa.', 'Mẹo: Chiên chả vừa chín để không bị khô; ớt hiểm tạo vị cay, ớt sừng cho mùi thơm và màu đẹp.']),
    'cha_ca_kho_van_trung': ('Chả cá basa chiên kho cà chua sa tế, thêm xốt mayonnaise và trứng đánh tạo vân, ăn với bánh mì.',
        ['Chiên sơ chả cá rồi cắt miếng vừa ăn. Băm nhỏ cà chua, cắt nhỏ hành ngò, đánh tan trứng.', 'Phi thơm hành tím với 2 muỗng canh dầu điều, cho cà chua vào xào, thêm 1/2 chén nước.', 'Nêm 1,5 muỗng cà phê đường, 1 muỗng cà phê hạt nêm, 1/3 muỗng cà phê muối, 1 muỗng cà phê sa tế tôm, 1/3 muỗng cà phê bột ngọt. Cho chả cá vào kho nhỏ lửa đến khi nước hơi cạn.', 'Khuấy tan 1/2 muỗng canh xốt mayonnaise vào, rót trứng từ từ để tạo vân, thêm hành lá, ngò rí rồi tắt lửa.', 'Bày ra đĩa, rắc tiêu, trang trí xà lách, ớt, ngò rí, ăn kèm bánh mì.', 'Mẹo: Rót trứng từ từ và dùng đũa đánh đều tay để vân đẹp; để chả cá chiên vào ngăn mát rồi mới cắt cho miếng đẹp.']),
    'cha_ca_la_vong': ('Cá lóc ướp riềng, nghệ, mẻ, mắm tôm rồi áp chảo, ăn với bún, rau thơm và mắm tôm pha.',
        ['Cá lạng lát xéo, rửa với hỗn hợp nước cốt gừng pha rượu để khử mùi, để ráo.', 'Ướp cá với 1/3 muỗng cà phê muối, 1/3 muỗng cà phê tiêu, 2 muỗng cà phê bột ngọt, 3 muỗng cà phê riềng, 3 muỗng canh nước nghệ, 2 muỗng cà phê hành tím băm, 2 muỗng cà phê thì là băm, 1 muỗng cà phê sả băm, 2 muỗng canh mẻ, 3 muỗng cà phê mắm tôm; đảo đều rồi để lạnh cho thấm.', 'Cho 1 muỗng canh dầu vào chảo, phi nhanh hành lá và thì là cắt khúc khoảng 10cm.', 'Cho 2 muỗng canh dầu vào chảo phẳng, áp chảo cá đến khi xém vàng thì lật cho chín đều, gắp ra đĩa.', 'Pha mắm tôm: 1,5 muỗng canh mắm tôm, 1/2 muỗng canh rượu trắng, 1/4 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê tỏi băm, 1 muỗng cà phê nước cốt chanh, 1 muỗng cà phê dầu tỏi. Ăn cá với bún, húng lủi, thì là, hành hoa, ớt sừng thái chỉ.', 'Mẹo: Ướp gia vị khô và nước nghệ trước rồi mới cho gia vị lỏng để cá dễ thấm.']),
    'cha_ca_ngu_sac': ('Chả cá basa trộn cà rốt, bắp, hành lá, đặt trên bánh tráng rồi áp chảo, chấm xốt phô mai cay.',
        ['Trộn chả cá với cà rốt, hành lá, bắp và chút tiêu, nhồi kỹ cho dai.', 'Phết chả cá lên bánh tráng, tạo hình tùy thích.', 'Đun nóng dầu, cho chả vào áp chảo đến khi chín đều.', 'Xếp ra đĩa, chấm với xốt phô mai cay.', 'Mẹo: Dùng bánh tráng dày để tạo hình dễ và đẹp hơn.']),
    'cha_ech_la_lot_chien': ('Chả ếch băm trộn giò sống, lá lốt, sả, cà ri, áo bột chiên giòn, chấm nước mắm me.',
        ['Làm sạch ếch, để ráo rồi băm nhuyễn. Lá lốt cắt nhỏ.', 'Trộn ếch với giò sống, lá lốt, 1 muỗng canh hành tỏi băm, 1 muỗng canh sả băm, 2 muỗng canh ớt băm, 3 muỗng canh bột chiên giòn, 1 muỗng cà phê hạt nêm, 2 muỗng canh bột cà ri, 1 muỗng cà phê bột nghệ.', 'Vo viên cỡ trái chanh, ấn dẹt, lăn qua một lớp bột chiên giòn. Chiên trong chảo dầu nóng đến khi vàng giòn.', 'Làm nước mắm me: đun 4 muỗng canh đường, 2 muỗng canh nước mắm, 2 muỗng canh nước, 3 muỗng canh nước cốt me đến khi tan đường, thêm 1 muỗng canh gừng băm, 1 muỗng canh ớt băm rồi tắt lửa.', 'Bày chả ếch ra đĩa với rau thơm, xà lách, dưa leo, chấm nước mắm me.', 'Mẹo: Chọn ếch tươi, thịt trong, xương nhỏ để dễ băm và ăn không bị cứng; lá lốt nhỏ thơm hơn.']),
    'cha_gio_rong_bien': ('Chả giò cuốn lá rong biển nhân tôm, mực, thịt nạc, rau củ, hai đầu lăn mè rồi chiên giòn.',
        ['Lau thật ráo tôm, đập dập rồi băm nhỏ; băm nhỏ mực; vắt ráo các loại rau củ băm.', 'Trộn tôm, mực, thịt nạc dăm, giò sống với 1 lá rong biển cắt nhỏ. Nêm 1 muỗng cà phê bột năng, 1/2 muỗng canh tỏi băm, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê nước mắm.', 'Thêm rau củ và lòng trắng trứng, quết dai rồi để ngăn mát 15 phút.', 'Cắt rong biển thành miếng 3x5cm, đặt nhân lên rồi cuốn tròn, nhúng hai đầu vào mè trắng.', 'Quay chả trong lò vi sóng 2 phút ở mức cao, để nguội rồi chiên lửa vừa đến khi mè vàng, vớt ra để ráo dầu.', 'Chấm với xốt mayonnaise trộn tương ớt tỉ lệ 1:1.', 'Mẹo: Nguyên liệu càng ráo nhân càng kết dính; làm chín bằng lò vi sóng trước giúp chiên nhanh và chả không khô.']),
    'cha_khoai_hap': ('Chả hấp từ khoai mỡ, khoai môn tán trộn thịt xay, tôm, nấm mèo, phết lòng đỏ trứng.',
        ['Khoai cắt cỡ ngón tay, cho vào tô với 1 muỗng canh nước, chút muối và tiêu, bọc màng, quay lò vi sóng 5–7 phút rồi tán nhỏ.', 'Tách riêng lòng trắng và lòng đỏ trứng. Nấm mèo ngâm nở thái sợi, ngò rí băm nhỏ, ớt sừng thái sợi.', 'Trộn đều tôm, thịt, khoai, nấm mèo, lòng trắng trứng với 1/2 muỗng cà phê bột ngọt, 1/3 muỗng cà phê muối, 1 muỗng cà phê đường, 1/3 muỗng cà phê tiêu và ngò rí.', 'Thoa dầu vào đĩa sâu lòng, cho hỗn hợp vào nén chặt, hấp 15 phút. Phết lòng đỏ lên mặt, hấp tiếp không đậy nắp đến khi lòng đỏ chín.', 'Ăn kèm xà lách, rau sống và nước tương.', 'Mẹo: Có thể đổi sang loại khoai khác; làm chín khoai bằng lò vi sóng nhanh hơn và khoai ráo thơm.']),
    'cha_lua_kho_trung_cut': ('Chả lụa kho trứng cút và su hào với sả, hành tỏi ớt, nêm xốt tương, mặn ngọt đưa cơm.',
        ['Chả lụa cắt khối vừa ăn. Su hào gọt vỏ, cắt khối 1,5cm bằng dao răng cưa. Luộc chín trứng cút, bóc vỏ. Băm nhuyễn sả, cắt nhỏ ngò rí.', 'Phi thơm 1 muỗng canh hành, 1 muỗng canh tỏi, 1 muỗng canh ớt băm, 1 muỗng canh sả với 2 muỗng canh dầu ăn và 1 muỗng cà phê dầu điều.', 'Cho su hào và chả lụa vào xào sơ, đổ nước xâm xấp mặt. Nước sôi thì thả trứng cút, nêm 1 muỗng canh xốt tương, 1 muỗng cà phê đường, 2,5 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt.', 'Hạ lửa nhỏ, kho đến khi nước gần cạn thì tắt bếp, cho ngò rí vào đảo đều. Bày ra đĩa, rắc tiêu, ăn nóng với cơm.', 'Mẹo: Phi hành tỏi trước rồi mới cho sả vì hành tỏi nhiều nước hơn; kho lửa nhỏ cho thấm.']),
    'cha_trung_hap': ('Chả trứng hấp từ trứng vịt, trứng muối, thịt nạc xay, nấm mèo, bún tàu, mặt phết lòng đỏ màu điều.',
        ['Ướp thịt xay với 1 muỗng cà phê hành tím, 1/4 muỗng cà phê hạt nêm, 1/4 muỗng cà phê tiêu, 1/4 muỗng cà phê đường, 1 muỗng cà phê nước.', 'Tách lòng đỏ trứng muối, cắt nhỏ. Nấm mèo thái sợi, bún tàu cắt khúc ngắn.', 'Tách 2 lòng đỏ trứng vịt để riêng, lấy 1 muỗng canh lòng trắng pha với 1 muỗng cà phê dầu điều. Phần trứng còn lại trộn với thịt, nấm mèo, bún tàu và 1 muỗng canh lòng trắng trứng muối.', 'Cho hỗn hợp vào chén nhỏ, hấp 20 phút. Khi chả chín, phết hỗn hợp lòng đỏ pha dầu điều lên mặt, hấp thêm khoảng 2 phút đến khi mặt khô.', 'Ăn với cơm hoặc cơm tấm bì.', 'Mẹo: Hấp lửa vừa để chả không bị rỗ; thêm chút nước vào thịt cho dễ hòa với trứng, chả mềm hơn; lòng đỏ trứng muối giúp chả béo.']),
    'cha_tom_xien_que_nuong_me': ('Xiên que tôm nguyên con, chả tôm quết, hành tây, ớt chuông, cà chua bi nướng, chấm xốt mayonnaise mè.',
        ['Lấy 12 con tôm bỏ đầu, bóc vỏ chừa đuôi. Số còn lại bóc vỏ, xẻ lưng rút chỉ, lau khô. Hành tây cắt múi cau, ớt chuông cắt quả trám 2cm, mỡ gáy ướp chút đường và muối.', 'Quết nhuyễn tỏi và đầu hành, cho tôm vào quết mịn dai. Nêm 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê muối, 1/4 muỗng cà phê tiêu, thêm 1 muỗng canh lòng trắng trứng và mỡ, quết đều.', 'Chia chả thành 12 viên cỡ trái tắc, để ngăn mát khoảng 10 phút. Ướp tôm nguyên con với 1/3 muỗng cà phê bột ngọt, 1/3 muỗng cà phê muối, 1/3 muỗng cà phê đường, chút tiêu và 1/2 muỗng canh mè rang.', 'Ngâm que xiên trong nước, xiên xen kẽ hành tây, tôm, ớt chuông, viên chả và cà chua bi rồi nướng vừa chín.', 'Pha xốt: trộn 2 muỗng canh xốt mayonnaise, 1 muỗng canh tương ớt và 1/2 muỗng canh mè rang giã. Bày xiên ra đĩa, chấm kèm.', 'Mẹo: Lau khô tôm trước khi quết để chả dai; lòng trắng và mỡ giúp chả không khô; ngâm que tre để khỏi cháy.']),
    'chan_ga_sa_tac': ('Chân gà luộc ngâm nước giấm đường cùng sả, tắc, ớt, lá chanh, chua ngọt giòn, ăn chơi.',
        ['Làm sạch chân gà, cắt móng, chà với muối hạt và rượu trắng rồi rửa lại. Ớt sừng và sả thái lát xéo mỏng, đầu sả đập dập, tắc và lá chanh cắt đôi.', 'Luộc chân gà 5–7 phút trong nước có 1 muỗng cà phê muối, vớt ra ngâm nước đá cho nguội.', 'Nấu tan 600ml nước với 8 muỗng canh đường, 6 muỗng canh giấm gạo, 2 muỗng cà phê muối, 2 muỗng canh nước mắm rồi để nguội.', 'Cho sả, tắc, ớt, lá chanh và chân gà vào nước ngâm, để ngăn mát 1 ngày. Lấy ra đĩa dùng ăn chơi hoặc khai vị.', 'Mẹo: Chà chân gà với muối và rượu để khử mùi; chẻ đôi chân gà cho dễ thấm và dễ ăn.']),
    'chan_gio_cuon_ham_sam': ('Chân giò rút xương cuộn tròn hầm hồng sâm, đương quy, táo đỏ, hạt sen, củ sen, cà rốt, ấm bụng.',
        ['Ướp thịt với 1/2 muỗng cà phê bột ngọt và 1/2 muỗng cà phê muối, dùng chỉ cotton cuộn tròn. Rửa sạch sâm, đương quy, kỷ tử, táo đỏ rồi ngâm nước. Củ sen thái lát, ngâm nước muối loãng.', 'Chần sơ cuộn thịt trong nước có chút gừng và muối.', 'Cho thịt vào nồi nước dùng cùng hồng sâm, nêm 1 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, hầm khoảng 20 phút.', 'Phi thơm hành khô băm, tiêu sọ và gừng lát, cho đương quy, táo đỏ, hạt sen vào xào.', 'Khi thịt vừa chín, cho hỗn hợp xào và củ sen vào hầm 15 phút, thêm cà rốt nấu đến khi mọi thứ chín đều rồi tắt lửa. Ăn kèm bún hoặc cơm.', 'Mẹo: Lạng bớt thịt để cuộn đều đẹp; cho đương quy, hạt sen, táo đỏ vào lúc thịt vừa chín để chín đồng đều.']),
    'chao_bo_cau': ('Cháo bồ câu ướp gừng hành, hầm cách thủy cùng gạo rang, đậu xanh và nấm hương, vị ngọt thanh, thơm gừng.',
        ['Nấu xương gà với 4 lát gừng, vài nhánh hành lá và nấm hương để lấy nước dùng.', 'Ướp bồ câu với 1 muỗng canh gừng băm, 1 muỗng canh hành lá băm, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê hạt nêm vị gà trong 15–20 phút, rồi nhét phần gừng hành vào bụng chim và xoa đều.', 'Vo gạo tẻ, để ráo rồi rang vàng. Ngâm đậu xanh cho nở, cắt nhỏ hành lá.', 'Vớt xương ra, cho gạo rang vào nồi nước dùng nấu thành cháo.', 'Đặt bồ câu vào thố, múc cháo cùng nấm hương vào, thêm đậu xanh và hành tím nướng. Hấp cách thủy khoảng 1 giờ.', 'Múc ra chén, rắc hành lá và ngò rí.', 'Mẹo: Chọn gạo tẻ nở mềm, xốp để cháo ngon; hấp lửa nhỏ đều để thịt chim chín mềm.']),
    'chao_ca_hoi': ('Cháo gạo nấu đậu đen nhừ với cà rốt, bắp, đậu que, thả cá hồi vào cuối, ngọt dịu, hợp cho bé.',
        ['Cắt cá hồi hạt lựu 1,5cm, ướp 1 muỗng cà phê hạt nêm và 1/2 muỗng cà phê tiêu.', 'Cà rốt: một phần tỉa hoa thái lát mỏng, một phần cắt hạt lựu. Đậu que cắt khúc 2cm. Bắp luộc chín, tách hạt. Vo sạch gạo và đậu đen; cắt nhỏ hành ngò.', 'Nấu gạo và đậu đen với 1,5 lít nước trong nồi áp suất 10 phút cho nhừ.', 'Thêm cà rốt, bắp, đậu que nấu khoảng 5 phút, nêm 2 muỗng cà phê hạt nêm và 1/2 muỗng cà phê muối. Cho cá vào rồi nhấc nồi xuống ngay, rắc tiêu và hành ngò.', 'Múc ra tô, ăn nóng.', 'Mẹo: Chọn cá thịt đỏ, săn chắc; ngâm đậu đen trước cho mau mềm; cho cá vào sau cùng để cá không nát và giữ vị.']),
    'chao_hau': ('Cháo gạo rang nấu nước dùng gà, thêm hàu sữa xào dầu hào, gừng, tiêu xanh, ăn kèm tía tô và hành phi.',
        ['Rang gạo cho thơm rồi nấu cháo với 2 lít nước dùng gà.', 'Ngâm rửa sạch thịt hàu, để ráo. Cắt nhỏ tía tô và hành lá. Đập dập gừng, giã sơ tiêu xanh.', 'Phi thơm 50g hành tím thái lát cùng gừng và tiêu xanh. Tắt lửa, cho hàu vào trộn với 2 muỗng canh dầu hào.', 'Trút hàu vào nồi cháo, thêm cà rốt băm, 1/2 muỗng canh hạt nêm, 1 muỗng cà phê bột ngọt, 1/2 muỗng canh dầu màu điều rồi tắt bếp.', 'Múc ra tô, thêm tía tô, hành phi và rắc tiêu, ăn nóng.', 'Mẹo: Rang gạo trước giúp cháo mau bung; dầu hào tạo mùi vị đặc trưng cho cháo.']),
    'chao_hau_sua_dau_xanh': ('Cháo gạo thơm, gạo nếp rang với đậu xanh, hàu sữa xào gừng tỏi, nêm nước mắm, thơm rau răm.',
        ['Trộn gạo thơm với gạo nếp, rang vàng rồi cho dầu phi hành vào đảo cho thơm.', 'Ướp hàu với 1/3 muỗng cà phê tiêu, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê tỏi băm, 1/2 muỗng cà phê gừng băm. Cắt nhỏ hành lá, ngò rí, rau răm.', 'Đun 2 lít nước dùng với 2 củ hành nướng; khi sôi lại thì hạ lửa, cho gạo và đậu xanh vào nấu đến khi nở mềm.', 'Nêm 1 muỗng cà phê đường, 1 muỗng cà phê bột ngọt, 1/2 muỗng canh muối, khuấy đều.', 'Xào hàu với dầu nóng cho chín thơm, trút vào nồi cháo rồi tắt bếp. Nêm thêm 1 muỗng canh nước mắm, cho hành ngò, rau răm vào.', 'Múc ra tô, xếp hàu lên trên, rắc hành phi; ăn kèm chanh, ớt, bánh tráng nướng.', 'Mẹo: Rang gạo vàng trước khi nấu để hạt bung mà cháo không bị nhão.']),
    'chao_luon_khoai_mon_dau_xanh': ('Cháo gạo tấm nấu đậu xanh, khoai môn sánh bùi, thịt lươn gỡ trộn hành phi, nêm nước mắm tiêu.',
        ['Lươn rửa với giấm rồi rửa lại nước sạch, cắt khúc khoảng 10cm, khứa hai bên sống lưng. Khoai môn cắt khối 1cm. Đậu xanh ngâm mềm, bỏ bớt vỏ. Băm hành tím, phi thơm một phần và giữ lại dầu.', 'Nấu gạo tấm và nếp với 1/2 lít nước, nêm 2 muỗng canh hạt nêm, cho đậu xanh vào. Cháo nhừ thì thêm khoai môn; cháo đặc thì thêm 1/2 lít nước.', 'Luộc lươn trong 1 lít nước sôi với 1/2 muỗng cà phê muối và 1 muỗng cà phê hạt nêm. Vớt ra gỡ thịt; trả xương và nước luộc vào nồi cháo.', 'Trộn thịt lươn với hành phi, 1/2 muỗng cà phê hạt nêm, 1 muỗng cà phê nước mắm và tiêu.', 'Vớt xương khỏi nồi cháo, cho thịt lươn vào, nêm 1 muỗng canh nước mắm, tiêu, hành ngò, hành phi và 2 muỗng canh dầu phi hành. Múc ra tô ăn nóng.', 'Mẹo: Chọn lươn sống, bụng vàng, lưng nâu, thân ngắn; chọn khoai môn to, ruột trắng đục có vân tím để nhiều bột.']),
    'chan_gio_kho_tuong_sa': ('Chân giò cuộn kho tương hột, sả, nước dừa và cốt dừa cùng cà tím, ớt chuông, đậm đà, béo cay.',
        ['Cà tím chẻ đôi, cắt khúc 3cm, ngâm nước muối loãng. Ớt Đà Lạt cắt miếng, hành tây cắt múi cau, sả đập dập cắt khúc.', 'Chân giò rửa sạch, lạng bớt nạc, ướp 1,5 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê nước hành tỏi rồi cuộn tròn. Chần qua nước sôi có ít sả đập dập và 1 muỗng canh giấm gạo, để nguội, cắt khoanh dày 3cm, buộc chỉ.', 'Ướp thịt với 1 muỗng cà phê ớt bột, 1 muỗng cà phê muối, 1 muỗng cà phê hạt nêm, 1 muỗng canh đường, 2/3 chén tương hột, 2 muỗng canh nước sả, 1 muỗng canh nước hành tỏi trong 10 phút.', 'Phi thơm sả, hành tím, ớt hiểm với dầu điều, cho chân giò vào xào săn, đổ nước dừa vào kho lửa liu riu cho thấm.', 'Cho cà tím vào nấu sôi 7 phút, sau đó thêm ớt Đà Lạt, hành tây, nước cốt dừa, đun sôi lại rồi tắt bếp. Ăn với cơm hoặc bánh mì.', 'Mẹo: Lạng bớt nạc để cuộn đều đẹp; chần với sả và giấm giúp thịt giữ dáng, thơm và giòn hơn.']),
    'chan_gio_nau_nuoc_tuong': ('Chân giò cuộn luộc rồi om nước tương với hồi, đinh hương, tỏi ớt, thái lát cuốn bánh tráng rau sống.',
        ['Rửa sạch chân giò rút xương, ướp 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê tiêu trong 15 phút. Cuộn tròn và buộc chỉ quanh cuộn.', 'Luộc chân giò trong nước sôi đến khi vừa chín, vớt ra rửa nước lạnh, để ráo.', 'Phi thơm 1 muỗng cà phê dầu ăn với 1 muỗng cà phê tiêu sọ đập dập, ớt, tỏi, hành tím, hoa hồi, đinh hương.', 'Thêm 2 chén nước, 10 muỗng canh nước tương, 1 muỗng canh đường, cho chân giò vào nấu 1 tiếng.', 'Vớt ra để nguội, thái lát mỏng, cuốn với bánh tráng, rau sống, đồ chua; chấm nước tương ớt tỏi băm.', 'Mẹo: Luộc sơ và để ráo trước khi nấu để bớt váng mỡ; ướp thịt trước khi cuộn để gia vị thấm vào trong.']),
    'chan_gio_om_sau': ('Chân giò thui vàng, ướp nghệ và giấm bỗng, om sả với nước sấu chua dịu, ăn cùng bún hoặc cơm.',
        ['Thui chân giò trên lửa rồi chặt khoanh vừa ăn.', 'Ướp với 2 muỗng canh hành tỏi băm, 1 muỗng canh đường, 3 muỗng canh nước mắm, 2 muỗng canh nước nghệ, 2 muỗng canh giấm bỗng, 1 muỗng cà phê bột ngọt trong 30 phút. Sấu khứa hình chữ thập, sả cắt khúc 5cm đập dập.', 'Phi thơm sả và 1 muỗng canh hành tỏi với 2 muỗng canh dầu ăn, cho chân giò vào xào săn.', 'Đun sôi nước dùng, thả sấu vào cho ra vị chua rồi đổ vào nồi thịt. Đậy nắp om 25–30 phút đến khi thịt mềm, nước còn sâm sấp.', 'Múc ra tô, rắc hành lá, ớt; ăn nóng với bún hoặc cơm, chấm nước mắm ớt.', 'Mẹo: Chọn chân giò trước nhiều thịt; thui giúp da săn và giòn hơn; om có đậy nắp để thịt mềm, giữ mùi.']),
    'chan_nam_xao_thit_ga': ('Thịt đùi gà xào măng, chân nấm hương giã xé sợi, thêm mực khô nướng, thơm mỡ hành, mặn ngọt vừa.',
        ['Ngâm chân nấm hương nước ấm 2–3 giờ, luộc vừa chín, cắt bỏ phần cứng, xả nước 3–4 lần. Giã dập rồi xé tơi.', 'Gà lọc xương, thái lát dày 2–3mm, ướp 1 muỗng canh hành tỏi băm, 1 muỗng cà phê bột ngọt, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu trong 5–10 phút.', 'Măng luộc chẻ mỏng như thịt gà. Nướng mực khô, xé sợi. Hành ngò cắt khúc, ớt sừng cắt sợi.', 'Phi thơm hành tỏi với mỡ nước, xào gà cùng măng đến khi gà vừa chín thì trút ra.', 'Xào chân nấm với mỡ nước cho thơm, nêm 1/4 muỗng cà phê muối, 1/4 muỗng cà phê bột ngọt, thêm ít nước cho nấm mềm. Cho gà và măng vào đảo đều, tắt bếp, thêm hành ngò, ớt, tiêu.', 'Bày ra dĩa, rắc mực khô xé lên trên; ăn nóng với cơm, chấm nước tương.', 'Mẹo: Ngâm, luộc rồi giã chân nấm trước khi xé để nấm mềm; xào nấm riêng cho thấm vị.']),
    'chao_nam_tram': ('Cháo gạo thơm với viên tôm thịt quết nhuyễn và nấm tràm xào, nêm nước mắm, rắc tiêu hành ngò.',
        ['Vo gạo, nấu cháo với nước dùng cho gạo nở. Ngâm nấm tràm trong nước vo gạo, rửa nhiều lần, vắt ráo, xé nhỏ. Cắt nhỏ hành ngò, thái khoanh ớt.', 'Tôm bỏ đầu, bóc vỏ, quết nhuyễn cùng thịt xay, hành tỏi, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu, chút đầu hành băm và 1/2 lòng trắng trứng vịt. Vo viên, thả vào nồi cháo.', 'Phi thơm hành, xào nấm tràm, nêm 1/2 muỗng cà phê hạt nêm rồi trút vào cháo. Nêm thêm 1 muỗng canh nước mắm, tắt bếp.', 'Múc ra chén, rắc hành ngò, tiêu; thêm chanh ớt tùy thích.', 'Mẹo: Ngâm nấm bằng nước vo gạo cho sạch cát; xào nấm với hạt nêm cho đậm vị; quết thêm lòng trắng trứng để viên tôm thịt không khô.']),
    'chao_ngheu': ('Cháo gạo dẻo, gạo nếp nấu nước dừa, thịt nghêu ướp hành tiêu xào sơ, béo nhẹ, ăn kèm giá chanh ớt.',
        ['Vo gạo dẻo và gạo nếp, để ráo. Băm hành tím, tỏi; đầu hành lá băm nhuyễn, phần lá cắt nhỏ.', 'Tách thịt nghêu, rạch nặn bỏ phần đen, rửa sạch. Ướp 1 muỗng cà phê hành phi, 1 muỗng cà phê đầu hành băm, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê muối hột, 1/2 muỗng cà phê hạt nêm trong 10 phút rồi xào sơ.', 'Nhồi dừa nạo với nước nóng, vắt lấy 1 chén nước cốt và 1 tô nước dão.', 'Đun sôi 1 lít nước dùng với gạo, hạ lửa nấu đến khi gạo nở hết. Thêm 2/3 phần nước dão dừa, sôi lại thì nêm 1/2 muỗng cà phê tiêu và 1/2 muỗng cà phê hạt nêm.', 'Cho nghêu vào khuấy nhanh rồi thêm nước cốt dừa. Múc ra tô, ăn kèm giá, chanh, ớt, tiêu, nước mắm, hành phi.', 'Mẹo: Dùng muối hột cho cháo đậm đà; đừng xào nghêu quá kỹ kẻo thịt dai.']),
    'chao_thap_cam': ('Cháo chay gạo đậu xanh nấu khoai môn, khoai lang, bí đỏ, nấm linh chi xào, thêm nước cốt dừa béo ngọt.',
        ['Vo gạo và đậu xanh, nấu cháo với 1,5 lít nước.', 'Cắt hạt lựu khoai lang, bí đỏ, khoai môn. Cắt nhỏ ngò rí, thái xéo hành boa-rô.', 'Phi thơm hành boa-rô, xào sơ nấm linh chi nâu và trắng.', 'Khi cháo gần chín, cho các loại củ vào, rồi đến nấm đã xào. Nêm 2 muỗng canh hạt nêm nấm hương, 1,5 muỗng canh muối, 1/2 muỗng canh bột ngọt, 1 muỗng canh đường.', 'Đổ 1 chén nước cốt dừa, thêm ngò rí rồi tắt bếp. Ăn nóng.', 'Mẹo: Xào nấm với hành boa-rô cho thơm; khi gạo đã nở, thả vài viên đá lạnh vào để cháo mau nhừ.']),
    'chao_tim_gan': ('Cháo gạo dẻo, nếp nấu với tim gan heo thái mỏng ướp gừng, nấm rơm, hành tây, thơm gừng sợi.',
        ['Hành tây cắt múi nhỏ. Đầu hành lá băm nhuyễn, phần lá cắt nhỏ; cắt nhỏ ngò rí. Gừng: một nửa băm, một nửa cắt sợi.', 'Nấm rơm rửa sạch, cắt tư, xào sơ với đầu hành, nêm 1/3 muỗng cà phê hạt nêm và 1/2 muỗng cà phê tiêu.', 'Tim, gan heo thái mỏng, ướp 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê gừng băm và đầu hành băm.', 'Nấu gạo dẻo và nếp với 0,5 lít nước đến khi cạn, gạo nở thì thêm 1 lít nước lạnh, nấu tiếp cho gạo bung.', 'Cho nấm, hành tây, tim gan vào nấu vừa chín tới, nêm 1/2 muỗng cà phê muối, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê tiêu, 1/2 muỗng cà phê nước mắm, tắt bếp.', 'Múc ra tô, rắc hành phi, hành ngò, gừng sợi; ăn nóng với nước mắm, chanh, ớt.', 'Mẹo: Nấu cả gạo tẻ lẫn nếp cho cháo thơm; có thể dùng gạo tấm cho mau nhừ; nấu ít nước trước rồi thêm nước lạnh để cháo nhanh nhừ.']),
    'chim_cut_chien_mam_me': ('Chim cút tẩm bột chiên giòn, xóc xốt me chua ngọt với hành tây, thơm, sả, rau răm, rắc mè.',
        ['Chim cút cắt 4, trụng nước sôi có ít gừng và rượu, để ráo. Hành tây cắt múi cau nhỏ, thơm thái lát mỏng, sả và ớt sừng thái lát, ớt hiểm đập dập, rau răm nhặt lá.', 'Pha xốt: 3 muỗng canh nước me, 2 muỗng canh đường, 1 muỗng canh nước mắm, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, khuấy đều.', 'Áo chim cút với 1/2 gói bột tẩm khô chiên giòn. Chiên nhanh 1 muỗng canh sả và ít rau răm trong dầu nóng, vớt ra; tiếp đó chiên chim cút vàng chín, để ráo dầu.', 'Phi thơm sả, tỏi băm, xào thơm và hành tây, đổ xốt me vào đun sôi rồi tắt bếp. Cho chim cút, rau răm, ớt hiểm vào xóc đều.', 'Bày ra dĩa, rắc mè rang và sả chiên, ăn nóng.', 'Mẹo: Trụng chim với rượu gừng cho sạch, sáng màu; chiên sả, rau răm trước để dầu sạch và thơm hơn.']),
    'chim_cut_nhoi_com_hap': ('Chim cút nhồi giò sống trộn cốm, chiên sơ rồi hấp với nấm hương, hạt sen, cà rốt trong nước dùng.',
        ['Chim cút mổ moi, làm sạch, ướp 1/2 muỗng cà phê hạt nêm và 1/2 muỗng cà phê tiêu. Cà rốt tỉa hoa, thái lát 5mm; đầu hành lá cắt khúc.', 'Trộn giò sống với 2 muỗng canh cốm, 1 muỗng cà phê hành tím băm, 1/2 muỗng cà phê tiêu. Nhồi vào bụng chim, ghim tăm lại, phết hắc xì dầu lên da.', 'Chiên sơ chim trong dầu nóng đến khi da hơi vàng, vớt ra để ráo.', 'Đặt chim vào dĩa sâu lòng, xếp nấm, cà rốt, hạt sen, đầu hành, đổ nước dùng vào, hấp khoảng 20 phút cho chín.', 'Rắc ngò rí và tiêu, ăn nóng.', 'Mẹo: Quết cốm với giò sống giúp nhân đẹp màu và kết dính; hắc xì dầu cho da chim nâu đẹp và thơm.']),
    'coi_so_diep_xot_cay': ('Cồi sò điệp xào nhanh lửa lớn rồi đảo cùng hành tây, ớt chuông trong xốt ớt tỏi cay ngọt.',
        ['Rửa sạch, để ráo cồi điệp, ướp 1/2 muỗng cà phê tiêu, 1 muỗng cà phê hạt nêm trong 5 phút.', 'Hành tây cắt múi cau khoảng 2cm, ớt chuông cắt hình thoi 2cm, hành lá cắt xéo 2cm.', 'Phi thơm 1 muỗng canh tỏi băm với 1 muỗng canh dầu điều, xào nhanh cồi điệp trên lửa lớn, thêm 1 muỗng canh rượu trắng, đảo đều rồi trút ra.', 'Phi 1/2 muỗng cà phê tỏi băm với dầu điều, 1/2 muỗng canh ớt xay, 1 muỗng cà phê ớt bột. Cho hành tây, ớt chuông vào xào nhanh.', 'Trả cồi điệp vào, nêm 1 muỗng cà phê hạt nêm, 2 muỗng cà phê đường, 1/2 muỗng canh nước mắm, 1 muỗng canh tương ớt, đảo nhanh, tắt bếp, xóc cùng hành lá. Ăn nóng với cơm hoặc bánh mì.', 'Mẹo: Xào lửa lớn, nhanh tay để điệp săn, không ra nước; thêm rượu trắng cho điệp thơm.']),
    'com_chien_dua': ('Cơm trộn trứng chiên với tôm mực, bông cải, cà rốt trong xốt cà ri nước cốt dừa, thêm dừa nạo.',
        ['Tôm bóc vỏ, mực cắt hạt lựu, ướp 1/2 muỗng cà phê hạt nêm và chút tiêu. Bông cải cắt miếng 1,5cm, cà rốt cắt hạt lựu nhỏ.', 'Trộn cơm với 1 muỗng cà phê bột ngọt, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê đường, 1/3 muỗng cà phê muối và 1 quả trứng.', 'Hòa 1 muỗng cà phê bột cà ri với 3 muỗng canh nước cốt dừa và 1 muỗng canh nước mắm.', 'Phi thơm 1 muỗng cà phê hành tỏi băm, xào tôm mực vừa chín, trút ra.', 'Phi tiếp 1 muỗng canh tỏi, cho hỗn hợp cà ri vào xào thơm, cho cơm vào chiên đến khi săn. Thêm bông cải, cà rốt, rồi tôm mực và dừa nạo, đảo đều, tắt bếp.', 'Bày ra dĩa, rắc tiêu, trang trí ngò rí, ăn nóng.', 'Mẹo: Xào cà ri trước cho dậy mùi; trộn trứng vào cơm trước khi chiên để hạt cơm tơi, không khô.']),
    'chao_yen_mach_thit_bo': ('Cháo yến mạch nấu cà rốt, bông cải xanh, thịt bò băm xào dầu olive, thêm phô mai viên, mềm dễ ăn.',
        ['Cắt cà rốt hạt lựu 0,5cm, bông cải xanh cắt nhỏ bằng cà rốt, phô mai viên cắt 8.', 'Ướp bò băm với 1/2 muỗng cà phê hạt nêm, 1/4 muỗng cà phê bột ngọt, 1 muỗng cà phê hành tỏi băm, 1 muỗng cà phê dầu olive và 1 muỗng canh nước lạnh.', 'Đun sôi 800ml nước dùng, nấu chín cà rốt và bông cải rồi cho yến mạch vào nấu mềm.', 'Phi thơm 1 muỗng cà phê hành tỏi với dầu olive, xào bò vừa chín, đổ vào nồi cháo. Nêm 1/2 muỗng cà phê muối, 1/4 muỗng cà phê bột ngọt, 1 muỗng cà phê hạt nêm, tắt bếp, thêm hành ngò, tiêu.', 'Múc ra bát, thả phô mai lên, ăn nóng.', 'Mẹo: Yến mạch chín rất nhanh nên cho vào sau cùng; ướp bò với nước lạnh để thịt tơi mềm, thấm vị.']),
    'com_chien_dua_bo': ('Cơm trộn gia vị phở bò chiên với dưa cải chua và thịt bò xào tỏi, chua mặn hài hòa.',
        ['Trộn cơm với 10g gia vị nêm phở bò, 2g đường, 2g bột ngọt.', 'Ướp bò với 1 muỗng canh tỏi băm, 1 muỗng canh dầu ăn và 5g gia vị nêm phở bò. Ướp cải chua với 1 muỗng cà phê đường.', 'Phi thơm tỏi, xào sơ thịt bò rồi trút ra riêng.', 'Xào cải chua và cơm đến khi cơm săn hạt, nêm tiêu, thêm hành ngò rồi tắt bếp.', 'Bày cơm ra dĩa, xếp bò lên trên, ăn nóng với nước tương và tương ớt.', 'Mẹo: Trộn gia vị vào cơm trước để thấm đều; ướp dưa chua với ít đường cho cân vị.']),
    'com_chien_duong_chau': ('Cơm chiên trứng với xá xíu, lạp xưởng, tôm khô rim, đậu Hà Lan, cà rốt, hạt cơm tơi, đậm vị.',
        ['Nấu cơm hơi khô. Lạp xưởng luộc sơ, cắt hạt lựu; xá xíu, cà rốt cắt hạt lựu. Đánh tan trứng. Ngâm mềm tôm khô. Luộc chín đậu Hà Lan và cà rốt. Cắt nhỏ hành lá.', 'Trộn cơm với xá xíu, đậu Hà Lan, cà rốt, 2 muỗng cà phê hạt nêm vị heo, 1 muỗng cà phê nước tương, 1 muỗng cà phê đường, 1 muỗng canh xốt cà chua, 1 muỗng canh dầu điều.', 'Xào sơ lạp xưởng cho ra mỡ, trút ra. Phi 1 muỗng cà phê tỏi, xào tôm khô với 1 muỗng cà phê đường cho bóng; trộn lạp xưởng và tôm vào cơm.', 'Đun nóng 2 muỗng canh dầu, đổ trứng vào vừa chiên vừa đánh thành miếng nhỏ, cho cơm vào đảo đến khi hạt se mặt.', 'Bày ra dĩa, trang trí ngò rí, ăn nóng với dưa leo, cà chua, nước tương, ớt.', 'Mẹo: Dùng gạo cũ nấu khô cho cơm tơi; đừng chiên lâu, đảo nhiều kẻo nát; rim tôm khô với đường cho ngon.']),
    'com_chien_mayonnaise': ('Cơm chiên bằng xốt mayonnaise với trứng, thịt nguội, cải ngọt, cà rốt, béo nhẹ, thơm tỏi.',
        ['Thịt nguội cắt hạt lựu. Cải ngọt bỏ gốc, cắt khúc ngắn, để riêng cọng và lá. Đánh tan trứng. Hành tây cắt hạt lựu, cà rốt cắt nhỏ, hành lá và ngò rí cắt nhỏ.', 'Phi thơm tỏi với 2 muỗng canh xốt mayonnaise, xào hành tây và cọng cải.', 'Cho trứng vào chiên sơ, thêm cơm và cà rốt đảo đều, nêm 1,5 muỗng cà phê hạt nêm.', 'Cho lá cải và thịt nguội vào, chiên đến khi cơm săn hạt. Thêm 1 muỗng canh xốt mayonnaise trộn đều, tắt bếp, rắc tiêu, hành lá, ngò rí.', 'Ăn nóng với nước tương và ớt.', 'Mẹo: Chiên đến khi hạt cơm săn lại; dùng mayonnaise thay dầu ăn cho cơm béo thơm.']),
    'com_chien_nam_man': ('Cơm chiên chay với nấm đông cô, củ năng, nấm bào ngư tẩm bột chiên giòn và rong biển, thơm dầu mè.',
        ['Nấm đông cô ngâm nở, cắt sợi. Củ năng cắt hạt lựu, ngò rí cắt nhỏ. Nấm bào ngư rửa, vắt ráo, cắt sợi.', 'Ướp nấm bào ngư với 1/2 muỗng canh hạt nêm nấm hương và 1/2 muỗng canh nước tương, lăn qua bột mì rồi chiên ngập dầu đến vàng, vớt ráo.', 'Trộn cơm với 1 muỗng cà phê hạt nêm nấm hương, 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1 muỗng canh dầu mè, 1 muỗng canh nước tương, để thấm.', 'Phi thơm boa-rô, xào săn nấm đông cô, cho củ năng và cơm vào đảo đến khi cơm săn, nêm vừa ăn rồi tắt bếp.', 'Cho nấm bào ngư chiên và rong biển vào trộn đều. Bày ra dĩa, rắc ngò rí, tiêu; ăn với nước tương, ớt.', 'Mẹo: Ướp nấm cho thấm rồi mới chiên để đậm vị; cho rong biển vào cuối để giữ màu và mùi.']),
    'com_chien_nam_thit_bo': ('Cơm chiên với thịt bò ướp thơm, nấm rơm, cà rốt, đậu bi cắt hạt lựu, đậm đà, hạt cơm săn.',
        ['Thịt bò cắt hạt lựu nhỏ, ướp 1 muỗng cà phê thơm băm, 1 muỗng cà phê tỏi băm, 1/2 muỗng cà phê hạt nêm, 1 muỗng canh nước tương, 1/2 muỗng cà phê tiêu.', 'Nấm rơm ngâm nước muối, rửa sạch, chần sơ trong nước muối cùng cà rốt và đậu bi, thả vào nước lạnh rồi cắt hạt lựu. Ngò rí cắt nhỏ.', 'Trộn cơm với 1 muỗng cà phê hạt nêm và 1/2 muỗng cà phê muối.', 'Phi thơm 1 muỗng cà phê tỏi, xào bò vừa chín tới, trút ra.', 'Thêm 1 muỗng canh dầu, xào săn cơm với nấm rơm, cho cà rốt, đậu bi vào đảo cho thấm, cuối cùng trả bò vào, tắt bếp. Bày ra dĩa, ăn với nước tương và ớt.', 'Mẹo: Ướp bò với thơm giúp thịt mềm; chần nấm trước để giữ vị ngọt.']),
    'com_chien_trai_cay': ('Cơm chiên trứng với tôm rang muối, giò lụa, thêm thanh long, thơm, nho, lê giòn mát, chua ngọt nhẹ.',
        ['Rang tôm với muối hột, bóc vỏ, cắt hạt lựu. Cắt hạt lựu trái cây và giò lụa.', 'Đánh tan trứng, nêm ít muối, tiêu, bột ngọt.', 'Phi thơm hành tím, cho cơm vào chiên săn, đổ trứng vào đảo đến khi trứng chín, hạt cơm tơi.', 'Nêm 2/3 muỗng cà phê muối, 2/3 muỗng cà phê bột ngọt, 1/4 muỗng cà phê tiêu, 1 muỗng cà phê nước tương. Cho tôm, giò lụa vào, sau cùng thêm trái cây trộn nhanh rồi tắt bếp, rắc tiêu, ngò rí.', 'Múc ra dĩa, ăn kèm nước tương tùy thích.', 'Mẹo: Cho trái cây vào cuối để không nát, giữ độ giòn; rang tôm với muối cho tôm đậm và ngọt.']),
    'com_chien_trai_thom': ('Cơm chiên tôm tươi, tôm khô, thơm và hành tây, múc vào vỏ trái thơm, ăn kèm rau sống.',
        ['Bổ dọc trái thơm, giữ phần đầu để trang trí, bỏ cùi; lấy khoảng 3 muỗng canh ruột thơm cắt hạt lựu, ướp 1/2 muỗng cà phê hạt nêm. Hành tây cắt hạt lựu, hành lá cắt nhỏ.', 'Tôm tươi bóc vỏ, cắt hạt lựu, ướp 1/2 muỗng cà phê hạt nêm và tiêu, trộn với 1/2 muỗng cà phê bột năng. Phi hành tỏi, xào tôm săn lại, thêm ít nước dùng cho chín.', 'Ngâm tôm khô nước ấm, xào sơ với hành, tỏi băm và tiêu.', 'Phi thơm hành tỏi, xào săn cơm, nêm 1/2 muỗng cà phê đường, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê muối. Cho tôm khô, tôm tươi, thơm, hành tây vào đảo nhanh, tắt bếp, trộn hành lá.', 'Múc cơm vào vỏ thơm, trang trí ngò rí, ớt; ăn kèm xà lách, dưa leo, nước tương và ớt.', 'Mẹo: Rửa tôm khô bằng nước ấm và rang với hành tím để khử mùi; nấu cơm với chút dầu hoặc nước dùng để cơm chiên bóng, rời hạt.']),
    'com_ga': ('Cơm gạo rang mỡ gà nấu nước luộc gà với nghệ, ăn cùng gà xé, gỏi hành tây rau răm và nước tương.',
        ['Luộc gà với gừng đập dập, nêm 1/2 muỗng cà phê bột ngọt, 1/3 muỗng cà phê muối; xé gà miếng nhỏ.', 'Thắng mỡ gà, phi thơm 1 muỗng canh tỏi băm. Dùng 2 muỗng canh mỡ rang gạo, giữ lại 1 muỗng canh. Pha 1/4 muỗng canh bột nghệ vào nước luộc gà (chừa 2 muỗng canh) rồi nấu gạo chín.', 'Rau răm cắt nhỏ. Hành tây thái mỏng, ngâm đá cho bớt hăng; cà rốt cắt sợi. Trộn hành tây, cà rốt với 1 muỗng canh giấm gạo, 1/2 muỗng canh đường, rắc rau răm.', 'Pha nước chấm: 2 muỗng canh nước tương, 2 muỗng canh nước luộc gà, ít muối, ít bột ngọt, 1 trái ớt hiểm thái lát, 1/2 muỗng canh đầu hành băm.', 'Trộn cơm với 1 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 1 muỗng cà phê hạt nêm; đảo cơm với 1 muỗng canh mỡ gà cho săn.', 'Ém cơm ra dĩa, xếp gà lên, rắc rau răm, hành phi; ăn với nước chấm và gỏi.', 'Mẹo: Rang gạo với mỡ gà tỏi đến khi hạt trong, săn; dùng nước luộc gà pha nước chấm cho ngon.']),
    'com_ga_xoi_mo': ('Đùi gà hấp, phết mạch nha rồi xối dầu sôi cho da vàng giòn, ăn với cơm xào mỡ gà nghệ lá dứa.',
        ['Khứa mặt trong đùi gà, không làm rách da. Ướp 2 muỗng cà phê hạt nêm, 1 muỗng canh nước gừng, 1 muỗng canh nước cốt tỏi, 1 muỗng canh rượu ngũ vị hương, 1 muỗng canh nước tương. Thái lát cà chua, dưa leo.', 'Hấp chín đùi gà, để nguội, lau khô da, thoa một lớp bột chiên gà giòn.', 'Pha 2 muỗng canh mạch nha với 1 muỗng canh nước cốt chanh, phết lên da, khô lại phết tiếp, để mặt da khô.', 'Đun sôi dầu, dùng vá xối dầu lên da gà đến khi vàng giòn. Để ráo, chặt miếng.', 'Trộn cơm với 1 muỗng cà phê hạt nêm. Thắng mỡ gà, tắt bếp, cho 1/4 muỗng cà phê bột nghệ, lá dứa, gừng lát vào. Dùng mỡ này phi 1 muỗng canh tỏi băm rồi xào sơ cơm.', 'Ém cơm ra dĩa, xếp gà, cà chua, dưa leo quanh; ăn nóng với nước tương.', 'Mẹo: Để gà hấp thật nguội trước khi xối dầu để da giòn, vàng đẹp; lớp bột chiên giúp da khô giòn.']),
    'com_gao_luc_chien_ngheu': ('Cơm gạo lứt chiên với thịt nghêu xào tỏi, rau củ hạt lựu và lòng đỏ trứng muối bùi béo.',
        ['Luộc nghêu với 1 chén nước, tách lấy thịt. Cắt hạt lựu cà rốt, đậu cô ve, hành tây. Lấy lòng đỏ trứng muối tán nhuyễn. Cắt nhỏ ngò rí.', 'Trộn cơm gạo lứt với 2 muỗng cà phê hạt nêm, 1/2 muỗng canh nước tương, 1/2 muỗng cà phê bột ngọt, 1/3 muỗng cà phê đường.', 'Phi thơm ít tỏi, xào nhanh nghêu rồi trút ra.', 'Phi tỏi tiếp, xào cà rốt, hành tây, đậu cô ve, cho cơm vào chiên đến khi săn hạt. Thêm nghêu và một nửa lòng đỏ trứng muối, trộn đều, tắt bếp.', 'Bày ra dĩa, phủ phần trứng muối còn lại, rắc tiêu, ngò rí; ăn với nước tương.', 'Mẹo: Ngâm gạo lứt trước khi nấu cho cơm mềm; xào nghêu nhanh rồi trút ra để giữ vị ngọt.']),
    'com_gao_luc_tron_rau_cu': ('Cơm gạo lứt nấu sữa tươi trộn đậu hũ, nấm, rau củ xào, sườn chay chiên giòn và cơm cháy, thơm húng quế.',
        ['Ngâm gạo lứt 1 tiếng, nấu với 1/2 muỗng cà phê hạt nêm nấm hương. Khi nồi chuyển sang hâm, đổ 1/2 chén sữa tươi vào, đậy nắp thêm 5 phút.', 'Nấm rơm cắt tư, nấm đông cô cắt hạt lựu nhỏ. Đậu hũ cắt hạt lựu, chiên vàng. Cà rốt, đậu cô ve cắt hạt lựu, chần sơ. Thái ớt hiểm, cắt sợi húng quế.', 'Sườn chay ngâm mềm, xé sợi, ướp ít tiêu, ớt bột rồi chiên vàng giòn.', 'Phi thơm boa-rô, múc riêng ra 2 muỗng canh. Xào đậu hũ, nấm, cà rốt, đậu cô ve lửa lớn, nêm 1,5 muỗng cà phê hạt nêm nấm, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê dầu mè, ít tiêu.', 'Cho cơm vào thố, trộn với 2 muỗng canh hành phi và nửa phần cơm lứt sấy giòn; thêm nhân xào, sườn chay, phủ phần cơm sấy còn lại.', 'Đặt thố lên bếp đun nóng 5 phút, rắc húng quế, mè rang. Trộn đều khi ăn, chấm nước tương với ớt.', 'Mẹo: Cho sữa khi cơm gần chín để cơm bóng, béo thơm; nấu cơm có gia vị cho đậm; đun nóng thố cơm để cơm trộn thơm hơn.']),
    'com_gao_lut_hat_sen': ('Cơm gạo lứt nấu cùng hạt sen, nấm hương, khoai môn, lá dứa, thêm sữa, đậu hũ, gói lá sen hấp thơm.',
        ['Vo gạo lứt, ngâm 30 phút. Đậu hũ cắt hạt lựu, chiên rồi xóc với ít bột canh. Luộc vừa chín hạt sen; luộc đậu que rồi cắt nhỏ.', 'Khoai môn cắt khối 1,5cm, nấm hương cắt đôi, hành boa-rô thái lát, lá dứa cắt khúc.', 'Phi thơm boa-rô, xào nấm hương, khoai môn, hạt sen, nêm 1 muỗng canh nước tương, xóc đều rồi tắt bếp.', 'Cho gạo, lá dứa, rau củ xào vào nồi, nêm 1/2 muỗng canh hạt nêm nấm hương, 2 muỗng canh nước tương. Đổ nước ngập gạo khoảng 1,5 đốt ngón tay, đậy nắp nấu đến khi cạn nước.', 'Thêm sữa tươi, 1 muỗng cà phê dầu mè, đậu hũ, đậu que, xới đều, nấu thêm 10 phút.', 'Xới cơm vào lá sen, buộc lại, hấp 5 phút. Ăn nóng với nước tương và ớt.', 'Mẹo: Xào rau củ với nước tương trước cho đậm; lá dứa tăng mùi thơm; cho sữa và dầu mè sau để cơm mềm, béo.']),
    'com_gao_lut_tron': ('Cơm gạo lứt nấu sữa trộn đậu hũ chiên, ham chay, nấm, ớt chuông, hạt sen, rưới nước tương mè rang.',
        ['Vo gạo lứt, ngâm 1–2 giờ. Cắt hạt lựu 1cm ham chay, đậu hũ, ớt chuông. Luộc chín hạt sen. Băm 2 muỗng canh boa-rô, gừng cắt sợi. Ngâm mềm nấm đông cô, nấm mèo, bỏ chân, cắt sợi.', 'Nấu gạo trong nồi cơm điện với nước và 1/2 chén sữa tươi (tổng lượng nước gấp đôi gạo), nêm 1/2 muỗng canh hạt nêm nấm hương.', 'Chiên gừng sợi trong dầu nóng cho thơm, vớt ra; chiên tiếp đậu hũ vàng, để ráo.', 'Phi boa-rô, xào nấm, thêm ớt chuông, nêm 2 muỗng cà phê hạt nêm nấm hương, 2 muỗng canh nước tương, 1 muỗng cà phê đường, 1/2 muỗng cà phê tiêu. Cho hạt sen, rồi đậu hũ, ham chay, 1 muỗng cà phê dầu mè xóc đều, tắt bếp.', 'Pha nước tương mè: 3 muỗng canh nước tương, 2 muỗng canh tương cà, 1 muỗng canh tương ớt, 1 muỗng cà phê giấm gạo, 2 muỗng cà phê đường, 1 muỗng cà phê dầu mè đen, 1 muỗng canh mè rang, 1 muỗng canh nước.', 'Cho cơm vào dĩa sâu, đổ phần xào lên trộn, rắc gừng chiên, ngò rí. Khi ăn rưới nước tương mè, ăn kèm dưa cải chua.', 'Mẹo: Chiên gừng trước để dầu thơm cho đậu hũ; nấu cơm với sữa và hạt nêm để cơm mềm, béo, thấm vị.']),
    'com_hen_tron': ('Cơm nguội trộn hến xào, rau sống, bắp chuối, khế, bạc hà, đậu phộng, tóp mỡ, chan mắm ruốc cay.',
        ['Đun sôi 200ml nước với gừng đập dập, 1/2 muỗng cà phê muối, chần hến rồi để ráo. Ướp hến với 1 muỗng cà phê bột ngọt, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê hạt nêm.', 'Cắt ngắn hoa chuối bào. Bạc hà, khế thái mỏng, bóp muối, xả sạch, vắt ráo. Rau thơm cắt nhuyễn. Chần sơ giá.', 'Đun 1 muỗng canh dầu điều, đảo đậu phộng với chút muối.', 'Phi thơm hành tỏi với 2 muỗng canh mỡ nước, xào săn hến, rắc hành lá và 1/3 muỗng cà phê ớt băm, tắt bếp.', 'Pha mắm ruốc: 2 muỗng cà phê mắm ruốc, 4 muỗng canh nước nóng, 1/2 muỗng canh đường, tỏi ớt băm, khuấy đều rồi đun sôi.', 'Cho cơm vào tô, xếp rau, giá, tóp mỡ, đậu phộng, hến, rắc mè, chan mắm ruốc và ít sa tế.', 'Mẹo: Xào hến nhanh tay để hến không dai, không teo.']),
    'com_hoang_bao': ('Cơm rang mỡ gà trộn trứng muối, chiên với chả quế, xá xíu, tôm khô, hạt sen, gói trong trứng tráng.',
        ['Băm hành lá, thái ớt. Ngâm tôm khô, xào sơ với gia vị. Cắt hạt lựu chả quế, xá xíu, cà rốt. Luộc trứng muối, lấy lòng đỏ tán nhuyễn. Luộc chín đậu Hà Lan, cà rốt, hạt sen.', 'Phi thơm 1 muỗng canh tỏi với 1 muỗng canh mỡ gà, rang gạo cho thơm, nêm 1 muỗng cà phê hạt nêm, 1 muỗng canh nước tương, đổ nước dùng nấu chín sơ. Xới tơi, để nguội rồi trộn với lòng đỏ trứng muối.', 'Đánh tan trứng gà, tráng thành miếng tròn mỏng đường kính 25–30cm.', 'Phi tỏi với mỡ gà, xào tôm, chả, đậu Hà Lan, xá xíu, cà rốt. Cho cơm vào chiên săn, thêm hạt sen, nêm 1 muỗng cà phê hạt nêm, 1 muỗng cà phê nước tương, hành lá, tiêu, tắt bếp.', 'Múc cơm vào miếng trứng, túm lại, buộc chặt; dùng kéo cắt và lật mép ra như cánh hoa, giấu nút buộc bên dưới.', 'Mẹo: Rang gạo với mỡ gà cho cơm thơm; trộn lòng đỏ trứng muối giúp cơm bùi, không dính.']),
    'com_nam_rong_bien_mayo': ('Cơm trắng trộn cá ngừ ngâm dầu, cà rốt, rong biển và xốt mayonnaise, nắm viên, phủ chà bông.',
        ['Chắt bớt dầu cá ngừ, đánh tơi thịt cá. Cắt nhỏ cà rốt.', 'Trộn cơm với cá ngừ, cà rốt, rong biển và 2 muỗng canh xốt mayonnaise, rồi nắm thành viên.', 'Rắc chà bông và thêm xốt mayonnaise lên trên.', 'Mẹo: Dùng cơm dẻo cho viên cơm mềm, dễ nắm.']),
    'com_rau_cu_nam_huong': ('Cơm trộn trứng chiên với tôm, nấm hương, bông cải xanh, ớt chuông, thơm gừng và dầu mè.',
        ['Tôm cắt hạt lựu, ướp 1/4 muỗng cà phê muối, 1/4 muỗng cà phê tiêu, 1/3 muỗng cà phê bột ngọt, 1 muỗng cà phê tỏi băm, 1/2 muỗng cà phê gừng sợi.', 'Đánh trứng với 1/3 muỗng cà phê hạt nêm, 1/3 muỗng cà phê bột ngọt, 1/4 muỗng cà phê tiêu, 1/2 muỗng cà phê dầu mè.', 'Nấm hương ngâm nở, bỏ chân, thái mỏng. Bông cải tách nhánh nhỏ, chần nước muối, để ráo. Ớt chuông cắt hạt lựu; hành lá, ngò rí cắt nhỏ.', 'Trộn trứng với cơm. Phi thơm 1 muỗng canh tỏi với 2 muỗng canh dầu, xào chín tôm và nấm, cho cơm vào đảo đến khi cơm săn, trứng chín.', 'Thêm ớt chuông, bông cải xào vừa chín, cho hành ngò vào, tắt bếp. Rắc tiêu, ăn với nước tương.', 'Mẹo: Tách bông cải nhỏ để chín cùng lúc với ớt chuông; trộn trứng vào cơm trước cho dễ chiên và thấm đều.']),
    'com_sen_com': ('Cơm chiên chay với hạt sen, đậu bi, cà rốt, nấm hương, thịt nguội chay, rắc cốm chiên phồng.',
        ['Hòa 1 muỗng canh nước nóng với 1/2 muỗng cà phê bột ngọt, 1/2 muỗng cà phê đường, 1/5 muỗng cà phê muối, trộn đều với cơm.', 'Cắt hạt lựu hạt sen, đậu bi, cà rốt rồi luộc chín. Nấm hương ngâm nở, cắt hạt lựu; thịt nguội chay cắt hạt lựu. Chiên phồng cốm. Băm boa-rô, cắt nhỏ ngò rí, thái ớt.', 'Phi boa-rô với 2 muỗng canh dầu, múc ra 1 muỗng canh dầu. Xào rau củ, nấm, hạt sen, thịt nguội, nêm 1/2 muỗng cà phê bột ngọt, 1/3 muỗng cà phê muối, trút ra.', 'Cho 1 muỗng canh dầu hành vào chảo, xào săn cơm lửa nhỏ, nêm 1/2 muỗng canh nước tương, trộn rau củ vào, tắt bếp.', 'Pha nước chấm: 1 muỗng canh nước tương, 1/3 muỗng cà phê giấm gạo, 1/3 muỗng cà phê đường, ớt thái lát.', 'Bày cơm ra dĩa, rải cốm lên, xếp cánh hoa sen quanh dĩa, ăn với nước chấm.', 'Mẹo: Trộn cơm với gia vị hòa nước trước để cơm mềm, thấm đều; nấu cơm bằng nước dừa hoặc nước dùng cho ngọt.']),
    'com_tam_suon_cay': ('Sườn cây ướp sữa đặc, sả, ngũ vị hương nướng than, ăn cơm tấm với mỡ hành, đồ chua, nước mắm.',
        ['Cắt nhỏ hành lá, để riêng đầu và lá. Khứa vài đường trên sườn, ướp baking soda 1 giờ rồi rửa sạch, để ráo.', 'Xay nhuyễn 1 muỗng canh hành tím, 1 muỗng canh đầu hành, 1/2 muỗng canh tỏi, 1 muỗng canh sả bào, 2 muỗng canh sữa đặc, 1 muỗng cà phê bột ngọt, 1 muỗng canh hạt nêm, 1 muỗng canh nước mắm, 3 muỗng canh nước tương, 1/3 muỗng cà phê ngũ vị hương, 3 muỗng canh dầu ăn. Ướp sườn 2 giờ.', 'Mỡ heo cắt hạt lựu 1cm, thắng lấy tóp và mỡ nước. Trộn hành lá với 1/2 muỗng cà phê tỏi băm, 1/4 muỗng cà phê bột ngọt, 1/2 muỗng cà phê nước mắm, rưới mỡ nóng vào.', 'Pha nước mắm: nấu tan 4 muỗng canh đường, 2 muỗng canh nước mắm, 2 muỗng canh nước, 1/2 muỗng cà phê bột ngọt, 1 muỗng cà phê giấm, 1/2 muỗng cà phê tỏi băm.', 'Nướng sườn trên than hoặc lò 250°C đến khi chín.', 'Bày cơm tấm, mỡ hành, dưa leo, cà chua, sườn ra dĩa; ăn với nước mắm, đồ chua, ớt.', 'Mẹo: Khứa thịt cho dễ thấm và dễ ăn; xay nhuyễn gia vị ướp để khi nướng không bị cháy.']),
    'com_tam_suon_mayonnaise': ('Sườn non ướp mayonnaise, ngũ vị hương nướng vàng, ăn cơm tấm với mỡ hành, nước mắm chua ngọt.',
        ['Băm nhỏ đầu hành, phần lá cắt nhỏ cho vào chén. Sườn chặt khúc 5cm.', 'Ướp sườn với 1 muỗng canh đường, 2 muỗng cà phê hạt nêm, 1/4 muỗng cà phê muối, 1/3 muỗng cà phê ngũ vị hương, 1/4 muỗng cà phê tiêu, 1 muỗng canh nước tỏi, đầu hành băm, 1 muỗng cà phê dầu điều, 2 muỗng canh xốt mayonnaise, 1 muỗng canh nước tương.', 'Mỡ cắt khối 1cm, thắng với ít nước đến khi tóp vàng ngà. Tắt bếp, phi 1/2 muỗng cà phê tỏi băm, chan mỡ nóng vào chén hành lá, nêm ít hạt nêm, trộn đều.', 'Nướng sườn trên than hoặc lò 180 độ đến khi chín vàng.', 'Pha nước mắm: 2,5 muỗng canh đường, 2 muỗng canh nước mắm, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê bột ngọt, 1 muỗng canh nước cốt chanh, 1 muỗng canh tỏi ớt băm, 1/2 chén nước lọc.', 'Bày cơm và sườn ra dĩa, rưới mỡ hành và nước mắm; ăn kèm dưa leo, cà chua, đồ chua.', 'Mẹo: Khi mặt thịt se lại thì quét gia vị lên cho sườn bóng thơm; ướp mayonnaise giúp sườn đậm vị, không khô.']),
    'com_thap_cam_kieu_nhat': ('Cơm gạo dẻo xào rau củ, nấu bằng nước luộc thịt với tôm khô và nước tương, trộn thịt nạc dăm xé.',
        ['Vo gạo, để ráo. Cho tôm khô, thịt nạc dăm, 800ml nước, 1/2 muỗng cà phê hạt nêm, đầu hành đập dập vào nồi, đun sôi rồi hạ lửa.', 'Vớt thịt chín, cắt sợi, ướp 1 muỗng cà phê nước tương.', 'Cà rốt cắt sợi, củ sen thái mỏng. Nấm đông cô ngâm nước vo gạo, cắt gốc, chần rồi cắt sợi. Hành lá cắt nhỏ.', 'Đun 2 muỗng canh dầu, xào sơ gạo cùng cà rốt, củ sen, nấm đến khi hạt gạo săn, cho tất cả vào nồi cơm điện.', 'Đong 550ml nước luộc thịt kèm tôm khô, nêm 5 muỗng canh nước tương, 1 muỗng cà phê đường, 1/2 muỗng cà phê hạt nêm, khuấy tan, đổ vào nồi, đảo đều rồi nấu chín. Trộn thịt vào.', 'Xới ra dĩa, rắc tiêu và hành lá, ăn nóng.', 'Mẹo: Có thể thay gạo Nhật bằng gạo thơm và pha ít nếp; ngâm củ sen nước pha chút giấm gạo cho sạch nhựa; xào gạo trước để cơm không nát.']),
    'com_tom_bi_do': ('Cơm nguội chiên với tôm sú, đậu cô ve và bí đỏ bào nhuyễn, màu vàng đẹp, ngọt dịu.',
        ['Bí đỏ gọt vỏ, bào nhuyễn. Tôm bóc vỏ, bỏ chỉ, cắt hạt lựu. Đậu cô ve tước xơ, cắt hạt lựu. Cắt nhỏ hành lá, rửa ngò rí.', 'Phi thơm 1 muỗng canh tỏi băm, xào chín tôm và đậu cô ve.', 'Cho cơm vào, nêm 1,5 muỗng cà phê hạt nêm, chiên đến khi săn hạt.', 'Thêm bí đỏ đảo đều; bí chín thì rắc hành lá, trộn đều, tắt bếp.', 'Bày ra dĩa, rắc ngò rí, ăn nóng với nước tương và ớt.', 'Mẹo: Bào bí thật nhuyễn cho mau chín; dùng cơm nguội hoặc cơm khô; chiên lửa lớn, nhanh tay để cơm không nhão.']),
    'com_tom_trung_muoi': ('Cơm chiên tôm khô với lòng đỏ trứng muối nướng tán nhuyễn và hành lá, bùi béo, mặn ngọt.',
        ['Ngâm lòng đỏ trứng muối với rượu trắng 30 phút, rửa sạch, nướng nồi chiên không dầu 180 độ trong 4 phút, để nguội rồi dùng nĩa tán nhuyễn.', 'Ngâm tôm khô nước ấm khoảng 30 phút, rửa, để ráo. Cắt nhỏ hành lá.', 'Trộn cơm với 1 muỗng cà phê bột ngọt, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê đường.', 'Phi thơm tỏi với 2 muỗng canh dầu, xào tôm khô, cho cơm vào đảo đến khi săn hạt. Tắt bếp, trộn vào một nửa trứng muối và hành lá.', 'Nén cơm vào bát rồi úp ra dĩa, phủ phần trứng muối còn lại và vài cọng ngò.', 'Mẹo: Nướng sơ trứng muối cho thơm và dễ tơi khi trộn cơm.']),
    'com_tran_chau': ('Cơm gạo dẻo trộn giấm đường với rau củ, vo viên nhân thịt băm xào nước tương sệt, ăn nguội.',
        ['Ướp thịt băm với 1 muỗng cà phê đầu hành băm, 1 muỗng cà phê hạt nêm, ít tiêu, đường và nước. Pha loãng bột năng với ít nước.', 'Xào cà rốt, bắp, hành lá với ít dầu, nêm 1 muỗng cà phê hạt nêm, trút ra.', 'Pha xốt: 1,5 muỗng canh giấm gạo, 2 muỗng cà phê đường, 1/4 muỗng cà phê muối, khuấy tan. Trộn cơm với xốt, rau xào, mè rang cho vị chua ngọt nhẹ.', 'Xào thịt, thêm nước sâm sấp, 1 muỗng cà phê nước tương, xào đến khi chín rồi cho bột năng vào cho sệt.', 'Chia cơm 8 phần, ấn dẹt, cho nhân vào giữa rồi vo tròn. Bày ra dĩa, ăn nguội, chấm nước tương tùy thích.', 'Mẹo: Cho chút nước khi ướp để thịt xào không vón; nêm nước tương khi xào cho nhân đẹp màu.']),
}
